        };

        SetField(
            preview,
            "_todoStore",
            new TodoStore(Path.Combine(tempDirectory, "todos.json")));
        SetField(
            preview,
            "_settingsStore",
            new AppSettingsStore(Path.Combine(tempDirectory, "settings.json")));
        SetField(
            preview,
            "_scheduledTaskStore",
            new ScheduledTaskStore(
                Path.Combine(tempDirectory, "scheduled-tasks.json")));
        GetField<ObservableCollection<TodoItem>>(preview, "_todos").Clear();
        GetField<ObservableCollection<ScheduledTaskItem>>(
            preview,
            "_scheduledTasks").Clear();
        GetField<DispatcherTimer>(preview, "_scheduledTaskTimer").Stop();

        var stateText = new TextBlock
        {
            FontFamily = new FontFamily("Microsoft YaHei"),
            FontSize = 13,
            Foreground = new SolidColorBrush(Color.FromRgb(0x75, 0x43, 0x2A)),
            Margin = new Thickness(0, 10, 0, 0),
            TextWrapping = TextWrapping.Wrap
        };
        var instructions = new Window
        {
            Width = 390,
            Height = 250,
            Left = 28,
            Top = 40,
            ResizeMode = ResizeMode.NoResize,
            ShowInTaskbar = true,
            Topmost = true,
            WindowStartupLocation = WindowStartupLocation.Manual,
            Title = "小鲁班打工动画操作提示",
            Content = new Border
            {
                Padding = new Thickness(18),
                BorderBrush = new SolidColorBrush(Color.FromRgb(0xF0, 0xA2, 0x59)),
                BorderThickness = new Thickness(2),
                CornerRadius = new CornerRadius(18),
                Background = new SolidColorBrush(Color.FromRgb(0xFF, 0xF8, 0xEA)),
                Child = new StackPanel
                {
                    Children =
                    {
                        new TextBlock
                        {
                            FontFamily = new FontFamily("Microsoft YaHei"),
                            FontSize = 18,
                            FontWeight = FontWeights.Bold,
                            Foreground = new SolidColorBrush(Color.FromRgb(0xAD, 0x61, 0x2E)),
                            Text = "小鲁班开工啦！"
                        },
                        new TextBlock
                        {
                            FontFamily = new FontFamily("Microsoft YaHei"),
                            FontSize = 13,
                            Foreground = new SolidColorBrush(Color.FromRgb(0x75, 0x43, 0x2A)),
                            Margin = new Thickness(0, 9, 0, 0),
                             TextWrapping = TextWrapping.Wrap,
                             Text =
                                "普通状态是自然双手打字。单击：画面保持不变；双击：立即 2 倍速，并在最近自然接缝切换认真表情，再双击可续期。打工时按住人物可直接拖动，动画不断、松手继续；拖到左/右/下边缘会保持打工并吸附，顶部不吸附。待机左上角显示萌太阳，打工时切换为萌月亮；普通探头状态隐藏太阳。"
                        },
                        new TextBlock
                        {
                            FontFamily = new FontFamily("Microsoft YaHei"),
                            FontSize = 12,
                            Foreground = new SolidColorBrush(Color.FromRgb(0x9A, 0x68, 0x48)),
                            Margin = new Thickness(0, 8, 0, 0),
                            Text = "键盘：W 切换打工/待机 · T 模拟单击（视觉不变） · F 立即 2x 认真/续期 · I 立即回待机 · Esc 结束"
                        },
                        stateText
                    }
                }
            }
        };

        void HandlePreviewKey(object? sender, KeyEventArgs e)
        {
            try
            {
                var state = GetRawField(preview, "_workState")?.ToString();
                switch (e.Key)
                {
                    case Key.W:
                        if (string.Equals(state, "Idle", StringComparison.Ordinal))
                        {
                            _ = Invoke(preview, "TryEnterWorkMode");
                        }
                        else if (string.Equals(state, "Typing", StringComparison.Ordinal))
                        {
                            Invoke(preview, "RequestWorkExit");
                        }
                        break;
                    case Key.T:
                        Invoke(preview, "HandleWorkPetClick", 1);
                        break;
                    case Key.F:
                        Invoke(preview, "HandleWorkPetClick", 2);
                        break;
                    case Key.I:
                        Invoke(preview, "StopWorkModeImmediately", true);
                        break;
                    case Key.Escape:
                        preview.Close();
                        break;
                    default:
                        return;
                }

                e.Handled = true;
            }
            catch (Exception exception)
            {
                stateText.Text = $"操作失败：{exception.GetBaseException().Message}";
            }
        }

        var statusTimer = new DispatcherTimer
        {
            Interval = TimeSpan.FromMilliseconds(100)
        };
        statusTimer.Tick += (_, _) =>
        {
            var state = GetRawField(preview, "_workState")?.ToString() ?? "?";
            var activeClip = GetRawField(preview, "_activeClip");
            var clipName = activeClip is null
                ? "无"
                : GetProperty<string>(activeClip, "ActionName");
            var rate = GetField<double>(preview, "_workLoopPlaybackRate");
            var edgeDock = GetRawField(preview, "_edgeDock")?.ToString() ?? "?";
            var workEdgeDock = GetRawField(preview, "_workEdgeDock")?.ToString() ?? "?";
            stateText.Text =
                $"当前：{state} / {clipName} / {rate:0.#}x / " +
                $"吸附:{(workEdgeDock != "None" ? $"工作-{workEdgeDock}" : edgeDock)}";
        };

        preview.PreviewKeyDown += HandlePreviewKey;
        instructions.PreviewKeyDown += HandlePreviewKey;
        preview.Loaded += (_, _) =>
            preview.Dispatcher.BeginInvoke(
                DispatcherPriority.ApplicationIdle,
                new Action(() =>
                {
                    try
                    {
                        SetField(preview, "_edgeRoamingEnabled", false);
                        SetField(preview, "_automaticAnimationEnabled", true);
                        SetField(preview, "_nextEdgeRoamDueTimestamp", 0L);
                        SetField(preview, "_nextAutomaticActivityDueTimestamp", long.MaxValue);
                        GetField<DispatcherTimer>(preview, "_automaticTimer").Stop();
                        Invoke(preview, "ApplyPetSizeScale", 1d, false, false);
                        Invoke(
                            preview,
                            "ShowStableFrame",
                            GetField<object>(preview, "_idleFrame"));
                        Invoke(preview, "RefreshWorkModeButton");
                        instructions.Owner = preview;
                        instructions.Show();
                        instructions.Activate();
                        statusTimer.Start();
                    }
                    catch (Exception exception)
                    {
                        Console.Error.WriteLine(exception);
                        application.Shutdown(1);
                    }
                }));
        preview.Closed += (_, _) =>
        {
            statusTimer.Stop();
            instructions.Close();
        };

        Console.WriteLine(
            "[PREVIEW] Verify natural two-hand typing, tap-to-serious, double-click " +
            "serious renewal, and left/right/bottom edge-dock handoff. Close the pet " +
            "window or press Esc to finish.");
        application.ShutdownMode = ShutdownMode.OnMainWindowClose;
        try
        {
            return application.Run(preview);
        }
        finally
        {
            statusTimer.Stop();
            try
            {
                Directory.Delete(tempDirectory, recursive: true);
            }
            catch
            {
                // Preview cleanup must not hide its visual verification result.
            }
        }
    }

    private static int RunReminderClosePreview(Application application)
    {
        var tempDirectory = Path.Combine(
            Path.GetTempPath(),
            $"xlb-pet-reminder-close-preview-{Guid.NewGuid():N}");
        Directory.CreateDirectory(tempDirectory);
        var preview = new MainWindow
        {
            Left = 700,
            ShowActivated = true,
            ShowInTaskbar = true,
            Title = "小鲁班提醒关闭回归预览（关闭桌宠结束）",
            Top = 360,
            Topmost = true
        };

        SetField(
            preview,
            "_todoStore",
            new TodoStore(Path.Combine(tempDirectory, "todos.json")));
        SetField(
            preview,
            "_settingsStore",
            new AppSettingsStore(Path.Combine(tempDirectory, "settings.json")));
        var scheduledStore = new ScheduledTaskStore(
            Path.Combine(tempDirectory, "scheduled-tasks.json"));
        SetField(preview, "_scheduledTaskStore", scheduledStore);
        GetField<ObservableCollection<TodoItem>>(preview, "_todos").Clear();
        var scheduledTasks =
            GetField<ObservableCollection<ScheduledTaskItem>>(
                preview,
                "_scheduledTasks");
        scheduledTasks.Clear();
        GetField<Queue<ScheduledTaskItem>>(
            preview,
            "_reminderQueue").Clear();
        GetField<HashSet<Guid>>(
            preview,
            "_queuedReminderIds").Clear();
        GetField<DispatcherTimer>(
            preview,
            "_scheduledTaskTimer").Stop();
        Invoke(preview, "ApplyPetSizeScale", 1d, false, false);

        var dueAt = DateTimeOffset.Now.AddSeconds(-2);
        var reminder = new ScheduledTaskItem
        {
            Text = "关闭这个提醒后，请右键小鲁班；待办面板能打开就说明桌宠没有卡死。",
            DueAt = dueAt,
            CreatedAt = dueAt.AddMinutes(-1)
        };
        Invoke(preview, "InsertScheduledTaskSorted", reminder);
        if (!scheduledStore.Save(scheduledTasks))
        {
            throw new InvalidOperationException(
                "Failed to prepare reminder-close preview data.");
        }

        preview.Loaded += (_, _) =>
            preview.Dispatcher.BeginInvoke(
                DispatcherPriority.ApplicationIdle,
                new Action(() =>
                {
                    try
                    {
                        SetField(
                            preview,
                            "_automaticAnimationEnabled",
                            false);
                        GetField<DispatcherTimer>(
                            preview,
                            "_automaticTimer").Stop();
                        Invoke(
                            preview,
                            "ProcessScheduledTasksAt",
                            DateTimeOffset.Now);
                        if (GetRawField(preview, "_reminderWindow") is
                            ReminderWindow reminderWindow)
                        {
                            // Make the owned diagnostic window independently
                            // targetable by Windows UI automation.
                            reminderWindow.ShowInTaskbar = true;
                            reminderWindow.Title =
                                "小鲁班提醒关闭按钮实机验证";
                        }
                    }
                    catch (Exception exception)
                    {
                        Console.Error.WriteLine(exception);
                        application.Shutdown(1);
                    }
                }));

        Console.WriteLine(
            "[PREVIEW] Close the reminder with its X, then right-click Luban. " +
            "The Todo panel must open and the reminder must remain unacknowledged.");
        application.ShutdownMode = ShutdownMode.OnMainWindowClose;
        try
        {
            return application.Run(preview);
        }
        finally
        {
            try
            {
                Directory.Delete(tempDirectory, recursive: true);
            }
            catch
            {
                // Preview cleanup must not hide its visual verification result.
            }
        }
    }

    private static void RunCheck(string name, Action check)
    {
        Console.WriteLine($"[RUN] {name}");
        check();
        Console.WriteLine($"[PASS] {name}");
    }

    private static void RunIsolatedUiStateChecks(string argument)
    {
        var executablePath = Environment.ProcessPath;
        if (string.IsNullOrWhiteSpace(executablePath))
        {
            throw new InvalidOperationException(
                "无法定位 UiStateChecks 当前可执行文件，不能启动隔离回归进程");
        }

        var startInfo = new ProcessStartInfo
        {
            FileName = executablePath,
            WorkingDirectory = Environment.CurrentDirectory,
            UseShellExecute = false,
            CreateNoWindow = true,
            RedirectStandardOutput = true,
            RedirectStandardError = true
        };
        startInfo.ArgumentList.Add(argument);

        using var process = Process.Start(startInfo) ??
                            throw new InvalidOperationException(
                                $"无法启动隔离 UiStateChecks 进程：{argument}");
        var standardOutputTask = process.StandardOutput.ReadToEndAsync();
        var standardErrorTask = process.StandardError.ReadToEndAsync();
        if (!process.WaitForExit((int)TimeSpan.FromMinutes(5).TotalMilliseconds))
        {
            process.Kill(entireProcessTree: true);
            throw new TimeoutException(
                $"隔离 UiStateChecks 进程超时：{argument}");
        }

        var standardOutput = standardOutputTask.GetAwaiter().GetResult();
        var standardError = standardErrorTask.GetAwaiter().GetResult();
        if (!string.IsNullOrWhiteSpace(standardOutput))
        {
            Console.Write(standardOutput);
        }

        if (!string.IsNullOrWhiteSpace(standardError))
        {
            Console.Error.Write(standardError);
        }

        Assert(process.ExitCode == 0,
            $"隔离 UiStateChecks 进程失败：{argument}, exit={process.ExitCode}");
    }

    private static void AssertAltTabWindowSourceContract()
    {
        var chromeSource = File.ReadAllText(
            FindWorkspaceFile("WindowChromeAppearance.cs"));
        Assert(
            chromeSource.Contains(
                "window.ShowInTaskbar = false;",
                StringComparison.Ordinal) &&
            chromeSource.Contains(
                "window.SourceInitialized += Window_SourceInitialized;",
                StringComparison.Ordinal) &&
            chromeSource.Contains(
                "currentStyle | WsExToolWindow",
                StringComparison.Ordinal) &&
            chromeSource.Contains(
                "& ~WsExAppWindow",
                StringComparison.Ordinal) &&
            chromeSource.Contains(
                "SetWindowLongPtr(",
                StringComparison.Ordinal) &&
            chromeSource.Contains(
                "SwpFrameChanged",
                StringComparison.Ordinal),
            "窗口基础代码必须在 SourceInitialized 后设置 WS_EX_TOOLWINDOW、" +
            "清除 WS_EX_APPWINDOW，并保留 ShowInTaskbar=False");

        foreach (var (sourceFile, xamlFile) in new[]
                 {
                     ("MainWindow.xaml.cs", "MainWindow.xaml"),
                     ("TodoWindow.xaml.cs", "TodoWindow.xaml"),
                     ("ReminderWindow.xaml.cs", "ReminderWindow.xaml"),
                     ("CuteConfirmationWindow.xaml.cs", "CuteConfirmationWindow.xaml"),
                     ("ScheduledTaskEditWindow.xaml.cs", "ScheduledTaskEditWindow.xaml"),
                     ("TaskTextEditWindow.xaml.cs", "TaskTextEditWindow.xaml")
                 })
        {
            var source = File.ReadAllText(FindWorkspaceFile(sourceFile));
            var xaml = File.ReadAllText(FindWorkspaceFile(xamlFile));
            Assert(
                source.Contains(
                    "WindowChromeAppearance.ExcludeFromAltTab(this);",
                    StringComparison.Ordinal),
                $"{sourceFile} 必须接入统一 Alt+Tab 排除样式");
            Assert(
                xaml.Contains(
                    "ShowInTaskbar=\"False\"",
                    StringComparison.Ordinal),
                $"{xamlFile} 必须保留 ShowInTaskbar=False 的 WPF 契约");
        }
    }

    private static void AssertAltTabAuxiliaryWindowRuntimeContract() =>
        AssertAltTabWindowRuntimeContract(includeMainWindow: false);

    private static void AssertAltTabAllWindowRuntimeContract() =>
        AssertAltTabWindowRuntimeContract(includeMainWindow: true);

    private static void AssertAltTabWindowRuntimeContract(bool includeMainWindow)
    {
        MainWindow? mainWindow = null;
        TodoWindow? todoWindow = null;
        ReminderWindow? reminderWindow = null;
        CuteConfirmationWindow? confirmationWindow = null;
        ScheduledTaskEditWindow? scheduledEditor = null;
        TaskTextEditWindow? textEditor = null;

        try
        {
            if (includeMainWindow)
            {
                mainWindow = new MainWindow
                {
                    Left = -32000,
                    Top = -32000,
                    Opacity = 0,
                    ShowActivated = false
                };
                mainWindow.Show();
                PumpDispatcher(TimeSpan.FromMilliseconds(30));
                AssertWindowExcludedFromAltTab(mainWindow, nameof(MainWindow));
            }

            todoWindow = new TodoWindow
            {
                Left = -32000,
                Top = -32000,
                Opacity = 0,
                ShowActivated = false,
                Owner = mainWindow
            };
            todoWindow.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
            AssertWindowExcludedFromAltTab(todoWindow, nameof(TodoWindow));

            reminderWindow = new ReminderWindow
            {
                Left = -32000,
                Top = -32000,
                Opacity = 0,
                ShowActivated = false,
                Owner = (Window?)mainWindow ?? todoWindow
            };
            reminderWindow.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
            AssertWindowExcludedFromAltTab(
                reminderWindow,
                nameof(ReminderWindow));

            confirmationWindow = new CuteConfirmationWindow(
                "Alt+Tab 回归",
                "确认窗口不应进入 Alt+Tab",
                showSessionSuppression: false)
            {
                Left = -32000,
                Top = -32000,
                Opacity = 0,
                ShowActivated = false,
                Owner = todoWindow
            };
            confirmationWindow.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
            AssertWindowExcludedFromAltTab(
                confirmationWindow,
                nameof(CuteConfirmationWindow));

            textEditor = new TaskTextEditWindow(
                "Alt+Tab 回归",
                "待办编辑窗口",
                showAdvancedEdit: false)
            {
                Left = -32000,
                Top = -32000,
                Opacity = 0,
                ShowActivated = false,
                Owner = todoWindow
            };
            textEditor.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
            AssertWindowExcludedFromAltTab(
                textEditor,
                nameof(TaskTextEditWindow));

            scheduledEditor = new ScheduledTaskEditWindow(
                new ScheduledTaskItem
                {
                    Text = "定时任务编辑窗口",
                    DueAt = DateTimeOffset.Now.AddHours(1)
                })
            {
                Left = -32000,
                Top = -32000,
                Opacity = 0,
                ShowActivated = false,
                Owner = todoWindow
            };
            scheduledEditor.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
            AssertWindowExcludedFromAltTab(
                scheduledEditor,
                nameof(ScheduledTaskEditWindow));

            if (mainWindow is not null)
            {
                Assert(ReferenceEquals(todoWindow.Owner, mainWindow),
                    "待办窗口必须保持主桌宠 Owner 关系");
                Assert(ReferenceEquals(reminderWindow.Owner, mainWindow),
                    "提醒窗口必须保持主桌宠 Owner 关系");
            }
            else
            {
                Assert(todoWindow.Owner is null,
                    "独立辅助窗口专项的待办根窗口必须保持无测试壳 Owner");
                Assert(ReferenceEquals(reminderWindow.Owner, todoWindow),
                    "无图集专项中提醒窗口必须仍覆盖真实 Owner 关系");
            }

            Assert(ReferenceEquals(confirmationWindow.Owner, todoWindow) &&
                   ReferenceEquals(textEditor.Owner, todoWindow) &&
                   ReferenceEquals(scheduledEditor.Owner, todoWindow),
                "确认、待办编辑和定时任务编辑窗口必须保持待办窗口 Owner 关系");
        }
        finally
        {
            CloseAltTabTestWindow(scheduledEditor);
            CloseAltTabTestWindow(textEditor);
            CloseAltTabTestWindow(confirmationWindow);
            CloseAltTabTestWindow(reminderWindow);
            CloseAltTabTestWindow(todoWindow);
            CloseAltTabTestWindow(mainWindow);
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
        }
    }

    private static void AssertWindowExcludedFromAltTab(
        Window window,
        string name)
    {
        var handle = new WindowInteropHelper(window).Handle;
        Assert(handle != IntPtr.Zero, $"{name} 必须已创建真实 HWND");
        Assert(!window.ShowInTaskbar,
            $"{name} 的 ShowInTaskbar 必须保持 false");

        var extendedStyle = GetAltTabWindowLongPtr(
            handle,
            AltTabGwlExStyle).ToInt64();
        Assert((extendedStyle & AltTabWsExToolWindow) != 0,
            $"{name} 必须包含 WS_EX_TOOLWINDOW，实际 0x{extendedStyle:X}");
        Assert((extendedStyle & AltTabWsExAppWindow) == 0,
            $"{name} 必须清除 WS_EX_APPWINDOW，实际 0x{extendedStyle:X}");
        Assert(IsWindowVisible(handle),
            $"{name} 必须是已显示的真实窗口，不能用隐藏 HWND 规避 Alt+Tab");

        var visibleWindows = new HashSet<IntPtr>();
        var eligibleAltTabWindows = new HashSet<IntPtr>();
        var enumerated = EnumWindows(
            (candidate, _) =>
            {
                if (!IsWindowVisible(candidate))
                {
                    return true;
                }

                visibleWindows.Add(candidate);
                if (IsEligibleAltTabWindow(candidate))
                {
                    eligibleAltTabWindows.Add(candidate);
                }

                return true;
            },
            IntPtr.Zero);
        Assert(enumerated, $"EnumWindows 失败，Win32={Marshal.GetLastWin32Error()}");
        Assert(visibleWindows.Contains(handle),
            $"{name} 必须出现在 EnumWindows 的可见窗口集合");
        Assert(!eligibleAltTabWindows.Contains(handle),
            $"{name} 不得进入 eligible Alt+Tab 窗口集合");
    }

    private static bool IsEligibleAltTabWindow(IntPtr handle)
    {
        if (!IsWindowVisible(handle))
        {
            return false;
        }

        var extendedStyle = GetAltTabWindowLongPtr(
            handle,
            AltTabGwlExStyle).ToInt64();
        if ((extendedStyle & AltTabWsExToolWindow) != 0)
        {
            return false;
        }

        if ((extendedStyle & AltTabWsExAppWindow) != 0)
        {
            return true;
        }

        return GetWindow(handle, AltTabGwOwner) == IntPtr.Zero;
    }

    private static void CloseAltTabTestWindow(Window? window)
    {
        if (window is null)
        {
            return;
        }

        switch (window)
        {
            case TodoWindow todoWindow:
                todoWindow.CloseForApplication();
                break;
            case ReminderWindow reminderWindow:
                reminderWindow.CloseForApplication();
                break;
            case ScheduledTaskEditWindow scheduledEditor:
                scheduledEditor.CloseWithoutSaving();
                break;
            case TaskTextEditWindow textEditor:
                textEditor.CloseWithoutSaving();
                break;
            default:
                window.Close();
                break;
        }
    }

    private static void RunMemoryProfile(MainWindow window)
    {
        WaitForSpritePagePrefetchToSettle(window);
        PrepareIdleSpriteCollectionBaseline(window);
        ResetSpritePageCollectionTestState(window);

        var idleFrame = GetField<object>(window, "_idleFrame");
        PrimeSpritePageForFrame(window, idleFrame);
        Invoke(window, "ShowStableFrame", idleFrame);
        WriteMemoryProfileMetric(window, "startup-idle");

        var reactionClip = GetField<Array>(window, "_reactionClips")
            .Cast<object>()
            .First();
        SetField(window, "_activeClip", reactionClip);
        foreach (var pageName in GetClipPageNames(reactionClip)
                     .OrderBy(static name => name, StringComparer.Ordinal))
        {
            LoadSpritePageForMemoryProfile(window, pageName);
        }

        WriteMemoryProfileMetric(window, "active-reaction");

        SetField(window, "_activeClip", null);
        PrimeSpritePageForFrame(window, idleFrame);
        Invoke(window, "ShowStableFrame", idleFrame);

        foreach (var clip in GetField<Array>(window, "_reactionClips")
                     .Cast<object>())
        {
            SetField(window, "_activeClip", clip);
            foreach (var pageName in GetClipFrames(clip)
                         .Cast<object>()
                         .Select(frame => GetProperty<object>(frame, "Image"))
                         .Select(frame => GetSpriteFrameInfo(frame).PageName)
                         .Distinct(StringComparer.Ordinal))
            {
                LoadSpritePageForMemoryProfile(window, pageName);
            }

            SetField(window, "_activeClip", null);
            PrimeSpritePageForFrame(window, idleFrame);
            Invoke(window, "ShowStableFrame", idleFrame);
            Invoke(window, "TrimResidentSpritePagesToBudget", (object?)null);
        }

        WriteMemoryProfileMetric(window, "all-reactions");
        var profiledPool = GetRawField(window, "_spritePageBufferPool")
            ?? throw new InvalidOperationException(
                "MainWindow 缺少 sprite 页像素复用池");
        Assert(GetProperty<long>(profiledPool, "AllocationCount") <= 25 &&
               GetProperty<long>(profiledPool, "ReuseCount") >= 13,
            "四种普通动作依次覆盖时最多只允许比旧分桶基线多一次分配，并必须保留best-fit复用，不能退回逐页LOH重分配");

        SetField(window, "_edgeRoamPreloadRequested", true);
        var roamPageNames = new[]
            {
                "_roamBoardingFrames",
                "_roamFlightFrames",
                "_roamWaveFrames"
            }
            .SelectMany(fieldName =>
                GetField<Array>(window, fieldName).Cast<object>())
            .Select(frame => GetSpriteFrameInfo(frame).PageName)
            .Distinct(StringComparer.Ordinal)
            .OrderBy(static name => name, StringComparer.Ordinal);
        foreach (var pageName in roamPageNames)
        {
            LoadSpritePageForMemoryProfile(window, pageName);
        }

        Invoke(window, "TrimReusableSpritePageBuffersForReadyRoam");
        WriteMemoryProfileMetric(window, "active-roam");
        var activeRoamResidentBytes = GetField<long>(
            window,
            "_residentSpritePageBytes");
        var activeRoamPoolBytes = GetProperty<long>(
            profiledPool,
            "AllocatedBytes");
        Assert(activeRoamResidentBytes == ExpectedActiveRoamSpriteResidentBytes &&
               activeRoamPoolBytes == ExpectedActiveRoamSpriteResidentBytes,
            "The memory profile must establish the exact roaming " +
            "resident/pool hot set before completion.");
        SetField(window, "_edgeRoamPreloadRequested", false);
        SetField(window, "_isEdgeRoaming", true);
        SetField(
            window,
            "_edgeRoamPhase",
            GetNestedEnum("EdgeRoamPhase", "Traveling"));
        SetField(window, "_edgeRoamStopScheduleNext", false);
        SetField(window, "_edgeRoamStopInterrupted", false);
        SetField(window, "_openTodoAfterEdgeRoamStopRequested", false);
        SetField(window, "_pointerDown", false);
        SetField(window, "_dragInteractionActive", false);
        SetField(window, "_isInsideVisualRenderingCallback", true);
        try
        {
            Invoke(window, "CompleteEdgeRoamStop", true);
            var idleTrimTimer = GetField<DispatcherTimer>(
                window,
                "_spritePageIdleTrimTimer");
            Assert(idleTrimTimer.IsEnabled &&
                   idleTrimTimer.Interval == TimeSpan.Zero &&
                   GetField<long>(window, "_residentSpritePageBytes") ==
                   activeRoamResidentBytes &&
                   GetProperty<long>(profiledPool, "AllocatedBytes") ==
                   activeRoamPoolBytes,
                "Roaming completion inside Rendering must only post the " +
                "zero-delay dispatcher trim.");
        }
        finally
        {
            SetField(window, "_isInsideVisualRenderingCallback", false);
        }

        Invoke(window, "SpritePageIdleTrimTimer_Tick", null, EventArgs.Empty);
        Assert(GetField<long>(window, "_residentSpritePageBytes") ==
                   ExpectedIdleSpriteResidentBytes &&
               GetProperty<long>(profiledPool, "AllocatedBytes") ==
                   ExpectedIdleSpriteResidentBytes,
            "The memory profile must prove roaming completion releases the " +
            "hot set to the single exact-sized idle page.");
        WriteMemoryProfileMetric(window, "trimmed-idle");
    }

    private static void LoadSpritePageForMemoryProfile(
        MainWindow window,
        string pageName)
    {
        WaitForSpritePagePrefetchToSettle(window);
        var pageMap = GetField<IDictionary>(window, "_spritePages");
        var page = pageMap[pageName]
            ?? throw new InvalidOperationException(
                $"内存剖面找不到分页 {pageName}");
        Invoke(
            window,
            "PrepareSpritePageBufferForIncomingPage",
            pageName,
            page);
        Invoke(window, "LoadSpritePageIntoBuffer", pageName, page);
        Invoke(
            window,
            "ShowStableFrame",
            GetFirstSpriteFrameOnPage(window, pageName));
    }

    private static void WriteMemoryProfileMetric(
        MainWindow window,
        string stage)
    {
        GCSettings.LargeObjectHeapCompactionMode =
            GCLargeObjectHeapCompactionMode.CompactOnce;
        GC.Collect(
            GC.MaxGeneration,
            GCCollectionMode.Aggressive,
            blocking: true,
            compacting: true);
        GC.WaitForPendingFinalizers();
        GC.Collect(
            GC.MaxGeneration,
            GCCollectionMode.Aggressive,
            blocking: true,
            compacting: true);

        var process = Process.GetCurrentProcess();
        process.Refresh();
        var gcInfo = GC.GetGCMemoryInfo();
        var bufferPool = GetRawField(window, "_spritePageBufferPool")
            ?? throw new InvalidOperationException(
                "MainWindow 缺少 sprite 页像素复用池");
        var residentPageCount = GetField<IDictionary>(
            window,
            "_residentSpritePages").Count;
        Console.WriteLine(
            $"[MEMORY] {stage}: resident=" +
            $"{GetField<long>(window, "_residentSpritePageBytes") / 1048576d:F2}MiB, " +
            $"pages={residentPageCount}, pool-allocated=" +
            $"{GetProperty<long>(bufferPool, "AllocatedBytes") / 1048576d:F2}MiB, " +
            $"pool-rented={GetProperty<long>(bufferPool, "RentedBytes") / 1048576d:F2}MiB, " +
            $"pool-free={GetProperty<long>(bufferPool, "FreeBytes") / 1048576d:F2}MiB, " +
            $"pool-allocations={GetProperty<long>(bufferPool, "AllocationCount")}, " +
            $"pool-reuses={GetProperty<long>(bufferPool, "ReuseCount")}, " +
            $"managed={GC.GetTotalMemory(forceFullCollection: false) / 1048576d:F2}MiB, " +
            $"heap={gcInfo.HeapSizeBytes / 1048576d:F2}MiB, " +
            $"committed={gcInfo.TotalCommittedBytes / 1048576d:F2}MiB, " +
            $"fragmented={gcInfo.FragmentedBytes / 1048576d:F2}MiB, " +
            $"private={process.PrivateMemorySize64 / 1048576d:F2}MiB, " +
            $"working={process.WorkingSet64 / 1048576d:F2}MiB");
    }

    private static void AssertDisplayFrameContract(MainWindow window)
    {
        var petImage = GetField<Rectangle>(window, "PetImage");
        var spriteBrush = GetField<ImageBrush>(window, "PetSpriteBrush");
        var viewport = GetField<Canvas>(window, "PetFrameViewport");
        var pageMap = GetField<IDictionary>(window, "_spritePages");
        var residentPages = GetField<IDictionary>(window, "_residentSpritePages");
        var displayFrameBuffer = GetField<WriteableBitmap>(window, "_displayFrameBuffer");

        Assert(pageMap.Count > 0, "运行时必须登记至少一个图集分页");
        var maximumPageWidth = pageMap.Values.Cast<object>()
            .Max(page => GetProperty<int>(page, "Width"));
        var maximumPageHeight = pageMap.Values.Cast<object>()
            .Max(page => GetProperty<int>(page, "Height"));
        var maximumDecodedPageBytes = pageMap.Values.Cast<object>()
            .Max(page => checked(
                (long)GetProperty<int>(page, "Width") *
                GetProperty<int>(page, "Height") * 4));
        var idlePageNameAtEntry = GetSpriteFrameInfo(
            GetField<object>(window, "_idleFrame")).PageName;
        Assert(maximumDecodedPageBytes <= MaximumDecodedSpritePageBytes &&
               residentPages.Contains(idlePageNameAtEntry),
            $"单页不得超过24MiB且idle必须始终常驻；实际最大页 " +
            $"{maximumDecodedPageBytes / 1024d / 1024d:F2}MiB，" +
            $"当前resident页 {residentPages.Count}");
        AssertResidentSpriteCacheAccounting(window, "完整分页校验开始");
        var bitmapFields = typeof(MainWindow).GetFields(InstanceFlags)
                .Select(field => field.GetValue(window))
                .OfType<BitmapSource>()
                .ToArray();
        Assert(bitmapFields.Length == 1 &&
               bitmapFields.Contains(displayFrameBuffer),
            $"MainWindow只能常驻一个{RenderPixelWidth}×{RenderPixelHeight}" +
            "高密度显示位图；常驻解码页只能是托管Pbgra32数组，" +
            "不能额外常驻WPF分页位图");
        Assert(ReferenceEquals(petImage.Fill, spriteBrush) &&
               ReferenceEquals(spriteBrush.ImageSource, displayFrameBuffer) &&
               displayFrameBuffer.PixelWidth == RenderPixelWidth &&
               displayFrameBuffer.PixelHeight == RenderPixelHeight &&
               displayFrameBuffer.Format == PixelFormats.Pbgra32 &&
               !displayFrameBuffer.IsFrozen,
            $"PetImage必须永久使用唯一的{RenderPixelWidth}×{RenderPixelHeight} " +
            "Pbgra32高密度完整帧缓冲，不能直接裁切整张图集");
        Assert(spriteBrush.ViewboxUnits == BrushMappingMode.Absolute &&
               spriteBrush.Stretch == Stretch.Fill,
            "分页裁剪必须使用Absolute Viewbox并填充PetImage");
        Assert(window.FindName("PetImageBuffer") is null &&
               window.FindName("PetSpriteBufferBrush") is null &&
               window.FindName("PetImageOverlay") is null,
            "不得恢复旧双位图Surface或任何过渡Overlay图层");

        AssertClose(viewport.Width, LogicalPetWidth, "逻辑帧视口宽度");
        AssertClose(viewport.Height, LogicalPetHeight, "逻辑帧视口高度");
        Assert(viewport.ClipToBounds, "逻辑帧视口必须裁剪图集其余区域");
        Assert(string.Equals(
                window.FontFamily.Source,
                "Microsoft YaHei",
                StringComparison.OrdinalIgnoreCase),
            $"MainWindow 必须统一使用 Microsoft YaHei，实际 {window.FontFamily.Source}");

        var pages = GetDictionaryEntries(pageMap)
            .Select(entry => new RuntimePage(
                (string)entry.Key,
                GetProperty<string>(entry.Value!, "ResourcePath"),
                GetProperty<int>(entry.Value!, "Width"),
                GetProperty<int>(entry.Value!, "Height"),
                GetProperty<int>(entry.Value!, "UncompressedByteCount"),
                GetProperty<int>(entry.Value!, "PayloadByteCount"),
                GetProperty<string>(entry.Value!, "Encoding"),
                GetProperty<string>(entry.Value!, "ContentSha256"),
                GetProperty<string>(entry.Value!, "DecodedSha256"),
                GetProperty<IDictionary>(entry.Value!, "Frames"),
                entry.Value!))
            .ToArray();
        AssertSpritePagesManifestAndResourcesContract(pages);

        var totalPageFrames = 0;
        foreach (var page in pages)
        {
            var pageFrames = GetDictionaryEntries(page.Frames);
            Assert(pageFrames.Length > 0, $"分页 {page.Name} 不得为空");

            // The runtime only permits the constructor to decode synchronously;
            // this explicit private wrapper primes deterministic test data before
            // ShowStableFrame. Runtime page changes themselves remain async.
            Invoke(
                window,
                "LoadSpritePageIntoBuffer",
                page.Name,
                page.RuntimeValue);
            Invoke(window, "ShowStableFrame", pageFrames[0].Value);
            Assert(ReferenceEquals(spriteBrush.ImageSource, displayFrameBuffer),
                $"切换到 {page.Name} 后ImageSource引用不得改变");
            Assert(GetField<string>(window, "_loadedSpritePageName") == page.Name,
                $"切换后_loadedSpritePageName必须为 {page.Name}");
            var activePagePixels = GetField<byte[]>(window, "_spritePagePixels");
            AssertBufferMatchesPage(activePagePixels, page);

            foreach (var frameEntry in pageFrames)
            {
                totalPageFrames++;
                var frame = GetSpriteFrameInfo(frameEntry.Value!);
                Assert(frame.PageName == page.Name,
                    $"{frame.Name} 的PageName必须为 {page.Name}");
                Assert(frameEntry.Key is string key && key == frame.Name,
                    $"{page.Name} 帧字典键必须与SpriteFrame.Name一致");
                Assert(frame.X >= 0 && frame.Y >= 0 &&
                       frame.Width > 0 && frame.Height > 0 &&
                       frame.X + frame.Width <= page.Width &&
                       frame.Y + frame.Height <= page.Height,
                    $"{page.Name}/{frame.Name} 必须位于分页边界内");
                Assert(frame.DestinationX < RenderPixelWidth &&
                       frame.DestinationY < RenderPixelHeight &&
                       frame.DestinationX + frame.Width > 0 &&
                       frame.DestinationY + frame.Height > 0,
                    $"{page.Name}/{frame.Name} 必须与{RenderPixelWidth}×" +
                    $"{RenderPixelHeight}渲染区相交");

                Invoke(window, "ShowStableFrame", frameEntry.Value);
                Assert(ReferenceEquals(spriteBrush.ImageSource, displayFrameBuffer),
                    $"显示 {page.Name}/{frame.Name} 时ImageSource引用不得改变");
                Assert(GetField<string>(window, "_loadedSpritePageName") == page.Name,
                    $"同页切帧时_loadedSpritePageName必须保持 {page.Name}");
                AssertSpriteSurfaceConfigured(petImage, spriteBrush, frame);
                AssertNoSpriteSurfaceAnimations(petImage, spriteBrush, frame.Name);
            }

            AssertSamePageDoesNotRewrite(
                window,
                page,
                pageFrames,
                activePagePixels,
                spriteBrush);
        }

        var expectedPinnedPageNames = GetExpectedPinnedSpritePageNames(window);
        Assert(residentPages.Count < pages.Length &&
               expectedPinnedPageNames.All(residentPages.Contains) &&
               residentPages.Contains(GetField<string>(window, "_loadedSpritePageName")),
            $"逐页清单/像素校验后缓存必须保持有界，固定热页与当前页仍须常驻；" +
            $"resident={residentPages.Count}/{pages.Length}");
        AssertResidentSpriteCacheAccounting(window, "逐页清单与像素校验完成");

        using (var manifest = JsonDocument.Parse(File.ReadAllText(
                   FindWorkspaceFile("Assets", "luban-sprite-pages.json"))))
        {
            var declaredPageFrames = manifest.RootElement
                .GetProperty("pageFrameCount")
                .GetInt32();
            Assert(totalPageFrames == declaredPageFrames,
                $"运行时分页应动态覆盖清单声明的{declaredPageFrames}个PageFrame，" +
                $"实际 {totalPageFrames}");
        }
        AssertSameFrameReturnsEarly(
            window,
            petImage,
            spriteBrush,
            pages[0].Frames.Values.Cast<object>().First());
        AssertDirtyRectanglePixelContract(window);
        AssertSingleBufferPremultipliedBlendContract(window);
        AssertCompressedPageLoadPerformance(window, pages);
        AssertResidentSpriteCacheAccounting(window, "逐页热命中性能校验完成");
        var idleFrame = GetField<object>(window, "_idleFrame");
        var idlePageName = GetSpriteFrameInfo(idleFrame).PageName;
        var idlePage = pages.Single(page => page.Name == idlePageName);
        Invoke(
            window,
            "LoadSpritePageIntoBuffer",
            idlePage.Name,
            idlePage.RuntimeValue);
        Invoke(window, "ShowStableFrame", idleFrame);
    }

    private static void AssertDirtyRectanglePixelContract(MainWindow window)
    {
        var pageMap = GetField<IDictionary>(window, "_spritePages");
        var offsetFrame = GetDictionaryEntries(pageMap)
            .SelectMany(page => GetDictionaryEntries(
                GetProperty<IDictionary>(page.Value!, "Frames")))
            .Select(frame => frame.Value!)
            .First(frame =>
            {
                var info = GetSpriteFrameInfo(frame);
                return info.X > 0 && info.Y > 0 &&
                       info.DestinationX >= 0 && info.DestinationY >= 0 &&
                       info.DestinationX + info.Width <= RenderPixelWidth &&
                       info.DestinationY + info.Height <= RenderPixelHeight;
            });
        PrimeSpritePageForFrame(window, offsetFrame);
        var offsetInfo = GetSpriteFrameInfo(offsetFrame);
        var offsetPage = GetDictionaryEntries(pageMap).Single(entry =>
            string.Equals(
                entry.Key as string,
                offsetInfo.PageName,
                StringComparison.Ordinal));
        var pageStride = GetProperty<int>(offsetPage.Value!, "Width") * 4;
        var pagePixels = GetField<byte[]>(window, "_spritePagePixels");
        var expectedOffsetCopy = new byte[RenderPixelWidth * RenderPixelHeight * 4];
        var actualOffsetCopy = new byte[expectedOffsetCopy.Length];
        var visibleOffsetBounds = new Int32Rect(
            offsetInfo.DestinationX,
            offsetInfo.DestinationY,
            offsetInfo.Width,
            offsetInfo.Height);
        var displayStride = RenderPixelWidth * 4;
        for (var row = 0; row < offsetInfo.Height; row++)
        {
            Buffer.BlockCopy(
                pagePixels,
                (offsetInfo.Y + row) * pageStride + offsetInfo.X * 4,
                expectedOffsetCopy,
                (offsetInfo.DestinationY + row) * displayStride +
                offsetInfo.DestinationX * 4,
                offsetInfo.Width * 4);
        }

        InvokeOverload(
            window,
            "CopyFramePixels",
            offsetFrame,
            actualOffsetCopy,
            visibleOffsetBounds);
        Assert(actualOffsetCopy.AsSpan().SequenceEqual(expectedOffsetCopy),
            $"非零图集source offset必须逐字节复制正确：{offsetInfo.PageName}/{offsetInfo.Name}, " +
            $"source=({offsetInfo.X},{offsetInfo.Y})");

        var idleFrame = GetField<object>(window, "_idleFrame");
        var idleInfo = GetSpriteFrameInfo(idleFrame);
        var runtimeSideFrame =
            GetField<Array>(window, "_edgeLeftFrames").GetValue(0)!;
        var runtimeSideInfo = GetSpriteFrameInfo(runtimeSideFrame);
        var negativeDestinationFrame = FindSpriteFrameBySuffix(
            window,
            "luban-edge-left-smooth-001.png");
        var negativeInfo = GetSpriteFrameInfo(negativeDestinationFrame);
        Assert(negativeInfo.DestinationX < 0 &&
               runtimeSideInfo.DestinationX == negativeInfo.DestinationX &&
               runtimeSideInfo.Width == negativeInfo.Width &&
               string.Equals(
                   runtimeSideInfo.Name,
                   negativeInfo.Name,
                   StringComparison.Ordinal),
            "左右贴边运行帧必须原样保留清单中的负DestinationX透明gutter，" +
            "不能二次平移并在左右屏幕边缘留下缺臂缝隙");
        Assert(!string.Equals(
                idleInfo.PageName,
                negativeInfo.PageName,
                StringComparison.Ordinal),
            "脏矩形跨页夹具必须使用两个不同的图集页");
        PrimeSpritePageForFrame(window, idleFrame);
        Assert(GetField<string>(window, "_loadedSpritePageName") == idleInfo.PageName,
            "写入待机帧前必须先加载待机图集页");
        SetField(window, "_directDisplayFrameBounds", null);
        Invoke(window, "WriteDirectSpriteFrame", idleFrame);
        PrimeSpritePageForFrame(window, negativeDestinationFrame);
        Assert(GetField<string>(window, "_loadedSpritePageName") == negativeInfo.PageName,
            "写入边缘帧前必须先加载边缘图集页");
        Invoke(window, "WriteDirectSpriteFrame", negativeDestinationFrame);
        var incrementalPixels = GetField<byte[]>(window, "_displayFramePixels");
        var fullReference = new byte[incrementalPixels.Length];
        InvokeOverload(window, "CopyFramePixels", negativeDestinationFrame, fullReference);
        Assert(incrementalPixels.AsSpan().SequenceEqual(fullReference),
            "不同bounds增量切到负Destination裁剪帧时，结果必须逐字节等于全清重绘参考");

        PrimeSpritePageForFrame(window, idleFrame);
        Assert(GetField<string>(window, "_loadedSpritePageName") == idleInfo.PageName,
            "切回待机帧前必须重新加载待机图集页");
        Invoke(window, "WriteDirectSpriteFrame", idleFrame);
        Array.Clear(fullReference);
        InvokeOverload(window, "CopyFramePixels", idleFrame, fullReference);
        Assert(incrementalPixels.AsSpan().SequenceEqual(fullReference),
            "不同bounds从负Destination帧切回较大普通帧时，旧像素清理必须逐字节等于全清重绘参考");
        AssertDirtyRectangleDifferenceEquivalence();
        SetField(window, "_currentSpriteFrame", null);
        Invoke(window, "ShowStableFrame", idleFrame);
    }

    private static void AssertDirtyRectangleDifferenceEquivalence()
    {
        var rectanglePairs = new List<(Int32Rect Previous, Int32Rect Next)>
        {
            (new Int32Rect(0, 0, 399, 509), new Int32Rect(0, 0, 399, 509)),
            (new Int32Rect(10, 20, 300, 400), new Int32Rect(30, 40, 80, 90)),
            (new Int32Rect(30, 40, 80, 90), new Int32Rect(10, 20, 300, 400)),
            (new Int32Rect(0, 0, 200, 250), new Int32Rect(150, 200, 249, 309)),
            (new Int32Rect(0, 0, 80, 90), new Int32Rect(300, 400, 99, 109)),
            (new Int32Rect(0, 200, 399, 120), new Int32Rect(100, 0, 200, 509)),
            (new Int32Rect(398, 508, 1, 1), Int32Rect.Empty),
            (new Int32Rect(0, 0, 1, 1), new Int32Rect(398, 508, 1, 1))
        };
        var random = new Random(0x5A17D1FF);
        for (var index = 0; index < 96; index++)
        {
            var previousX = random.Next(RenderPixelWidth);
            var previousY = random.Next(RenderPixelHeight);
            var nextX = random.Next(RenderPixelWidth);
            var nextY = random.Next(RenderPixelHeight);
            rectanglePairs.Add((
                new Int32Rect(
                    previousX,
                    previousY,
                    random.Next(1, RenderPixelWidth - previousX + 1),
                    random.Next(1, RenderPixelHeight - previousY + 1)),
                index % 17 == 0
                    ? Int32Rect.Empty
                    : new Int32Rect(
                        nextX,
                        nextY,
                        random.Next(1, RenderPixelWidth - nextX + 1),
                        random.Next(1, RenderPixelHeight - nextY + 1))));
        }

        var initial = new byte[RenderPixelWidth * RenderPixelHeight * 4];
        var baseline = new byte[initial.Length];
        var candidate = new byte[initial.Length];

        foreach (var (previousBounds, nextBounds) in rectanglePairs)
        {
            var dirtyBounds = (Int32Rect)InvokeStatic(
                typeof(MainWindow),
                "UnionPixelBounds",
                previousBounds,
                nextBounds)!;
            Array.Fill(initial, (byte)0xA5);
            InvokeStatic(
                typeof(MainWindow),
                "ClearPixelBounds",
                initial,
                dirtyBounds);
            WriteDeterministicRectanglePixels(initial, previousBounds);
            Buffer.BlockCopy(initial, 0, baseline, 0, initial.Length);
            Buffer.BlockCopy(initial, 0, candidate, 0, initial.Length);
            InvokeStatic(
                typeof(MainWindow),
                "ClearPixelBounds",
                baseline,
                dirtyBounds);
            InvokeStatic(
                typeof(MainWindow),
                "ClearPixelBoundsDifference",
                candidate,
                previousBounds,
                nextBounds);
            WriteDeterministicRectanglePixels(baseline, nextBounds);
            WriteDeterministicRectanglePixels(candidate, nextBounds);
            Assert(candidate.AsSpan().SequenceEqual(baseline),
                $"差集清理必须逐字节等于旧版union全清后重绘：" +
                $"previous={previousBounds}, next={nextBounds}");
        }
    }

    private static void WriteDeterministicRectanglePixels(
        byte[] pixels,
        Int32Rect bounds)
    {
        var stride = RenderPixelWidth * 4;
        for (var row = 0; row < bounds.Height; row++)
        {
            for (var column = 0; column < bounds.Width; column++)
            {
                var x = bounds.X + column;
                var y = bounds.Y + row;
                var offset = y * stride + x * 4;
                pixels[offset] = (byte)((x * 3 + y * 5 + 17) & 0xFF);
                pixels[offset + 1] = (byte)((x * 7 + y * 11 + 29) & 0xFF);
                pixels[offset + 2] = (byte)((x * 13 + y * 17 + 41) & 0xFF);
                pixels[offset + 3] = (byte)(1 + ((x * 19 + y * 23) % 255));
            }
        }
    }

    private static void AssertHighDensityScalingAndDpiContract(MainWindow window)
    {
        var displayFrameBuffer = GetField<WriteableBitmap>(window, "_displayFrameBuffer");
        var spriteBrush = GetField<ImageBrush>(window, "PetSpriteBrush");
        var petImage = GetField<Rectangle>(window, "PetImage");
        var petVisual = GetField<Grid>(window, "PetVisual");

        AssertClose(petVisual.Width, LogicalPetWidth,
            "高密度渲染不得改变人物逻辑画布宽度");
        AssertClose(petVisual.Height, LogicalPetHeight,
            "高密度渲染不得改变人物逻辑画布高度");
        Assert(RenderOptions.GetBitmapScalingMode(petImage) == BitmapScalingMode.Fant,
            "高密度位图缩小时必须继续使用Fant高质量采样");

        try
        {
            Invoke(window, "ApplyPetSizeScale", 1.40d, false, false);
            var visibleWidth = LogicalPetWidth * 1.40d;
            var visibleHeight = LogicalPetHeight * 1.40d;
            var requiredPixelsAt96DpiWidth = (int)Math.Ceiling(visibleWidth);
            var requiredPixelsAt96DpiHeight = (int)Math.Ceiling(visibleHeight);
            var requiredPixelsAt150DpiWidth = (int)Math.Ceiling(visibleWidth * 1.5d);
            var requiredPixelsAt150DpiHeight = (int)Math.Ceiling(visibleHeight * 1.5d);
            var petSizeViewbox = GetField<Viewbox>(window, "PetSizeViewbox");
            AssertClose(window.Width, 454,
                "140%时窗口逻辑宽度");
            AssertClose(window.Height, 454,
                "140%时窗口逻辑高度");
            AssertClose(petSizeViewbox.Width, visibleWidth,
                "140% visible pet logical width");
            AssertClose(petSizeViewbox.Height, visibleHeight,
                "140% visible pet logical height");
            Assert(displayFrameBuffer.PixelWidth >= requiredPixelsAt96DpiWidth &&
                   displayFrameBuffer.PixelHeight >= requiredPixelsAt96DpiHeight,
                $"140%@100%DPI不得再上采样：窗口需要 " +
                $"{requiredPixelsAt96DpiWidth}×{requiredPixelsAt96DpiHeight}px，" +
                $"完整帧实际 {displayFrameBuffer.PixelWidth}×" +
                $"{displayFrameBuffer.PixelHeight}px");
            Assert(requiredPixelsAt150DpiWidth == RenderPixelWidth &&
                   requiredPixelsAt150DpiHeight == RenderPixelHeight &&
                   displayFrameBuffer.PixelWidth >= requiredPixelsAt150DpiWidth &&
                   displayFrameBuffer.PixelHeight >= requiredPixelsAt150DpiHeight,
                $"140%@150%DPI不得上采样：窗口需要 " +
                $"{requiredPixelsAt150DpiWidth}×{requiredPixelsAt150DpiHeight}px，" +
                $"完整帧实际 {displayFrameBuffer.PixelWidth}×" +
                $"{displayFrameBuffer.PixelHeight}px");
            AssertRectClose(
                spriteBrush.Viewbox,
                new Rect(0, 0, RenderPixelWidth, RenderPixelHeight),
                "140%高密度完整帧Viewbox");
        }
        finally
        {
            // 后续布局契约以默认逻辑尺寸为基线；测试不得受用户本机已保存的
            // 140% 设置影响。
            Invoke(window, "ApplyPetSizeScale", 1d, false, false);
        }

        var manifestPath = FindWorkspaceFile("app.manifest");
        var manifest = XDocument.Load(manifestPath);
        var dpiAwareness = manifest
            .Descendants()
            .FirstOrDefault(element => element.Name.LocalName == "dpiAwareness")?
            .Value;
        var legacyDpiAware = manifest
            .Descendants()
            .FirstOrDefault(element => element.Name.LocalName == "dpiAware")?
            .Value;
        Assert(dpiAwareness is not null &&
               dpiAwareness.Split(',').Any(value =>
                   string.Equals(value.Trim(), "PerMonitorV2", StringComparison.OrdinalIgnoreCase)) &&
               string.Equals(legacyDpiAware?.Trim(), "true/pm", StringComparison.OrdinalIgnoreCase),
            "app.manifest必须声明PerMonitorV2，并保留true/pm兼容声明，避免异DPI副屏整窗位图缩放");

        var project = XDocument.Load(FindWorkspaceFile("DesktopPet.csproj"));
        var applicationManifest = project
            .Descendants()
            .FirstOrDefault(element => element.Name.LocalName == "ApplicationManifest")?
            .Value
            .Trim();
        Assert(string.Equals(applicationManifest, "app.manifest", StringComparison.OrdinalIgnoreCase),
            "DesktopPet.csproj必须通过ApplicationManifest引用app.manifest");

        var appXaml = XDocument.Load(FindWorkspaceFile("App.xaml"));
        var toolTipStyle = appXaml.Descendants()
            .FirstOrDefault(element =>
                element.Name.LocalName == "Style" &&
                ((string?)element.Attribute("TargetType"))?.Contains(
                    "ToolTip",
                    StringComparison.OrdinalIgnoreCase) == true);
        var toolTipFontSetter = toolTipStyle?.Descendants()
            .FirstOrDefault(element =>
                element.Name.LocalName == "Setter" &&
                string.Equals(
                    (string?)element.Attribute("Property"),
                    "FontFamily",
                    StringComparison.OrdinalIgnoreCase));
        Assert(string.Equals(
                (string?)toolTipFontSetter?.Attribute("Value"),
                "Microsoft YaHei",
                StringComparison.OrdinalIgnoreCase),
            "App.xaml必须为所有ToolTip统一设置Microsoft YaHei，覆盖字符串ToolTip弹层");
    }

    private static void AssertSupersededPendingSpriteFrameDoesNotFlashBack(
        MainWindow window)
    {
        var pageEntries = GetDictionaryEntries(
            GetField<IDictionary>(window, "_spritePages"));
        var hotPageEntry = pageEntries.First(entry =>
            GetProperty<IDictionary>(entry.Value!, "Frames").Count >= 2);
        var coldPageEntry = pageEntries.First(entry =>
            !Equals(entry.Key, hotPageEntry.Key));
        var hotFrames = GetDictionaryEntries(
            GetProperty<IDictionary>(hotPageEntry.Value!, "Frames"));
        var coldAtlasFrame = GetDictionaryEntries(
            GetProperty<IDictionary>(coldPageEntry.Value!, "Frames"))[0].Value!;
        var coldFrame = CloneSpriteFrameWithName(
            coldAtlasFrame,
            "Assets/luban-edge-synthetic-cold.png");
        var hotFrameA1 = hotFrames[0].Value!;
        var hotFrameA2 = hotFrames[1].Value!;
        var hotPageName = (string)hotPageEntry.Key;
        var coldPageName = (string)coldPageEntry.Key;

        WaitForSpritePagePrefetchToSettle(window);
        var deferredDispatchTimer = GetField<DispatcherTimer>(
            window,
            "_spritePagePrefetchDispatchTimer");
        deferredDispatchTimer.Stop();
        SetField(window, "_pendingSpriteFrame", null);
        SetField(window, "_pendingSpriteFrameBlendDuration", TimeSpan.Zero);
        SetField(window, "_desiredSpritePageName", null);
        SetField(window, "_desiredSpritePageUrgent", false);
        SetField(window, "_renderDeferredSpritePageName", null);
        SetField(window, "_renderDeferredSpritePageUrgent", false);
        SetField(window, "_renderDeferredSpritePageCancellation", false);

        Invoke(
            window,
            "LoadSpritePageIntoBuffer",
            hotPageName,
            hotPageEntry.Value!);
        EvictResidentSpritePageForTest(window, coldPageName);
        Invoke(window, "ShowStableFrame", hotFrameA1);
        var pillowImage = GetField<Image>(window, "PillowImage");
        Assert(pillowImage.Visibility == Visibility.Visible && pillowImage.Opacity == 1d,
            "普通热页帧必须显示静态枕头层");

        // Reproduce the narrower Rendering -> one-shot timer race. The cold
        // request exists only in the deferred signal until the timer ticks;
        // a newer hot frame must erase it without ever creating a Task/CTS.
        SetField(window, "_isInsideVisualRenderingCallback", true);
        try
        {
            Invoke(window, "ShowStableFrame", coldFrame);
        }
        finally
        {
            SetField(window, "_isInsideVisualRenderingCallback", false);
        }

        Assert(Equals(GetRawField(window, "_pendingSpriteFrame"), coldFrame) &&
               string.Equals(
                   GetRawField(window, "_renderDeferredSpritePageName") as string,
                   coldPageName,
                   StringComparison.Ordinal) &&
               deferredDispatchTimer.IsEnabled &&
               GetRawField(window, "_spritePagePrefetchTask") is null &&
               pillowImage.Visibility == Visibility.Visible &&
               pillowImage.Opacity == 1d,
            "Rendering 中的冷页请求必须只唤醒一次性调度并保持旧帧枕头状态，不能提前闪目标页或创建后台任务");
        Invoke(window, "ShowStableFrame", hotFrameA2);
        Assert(GetRawField(window, "_pendingSpriteFrame") is null &&
               GetRawField(window, "_renderDeferredSpritePageName") is null &&
               !deferredDispatchTimer.IsEnabled &&
               GetRawField(window, "_spritePagePrefetchTask") is null &&
               Equals(GetRawField(window, "_currentSpriteFrame"), hotFrameA2),
            "Timer Tick 前被热页取代的 deferred 冷页必须彻底淘汰，不能延迟启动过时解码");
        Invoke(window, "SpritePagePrefetchDispatchTimer_Tick", null, EventArgs.Empty);
        Assert(GetRawField(window, "_spritePagePrefetchTask") is null,
            "已淘汰的 deferred 冷页即使触发空 Tick 也不得创建 Task/CTS");
        Invoke(window, "ShowStableFrame", hotFrameA1);

        // Repeat the same supersession while an independent 20-second idle
        // grace timer is armed. Clearing the obsolete page request must stop
        // only the prefetch dispatcher, not consume or accelerate idle trim.
        var idleTrimTimer = GetField<DispatcherTimer>(
            window,
            "_spritePageIdleTrimTimer");
        idleTrimTimer.Stop();
        SetField(window, "_isInsideVisualRenderingCallback", true);
        try
        {
            Invoke(window, "ShowStableFrame", coldFrame);
            Invoke(window, "RequestIdleSpritePageTrim", false);
        }
        finally
        {
            SetField(window, "_isInsideVisualRenderingCallback", false);
        }

        Assert(Equals(GetRawField(window, "_pendingSpriteFrame"), coldFrame) &&
               !GetField<bool>(window, "_residentSpritePageTrimPending") &&
               deferredDispatchTimer.IsEnabled &&
               idleTrimTimer.IsEnabled &&
               idleTrimTimer.Interval == TimeSpan.FromSeconds(20),
            "deferred冷页与idle trim必须分别使用dispatcher信号和独立20秒宽限timer");
        Invoke(window, "ShowStableFrame", hotFrameA1);
        Assert(GetRawField(window, "_pendingSpriteFrame") is null &&
               GetRawField(window, "_renderDeferredSpritePageName") is null &&
               !deferredDispatchTimer.IsEnabled &&
               idleTrimTimer.IsEnabled,
            "热页淘汰obsolete deferred请求时只能停止分页dispatcher，不能提前消费idle宽限期");

        idleTrimTimer.Stop();
        idleTrimTimer.Interval = TimeSpan.FromSeconds(7);
        idleTrimTimer.Start();
        Invoke(window, "RequestSpritePagePrefetch", hotPageName, true);
        Assert(idleTrimTimer.IsEnabled &&
               idleTrimTimer.Interval == TimeSpan.FromSeconds(7) &&
               GetRawField(window, "_spritePagePrefetchTask") is null,
            "resident命中不是新的分页活动，不得重启20秒idle宽限或创建后台任务");
        ResetSpritePageCollectionTestState(window);

        // A1 -> cold C1: keep A1 visible while C starts decoding in the
        // background and records C1 as the pending pose.
        Invoke(window, "ShowStableFrame", coldFrame);
        Assert(Equals(GetRawField(window, "_pendingSpriteFrame"), coldFrame) &&
               string.Equals(
                   GetRawField(window, "_desiredSpritePageName") as string,
                   coldPageName,
                   StringComparison.Ordinal),
            "请求冷页C1时必须保持热页A1并记录pending=C1");

        // Before C's UI completion callback can run, a newer A2 request is
        // immediately displayable from the still-loaded hot page.
        Invoke(window, "ShowStableFrame", hotFrameA2);
        Assert(GetRawField(window, "_pendingSpriteFrame") is null &&
               GetRawField(window, "_desiredSpritePageName") is null &&
               Equals(GetRawField(window, "_currentSpriteFrame"), hotFrameA2),
            "热页A2取代冷页C1后必须立即清除旧pending/demand并保持current=A2");

        // Let C's canceled/already-completed task and its queued Dispatcher
        // callback fully settle, then emulate the next Rendering retry.
        var completionDeadline = Stopwatch.StartNew();
        while (GetRawField(window, "_spritePagePrefetchTask") is not null &&
               completionDeadline.Elapsed < TimeSpan.FromSeconds(3))
        {
            PumpDispatcher(TimeSpan.FromMilliseconds(10));
        }

        Assert(GetRawField(window, "_spritePagePrefetchTask") is null,
            "被A2取代的冷页C任务必须在3秒内完成取消/代际收敛");
        Invoke(window, "TryShowPendingSpriteFrame");
        Assert(GetRawField(window, "_pendingSpriteFrame") is null &&
               Equals(GetRawField(window, "_currentSpriteFrame"), hotFrameA2) &&
               string.Equals(
                   GetRawField(window, "_loadedSpritePageName") as string,
                   hotPageName,
                   StringComparison.Ordinal),
            "冷页C完成回调不得在下一次Rendering闪回C1；必须继续显示A2");

        // Once the exact same cold target is actually resident and committed,
        // its edge-pose pillow state must change atomically with current frame.
        Invoke(window, "ShowStableFrame", coldFrame);
        if (GetRawField(window, "_pendingSpriteFrame") is not null)
        {
            WaitForPrefetchedSpritePage(window, coldFrame);
            Invoke(window, "TryShowPendingSpriteFrame");
        }

        Assert(Equals(GetRawField(window, "_currentSpriteFrame"), coldFrame) &&
               pillowImage.Visibility == Visibility.Visible &&
               pillowImage.Opacity == 0d,
            "冷页目标只有在像素真正提交后才能同步隐藏枕头");
        Invoke(window, "ShowStableFrame", hotFrameA1);
        Assert(pillowImage.Visibility == Visibility.Visible && pillowImage.Opacity == 1d,
            "返回普通常驻页时必须与帧提交同步恢复枕头");

        var idleFrame = GetField<object>(window, "_idleFrame");
        var idlePageName = GetSpriteFrameInfo(idleFrame).PageName;
        var idlePageEntry = pageEntries.Single(entry =>
            string.Equals((string)entry.Key, idlePageName, StringComparison.Ordinal));
        Invoke(
            window,
            "LoadSpritePageIntoBuffer",
            idlePageName,
            idlePageEntry.Value!);
        Invoke(window, "ShowStableFrame", idleFrame);
    }

    private static void AssertSpritePageBudgetCapacityContract(MainWindow window)
    {
        var pageMap = GetField<IDictionary>(window, "_spritePages");
        var pool = GetRawField(window, "_spritePageBufferPool")
            ?? throw new InvalidOperationException(
                "MainWindow 缺少 sprite 页像素复用池");
        var poolType = pool.GetType();
        var reuseCapacityStepBytes = (int)(poolType.GetField(
                "ReuseCapacityStepBytes",
                StaticFlags)?.GetRawConstantValue() ?? 0);
        var ordinaryBudgetBytes = (long)(typeof(MainWindow).GetField(
                "SpritePageResidentBudgetBytes",
                StaticFlags)!.GetValue(null) ?? 0L);
        var roamBudgetBytes = (long)(typeof(MainWindow).GetField(
                "SpritePageRoamResidentBudgetBytes",
                StaticFlags)!.GetValue(null) ?? 0L);
        var pinnedPageNames = GetExpectedPinnedSpritePageNames(window);
        var startupIdlePageName = GetSpriteFrameInfo(
            GetField<object>(window, "_idleFrame")).PageName;

        long CapacityOf(string pageName) =>
            GetSpritePageByteCount(pageMap, pageName);

        long MaximumReusableCapacityOf(string pageName) =>
            GetMaximumReusableSpritePageCapacity(
                GetSpritePageByteCount(pageMap, pageName));

        static HashSet<string> PageNamesFromFrames(Array frames) =>
            frames.Cast<object>()
                .Select(frame => GetSpriteFrameInfo(frame).PageName)
                .ToHashSet(StringComparer.Ordinal);

        var ordinaryPageSets = GetField<Array>(window, "_reactionClips")
            .Cast<object>()
            .Select(GetClipPageNames)
            .ToList();
        foreach (var clipFieldName in new[]
                 {
                     "_todoEnterClip",
                     "_todoExitClip",
                     "_reminderEnterClip",
                     "_reminderHoldClip",
                     "_reminderExitClip",
                     "_workEnterClip",
                     "_workLoopClip",
                     "_workSeriousLoopClip",
                     "_workSeriousEnterClip",
                     "_workSeriousExitClip",
                     "_workExitClip"
                 })
        {
            ordinaryPageSets.Add(GetClipPageNames(
                GetRawField(window, clipFieldName)
                ?? throw new InvalidOperationException(
                    $"MainWindow 缺少 {clipFieldName}")));
        }

        foreach (var (fromFieldName, toFieldName) in new[]
                 {
                     ("_workEnterClip", "_workLoopClip"),
                     ("_workLoopClip", "_workSeriousEnterClip"),
                     ("_workSeriousEnterClip", "_workSeriousLoopClip"),
                     ("_workSeriousLoopClip", "_workSeriousExitClip"),
                     ("_workSeriousExitClip", "_workLoopClip"),
                     ("_workLoopClip", "_workExitClip")
                 })
        {
            ordinaryPageSets.Add(
                GetClipPageNames(GetRawField(window, fromFieldName)
                    ?? throw new InvalidOperationException(
                        $"MainWindow 缺少 {fromFieldName}"))
                .Concat(GetClipPageNames(GetRawField(window, toFieldName)
                    ?? throw new InvalidOperationException(
                        $"MainWindow 缺少 {toFieldName}")))
                .ToHashSet(StringComparer.Ordinal));
        }

        foreach (var frameFieldName in new[]
                 {
                     "_wakeFrames",
                     "_edgeLeftFrames",
                     "_edgeBottomFrames",
                     "_reminderEnterFrames",
                     "_reminderHoldFrames"
                 })
        {
            ordinaryPageSets.Add(PageNamesFromFrames(
                GetField<Array>(window, frameFieldName)));
        }

        var maximumOrdinaryBytes = 0L;
        foreach (var pageSet in ordinaryPageSets)
        {
            var protectedNames = pinnedPageNames
                .Concat(pageSet
                    .Where(pageName => !pinnedPageNames.Contains(pageName))
                    .OrderByDescending(CapacityOf)
                    .Take(2))
                .ToHashSet(StringComparer.Ordinal);
            var adjacentReuseWorstCaseBytes = protectedNames.Sum(pageName =>
                string.Equals(
                    pageName,
                    startupIdlePageName,
                    StringComparison.Ordinal)
                    ? CapacityOf(pageName)
                    : MaximumReusableCapacityOf(pageName));
            maximumOrdinaryBytes = Math.Max(
                maximumOrdinaryBytes,
                adjacentReuseWorstCaseBytes);
        }

        var roamPageNames = pinnedPageNames
            .Concat(PageNamesFromFrames(
                GetField<Array>(window, "_roamBoardingFrames")))
            .Concat(PageNamesFromFrames(
                GetField<Array>(window, "_roamFlightFrames")))
            .Concat(PageNamesFromFrames(
                GetField<Array>(window, "_roamWaveFrames")))
            .ToHashSet(StringComparer.Ordinal);
        var maximumRoamBytes = roamPageNames.Sum(pageName =>
            string.Equals(
                pageName,
                startupIdlePageName,
                StringComparison.Ordinal)
                ? CapacityOf(pageName)
                : MaximumReusableCapacityOf(pageName));

        Assert(reuseCapacityStepBytes == 1 * 1024 * 1024 &&
               maximumOrdinaryBytes == ExpectedMaximumOrdinarySpriteWorkingSetBytes &&
               maximumOrdinaryBytes <= ordinaryBudgetBytes,
            $"普通分页预算必须精确覆盖单页idle、当前页、下一页及best-fit复用余量：" +
            $"需要 {maximumOrdinaryBytes} bytes / " +
            $"{maximumOrdinaryBytes / 1048576d:F2}MiB，" +
            $"预算 {ordinaryBudgetBytes / 1048576d:F2}MiB");
        Assert(maximumRoamBytes == ExpectedMaximumRoamSpriteWorkingSetBytes &&
               maximumRoamBytes <= roamBudgetBytes &&
               GetProperty<long>(pool, "HardBudgetBytes") == roamBudgetBytes,
            $"绕屏分页预算与池硬预算必须容纳全部boarding/flight/wave页以及" +
            $"best-fit复用余量：需要 {maximumRoamBytes} bytes / " +
            $"{maximumRoamBytes / 1048576d:F2}MiB，" +
            $"预算 {roamBudgetBytes / 1048576d:F2}MiB");
        Console.WriteLine(
            $"[METRIC] sprite budget: ordinary-required=" +
            $"{maximumOrdinaryBytes / 1048576d:F2}/" +
            $"{ordinaryBudgetBytes / 1048576d:F2}MiB, roam-required=" +
            $"{maximumRoamBytes / 1048576d:F2}/" +
            $"{roamBudgetBytes / 1048576d:F2}MiB");
    }

    private static void AssertResidentSpritePageWarmupContract(MainWindow window)
    {
        var pageMap = GetField<IDictionary>(window, "_spritePages");
        var pageNames = GetDictionaryEntries(pageMap)
            .Select(entry => (string)entry.Key)
            .ToArray();
        Assert(pageNames.Length >= 3,
            "常驻缓存回归至少需要idle、固定热页和按需动作页");

        var residentPages = GetField<IDictionary>(window, "_residentSpritePages");
        var idlePageName = GetField<string>(window, "_loadedSpritePageName");
        var idlePixels = GetField<byte[]>(window, "_spritePagePixels");
        var residentBudgetBytes = (long)(typeof(MainWindow).GetField(
                "SpritePageResidentBudgetBytes",
                StaticFlags)!.GetValue(null) ?? 0L);
        var pinnedPageNames = GetField<HashSet<string>>(
            window,
            "_pinnedSpritePageNames");
        var warmupOrder = GetField<string[]>(window, "_spritePageWarmupOrder");
        var expectedPinnedPageNames = GetExpectedPinnedSpritePageNames(window);
        var expectedWarmupOrder = BuildExpectedSpritePageWarmupOrder(window);
        var residentLru = GetField<LinkedList<string>>(
            window,
            "_residentSpritePageLru");

        Assert(residentBudgetBytes == ExpectedResidentSpritePageBudgetBytes,
            $"普通解码分页常驻预算必须固定为52MiB，实际 " +
            $"{residentBudgetBytes / 1024d / 1024d:F2}MiB");
        Assert(residentPages.Count == 1 &&
               residentPages.Contains(idlePageName) &&
               ReferenceEquals(
                   GetProperty<byte[]>(residentPages[idlePageName]!, "Pixels"),
                   idlePixels) &&
               GetField<long>(window, "_residentSpritePageBytes") == idlePixels.LongLength &&
               residentLru.SequenceEqual([idlePageName]),
            "首屏前只能同步常驻当前idle页，且字节账与LRU必须同时登记该页");
        Assert(pinnedPageNames.SetEquals(expectedPinnedPageNames),
            "永久pinned集合必须且只能包含单个idle页");
        Assert(warmupOrder.Length == 0 && expectedWarmupOrder.Length == 0,
            "启动warmup顺序必须为空，构造阶段只同步加载idle页");
        AssertResidentSpriteCacheAccounting(window, "首屏缓存");

        var reminderPageNames = GetField<Array>(window, "_reminderEnterFrames")
            .Cast<object>()
            .Concat(GetField<Array>(window, "_reminderHoldFrames").Cast<object>())
            .Select(frame => GetSpriteFrameInfo(frame).PageName)
            .ToHashSet(StringComparer.Ordinal);
        Assert(reminderPageNames.Count > 0 &&
               reminderPageNames.All(pageName =>
                   !pinnedPageNames.Contains(pageName) &&
                   !(bool)Invoke(
                       window,
                       "IsSpritePageProtected",
                       pageName,
                       null)!),
            "提醒页在非提醒期间不得永久pinned或被其他静态条件保护");
        SetField(window, "_isReminderActive", true);
        Assert(reminderPageNames.All(pageName =>
                !(bool)Invoke(
                    window,
                    "IsSpritePageProtected",
                    pageName,
                    null)!),
            "提醒活动本身不得固定完整序列，必须继续使用当前/下一页滚动热集");
        SetField(window, "_isReminderActive", false);
        Assert(reminderPageNames.All(pageName =>
                !(bool)Invoke(
                    window,
                    "IsSpritePageProtected",
                    pageName,
                    null)!),
            "提醒结束后必须立即解除所有提醒页的动态保护");

        var urgentPageName = pageNames
            .Where(name => !expectedPinnedPageNames.Contains(name) &&
                           !expectedWarmupOrder.Contains(name, StringComparer.Ordinal))
            .OrderBy(name => GetSpritePageByteCount(pageMap, name))
            .First();

        SetField(window, "_spritePageWarmupEnabled", true);
        Invoke(window, "ResumeSpritePageWarmup");
        Assert(GetRawField(window, "_desiredSpritePageName") is null &&
               GetRawField(window, "_spritePagePrefetchTask") is null &&
               GetField<int>(window, "_spritePageWarmupIndex") == 0,
            "空warmup顺序不得启动任何后台解码任务");

        Invoke(window, "RequestSpritePagePrefetch", urgentPageName, true);
        Assert(string.Equals(
                   GetRawField(window, "_desiredSpritePageName") as string,
                   urgentPageName,
                   StringComparison.Ordinal) &&
               GetField<bool>(window, "_desiredSpritePageUrgent") &&
               GetRawField(window, "_spritePagePrefetchTask") is Task,
            "空warmup不得阻止紧急动作页启动单个后台解码任务");

        var deadline = Stopwatch.StartNew();
        while ((GetRawField(window, "_spritePagePrefetchTask") is not null ||
                GetRawField(window, "_desiredSpritePageName") is not null ||
                GetField<int>(window, "_spritePageWarmupIndex") < warmupOrder.Length) &&
               deadline.Elapsed < TimeSpan.FromSeconds(20))
        {
            PumpDispatcher(TimeSpan.FromMilliseconds(5));
            Thread.Yield();
        }

        Assert(GetRawField(window, "_spritePagePrefetchTask") is null &&
               GetRawField(window, "_desiredSpritePageName") is null &&
               GetField<int>(window, "_spritePageWarmupIndex") == warmupOrder.Length,
            "紧急页预取必须在20秒内完成，空warmup不得追加其他页");
        var expectedResidentPageNames = new HashSet<string>(
            [idlePageName, urgentPageName],
            StringComparer.Ordinal);
        Assert(expectedResidentPageNames.SetEquals(
                   GetDictionaryEntries(residentPages)
                       .Select(entry => (string)entry.Key)),
            "紧急页必须进入缓存，按名称固定但尚未使用的wake页不得被空warmup提前加载");
        Assert(string.Equals(
                   GetField<string>(window, "_loadedSpritePageName"),
                   idlePageName,
                   StringComparison.Ordinal) &&
               ReferenceEquals(GetField<byte[]>(window, "_spritePagePixels"), idlePixels),
            "后台预热只能发布常驻数组，不能擅自切换当前显示页");

        AssertResidentSpriteCacheAccounting(window, "空warmup与紧急页预取完成");

        SetField(window, "_spritePageWarmupEnabled", false);
        SetField(window, "_desiredSpritePageName", null);
        SetField(window, "_desiredSpritePageUrgent", false);
        SetField(
            window,
            "_spritePagePrefetchGeneration",
            GetField<int>(window, "_spritePagePrefetchGeneration") + 1);
        Invoke(window, "RequestSpritePagePrefetchCancellation");
        var shutdownDeadline = Stopwatch.StartNew();
        while (GetRawField(window, "_spritePagePrefetchTask") is not null &&
               shutdownDeadline.Elapsed < TimeSpan.FromSeconds(5))
        {
            PumpDispatcher(TimeSpan.FromMilliseconds(5));
        }

        Assert(GetRawField(window, "_spritePagePrefetchTask") is null,
            "聚焦测试结束时后台预热必须可取消并干净收敛");

        // Establish two large unprotected pages, touch A after B, then add
        // further pages until pressure chooses a victim. B must be the first of
        // the pair evicted; a dictionary-only FIFO or insertion-order policy
        // would incorrectly remove A as well or keep B.
        var lruCandidates = pageNames
            .Where(name => !expectedPinnedPageNames.Contains(name) &&
                           !expectedWarmupOrder.Contains(name, StringComparer.Ordinal) &&
                           !string.Equals(name, urgentPageName, StringComparison.Ordinal))
            .OrderByDescending(name => GetSpritePageByteCount(pageMap, name))
            .ToArray();
        Assert(lruCandidates.Length >= 5,
            "LRU压力测试至少需要五个非固定、非预热动作页");
        var recentlyTouchedPageName = lruCandidates[0];
        var olderPageName = lruCandidates[1];
        LoadSpritePageForTest(window, recentlyTouchedPageName);
        LoadSpritePageForTest(window, olderPageName);
        LoadSpritePageForTest(window, idlePageName);
        LoadSpritePageForTest(window, recentlyTouchedPageName);
        LoadSpritePageForTest(window, idlePageName);

        var observedLruEviction = false;
        foreach (var pageName in lruCandidates.Skip(2))
        {
            LoadSpritePageForTest(window, pageName);
            LoadSpritePageForTest(window, idlePageName);
            AssertResidentSpriteCacheAccounting(window, $"LRU加入 {pageName}");
            if (!residentPages.Contains(olderPageName) ||
                !residentPages.Contains(recentlyTouchedPageName))
            {
                Assert(!residentPages.Contains(olderPageName) &&
                       residentPages.Contains(recentlyTouchedPageName),
                    $"LRU必须先驱逐较旧页 {olderPageName}，并保留重新触达页 " +
                    recentlyTouchedPageName);
                observedLruEviction = true;
                break;
            }
        }

        Assert(observedLruEviction,
            "52MiB普通活动压力必须实际触发一次可观察的LRU驱逐");

        // A complete click clip is intentionally larger than the ordinary
        // rolling budget. Only the currently displayed, pending and next
        // decoding pages remain protected; merely belonging to the active clip
        // must not pin every forward/reverse page.
        var activeClip = GetField<Array>(window, "_reactionClips")
            .Cast<object>()
            .MaxBy(clip => GetClipPageNames(clip)
                .Sum(pageName => GetSpritePageByteCount(pageMap, pageName)))!;
        var activeClipPages = GetClipPageNames(activeClip);
        var activeClipFrames = GetClipFrames(activeClip);
        var currentFrame = GetProperty<object>(
            activeClipFrames.GetValue(0)!,
            "Image");
        var currentPageName = GetSpriteFrameInfo(currentFrame).PageName;
        PrimeSpritePageForFrame(window, currentFrame);
        Invoke(window, "ShowStableFrame", currentFrame);
        SetField(window, "_activeClip", activeClip);
        PrimeAllClipPagesForTest(window, activeClipFrames);
        Invoke(window, "TrimResidentSpritePagesToBudget", (object?)null);
        Assert(expectedPinnedPageNames.All(residentPages.Contains) &&
               residentPages.Contains(currentPageName) &&
               activeClipPages.Any(pageName => !residentPages.Contains(pageName)),
            "普通活动必须保留固定热页与当前页，但完整active clip必须按LRU滚动而非全部固定");
        AssertResidentSpriteCacheAccounting(window, "active clip滚动页保护");

        var pendingPageName = pageNames
            .Where(name => !expectedPinnedPageNames.Contains(name) &&
                            !activeClipPages.Contains(name))
            .OrderBy(name => GetSpritePageByteCount(pageMap, name))
            .First();
        var pendingFrame = GetFirstSpriteFrameOnPage(
            window,
            pendingPageName);
        LoadSpritePageForTest(window, pendingPageName);
        SetField(window, "_pendingSpriteFrame", pendingFrame);
        var pressurePageName = pageNames
            .Where(name => !expectedPinnedPageNames.Contains(name) &&
                           !string.Equals(name, currentPageName, StringComparison.Ordinal) &&
                           !string.Equals(name, pendingPageName, StringComparison.Ordinal))
            .OrderByDescending(name => GetSpritePageByteCount(pageMap, name))
            .First();
        LoadSpritePageForTest(window, pressurePageName);
        Invoke(window, "TrimResidentSpritePagesToBudget", (object?)null);
        Assert(residentPages.Contains(currentPageName) &&
               residentPages.Contains(pendingPageName) &&
               expectedPinnedPageNames.All(residentPages.Contains),
            "滚动LRU压力不得驱逐当前、pending或固定热页");
        AssertResidentSpriteCacheAccounting(window, "当前与pending滚动页保护");

        SetField(window, "_pendingSpriteFrame", null);
        SetField(window, "_activeClip", null);
        SetField(window, "_activeFrameIndex", -1);
        SetField(window, "_activeClipStartedTimestamp", 0L);
        SetField(window, "_activeFrameDeadlineTimestamp", 0L);
        Invoke(window, "ClearDeferredActiveClipClock");
        var idleFrame = GetField<object>(window, "_idleFrame");
        PrimeSpritePageForFrame(window, idleFrame);
        Invoke(window, "ShowStableFrame", idleFrame);
        Invoke(window, "TrimResidentSpritePagesToBudget", (object?)null);
        SetField(window, "_failedSpritePageName", null);
        Assert(expectedPinnedPageNames.All(residentPages.Contains),
            "压力测试清理后固定热页仍必须常驻");
        AssertResidentSpriteCacheAccounting(window, "LRU压力测试清理");
    }

    private static void AssertSpritePagePrefetchIdleTrimDeferralContract(
        MainWindow window)
    {
        WaitForSpritePagePrefetchToSettle(window);
        ResetSpritePageCollectionTestState(window);

        var pageMap = GetField<IDictionary>(window, "_spritePages");
        var residentPages = GetField<IDictionary>(window, "_residentSpritePages");
        var idleFrame = GetField<object>(window, "_idleFrame");
        var idlePageName = GetSpriteFrameInfo(idleFrame).PageName;
        var idleTrimTimer = GetField<DispatcherTimer>(
            window,
            "_spritePageIdleTrimTimer");
        var prefetchDispatchTimer = GetField<DispatcherTimer>(
            window,
            "_spritePagePrefetchDispatchTimer");
        var idleTrimGracePeriod = (TimeSpan)(typeof(MainWindow).GetField(
                "SpritePageIdleTrimGracePeriod",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var sentinelInterval = TimeSpan.FromSeconds(7);

        Assert(idleTrimGracePeriod == TimeSpan.FromSeconds(20),
            "分页请求idle裁剪回归必须保留20秒正式宽限期");

        var coldPageNames = GetDictionaryEntries(pageMap)
            .Select(entry => (string)entry.Key)
            .Where(pageName => !string.Equals(
                                   pageName,
                                   idlePageName,
                                   StringComparison.Ordinal) &&
                               !residentPages.Contains(pageName))
            .OrderBy(pageName => GetSpritePageByteCount(pageMap, pageName))
            .Take(2)
            .ToArray();
        Assert(coldPageNames.Length == 2,
            "分页请求idle裁剪回归至少需要两个未驻留冷页");
        var deferredPageName = coldPageNames[0];
        var directPageName = coldPageNames[1];
        var deferredFrame = GetFirstSpriteFrameOnPage(window, deferredPageName);

        void ArmSentinel()
        {
            idleTrimTimer.Stop();
            idleTrimTimer.Interval = sentinelInterval;
            idleTrimTimer.Start();
        }

        bool SentinelIsUntouched() =>
            idleTrimTimer.IsEnabled &&
            idleTrimTimer.Interval == sentinelInterval;

        SetField(window, "_pendingSpriteFrame", null);
        SetField(window, "_pendingSpriteFrameBlendDuration", TimeSpan.Zero);
        SetField(window, "_desiredSpritePageName", null);
        SetField(window, "_desiredSpritePageUrgent", false);
        SetField(window, "_renderDeferredSpritePageName", null);
        SetField(window, "_renderDeferredSpritePageUrgent", false);
        SetField(window, "_renderDeferredSpritePageCancellation", false);
        prefetchDispatchTimer.Stop();

        ArmSentinel();
        Invoke(window, "RequestSpritePagePrefetch", idlePageName, true);
        Assert(SentinelIsUntouched() &&
               GetRawField(window, "_spritePagePrefetchTask") is null &&
               GetRawField(window, "_desiredSpritePageName") is null,
            "resident命中不得重启idle裁剪宽限，也不得创建分页请求");

        SetField(window, "_pendingSpriteFrame", deferredFrame);
        Invoke(window, "RequestSpritePagePrefetch", deferredPageName, false);
        Assert(SentinelIsUntouched() &&
               GetRawField(window, "_spritePagePrefetchTask") is null &&
               GetRawField(window, "_desiredSpritePageName") is null,
            "pending忙碌时拒绝的非紧急请求不得重启idle裁剪宽限");
        SetField(window, "_pendingSpriteFrame", null);

        SetField(window, "_desiredSpritePageName", deferredPageName);
        SetField(window, "_desiredSpritePageUrgent", false);
        Invoke(window, "RequestSpritePagePrefetch", deferredPageName, true);
        Assert(SentinelIsUntouched() &&
               GetField<bool>(window, "_desiredSpritePageUrgent") &&
               GetRawField(window, "_spritePagePrefetchTask") is null,
            "重复desired只允许提升urgent，不得重启idle裁剪宽限或重复解码");
        SetField(window, "_desiredSpritePageName", null);
        SetField(window, "_desiredSpritePageUrgent", false);

        SetField(window, "_isInsideVisualRenderingCallback", true);
        try
        {
            Invoke(window, "RequestSpritePagePrefetch", deferredPageName, true);
        }
        finally
        {
            SetField(window, "_isInsideVisualRenderingCallback", false);
        }

        Assert(SentinelIsUntouched() &&
               string.Equals(
                   GetRawField(window, "_renderDeferredSpritePageName") as string,
                   deferredPageName,
                   StringComparison.Ordinal) &&
               GetField<bool>(window, "_renderDeferredSpritePageUrgent") &&
               prefetchDispatchTimer.IsEnabled &&
               GetRawField(window, "_spritePagePrefetchTask") is null,
            "Rendering冷页请求只能发布dispatcher信号，不能在composition内重启idle宽限");

        Invoke(window, "SpritePagePrefetchDispatchTimer_Tick", null, EventArgs.Empty);
        Assert(idleTrimTimer.IsEnabled &&
               idleTrimTimer.Interval == idleTrimGracePeriod &&
               GetRawField(window, "_renderDeferredSpritePageName") is null &&
               !prefetchDispatchTimer.IsEnabled &&
               GetRawField(window, "_spritePagePrefetchTask") is Task,
            "dispatcher真正接管Rendering冷页请求时必须且只能此时重设20秒idle宽限");
        WaitForSpritePagePrefetchToSettle(window);
        Assert(residentPages.Contains(deferredPageName),
            "dispatcher接管的冷页请求必须完成并进入resident缓存");

        ArmSentinel();
        Invoke(window, "RequestSpritePagePrefetch", directPageName, true);
        Assert(idleTrimTimer.IsEnabled &&
               idleTrimTimer.Interval == idleTrimGracePeriod &&
               GetRawField(window, "_spritePagePrefetchTask") is Task,
            "新的非Rendering冷页请求必须在真正接收时重设20秒idle宽限");
        WaitForSpritePagePrefetchToSettle(window);
        Assert(residentPages.Contains(directPageName),
            "新的非Rendering冷页请求必须完成并进入resident缓存");

        Invoke(window, "StopIdleSpritePageTrim");
        PrimeSpritePageForFrame(window, idleFrame);
        Invoke(window, "ShowStableFrame", idleFrame);
        Invoke(window, "TrimResidentSpritePagesToIdleTarget");
        SetField(window, "_pendingSpriteFrame", null);
        SetField(window, "_pendingSpriteFrameBlendDuration", TimeSpan.Zero);
        SetField(window, "_desiredSpritePageName", null);
        SetField(window, "_desiredSpritePageUrgent", false);
        SetField(window, "_renderDeferredSpritePageName", null);
        SetField(window, "_renderDeferredSpritePageUrgent", false);
        prefetchDispatchTimer.Stop();
        ResetSpritePageCollectionTestState(window);
        AssertResidentSpriteCacheAccounting(window, "分页请求idle宽限去重");
    }

    private static void AssertIdleSpritePageTrimContract(MainWindow window)
    {
        WaitForSpritePagePrefetchToSettle(window);
        PrepareIdleSpriteCollectionBaseline(window);
        ResetSpritePageCollectionTestState(window);

        var pageMap = GetField<IDictionary>(window, "_spritePages");
        var residentPages = GetField<IDictionary>(window, "_residentSpritePages");
        var idleTargetBytes = (long)(typeof(MainWindow).GetField(
                "SpritePageIdleResidentTargetBytes",
                StaticFlags)!.GetValue(null) ?? 0L);
        var residentBudgetBytes = (long)(typeof(MainWindow).GetField(
                "SpritePageResidentBudgetBytes",
                StaticFlags)!.GetValue(null) ?? 0L);
        var idleTrimGracePeriod = (TimeSpan)(typeof(MainWindow).GetField(
                "SpritePageIdleTrimGracePeriod",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var idleTrimRetryDelay = (TimeSpan)(typeof(MainWindow).GetField(
                "SpritePageIdleTrimRetryDelay",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        Assert(idleTargetBytes == ExpectedIdleSpritePageTargetBytes &&
               residentBudgetBytes == ExpectedResidentSpritePageBudgetBytes &&
               idleTrimGracePeriod == TimeSpan.FromSeconds(20) &&
               idleTrimRetryDelay == TimeSpan.FromSeconds(5),
            "动作结束后的idle热集目标必须是12MiB，普通活动软预算必须保持52MiB，" +
            "idle裁剪必须等待20秒且忙碌时5秒后重试");

        var idleFrame = GetField<object>(window, "_idleFrame");
        var idlePageName = GetSpriteFrameInfo(idleFrame).PageName;
        PrimeSpritePageForFrame(window, idleFrame);
        Invoke(window, "ShowStableFrame", idleFrame);
        foreach (var wakeFrame in GetField<Array>(window, "_wakeFrames")
                     .Cast<object>())
        {
            PrimeSpritePageForFrame(window, wakeFrame);
        }

        PrimeSpritePageForFrame(window, idleFrame);
        Invoke(window, "ShowStableFrame", idleFrame);
        var pinnedPageNames = GetExpectedPinnedSpritePageNames(window);
        var protectedPageName = GetDictionaryEntries(pageMap)
            .Select(entry => (string)entry.Key)
            .Where(pageName => !pinnedPageNames.Contains(pageName))
            .OrderBy(pageName => GetSpritePageByteCount(pageMap, pageName))
            .First();
        var protectedFrame = GetFirstSpriteFrameOnPage(
            window,
            protectedPageName);

        foreach (var pageName in GetDictionaryEntries(pageMap)
                     .Select(entry => (string)entry.Key)
                     .Where(pageName => !pinnedPageNames.Contains(pageName) &&
                                        !string.Equals(
                                            pageName,
                                            protectedPageName,
                                            StringComparison.Ordinal))
                     .OrderByDescending(pageName =>
                         GetSpritePageByteCount(pageMap, pageName)))
        {
            if (GetField<long>(window, "_residentSpritePageBytes") >
                idleTargetBytes + 12L * 1024L * 1024L)
            {
                break;
            }

            LoadSpritePageForTest(window, pageName);
        }

        LoadSpritePageForTest(window, protectedPageName);
        PrimeSpritePageForFrame(window, idleFrame);
        Invoke(window, "ShowStableFrame", idleFrame);
        SetField(window, "_pendingSpriteFrame", protectedFrame);
        SetField(
            window,
            "_pendingSpriteFrameBlendDuration",
            TimeSpan.FromMilliseconds(120));

        var residentBytesBefore = GetField<long>(
            window,
            "_residentSpritePageBytes");
        var collectionDebtBefore = GetField<long>(
            window,
            "_spritePageEvictedBytesSinceCollection");
        var spritePageBufferPool = GetRawField(
            window,
            "_spritePageBufferPool")
            ?? throw new InvalidOperationException(
                "MainWindow 缺少 sprite 页像素复用池");
        var poolAllocatedBefore = GetProperty<long>(
            spritePageBufferPool,
            "AllocatedBytes");
        var poolRentedBefore = GetProperty<long>(
            spritePageBufferPool,
            "RentedBytes");
        var poolFreeBefore = GetProperty<long>(
            spritePageBufferPool,
            "FreeBytes");
        var poolHardBudget = GetProperty<long>(
            spritePageBufferPool,
            "HardBudgetBytes");
        Assert(poolHardBudget == ExpectedRoamSpritePageBudgetBytes &&
               poolAllocatedBefore >= residentBytesBefore &&
               poolAllocatedBefore > idleTargetBytes,
            "the reusable pool hard budget must preserve the 92 MiB roaming " +
            "ceiling, and this test must establish total storage above idle.");
        Assert(residentBytesBefore > idleTargetBytes,
            "idle回收测试必须先建立超过12MiB的真实解码页缓存压力");
        var protectedPageNames = pinnedPageNames
            .Append(idlePageName)
            .Append(protectedPageName)
            .ToHashSet(StringComparer.Ordinal);
        Assert(protectedPageNames.All(pageMap.Contains),
            "idle与pending测试页必须都来自当前图集");

        Invoke(window, "TrimResidentSpritePagesToIdleTarget");
        var residentBytesAfter = GetField<long>(
            window,
            "_residentSpritePageBytes");
        var poolAllocatedAfter = GetProperty<long>(
            spritePageBufferPool,
            "AllocatedBytes");
        var poolRentedAfter = GetProperty<long>(
            spritePageBufferPool,
            "RentedBytes");
        var poolFreeAfter = GetProperty<long>(
            spritePageBufferPool,
            "FreeBytes");
        var returnedResidentBytes =
            residentBytesBefore - residentBytesAfter;
        var discardedPoolBytes =
            poolAllocatedBefore - poolAllocatedAfter;
        Assert(residentBytesAfter <= residentBytesBefore &&
               protectedPageNames.All(residentPages.Contains),
            "12MiB裁剪不得丢失永久、当前或pending保护页；若保护页较小可以继续收敛到目标内");
        Assert(poolAllocatedAfter == poolRentedAfter + poolFreeAfter &&
               poolAllocatedAfter >= residentBytesAfter &&
               poolAllocatedAfter <= Math.Max(idleTargetBytes, residentBytesAfter),
            "idle trim遇到受保护pending页时只能保留目标内可复用数组；" +
            "若受保护租出页本身超标则不得再保留free数组。");
        Assert(poolRentedBefore - poolRentedAfter ==
                   returnedResidentBytes &&
               poolFreeAfter - poolFreeBefore ==
                   returnedResidentBytes - discardedPoolBytes &&
               discardedPoolBytes > 0 &&
               GetField<long>(
                   window,
                   "_spritePageEvictedBytesSinceCollection") ==
                   collectionDebtBefore + discardedPoolBytes,
            "idle淘汰必须把resident像素数组归还复用池；只有池为收敛预算真正丢弃的数组才累计Gen2债");
        AssertResidentSpriteCacheAccounting(window, "12MiB idle回收与pending保护");

        SetField(window, "_pendingSpriteFrame", null);
        SetField(window, "_pendingSpriteFrameBlendDuration", TimeSpan.Zero);
        Invoke(window, "TrimResidentSpritePagesToIdleTarget");
        Assert(GetField<long>(window, "_residentSpritePageBytes") <= idleTargetBytes &&
               GetProperty<long>(spritePageBufferPool, "AllocatedBytes") <= idleTargetBytes &&
               pinnedPageNames.All(residentPages.Contains),
            "pending保护释放后必须立即收敛到12MiB目标并保留唯一pinned idle页");
        foreach (var pageName in GetDictionaryEntries(pageMap)
                     .Select(entry => (string)entry.Key)
                     .Where(pageName => !pinnedPageNames.Contains(pageName))
                     .OrderByDescending(pageName =>
                         GetSpritePageByteCount(pageMap, pageName)))
        {
            if (GetField<long>(window, "_residentSpritePageBytes") >
                idleTargetBytes + 12L * 1024L * 1024L)
            {
                break;
            }

            LoadSpritePageForTest(window, pageName);
        }

        PrimeSpritePageForFrame(window, idleFrame);
        Invoke(window, "ShowStableFrame", idleFrame);
        var timerResidentBytesBefore = GetField<long>(
            window,
            "_residentSpritePageBytes");
        var timerPoolAllocatedBefore = GetProperty<long>(
            spritePageBufferPool,
            "AllocatedBytes");
        var idleTrimTimer = GetField<DispatcherTimer>(
            window,
            "_spritePageIdleTrimTimer");
        Assert(timerResidentBytesBefore > idleTargetBytes,
            "idle timer测试必须重新建立超过12MiB的resident压力");

        Invoke(window, "RequestIdleSpritePageTrim", false);
        Assert(idleTrimTimer.IsEnabled &&
               idleTrimTimer.Interval == idleTrimGracePeriod &&
               GetField<long>(window, "_residentSpritePageBytes") ==
               timerResidentBytesBefore &&
               GetProperty<long>(spritePageBufferPool, "AllocatedBytes") ==
               timerPoolAllocatedBefore,
            "请求idle裁剪只能启动20秒宽限timer，不能立即淘汰resident页或池数组");

        SetField(window, "_desiredSpritePageName", protectedPageName);
        Invoke(window, "SpritePageIdleTrimTimer_Tick", null, EventArgs.Empty);
        Assert(idleTrimTimer.IsEnabled &&
               idleTrimTimer.Interval == idleTrimRetryDelay &&
               GetField<long>(window, "_residentSpritePageBytes") ==
               timerResidentBytesBefore &&
               GetProperty<long>(spritePageBufferPool, "AllocatedBytes") ==
               timerPoolAllocatedBefore,
            "idle timer到点时若仍有分页活动，只能5秒后重试，不能执行裁剪");

        SetField(window, "_desiredSpritePageName", null);
        SetField(window, "_desiredSpritePageUrgent", false);
        Assert((bool)Invoke(window, "CanRunIdleSpritePageCollection")!,
            "清除分页活动后必须恢复idle裁剪门禁");
        Invoke(window, "SpritePageIdleTrimTimer_Tick", null, EventArgs.Empty);
        var timerResidentBytesAfter = GetField<long>(
            window,
            "_residentSpritePageBytes");
        var timerPoolAllocatedAfter = GetProperty<long>(
            spritePageBufferPool,
            "AllocatedBytes");
        Assert(!idleTrimTimer.IsEnabled &&
               idleTrimTimer.Interval == idleTrimGracePeriod &&
               timerResidentBytesAfter <= idleTargetBytes &&
               timerPoolAllocatedAfter <= idleTargetBytes &&
               pinnedPageNames.All(residentPages.Contains),
            "pending保护释放且分页活动结束后，idle timer tick必须裁到12MiB目标，" +
            "恢复20秒宽限并只保留永久idle页");
        Console.WriteLine(
            $"[METRIC] idle sprite cache: resident " +
            $"{timerResidentBytesBefore / (1024d * 1024d):F2}->" +
            $"{timerResidentBytesAfter / (1024d * 1024d):F2} MiB, pool " +
            $"{timerPoolAllocatedBefore / (1024d * 1024d):F2}->" +
            $"{timerPoolAllocatedAfter / (1024d * 1024d):F2} MiB");

        // The preceding generic idle-target scenario may retain a free
        // best-fit array inside its 12 MiB target. Remove only that test slack
        // so the roaming fixture starts from the exact idle resident/pool
        // baseline used by --memory-profile.
        Invoke(
            window,
            "TrimSpritePageBufferPoolToTarget",
            timerResidentBytesAfter);
        ResetSpritePageCollectionTestState(window);
        SetField(window, "_edgeRoamPreloadRequested", true);
        var roamPageNames = new[]
            {
                "_roamBoardingFrames",
                "_roamFlightFrames",
                "_roamWaveFrames"
            }
            .SelectMany(fieldName =>
                GetField<Array>(window, fieldName).Cast<object>())
            .Select(frame => GetSpriteFrameInfo(frame).PageName)
            .Distinct(StringComparer.Ordinal)
            .OrderBy(static pageName => pageName, StringComparer.Ordinal)
            .ToArray();
        foreach (var pageName in roamPageNames)
        {
            LoadSpritePageForTest(window, pageName);
        }

        Invoke(window, "TrimReusableSpritePageBuffersForReadyRoam");

        var loadedRoamPageName = GetField<string>(
            window,
            "_loadedSpritePageName");
        Invoke(
            window,
            "ShowStableFrame",
            GetFirstSpriteFrameOnPage(window, loadedRoamPageName));

        var roamResidentBytesBefore = GetField<long>(
            window,
            "_residentSpritePageBytes");
        var roamPoolAllocatedBefore = GetProperty<long>(
            spritePageBufferPool,
            "AllocatedBytes");
        var roamResidentNamesBefore = GetDictionaryEntries(residentPages)
            .Select(entry => (string)entry.Key)
            .ToHashSet(StringComparer.Ordinal);
        Assert(roamResidentBytesBefore == ExpectedActiveRoamSpriteResidentBytes &&
               roamPoolAllocatedBefore == ExpectedActiveRoamSpriteResidentBytes,
            "The roaming completion fixture must establish the measured " +
            "exact resident/pool hot set before testing immediate release.");

        SetField(window, "_edgeRoamPreloadRequested", false);
        SetField(window, "_isEdgeRoaming", true);
        SetField(
            window,
            "_edgeRoamPhase",
            GetNestedEnum("EdgeRoamPhase", "Traveling"));
        SetField(window, "_edgeRoamStopScheduleNext", false);
        SetField(window, "_edgeRoamStopInterrupted", false);
        SetField(window, "_openTodoAfterEdgeRoamStopRequested", false);
        SetField(window, "_pointerDown", false);
        SetField(window, "_dragInteractionActive", false);
        SetField(window, "_isInsideVisualRenderingCallback", true);
        try
        {
            Invoke(window, "CompleteEdgeRoamStop", true);
            Assert(!GetField<bool>(window, "_isEdgeRoaming") &&
                   idleTrimTimer.IsEnabled &&
                   idleTrimTimer.Interval == TimeSpan.Zero &&
                   GetField<long>(window, "_residentSpritePageBytes") ==
                   roamResidentBytesBefore &&
                   GetProperty<long>(spritePageBufferPool, "AllocatedBytes") ==
                   roamPoolAllocatedBefore &&
                   roamResidentNamesBefore.SetEquals(
                       GetDictionaryEntries(residentPages)
                           .Select(entry => (string)entry.Key)),
                "Completing roaming inside Rendering may only post a " +
                "zero-delay idle trim; it must not evict resident pages or " +
                "mutate the LRU-backed resident set in the render callback.");
        }
        finally
        {
            SetField(window, "_isInsideVisualRenderingCallback", false);
        }

        Assert((bool)Invoke(window, "CanRunIdleSpritePageCollection")!,
            "Roaming completion must restore the complete idle trim gate.");
        Invoke(window, "SpritePageIdleTrimTimer_Tick", null, EventArgs.Empty);
        var roamResidentBytesAfter = GetField<long>(
            window,
            "_residentSpritePageBytes");
        var roamPoolAllocatedAfter = GetProperty<long>(
            spritePageBufferPool,
            "AllocatedBytes");
        Console.WriteLine(
            $"[METRIC] roam completion cache: resident " +
            $"{roamResidentBytesBefore / (1024d * 1024d):F2}->" +
            $"{roamResidentBytesAfter / (1024d * 1024d):F2} MiB, pool " +
            $"{roamPoolAllocatedBefore / (1024d * 1024d):F2}->" +
            $"{roamPoolAllocatedAfter / (1024d * 1024d):F2} MiB");
        Assert(!idleTrimTimer.IsEnabled &&
               idleTrimTimer.Interval == idleTrimGracePeriod &&
               roamResidentBytesAfter == ExpectedIdleSpriteResidentBytes &&
               roamPoolAllocatedAfter == ExpectedIdleSpriteResidentBytes &&
               pinnedPageNames.All(residentPages.Contains),
            "The dispatcher idle-trim tick after roaming must reduce the " +
            "exact resident/pool hot set to the single exact-sized idle " +
            "page without changing the 12 MiB retention target.");
        ResetSpritePageCollectionTestState(window);
    }

    private static void AssertIdleSpritePageCollectionGateContract(
        MainWindow window)
    {
        WaitForSpritePagePrefetchToSettle(window);
        PrepareIdleSpriteCollectionBaseline(window);
        ResetSpritePageCollectionTestState(window);
        Assert((bool)Invoke(window, "CanRunIdleSpritePageCollection")!,
            "完全空闲的桌宠必须允许进入证据驱动Gen2回收门禁");

        var arbitraryPageName = GetDictionaryEntries(
                GetField<IDictionary>(window, "_spritePages"))
            .Select(entry => (string)entry.Key)
            .First(pageName => !string.Equals(
                pageName,
                GetField<string>(window, "_loadedSpritePageName"),
                StringComparison.Ordinal));
        var arbitraryFrame = GetFirstSpriteFrameOnPage(window, arbitraryPageName);
        var completedPageTask = CreateCompletedSpritePageLoadTask(
            window,
            arbitraryPageName);
        var reactionClip = GetField<Array>(window, "_reactionClips").GetValue(0)!;
        var blockers = new (string FieldName, object Value, string Scenario)[]
        {
            ("_isClosing", true, "关闭"),
            ("_isInsideVisualRenderingCallback", true, "Rendering回调"),
            ("_activeClip", reactionClip, "动作"),
            ("_isReminderActive", true, "提醒"),
            ("_dragInteractionActive", true, "拖动"),
            ("_pointerDown", true, "按下拖动前态"),
            ("_isPetSizeTransitioning", true, "缩放过渡"),
            ("_isPetSizePreviewSessionActive", true, "缩放预览"),
            ("_isPetSizeAdjustmentActive", true, "缩放输入"),
            ("_petSizeTargetUpdatePending", true, "缩放目标待提交"),
            ("_petSizeCommitPending", true, "缩放保存待提交"),
            ("_isFrameBlending", true, "帧过渡"),
            ("_isPillowBreathing", true, "枕头呼吸"),
            ("_edgeRoamPreloadRequested", true, "绕屏预加载"),
            ("_isEdgeRoaming", true, "绕屏动作"),
            ("_bubbleMode", GetNestedEnum("BubbleMode", "Todo"), "Todo窗口"),
            ("_pendingSpriteFrame", arbitraryFrame, "待显示冷页"),
            ("_spritePagePrefetchTask", completedPageTask, "分页预取"),
            ("_desiredSpritePageName", arbitraryPageName, "分页请求"),
            ("_renderDeferredSpritePageName", arbitraryPageName, "Rendering延迟请求"),
            ("_renderDeferredSpritePageFailureName", arbitraryPageName, "Rendering延迟失败"),
            ("_renderDeferredSpritePageCancellation", true, "Rendering延迟取消"),
            ("_residentSpritePageTrimPending", true, "Rendering延迟trim"),
            ("_upcomingReminderPreloadPageName", arbitraryPageName, "到期前提醒图集预取")
        };

        foreach (var blocker in blockers)
        {
            var originalValue = GetRawField(window, blocker.FieldName);
            SetField(window, blocker.FieldName, blocker.Value);
            Assert(!(bool)Invoke(window, "CanRunIdleSpritePageCollection")!,
                $"{blocker.Scenario}期间必须禁止发起后台Gen2回收");
            SetField(window, blocker.FieldName, originalValue);
            Assert((bool)Invoke(window, "CanRunIdleSpritePageCollection")!,
                $"清除{blocker.Scenario}阻塞后空闲门禁必须恢复");
        }

        var edgeFrames = GetField<Array>(window, "_edgeLeftFrames");
        var edgeRestFrame = edgeFrames.GetValue(edgeFrames.Length - 1)!;
        var edgeHoldTimer = GetField<DispatcherTimer>(
            window,
            "_edgePeekHoldTimer");
        var idleFrameBeforeEdgeGate = GetRawField(window, "_currentSpriteFrame");
        SetField(window, "_edgeDock", GetNestedEnum("EdgeDock", "Left"));
        SetField(window, "_edgePeekFrameIndex", edgeFrames.Length - 1);
        SetField(window, "_currentSpriteFrame", edgeRestFrame);
        Assert(!(bool)Invoke(window, "CanRunIdleSpritePageCollection")!,
            "边缘探头运动段必须阻止后台Gen2回收");
        edgeHoldTimer.Interval = TimeSpan.FromSeconds(5);
        edgeHoldTimer.Start();
        Assert((bool)Invoke(window, "CanRunIdleSpritePageCollection")!,
            "边缘探头的稳定保持段必须允许空闲缓存收缩，不能永久保留动作高水位");
        foreach (var edgePageName in edgeFrames.Cast<object>()
                     .Select(frame => GetSpriteFrameInfo(frame).PageName)
                     .Distinct(StringComparer.Ordinal))
        {
            Assert((bool)Invoke(
                       window,
                       "IsSpritePageProtected",
                       edgePageName,
                       (object?)null)!,
                $"静止探头收缩期间必须保护完整边缘序列页：{edgePageName}");
        }

        edgeHoldTimer.Stop();
        SetField(window, "_edgeDock", GetNestedEnum("EdgeDock", "None"));
        SetField(window, "_edgePeekFrameIndex", 0);
        SetField(window, "_currentSpriteFrame", idleFrameBeforeEdgeGate);
        Assert((bool)Invoke(window, "CanRunIdleSpritePageCollection")!,
            "退出边缘探头后空闲回收门禁必须恢复");

        var automaticTimer = GetField<DispatcherTimer>(window, "_automaticTimer");
        Invoke(window, "StartPillowBreathing");
        Assert(GetField<bool>(window, "_isPillowBreathing") &&
               GetField<long>(window, "_pillowBreathingDueTimestamp") >
                   Stopwatch.GetTimestamp() &&
               !(bool)Invoke(window, "CanRunIdleSpritePageCollection")!,
            "真实枕头待机占位期间必须阻止Gen2回收");
        Invoke(window, "StopPillowBreathing");
        Assert(!GetField<bool>(window, "_isPillowBreathing") &&
               GetField<long>(window, "_pillowBreathingDueTimestamp") == 0 &&
               !automaticTimer.IsEnabled &&
               (bool)Invoke(window, "CanRunIdleSpritePageCollection")!,
            "停止枕头待机必须清理timer并恢复空闲Gen2门禁");

        var thresholdBytes = (long)(typeof(MainWindow).GetField(
                "SpritePageCollectionThresholdBytes",
                StaticFlags)!.GetValue(null) ?? 0L);
        var collectionDelay = (TimeSpan)(typeof(MainWindow).GetField(
                "SpritePageCollectionDelay",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var retryDelay = (TimeSpan)(typeof(MainWindow).GetField(
                "SpritePageCollectionRetryDelay",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var minimumInterval = (TimeSpan)(typeof(MainWindow).GetField(
                "MinimumSpritePageCollectionInterval",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var collectionTimer = GetField<DispatcherTimer>(
            window,
            "_spritePageCollectionTimer");
        Assert(thresholdBytes == ExpectedSpritePageCollectionThresholdBytes &&
               collectionDelay == TimeSpan.FromSeconds(1) &&
               retryDelay == TimeSpan.FromSeconds(5) &&
               minimumInterval == TimeSpan.FromSeconds(30),
            "idle Gen2门禁必须保持8MiB阈值、1秒延迟、5秒忙重试与30秒最短间隔");

        var naturalGeneration = GC.CollectionCount(GC.MaxGeneration);
        SetField(window, "_spritePageEvictedBytesSinceCollection", thresholdBytes);
        SetField(
            window,
            "_lastObservedSpritePageCollectionGeneration",
            naturalGeneration - 1);
        SetField(window, "_lastSpritePageCollectionTimestamp", 0L);
        Invoke(window, "ObserveNaturalSpritePageCollection");
        Assert(GetField<int>(
                   window,
                   "_lastObservedSpritePageCollectionGeneration") ==
                   naturalGeneration &&
               GetField<long>(
                   window,
                   "_spritePageEvictedBytesSinceCollection") ==
                   thresholdBytes &&
               GetField<long>(
                   window,
                   "_lastSpritePageCollectionTimestamp") == 0L,
            "普通自然Gen2不保证LOH压缩，必须保留分页淘汰债务直到显式idle CompactOnce完成");

        SetField(
            window,
            "_spritePageEvictedBytesSinceCollection",
            thresholdBytes - 1);
        Invoke(window, "ScheduleSpritePageCollectionIfNeeded");
        Assert(!collectionTimer.IsEnabled,
            "累计淘汰不足8MiB时不得启动Gen2 timer");

        SetField(window, "_spritePageEvictedBytesSinceCollection", thresholdBytes);
        SetField(window, "_lastSpritePageCollectionTimestamp", 0L);
        Invoke(window, "ScheduleSpritePageCollectionIfNeeded");
        Assert(collectionTimer.IsEnabled && collectionTimer.Interval == collectionDelay,
            "累计淘汰达到8MiB且完全空闲时必须先延迟1秒再评估Gen2");
        collectionTimer.Stop();

        SetField(
            window,
            "_lastSpritePageCollectionTimestamp",
            Stopwatch.GetTimestamp());
        Invoke(window, "ScheduleSpritePageCollectionIfNeeded");
        Assert(collectionTimer.IsEnabled &&
               collectionTimer.Interval >= TimeSpan.FromSeconds(29) &&
               collectionTimer.Interval <= minimumInterval,
            "上次请求后30秒内必须按剩余时间节流，不得每个动作都请求Gen2");
        collectionTimer.Stop();

        SetField(window, "_lastSpritePageCollectionTimestamp", 0L);
        SetField(window, "_spritePageCollectionInProgress", false);
        SetField(window, "_activeClip", reactionClip);
        Invoke(window, "SpritePageCollectionTimer_Tick", null, EventArgs.Empty);
        Assert(collectionTimer.IsEnabled &&
               collectionTimer.Interval == retryDelay &&
               !GetField<bool>(window, "_spritePageCollectionInProgress") &&
               GetField<long>(window, "_lastSpritePageCollectionTimestamp") == 0 &&
               GetField<long>(window, "_spritePageEvictedBytesSinceCollection") ==
               thresholdBytes,
            "timer到点若动作仍忙，只能5秒后重试，不能发起GC或扣除债务");
        SetField(window, "_activeClip", null);
        collectionTimer.Stop();

        SetField(
            window,
            "_spritePageEvictedBytesSinceCollection",
            thresholdBytes - 1);
        Invoke(window, "SpritePageCollectionTimer_Tick", null, EventArgs.Empty);
        Assert(!collectionTimer.IsEnabled &&
               !GetField<bool>(window, "_spritePageCollectionInProgress") &&
               GetField<long>(window, "_lastSpritePageCollectionTimestamp") == 0,
            "timer到点时债务低于8MiB必须直接退出，不能发起GC");

        ResetSpritePageCollectionTestState(window);
    }

