               startRoamPreload.Contains(
                   "EdgeRoamPreloadLeadTime",
                   StringComparison.Ordinal) &&
               continueRoamPreload.Contains(
                   "_roamBoardingFrames",
                   StringComparison.Ordinal) &&
               continueRoamPreload.Contains(
                   "_roamFlightFrames",
