               isPageProtected.Contains("_roamFlightFrames", StringComparison.Ordinal) &&
               failedPage.Contains("StopEdgeRoaming(", StringComparison.Ordinal) &&
               failedPage.Contains("immediate: true", StringComparison.Ordinal),
            "巡游活动时不得触发空闲Gen2；缓存只在活动期保护boarding/flight所需分页，" +
            "冷页失败必须立即安全停止巡游而不能永久忙等、重复烘焙或闪回旧帧");
    }

    private static void AssertAbsoluteTimelineMathContract(MainWindow window)
    {
        var source = File.ReadAllText(FindWorkspaceFile("MainWindow.xaml.cs"));
        var playbackSpeedField = typeof(MainWindow).GetField(
            "AnimationPlaybackSpeed",
            StaticFlags) ?? throw new InvalidOperationException(
            "找不到代码级动画速度常量 AnimationPlaybackSpeed");
        var playbackSpeed = Convert.ToDouble(
            playbackSpeedField.GetRawConstantValue(),
            System.Globalization.CultureInfo.InvariantCulture);
        Assert(playbackSpeedField.IsLiteral &&
               !playbackSpeedField.IsInitOnly &&
               playbackSpeed == 1.25d,
            $"动画速度必须是无需设置迁移的代码常量1.25，实际 {playbackSpeed:F3}");
        Assert(typeof(AppSettings).GetProperty(
                   "AnimationPlaybackSpeed",
                   InstanceFlags) is null,
            "动画速度不得写入AppSettings或设置JSON，修改代码常量后重新编译即可");
        var todoXaml = File.ReadAllText(FindWorkspaceFile("TodoWindow.xaml"));
        Assert(!todoXaml.Contains("AnimationPlaybackSpeed", StringComparison.Ordinal) &&
               !todoXaml.Contains("AnimationSpeedSlider", StringComparison.Ordinal),
            "待办窗口不得增加动画速度滑块或持久化入口");
        var authoredSixtyFpsInterval = TimeSpan.FromTicks(
            TimeSpan.TicksPerSecond / 60);
        var effectiveMotionFrameTicks =
            ToProductionCharacterAnimationTicks(authoredSixtyFpsInterval);
        var effectiveEdgeFullyPeekedTicks =
            ToProductionStopwatchTicks(TimeSpan.FromMilliseconds(650));
        var edgeRestHold = (TimeSpan)InvokeStatic(
            typeof(MainWindow),
            "GetEdgePeekRestHoldDuration",
            ExpectedEdgePeekFrameCount)!;
        var effectiveEdgeRestTicks =
            ToProductionStopwatchTicks(edgeRestHold);
        var effectiveReactionEndpointTicks =
            ToProductionCharacterAnimationTicks(
                TimeSpan.FromMilliseconds(1875));
        AssertClose(
            StopwatchTicksToMilliseconds(effectiveMotionFrameTicks),
            1000d / 60d / playbackSpeed,
            "1.25倍代码速度必须把基础60fps运行hold缩放到约13.333ms");
        AssertClose(
            StopwatchTicksToMilliseconds(effectiveEdgeFullyPeekedTicks),
            650d,
            "边缘开心探头必须独立保持650ms，不受全局1.25倍点击动作速度影响");
        AssertClose(
            StopwatchTicksToMilliseconds(effectiveEdgeRestTicks),
            edgeRestHold.TotalMilliseconds,
            "边缘害羞缩回休息必须独立保持800ms，不受全局1.25倍点击动作速度影响");
        AssertClose(
            StopwatchTicksToMilliseconds(effectiveReactionEndpointTicks),
            1500d,
            "the cute endpoint must remain visible one second longer");
        Assert(source.Contains("CompositionTarget.Rendering", StringComparison.Ordinal) &&
               source.Contains("Stopwatch.GetTimestamp", StringComparison.Ordinal),
            "动作、探头与淡化必须由 CompositionTarget.Rendering 和绝对 Stopwatch 时钟驱动");
        Assert(!source.Contains("_frameTimer", StringComparison.Ordinal) &&
               !source.Contains("_edgePeekTimer", StringComparison.Ordinal),
            "视觉状态机不得再由 DispatcherTimer 逐帧 stop/start 驱动");
        var renderingStart = source.IndexOf(
            "private void VisualClock_Rendering",
            StringComparison.Ordinal);
        var renderingEnd = renderingStart < 0
            ? -1
            : source.IndexOf("\n    private ", renderingStart + 1, StringComparison.Ordinal);
        Assert(renderingStart >= 0 && renderingEnd > renderingStart &&
               !source[renderingStart..renderingEnd]
                   .Contains("AppLogger", StringComparison.Ordinal),
            "统一渲染回调内不得写日志或触发任何磁盘I/O");
        AssertMainRenderingTimeDedupContract(window);
        AssertRenderingCadenceClassificationContract(source);
        AssertEdgePeekRenderingCadenceTimelineContract(window);

        var clips = GetField<Array>(window, "_reactionClips")
            .Cast<object>()
            .ToArray();
        foreach (var clip in clips)
        {
            var actionName = GetProperty<string>(clip, "ActionName");
            var durations = GetClipFrames(clip)
                .Cast<object>()
                .Select(GetFrameDuration)
                .ToArray();
            var holdTicks = durations
                .Select(ToProductionCharacterAnimationTicks)
                .ToArray();
            var authoredTotal = TimeSpan.FromTicks(
                durations.Sum(duration => duration.Ticks));
            var effectiveTotalTicks = holdTicks.Aggregate(
                0L,
                checked((total, ticks) => total + ticks));
            var expectedDurations = BuildExpectedMotionFrameDurations(actionName);
            var expectedFrameCount = expectedDurations.Length;
            var expectedAuthoredDuration = TimeSpan.FromTicks(
                expectedDurations.Sum(duration => duration.Ticks));
            var expectedEffectiveTotalTicks = expectedDurations
                .Select(ToProductionCharacterAnimationTicks)
                .Aggregate(0L, checked((total, ticks) => total + ticks));
            Assert(authoredTotal == expectedAuthoredDuration &&
                   durations.SequenceEqual(expectedDurations),
                $"{actionName} 的{expectedFrameCount}帧必须保留动作 profile 的精确时长，" +
                $"实际 {authoredTotal.TotalSeconds:F3} 秒");
            Assert(effectiveTotalTicks == expectedEffectiveTotalTicks,
                $"{actionName} 的运行时间轴必须逐帧使用生产ToCharacterAnimationTicks缩放，" +
                "包括稳定末姿势 hold");

            var deadlineToleranceTicks = (long)(typeof(MainWindow).GetField(
                    "VisualFrameDeadlineToleranceTicks",
                    StaticFlags)!.GetValue(null) ?? 0L);
            var absoluteCheckpoints = new[]
            {
                0L,
                effectiveMotionFrameTicks - deadlineToleranceTicks - 1,
                effectiveMotionFrameTicks - deadlineToleranceTicks,
                effectiveMotionFrameTicks * 2 - deadlineToleranceTicks,
                StopwatchTicksFromMilliseconds(250),
                StopwatchTicksFromMilliseconds(500)
            };

            for (var checkpointIndex = 0;
                 checkpointIndex < absoluteCheckpoints.Length;
                 checkpointIndex++)
            {
                var elapsedTicks = absoluteCheckpoints[checkpointIndex];
                var expectedIndex = ResolveAbsoluteFrameIndexAtStopwatchTicks(
                    holdTicks,
                    elapsedTicks,
                    deadlineToleranceTicks);
                var actualIndex = ResolveProductionClipFrameIndex(
                    window,
                    clip,
                    elapsedTicks);
                Assert(actualIndex == expectedIndex,
                    $"生产AdvanceActiveClip必须在同一绝对时刻定位同一动作帧；" +
                    $"action={actionName}, " +
                    $"elapsed={StopwatchTicksToMilliseconds(elapsedTicks):F3}ms，" +
                    $"expected={expectedIndex}, actual={actualIndex}");
            }

            var beforeStall = StopwatchTicksFromMilliseconds(140);
            var afterStall = checked(
                beforeStall + StopwatchTicksFromMilliseconds(250));
            var beforeIndex = ResolveProductionClipFrameIndex(window, clip, beforeStall);
            var afterIndex = ResolveProductionClipFrameIndex(window, clip, afterStall);
            var expectedAfterIndex = ResolveAbsoluteFrameIndexAtStopwatchTicks(
                holdTicks,
                afterStall,
                deadlineToleranceTicks);
            Assert(afterIndex > beforeIndex && afterIndex == expectedAfterIndex,
                "生产AdvanceActiveClip在250ms渲染停顿后必须直接定位正确帧，" +
                    "不得只补播下一帧或累积计时漂移");
        }

        AssertProductionDiscreteVsyncTimeline(
            window,
            clips[0],
            "reaction-cry");
        AssertProductionDiscreteVsyncTimeline(
            window,
            clips.Single(clip =>
                GetProperty<string>(clip, "ActionName") == "cute"),
            "reaction-cute");
        AssertTodoTransitionTimelineContract(window, source);
    }

    private static void AssertTodoTransitionTimelineContract(
        MainWindow window,
        string mainWindowSource)
    {
        var expectedEnterNames = BuildExpectedActionTimelineNames("think");
        var expectedFrameCount = expectedEnterNames.Length;
        var wakeFrameCount = GetExpectedWakeFrameNames().Length;
        var enterClip = GetRawField(window, "_todoEnterClip")!;
        var exitClip = GetRawField(window, "_todoExitClip")!;
        var enterFrames = GetClipFrames(enterClip).Cast<object>().ToArray();
        var exitFrames = GetClipFrames(exitClip).Cast<object>().ToArray();
        Assert(enterFrames.Length == expectedFrameCount &&
               exitFrames.Length == expectedFrameCount,
            $"Todo 打开/收起必须使用 idle、{wakeFrameCount}个60fps wake及完整think dense序列，共{expectedFrameCount}帧");
        var enterNames = enterFrames
            .Select(GetAnimationFrameName)
            .ToArray();
        var exitNames = exitFrames
            .Select(GetAnimationFrameName)
            .ToArray();
        Assert(enterNames.SequenceEqual(expectedEnterNames),
            $"Todo 入场必须按资源名完整覆盖{wakeFrameCount}帧起身与think dense序列");
        Assert(exitNames.SequenceEqual(enterNames.Reverse()),
            "Todo 出场必须与入场逐帧严格反序，保证中途反向时落在同一姿势");
        for (var expectedIndex = 0;
             expectedIndex < expectedEnterNames.Length;
             expectedIndex++)
        {
            var spriteFrame = GetProperty<object>(
                enterFrames[expectedIndex],
                "Image");
            var mappedIndex = (int)Invoke(
                window,
                "GetTodoEnterStartIndex",
                spriteFrame)!;
            Assert(mappedIndex == expectedIndex,
                $"Todo路径资源 {expectedEnterNames[expectedIndex]} 中途右键必须精确续播索引 {expectedIndex}");
        }

        const string resumedFrameName = "luban-think-smooth-015.png";
        var resumedEnterIndex = Array.IndexOf(expectedEnterNames, resumedFrameName);
        Assert(resumedEnterIndex >= 0,
            "Todo完整路径必须包含指定的think dense中间姿势");
        var resumedSpriteFrame = GetProperty<object>(
            enterFrames[resumedEnterIndex],
            "Image");
        var resumedExitIndex = exitFrames.Length - 1 - resumedEnterIndex;
        var resumedExitSpriteFrame = GetProperty<object>(
            exitFrames[resumedExitIndex],
            "Image");
        Assert(Equals(resumedExitSpriteFrame, resumedSpriteFrame),
            "Todo 入场/收起的 think-smooth 中间姿势必须按同一像素索引严格镜像");
        PrimeSpritePageForFrame(window, resumedSpriteFrame);
        Invoke(window, "ShowStableFrame", resumedSpriteFrame);
        SetField(window, "_activeClip", exitClip);
        SetField(window, "_activeFrameIndex", resumedExitIndex);
        SetField(window, "_activeClipStartedTimestamp", Stopwatch.GetTimestamp());
        SetField(window, "_activeFrameDeadlineTimestamp", long.MaxValue);
        SetField(window, "_bubbleMode", GetNestedEnum("BubbleMode", "None"));
        Invoke(window, "EnterTodoVisualState");
        var resumedPresentationAt = Stopwatch.GetTimestamp();
        Invoke(window, "TryShowPendingSpriteFrameAt", resumedPresentationAt);
        var resumedAt = GetField<long>(window, "_activeClipStartedTimestamp");
        var resumedDeadline = GetField<long>(window, "_activeFrameDeadlineTimestamp");
        var resumedHoldTicks = ToProductionCharacterAnimationTicks(
            GetFrameDuration(enterFrames[resumedEnterIndex]));
        Assert(ReferenceEquals(GetRawField(window, "_activeClip"), enterClip) &&
               GetField<int>(window, "_activeFrameIndex") == resumedEnterIndex &&
               Equals(GetRawField(window, "_currentSpriteFrame"), resumedSpriteFrame) &&
               resumedAt > 0 &&
               resumedDeadline - resumedAt == resumedHoldTicks &&
               !GetField<bool>(window, "_isFrameBlending"),
            "Todo 收起到 think-smooth 中间姿势时重新右键，必须从同名像素反向续播，不能重播或淡化闪回");
        SetField(window, "_activeClip", null);
        SetField(window, "_activeFrameIndex", -1);
        SetField(window, "_activeClipStartedTimestamp", 0L);
        SetField(window, "_activeFrameDeadlineTimestamp", 0L);
        Invoke(window, "ClearDeferredActiveClipClock");
        Invoke(window, "UpdateVisualClockSubscription");
        var idleFrame = GetField<object>(window, "_idleFrame");
        PrimeSpritePageForFrame(window, idleFrame);
        Invoke(window, "ShowStableFrame", idleFrame);

        var enterDurations = enterFrames
            .Select(GetFrameDuration)
            .ToArray();
        var sixtyFpsInterval = TimeSpan.FromTicks(TimeSpan.TicksPerSecond / 60);
        Assert(enterDurations.All(duration => duration == sixtyFpsInterval),
            "Todo全部入场帧必须统一使用精确60fps姿势间隔");
        Assert(exitFrames.All(frame =>
                GetFrameDuration(frame) == sixtyFpsInterval),
            "Todo 收起必须保持与打开相同的精确60fps绝对时间节奏");

        var enterSource = ExtractPrivateMethodSource(
            mainWindowSource,
            "EnterTodoVisualState");
        var exitSource = ExtractPrivateMethodSource(
            mainWindowSource,
            "StartTodoExitTransition");
        Assert(enterSource.Contains(
                   "_nextFrameBlendDuration = TimeSpan.Zero",
                   StringComparison.Ordinal) &&
               exitSource.Contains(
                   "_nextFrameBlendDuration = TimeSpan.Zero",
                   StringComparison.Ordinal) &&
               !mainWindowSource.Contains(
                   "TodoStateBlendDuration",
                   StringComparison.Ordinal),
            "Todo 相邻姿势必须直接切换，不得整图交叉淡化产生双轮廓或像素光纹");

        var total = TimeSpan.FromTicks(enterDurations.Sum(duration => duration.Ticks));
        var expectedTodoDuration = TimeSpan.FromTicks(
            expectedFrameCount * sixtyFpsInterval.Ticks);
        Assert(total == expectedTodoDuration,
            $"Todo 完整{expectedFrameCount}帧时间线应为{expectedTodoDuration.TotalSeconds:F3}秒，" +
            $"实际 {total.TotalMilliseconds:F0}ms");
        var enterHoldTicks = enterDurations
            .Select(ToProductionCharacterAnimationTicks)
            .ToArray();
        var effectiveFrameTicks =
            ToProductionCharacterAnimationTicks(sixtyFpsInterval);
        Assert(enterHoldTicks.All(ticks => ticks == effectiveFrameTicks),
            "Todo运行deadline必须逐帧调用生产ToCharacterAnimationTicks应用1.25倍代码速度");
        var checkpoints = new long[]
        {
            0,
            effectiveFrameTicks / 2,
            effectiveFrameTicks,
            StopwatchTicksFromMilliseconds(250),
            StopwatchTicksFromMilliseconds(500),
            StopwatchTicksFromMilliseconds(800)
        };
        var deadlineToleranceTicks = (long)(typeof(MainWindow).GetField(
                "VisualFrameDeadlineToleranceTicks",
                StaticFlags)!.GetValue(null) ?? 0L);
        var resolvedFrames = checkpoints
            .Select(elapsedTicks => ResolveProductionClipFrameIndex(
                window,
                enterClip,
                elapsedTicks))
            .ToArray();
        var expectedFrames = checkpoints
            .Select(elapsedTicks => ResolveAbsoluteFrameIndexAtStopwatchTicks(
                enterHoldTicks,
                elapsedTicks,
                deadlineToleranceTicks))
            .ToArray();
        Assert(resolvedFrames.SequenceEqual(expectedFrames),
            "Todo生产AdvanceActiveClip必须在相同绝对时刻稳定定位同一姿势");

        AssertProductionDiscreteVsyncTimeline(
            window,
            enterClip,
            "todo-enter");
    }

    private sealed record VsyncClipSample(
        int VsyncOrdinal,
        long ElapsedStopwatchTicks,
        int DisplayedFrameIndex);

    private sealed record VsyncClipRun(
        VsyncClipSample[] Samples,
        long CompletionElapsedTicks);

    private sealed record VsyncStallRun(
        int BeforeFrameIndex,
        int StalledFrameIndex,
        int NextFrameIndex,
        long StallElapsedTicks);

    private readonly record struct EdgePeekClockState(
        int FrameIndex,
        long DeadlineTimestamp);

    private static void AssertEdgePeekRenderingCadenceTimelineContract(
        MainWindow window)
    {
        PauseSpritePageWarmupForClockSimulation(window);
        var frames = GetField<Array>(window, "_edgeLeftFrames");
        Assert(frames.Length == ExpectedEdgePeekFrameCount,
            $"边缘合成节拍回归必须使用完整{ExpectedEdgePeekFrameCount}帧生产序列，" +
            $"实际{frames.Length}帧");

        var holdTicks = Enumerable.Range(0, frames.Length)
            .Select(frameIndex => ToProductionStopwatchTicks(
                (TimeSpan)InvokeStatic(
                    typeof(MainWindow),
                    "GetEdgePeekFrameHoldDuration",
                    frameIndex,
                    frames.Length)!))
            .ToArray();
        var cycleTicks = (long)InvokeStatic(
            typeof(MainWindow),
            "GetEdgePeekCycleDurationTicks",
            frames.Length)!;
        AssertClose(
            StopwatchTicksToMilliseconds(cycleTicks),
            10000d,
            "production edge peek cycle must be exactly 10 seconds");
        Assert(cycleTicks == holdTicks.Aggregate(
                   0L,
                   checked((total, ticks) => total + ticks)),
            $"边缘生产周期必须等于{ExpectedEdgePeekFrameCount}个姿势hold之和，" +
            "长时间模拟才不会掩盖周期漂移");

        try
        {
            foreach (var refreshRate in new[] { 59d, 59.94d, 60d })
            {
                AssertHealthyNearSixtyEdgePeekTimeline(
                    window,
                    frames,
                    holdTicks,
                    cycleTicks,
                    refreshRate);
            }

            foreach (var refreshRate in new[] { 120d, 144d })
            {
                AssertAbsoluteEdgePeekTimeline(
                    window,
                    frames,
                    holdTicks,
                    cycleTicks,
                    refreshRate);
            }

            AssertEdgePeekStallAndCadenceRecovery(
                window,
                frames,
                holdTicks,
                cycleTicks);
        }
        finally
        {
            CleanupProductionEdgePeekClockSimulation(window);
        }
    }

    private static void AssertHealthyNearSixtyEdgePeekTimeline(
        MainWindow window,
        Array frames,
        IReadOnlyList<long> holdTicks,
        long cycleTicks,
        double refreshRate)
    {
        var startedAt = StopwatchTicksFromSeconds(100);
        PrepareProductionEdgePeekClockSimulation(
            window,
            frames,
            startedAt,
            holdTicks[^1]);
        try
        {
            var fullyPeekedFrameIndex = frames.Length / 2 - 1;
            var restingFrameIndex = frames.Length - 1;
            var maximumVsyncTicks = (long)Math.Ceiling(
                Stopwatch.Frequency / refreshRate);
            var previousFrameIndex = frames.Length - 1;
            var previousDeadline = GetField<long>(
                window,
                "_edgePeekFrameDeadlineTimestamp");
            var endpointDisplayedAt = startedAt;
            var endpointHoldCounts = new int[frames.Length];
            var frameZeroTimestamps = new List<long>();
            var maximumCycleErrorRatio = 0d;
            var maximumVsyncOrdinal = checked(
                (int)Math.Ceiling(60d * refreshRate));
            var lastTimestamp = startedAt;

            for (var vsyncOrdinal = 1;
                 vsyncOrdinal <= maximumVsyncOrdinal;
                 vsyncOrdinal++)
            {
                var timestamp = checked(
                    startedAt + SyntheticStopwatchElapsedTicks(
                        refreshRate,
                        vsyncOrdinal));
                var presentationInterval = SyntheticPresentationInterval(
                    refreshRate,
                    vsyncOrdinal);
                var synchronize = (bool)InvokeStatic(
                    typeof(MainWindow),
                    "ShouldSynchronizeEdgePeekToRenderingCadence",
                    presentationInterval)!;
                Assert(synchronize,
                    $"{refreshRate:F2}Hz健康合成的第{vsyncOrdinal}次实际离散间隔必须持续识别为近60Hz");

                SetField(
                    window,
                    "_synchronizeEdgePeekToRenderingCadence",
                    synchronize);
                try
                {
                    AdvanceEdgePeekForControlledClock(window, timestamp);
                }
                finally
                {
                    SetField(
                        window,
                        "_synchronizeEdgePeekToRenderingCadence",
                        false);
                }

                var frameIndex = GetField<int>(window, "_edgePeekFrameIndex");
                var deadline = GetField<long>(
                    window,
                    "_edgePeekFrameDeadlineTimestamp");
                var logicalAdvance =
                    (frameIndex - previousFrameIndex + frames.Length) %
                    frames.Length;
                Assert(logicalAdvance is 0 or 1 &&
                       (logicalAdvance != 0 || deadline == previousDeadline),
                    $"{refreshRate:F2}Hz健康合成每次回调只能逻辑推进0或1帧，" +
                    $"vsync={vsyncOrdinal}, {previousFrameIndex}->{frameIndex}");

                if (logicalAdvance == 1)
                {
                    var expectedFrameIndex =
                        (previousFrameIndex + 1) % frames.Length;
                    Assert(frameIndex == expectedFrameIndex,
                        $"{refreshRate:F2}Hz边缘姿势必须完整有序且不漏帧，" +
                        $"expected={expectedFrameIndex}, actual={frameIndex}");
                    AssertDisplayedEdgeFrame(window, frames, frameIndex);

                    if (previousFrameIndex == fullyPeekedFrameIndex ||
                        previousFrameIndex == restingFrameIndex)
                    {
                        var expectedEndpointHoldTicks =
                            holdTicks[previousFrameIndex];
                        var actualEndpointHoldTicks =
                            timestamp - endpointDisplayedAt;
                        Assert(actualEndpointHoldTicks >= expectedEndpointHoldTicks &&
                               actualEndpointHoldTicks <
                               expectedEndpointHoldTicks + maximumVsyncTicks,
                            $"{refreshRate:F2}Hz frame{previousFrameIndex}端点实际hold必须" +
                            $"落在[{StopwatchTicksToMilliseconds(expectedEndpointHoldTicks):F0}ms, " +
                            $"目标+1vsync)；实际" +
                            $"{StopwatchTicksToMilliseconds(actualEndpointHoldTicks):F3}ms");
                        endpointHoldCounts[previousFrameIndex]++;
                    }

                    if (frameIndex == fullyPeekedFrameIndex ||
                        frameIndex == restingFrameIndex)
                    {
                        endpointDisplayedAt = timestamp;
                    }

                    if (frameIndex == 0)
                    {
                        frameZeroTimestamps.Add(timestamp);
                    }
                }
                else
                {
                    AssertDisplayedEdgeFrame(window, frames, frameIndex);
                }

                previousFrameIndex = frameIndex;
                previousDeadline = deadline;
                lastTimestamp = timestamp;
            }

            Assert(lastTimestamp - startedAt >= StopwatchTicksFromSeconds(60),
                $"{refreshRate:F2}Hz健康边缘模拟必须覆盖至少60秒");
            var completedCycles = frameZeroTimestamps.Count - 1;
            Assert(completedCycles >= 5 &&
                   endpointHoldCounts[fullyPeekedFrameIndex] >= 5 &&
                   endpointHoldCounts[restingFrameIndex] >= 5,
                $"{refreshRate:F2}Hz健康边缘模拟至少应完整覆盖20轮；" +
                $"cycles={completedCycles}, " +
                $"hold{fullyPeekedFrameIndex}=" +
                $"{endpointHoldCounts[fullyPeekedFrameIndex]}, " +
                $"hold{restingFrameIndex}=" +
                $"{endpointHoldCounts[restingFrameIndex]}");

            for (var cycleIndex = 1;
                 cycleIndex < frameZeroTimestamps.Count;
                 cycleIndex++)
            {
                var actualCycleTicks =
                    frameZeroTimestamps[cycleIndex] -
                    frameZeroTimestamps[cycleIndex - 1];
                var cycleErrorRatio =
                    Math.Abs(actualCycleTicks - cycleTicks) /
                    (double)cycleTicks;
                maximumCycleErrorRatio = Math.Max(
                    maximumCycleErrorRatio,
                    cycleErrorRatio);
                Assert(cycleErrorRatio < 0.02,
                    $"{refreshRate:F2}Hz边缘周期误差必须小于2%，" +
                    $"cycle={cycleIndex}, error={cycleErrorRatio:P3}");
            }

            Console.WriteLine(
                $"[METRIC] edge-peek vsync={refreshRate:F2}Hz: " +
                $"duration={StopwatchTicksToMilliseconds(lastTimestamp - startedAt):F3}ms, " +
                $"cycles={completedCycles}, maxCycleError={maximumCycleErrorRatio:P3}");
        }
        finally
        {
            CleanupProductionEdgePeekClockSimulation(window);
        }
    }

    private static void AssertAbsoluteEdgePeekTimeline(
        MainWindow window,
        Array frames,
        IReadOnlyList<long> holdTicks,
        long cycleTicks,
        double refreshRate)
    {
        var startedAt = StopwatchTicksFromSeconds(200);
        PrepareProductionEdgePeekClockSimulation(
            window,
            frames,
            startedAt,
            holdTicks[^1]);
        try
        {
            var expected = new EdgePeekClockState(
                frames.Length - 1,
                checked(startedAt + holdTicks[^1]));
            var maximumVsyncOrdinal = checked(
                (int)Math.Ceiling(30d * refreshRate));
            for (var vsyncOrdinal = 1;
                 vsyncOrdinal <= maximumVsyncOrdinal;
                 vsyncOrdinal++)
            {
                var timestamp = checked(
                    startedAt + SyntheticStopwatchElapsedTicks(
                        refreshRate,
                        vsyncOrdinal));
                var presentationInterval = SyntheticPresentationInterval(
                    refreshRate,
                    vsyncOrdinal);
                var synchronize = (bool)InvokeStatic(
                    typeof(MainWindow),
                    "ShouldSynchronizeEdgePeekToRenderingCadence",
                    presentationInterval)!;
                Assert(!synchronize,
                    $"{refreshRate:F0}Hz必须持续使用既有绝对deadline模型");

                expected = ResolveAbsoluteEdgePeekClockState(
                    holdTicks,
                    cycleTicks,
                    expected,
                    timestamp);
                SetField(
                    window,
                    "_synchronizeEdgePeekToRenderingCadence",
                    false);
                AdvanceEdgePeekForControlledClock(window, timestamp);
                var actual = new EdgePeekClockState(
                    GetField<int>(window, "_edgePeekFrameIndex"),
                    GetField<long>(
                        window,
                        "_edgePeekFrameDeadlineTimestamp"));
                Assert(actual == expected,
                    $"{refreshRate:F0}Hz边缘绝对时钟必须逐回调匹配既有模型，" +
                    $"vsync={vsyncOrdinal}, expected={expected}, actual={actual}");
                AssertDisplayedEdgeFrame(
                    window,
                    frames,
                    actual.FrameIndex);
            }

            Console.WriteLine(
                $"[METRIC] edge-peek absolute={refreshRate:F0}Hz: " +
                $"callbacks={maximumVsyncOrdinal}, final={expected.FrameIndex}");
        }
        finally
        {
            CleanupProductionEdgePeekClockSimulation(window);
        }
    }

    private static void AssertEdgePeekStallAndCadenceRecovery(
        MainWindow window,
        Array frames,
        IReadOnlyList<long> holdTicks,
        long cycleTicks)
    {
        const double refreshRate = 59.94d;
        var startedAt = StopwatchTicksFromSeconds(300);
        PrepareProductionEdgePeekClockSimulation(
            window,
            frames,
            startedAt,
            holdTicks[^1]);
        try
        {
            var firstFrameTimestamp = -1L;
            var firstFrameVsyncOrdinal = -1;
            for (var vsyncOrdinal = 1;
                 vsyncOrdinal <= (int)Math.Ceiling(10d * refreshRate);
                 vsyncOrdinal++)
            {
                var timestamp = checked(
                    startedAt + SyntheticStopwatchElapsedTicks(
                        refreshRate,
                        vsyncOrdinal));
                var synchronize = (bool)InvokeStatic(
                    typeof(MainWindow),
                    "ShouldSynchronizeEdgePeekToRenderingCadence",
                    SyntheticPresentationInterval(
                        refreshRate,
                        vsyncOrdinal))!;
                Assert(synchronize,
                    "250ms阻塞探针前的59.94Hz合成必须处于同步路径");
                SetField(
                    window,
                    "_synchronizeEdgePeekToRenderingCadence",
                    true);
                try
                {
                    AdvanceEdgePeekForControlledClock(window, timestamp);
                }
                finally
                {
                    SetField(
                        window,
                        "_synchronizeEdgePeekToRenderingCadence",
                        false);
                }

                if (GetField<int>(window, "_edgePeekFrameIndex") == 0)
                {
                    firstFrameTimestamp = timestamp;
                    firstFrameVsyncOrdinal = vsyncOrdinal;
                    break;
                }
            }

            Assert(firstFrameTimestamp >= startedAt &&
                   firstFrameVsyncOrdinal > 0,
                $"59.94Hz基线必须先从rest frame{frames.Length - 1}有序进入frame0");
            var beforeStall = new EdgePeekClockState(
                GetField<int>(window, "_edgePeekFrameIndex"),
                GetField<long>(
                    window,
                    "_edgePeekFrameDeadlineTimestamp"));
            Assert(beforeStall.FrameIndex == 0,
                "250ms阻塞探针必须从frame0的同步deadline开始");

            var stallTimestamp = checked(
                firstFrameTimestamp +
                StopwatchTicksFromMilliseconds(250));
            var gapSynchronizes = (bool)InvokeStatic(
                typeof(MainWindow),
                "ShouldSynchronizeEdgePeekToRenderingCadence",
                TimeSpan.FromMilliseconds(250))!;
            Assert(!gapSynchronizes,
                "250ms合成gap必须关闭近60Hz同步并恢复绝对时钟定位");
            var expectedAfterStall = ResolveAbsoluteEdgePeekClockState(
                holdTicks,
                cycleTicks,
                beforeStall,
                stallTimestamp);
            var skippedFrameCount =
                (expectedAfterStall.FrameIndex -
                 beforeStall.FrameIndex +
                 frames.Length) %
                frames.Length;
            Assert(skippedFrameCount > 1,
                "250ms阻塞样本必须跨过多个运动姿势，才能证明不是逐帧补播");

            SetField(
                window,
                "_synchronizeEdgePeekToRenderingCadence",
                gapSynchronizes);
            AdvanceEdgePeekForControlledClock(window, stallTimestamp);
            var actualAfterStall = new EdgePeekClockState(
                GetField<int>(window, "_edgePeekFrameIndex"),
                GetField<long>(
                    window,
                    "_edgePeekFrameDeadlineTimestamp"));
            Assert(actualAfterStall == expectedAfterStall,
                $"250ms gap必须由一次生产调用直接定位最终帧；" +
                $"expected={expectedAfterStall}, actual={actualAfterStall}");
            AssertDisplayedEdgeFrame(
                window,
                frames,
                actualAfterStall.FrameIndex);

            AdvanceEdgePeekForControlledClock(window, stallTimestamp);
            Assert(new EdgePeekClockState(
                       GetField<int>(window, "_edgePeekFrameIndex"),
                       GetField<long>(
                           window,
                           "_edgePeekFrameDeadlineTimestamp")) ==
                   actualAfterStall,
                "相同stall时间戳重复调用不得继续补播积压姿势");

            var previousFrameIndex = actualAfterStall.FrameIndex;
            var previousDeadline = actualAfterStall.DeadlineTimestamp;
            var synchronizedAdvanceObserved = false;
            for (var recoveryVsyncOrdinal = 1;
                 recoveryVsyncOrdinal <= 40;
                 recoveryVsyncOrdinal++)
            {
                var recoveryTimestamp = checked(
                    stallTimestamp + SyntheticStopwatchElapsedTicks(
                        refreshRate,
                        recoveryVsyncOrdinal));
                var presentationInterval = SyntheticPresentationInterval(
                    refreshRate,
                    recoveryVsyncOrdinal);
                var synchronize = (bool)InvokeStatic(
                    typeof(MainWindow),
                    "ShouldSynchronizeEdgePeekToRenderingCadence",
                    presentationInterval)!;
                Assert(synchronize,
                    "250ms gap后的正常59.94Hz间隔必须重新进入同步路径");
                SetField(
                    window,
                    "_synchronizeEdgePeekToRenderingCadence",
                    true);
                try
                {
                    AdvanceEdgePeekForControlledClock(window, recoveryTimestamp);
                }
                finally
                {
                    SetField(
                        window,
                        "_synchronizeEdgePeekToRenderingCadence",
                        false);
                }

                var frameIndex = GetField<int>(window, "_edgePeekFrameIndex");
                var deadline = GetField<long>(
                    window,
                    "_edgePeekFrameDeadlineTimestamp");
                var logicalAdvance =
                    (frameIndex - previousFrameIndex + frames.Length) %
                    frames.Length;
                Assert(logicalAdvance is 0 or 1 &&
                       (logicalAdvance != 0 || deadline == previousDeadline),
                    "stall恢复后的健康合成仍必须每次只逻辑推进0或1帧");
                if (logicalAdvance == 1)
                {
                    Assert(frameIndex ==
                           (previousFrameIndex + 1) % frames.Length,
                        "stall恢复后不得漏帧或乱序");
                    Assert(deadline == checked(
                               recoveryTimestamp + holdTicks[frameIndex]),
                        "stall恢复后的首次逻辑推进必须把deadline重基到当前合成时刻");
                    synchronizedAdvanceObserved = true;
                }

                AssertDisplayedEdgeFrame(window, frames, frameIndex);
                previousFrameIndex = frameIndex;
                previousDeadline = deadline;
            }

            Assert(synchronizedAdvanceObserved,
                "250ms绝对定位后的正常vsync必须实际恢复逐合成同步");
            Console.WriteLine(
                $"[METRIC] edge-peek stall=250ms: " +
                $"frame0->{actualAfterStall.FrameIndex}, " +
                $"baselineVsync={firstFrameVsyncOrdinal}, recovered=true");
        }
        finally
        {
            SetField(
                window,
                "_synchronizeEdgePeekToRenderingCadence",
                false);
            CleanupProductionEdgePeekClockSimulation(window);
        }
    }

    private static EdgePeekClockState ResolveAbsoluteEdgePeekClockState(
        IReadOnlyList<long> holdTicks,
        long cycleTicks,
        EdgePeekClockState current,
        long timestamp)
    {
        var frameIndex = current.FrameIndex;
        var deadline = current.DeadlineTimestamp;
        var overdueTicks = timestamp - deadline;
        if (overdueTicks >= cycleTicks)
        {
            deadline = checked(
                deadline + overdueTicks / cycleTicks * cycleTicks);
        }

        while (timestamp >= deadline)
        {
            frameIndex = (frameIndex + 1) % holdTicks.Count;
            deadline = checked(deadline + holdTicks[frameIndex]);
        }

        return new EdgePeekClockState(frameIndex, deadline);
    }

    private static long SyntheticStopwatchElapsedTicks(
        double refreshRate,
        int vsyncOrdinal) =>
        (long)Math.Round(
            vsyncOrdinal * Stopwatch.Frequency / refreshRate);

    private static TimeSpan SyntheticPresentationInterval(
        double refreshRate,
        int vsyncOrdinal)
    {
        var currentTicks = (long)Math.Round(
            vsyncOrdinal * TimeSpan.TicksPerSecond / refreshRate);
        var previousTicks = (long)Math.Round(
            (vsyncOrdinal - 1L) * TimeSpan.TicksPerSecond / refreshRate);
        return TimeSpan.FromTicks(currentTicks - previousTicks);
    }

    private static void PrepareProductionEdgePeekClockSimulation(
        MainWindow window,
        Array frames,
        long startedAt,
        long restHoldTicks)
    {
        Invoke(window, "StopVisualClock");
        GetField<DispatcherTimer>(window, "_automaticTimer").Stop();
        GetField<DispatcherTimer>(window, "_edgePeekHoldTimer").Stop();
        Invoke(window, "StopFrameBlend", false);
        Assert(GetRawField(window, "_activeClip") is null &&
               !GetField<bool>(window, "_isReminderActive"),
            "边缘时钟模拟开始前不得残留动作或提醒状态");
        SetField(window, "_bubbleMode", GetNestedEnum("BubbleMode", "None"));
        SetField(window, "_pendingSpriteFrame", null);
        SetField(window, "_pendingSpriteFrameBlendDuration", TimeSpan.Zero);
        SetField(window, "_failedSpritePageName", null);

        var primedPageNames = new HashSet<string>(StringComparer.Ordinal);
        foreach (var frame in frames.Cast<object>())
        {
            if (primedPageNames.Add(GetSpriteFrameInfo(frame).PageName))
            {
                PrimeSpritePageForFrame(window, frame);
            }
        }

        Invoke(window, "ResetPetVisualTransforms");
        var restFrameIndex = frames.Length - 1;
        var restFrame = frames.GetValue(restFrameIndex)!;
        SetField(window, "_edgeDock", GetNestedEnum("EdgeDock", "Left"));
        SetField(window, "_edgePeekFrameIndex", restFrameIndex);
        SetField(window, "_nextFrameBlendDuration", TimeSpan.Zero);
        Invoke(window, "ShowStableFrame", restFrame);
        Assert(Equals(GetRawField(window, "_currentSpriteFrame"), restFrame) &&
               GetRawField(window, "_pendingSpriteFrame") is null,
            $"边缘时钟模拟必须从已实际显示的rest frame{restFrameIndex}开始");
        SetField(
            window,
            "_edgePeekFrameDeadlineTimestamp",
            checked(startedAt + restHoldTicks));
        SetField(
            window,
            "_synchronizeEdgePeekToRenderingCadence",
            false);
    }

    private static void CleanupProductionEdgePeekClockSimulation(
        MainWindow window)
    {
        GetField<DispatcherTimer>(window, "_edgePeekHoldTimer").Stop();
        SetField(
            window,
            "_synchronizeEdgePeekToRenderingCadence",
            false);
        SetField(window, "_edgeDock", GetNestedEnum("EdgeDock", "None"));
        SetField(window, "_edgePeekFrameIndex", 0);
        SetField(window, "_edgePeekFrameDeadlineTimestamp", 0L);
        SetField(window, "_pendingSpriteFrame", null);
        SetField(window, "_pendingSpriteFrameBlendDuration", TimeSpan.Zero);
        Invoke(window, "ResetPetVisualTransforms");
        var idleFrame = GetField<object>(window, "_idleFrame");
        PrimeSpritePageForFrame(window, idleFrame);
        SetField(window, "_nextFrameBlendDuration", TimeSpan.Zero);
        Invoke(window, "ShowStableFrame", idleFrame);
        Invoke(window, "UpdateVisualClockSubscription");
        Invoke(window, "StopVisualClock");
    }

    private static void AssertDisplayedEdgeFrame(
        MainWindow window,
        Array frames,
        int frameIndex)
    {
        Assert(Equals(
                   GetRawField(window, "_currentSpriteFrame"),
                   frames.GetValue(frameIndex)) &&
               GetRawField(window, "_pendingSpriteFrame") is null &&
               !GetField<bool>(window, "_isFrameBlending"),
            $"生产AdvanceEdgePeek索引{frameIndex}必须直接显示对应SpriteFrame，" +
            "不得留下待显示帧或整图淡化");
    }

    private static void AssertProductionDiscreteVsyncTimeline(
        MainWindow window,
        object clip,
        string label)
    {
        var frames = GetClipFrames(clip);
        Assert(frames.Length > 30,
            $"{label}离散vsync测试至少需要30帧，以覆盖250ms阻塞跳帧");
        var holdTicks = frames
            .Cast<object>()
            .Select(frame => ToProductionCharacterAnimationTicks(
                GetFrameDuration(frame)))
            .ToArray();
        var totalHoldTicks = holdTicks.Aggregate(0L, checked((total, ticks) => total + ticks));
        var preStallElapsedTicks = StopwatchTicksFromMilliseconds(140);
        var deadlineToleranceTicks = (long)(typeof(MainWindow).GetField(
                "VisualFrameDeadlineToleranceTicks",
                StaticFlags)!.GetValue(null) ?? 0L);

        foreach (var refreshRate in new[] { 59d, 60d, 120d, 144d })
        {
            var firstRun = RunProductionVsyncClip(
                window,
                clip,
                refreshRate,
                holdTicks,
                totalHoldTicks);
            var replayRun = RunProductionVsyncClip(
                window,
                clip,
                refreshRate,
                holdTicks,
                totalHoldTicks);
            Assert(firstRun.CompletionElapsedTicks == replayRun.CompletionElapsedTicks &&
                   firstRun.Samples.SequenceEqual(replayRun.Samples),
                $"{label}在{refreshRate:F2}Hz相同绝对vsync时刻必须产生完全一致的显示帧轨迹");

            for (var sampleIndex = 1; sampleIndex < firstRun.Samples.Length; sampleIndex++)
            {
                var previous = firstRun.Samples[sampleIndex - 1];
                var current = firstRun.Samples[sampleIndex];
                Assert(current.ElapsedStopwatchTicks > previous.ElapsedStopwatchTicks &&
                       current.DisplayedFrameIndex >= previous.DisplayedFrameIndex,
                    $"{label}在{refreshRate:F2}Hz正常vsync下索引必须单调；" +
                    $"sample={sampleIndex}, previous={previous.DisplayedFrameIndex}, " +
                    $"current={current.DisplayedFrameIndex}");

                var expectedIndex = ResolveAbsoluteFrameIndexAtStopwatchTicks(
                    holdTicks,
                    current.ElapsedStopwatchTicks,
                    deadlineToleranceTicks);
                Assert(current.DisplayedFrameIndex == expectedIndex,
                    $"{label}在{refreshRate:F0}Hz必须按生产绝对deadline定位，不得累计漂移；" +
                    $"vsync={current.VsyncOrdinal}, expected={expectedIndex}, " +
                    $"actual={current.DisplayedFrameIndex}");
            }

            foreach (var longHoldFrameIndex in Enumerable.Range(0, holdTicks.Length)
                         .Where(index =>
                             StopwatchTicksToMilliseconds(holdTicks[index]) >= 400d))
            {
                var longHoldSamplePositions = firstRun.Samples
                    .Select((sample, sampleIndex) => (sample, sampleIndex))
                    .Where(candidate =>
                        candidate.sample.DisplayedFrameIndex == longHoldFrameIndex)
                    .Select(candidate => candidate.sampleIndex)
                    .ToArray();
                var expectedMinimumSamples = Math.Max(
                    1,
                    (int)Math.Floor(
                        (holdTicks[longHoldFrameIndex] - deadlineToleranceTicks) /
                        (double)Stopwatch.Frequency * refreshRate) - 1);
                Assert(longHoldSamplePositions.Length >= expectedMinimumSamples,
                    $"{label} frame {longHoldFrameIndex} must visibly hold across " +
                    $"{refreshRate:F0}Hz vsync samples; expected at least " +
                    $"{expectedMinimumSamples}, actual={longHoldSamplePositions.Length}");
                Assert(longHoldSamplePositions
                        .Zip(longHoldSamplePositions.Skip(1),
                            (previous, current) => current == previous + 1)
                        .All(isContiguous => isContiguous),
                    $"{label} frame {longHoldFrameIndex} hold samples must be contiguous");
            }

            var refreshIntervalTicks = (long)Math.Ceiling(
                Stopwatch.Frequency / refreshRate);
            Assert(firstRun.CompletionElapsedTicks + deadlineToleranceTicks >= totalHoldTicks &&
                   firstRun.CompletionElapsedTicks - totalHoldTicks <= refreshIntervalTicks,
                $"{label}在{refreshRate:F0}Hz的生产绝对时间轴完成误差不得超过一个vsync");

            var stallRun = RunProductionVsyncStall(
                window,
                clip,
                refreshRate,
                holdTicks,
                deadlineToleranceTicks,
                preStallElapsedTicks);
            Assert(stallRun.StalledFrameIndex > stallRun.BeforeFrameIndex &&
                   stallRun.NextFrameIndex >= stallRun.StalledFrameIndex,
                $"{label}在{refreshRate:F2}Hz遇到250ms阻塞时，单次回调必须跳到最终姿势，" +
                    "下一vsync不得快速补播积压帧");
            Console.WriteLine(
                $"[METRIC] {label} vsync={refreshRate:F2}Hz: " +
                $"callbacks={firstRun.Samples.Length - 1}, " +
                $"completion={StopwatchTicksToMilliseconds(firstRun.CompletionElapsedTicks):F3}ms, " +
                $"stallAt={StopwatchTicksToMilliseconds(stallRun.StallElapsedTicks):F3}ms, " +
                $"stall={stallRun.BeforeFrameIndex}->{stallRun.StalledFrameIndex}" +
                $"->{stallRun.NextFrameIndex}");
        }

        RestoreIdleAfterClipClockSimulation(window);
    }

    private static VsyncClipRun RunProductionVsyncClip(
        MainWindow window,
        object clip,
        double refreshRate,
        IReadOnlyList<long> holdTicks,
        long totalHoldTicks)
    {
        var frames = GetClipFrames(clip);
        var startedAt = StopwatchTicksFromSeconds(30);
        PrepareProductionClipClockSimulation(window, clip, frames, startedAt, holdTicks[0]);

        var samples = new List<VsyncClipSample>(frames.Length * 3);
        samples.Add(new VsyncClipSample(0, 0, 0));
        var previousRenderingTime = TimeSpan.Zero;
        var maximumVsyncCount = checked(
            (int)Math.Ceiling(totalHoldTicks / (double)Stopwatch.Frequency * refreshRate * 1.05) + 4);
        long completionElapsedTicks = -1;
        for (var vsyncOrdinal = 1; vsyncOrdinal <= maximumVsyncCount; vsyncOrdinal++)
        {
            var elapsedStopwatchTicks = (long)Math.Round(
                vsyncOrdinal * Stopwatch.Frequency / refreshRate);
            var renderingTime = TimeSpan.FromTicks((long)Math.Round(
                vsyncOrdinal * TimeSpan.TicksPerSecond / refreshRate));
            var displayedFrameIndex = AdvanceProductionClipAtSyntheticVsync(
                window,
                clip,
                frames,
                startedAt,
                elapsedStopwatchTicks,
                previousRenderingTime,
                renderingTime);
            samples.Add(new VsyncClipSample(
                vsyncOrdinal,
                elapsedStopwatchTicks,
                displayedFrameIndex));
            previousRenderingTime = renderingTime;
            if (displayedFrameIndex == frames.Length)
            {
                completionElapsedTicks = elapsedStopwatchTicks;
                break;
            }
        }

        Assert(completionElapsedTicks >= 0,
            $"{refreshRate:F2}Hz离散vsync必须在测试上限内完成动作");
        CleanupProductionClipClockSimulation(window);
        return new VsyncClipRun(samples.ToArray(), completionElapsedTicks);
    }

    private static VsyncStallRun RunProductionVsyncStall(
        MainWindow window,
        object clip,
        double refreshRate,
        IReadOnlyList<long> holdTicks,
        long deadlineToleranceTicks,
        long preStallElapsedTicks)
    {
        var frames = GetClipFrames(clip);
        var startedAt = StopwatchTicksFromSeconds(30);
        PrepareProductionClipClockSimulation(window, clip, frames, startedAt, holdTicks[0]);
        var previousRenderingTime = TimeSpan.Zero;
        var previousElapsedStopwatchTicks = 0L;
        var preStallVsyncCount = Math.Max(
            1,
            (int)Math.Floor(
                preStallElapsedTicks / (double)Stopwatch.Frequency * refreshRate));
        for (var vsyncOrdinal = 1; vsyncOrdinal <= preStallVsyncCount; vsyncOrdinal++)
        {
            previousElapsedStopwatchTicks = (long)Math.Round(
                vsyncOrdinal * Stopwatch.Frequency / refreshRate);
            var renderingTime = TimeSpan.FromTicks((long)Math.Round(
                vsyncOrdinal * TimeSpan.TicksPerSecond / refreshRate));
            _ = AdvanceProductionClipAtSyntheticVsync(
                window,
                clip,
                frames,
                startedAt,
                previousElapsedStopwatchTicks,
                previousRenderingTime,
                renderingTime);
            previousRenderingTime = renderingTime;
        }

        var beforeFrameIndex = GetDisplayedClipFrameIndex(window, clip, frames);
        var beforeDeadline = GetField<long>(window, "_activeFrameDeadlineTimestamp");
        var stallElapsedTicks = checked(
            previousElapsedStopwatchTicks + StopwatchTicksFromMilliseconds(250));
        var stallRenderingTime = previousRenderingTime + TimeSpan.FromMilliseconds(250);
        var expectedFromCurrentTimeline = ResolveFrameIndexFromProductionDeadline(
            holdTicks,
            beforeFrameIndex,
            beforeDeadline,
            startedAt + stallElapsedTicks,
            deadlineToleranceTicks);
        var expectedFromAbsoluteTimeline = ResolveAbsoluteFrameIndexAtStopwatchTicks(
            holdTicks,
            stallElapsedTicks,
            deadlineToleranceTicks);
        Assert(expectedFromCurrentTimeline == expectedFromAbsoluteTimeline,
            $"{refreshRate:F2}Hz在阻塞前的健康vsync不得积累足以改变姿势的deadline漂移");

        var stalledFrameIndex = AdvanceProductionClipAtSyntheticVsync(
            window,
            clip,
            frames,
            startedAt,
            stallElapsedTicks,
            previousRenderingTime,
            stallRenderingTime);
        Assert(stalledFrameIndex == expectedFromAbsoluteTimeline,
            $"{refreshRate:F2}Hz的250ms阻塞后必须由一次生产AdvanceActiveClip直接落到" +
            $"绝对姿势{expectedFromAbsoluteTimeline}，实际{stalledFrameIndex}");

        SetField(window, "_synchronizeActiveClipToRenderingCadence", false);
        Invoke(window, "AdvanceActiveClip", startedAt + stallElapsedTicks);
        Assert(GetDisplayedClipFrameIndex(window, clip, frames) == stalledFrameIndex,
            $"{refreshRate:F2}Hz同一绝对时间重复调用不得推进或补播第二个姿势");

        var nextElapsedTicks = checked(
            stallElapsedTicks + (long)Math.Round(Stopwatch.Frequency / refreshRate));
        var nextRenderingTime = stallRenderingTime + TimeSpan.FromTicks((long)Math.Round(
            TimeSpan.TicksPerSecond / refreshRate));
        var nextFrameIndex = AdvanceProductionClipAtSyntheticVsync(
            window,
            clip,
            frames,
            startedAt,
            nextElapsedTicks,
            stallRenderingTime,
            nextRenderingTime);
        var expectedNextFrameIndex = ResolveAbsoluteFrameIndexAtStopwatchTicks(
            holdTicks,
            nextElapsedTicks,
            deadlineToleranceTicks);
        Assert(nextFrameIndex == expectedNextFrameIndex,
            $"{refreshRate:F2}Hz阻塞后的下一正常vsync仍须回到绝对时间姿势，" +
            $"expected={expectedNextFrameIndex}, actual={nextFrameIndex}");

        CleanupProductionClipClockSimulation(window);
        return new VsyncStallRun(
            beforeFrameIndex,
            stalledFrameIndex,
            nextFrameIndex,
            stallElapsedTicks);
    }

    private static int AdvanceProductionClipAtSyntheticVsync(
        MainWindow window,
        object clip,
        Array frames,
        long startedAt,
        long elapsedStopwatchTicks,
        TimeSpan previousRenderingTime,
        TimeSpan renderingTime)
    {
        var synchronizeToCadence = (bool)InvokeStatic(
            typeof(MainWindow),
            "ShouldSynchronizeActiveClipToRenderingCadence",
            renderingTime - previousRenderingTime)!;
        SetField(window, "_synchronizeActiveClipToRenderingCadence", synchronizeToCadence);
        try
        {
            Invoke(window, "AdvanceActiveClip", checked(startedAt + elapsedStopwatchTicks));
        }
        finally
        {
            SetField(window, "_synchronizeActiveClipToRenderingCadence", false);
        }

        var nextBlendDuration = GetRawField(window, "_nextFrameBlendDuration");
        Assert(!GetField<bool>(window, "_isFrameBlending") &&
               GetRawField(window, "_pendingSpriteFrame") is null &&
               (nextBlendDuration is null ||
                nextBlendDuration is TimeSpan { Ticks: 0 }),
            "绝对时间轴在正常vsync或250ms stall后必须直接显示正确姿势，" +
            "不得启动整图淡化或留下逐帧补播队列");

        var displayedFrameIndex = GetDisplayedClipFrameIndex(window, clip, frames);
        if (displayedFrameIndex < frames.Length)
        {
            AssertDisplayedClipFrame(window, frames, displayedFrameIndex);
        }
        else
        {
            Assert(!ReferenceEquals(GetRawField(window, "_activeClip"), clip),
                "绝对时间轴到达片段末尾后必须完成该片段；最终静态画面由各片段自己的完成逻辑决定");
        }
        return displayedFrameIndex;
    }

    private static void PrepareProductionClipClockSimulation(
        MainWindow window,
        object clip,
        Array frames,
        long startedAt,
        long firstHoldTicks)
    {
        PauseSpritePageWarmupForClockSimulation(window);
        Invoke(window, "StopVisualClock");
        GetField<DispatcherTimer>(window, "_automaticTimer").Stop();
        Invoke(window, "StopFrameBlend", false);
        Invoke(window, "ClearResidentSpritePages");
        SetField(window, "_edgeRoamPreloadRequested", true);
        SetField(window, "_activeClip", clip);
        GetField<HashSet<string>>(window, "_pinnedSpritePageNames")
            .UnionWith(frames
                .Cast<object>()
                .Select(frame => GetProperty<object>(frame, "Image"))
                .Select(frame => GetSpriteFrameInfo(frame).PageName));
        PrimeAllClipPagesForTest(window, frames);
        var firstSpriteFrame = GetProperty<object>(frames.GetValue(0)!, "Image");
        PrimeSpritePageForFrame(window, firstSpriteFrame);
        SetField(window, "_pendingSpriteFrame", null);
        SetField(window, "_pendingSpriteFrameBlendDuration", TimeSpan.Zero);
        SetField(window, "_nextFrameBlendDuration", TimeSpan.Zero);
        Invoke(window, "ShowStableFrame", firstSpriteFrame);
        Invoke(window, "ClearDeferredActiveClipClock");
        SetField(window, "_bubbleMode", GetNestedEnum("BubbleMode", "None"));
        SetField(window, "_activeFrameIndex", 0);
        SetField(window, "_activeClipStartedTimestamp", startedAt);
        SetField(window, "_activeFrameDeadlineTimestamp", checked(startedAt + firstHoldTicks));
        SetField(window, "_synchronizeActiveClipToRenderingCadence", false);
    }

    private static void PauseSpritePageWarmupForClockSimulation(MainWindow window)
    {
        SetField(window, "_spritePageWarmupEnabled", false);
        SetField(window, "_desiredSpritePageName", null);
        SetField(window, "_desiredSpritePageUrgent", false);
        SetField(
            window,
            "_spritePagePrefetchGeneration",
            GetField<int>(window, "_spritePagePrefetchGeneration") + 1);
        Invoke(window, "RequestSpritePagePrefetchCancellation");

        var deadline = Stopwatch.StartNew();
        while (GetRawField(window, "_spritePagePrefetchTask") is not null &&
               deadline.Elapsed < TimeSpan.FromSeconds(10))
        {
            PumpDispatcher(TimeSpan.FromMilliseconds(5));
            Thread.Yield();
        }

        Assert(GetRawField(window, "_spritePagePrefetchTask") is null,
            "离散vsync测试开始前必须停止顺序预热，避免测试同步装载与后台解码竞争");
    }

    private static void CleanupProductionClipClockSimulation(MainWindow window)
    {
        GetField<DispatcherTimer>(window, "_automaticTimer").Stop();
        SetField(window, "_activeClip", null);
        SetField(window, "_activeFrameIndex", -1);
        SetField(window, "_activeClipStartedTimestamp", 0L);
        SetField(window, "_activeFrameDeadlineTimestamp", 0L);
        SetField(window, "_synchronizeActiveClipToRenderingCadence", false);
        SetField(window, "_lastVisualRenderingTime", TimeSpan.MinValue);
        SetField(window, "_edgeRoamPreloadRequested", false);
        var pinnedPageNames = GetField<HashSet<string>>(
            window,
            "_pinnedSpritePageNames");
        pinnedPageNames.IntersectWith(
            GetExpectedPinnedSpritePageNames(window));
        Invoke(window, "ClearDeferredActiveClipClock");
        Invoke(window, "StopVisualClock");
        Invoke(window, "TrimResidentSpritePagesToBudget", (object?)null);
        AssertResidentSpriteCacheAccounting(window, "离散vsync片段清理");
    }

    private static void RestoreIdleAfterClipClockSimulation(MainWindow window)
    {
        CleanupProductionClipClockSimulation(window);
        var idleFrame = GetField<object>(window, "_idleFrame");
        PrimeSpritePageForFrame(window, idleFrame);
        SetField(window, "_nextFrameBlendDuration", TimeSpan.Zero);
        Invoke(window, "ShowStableFrame", idleFrame);
    }

    private static void PrimeAllClipPagesForTest(MainWindow window, Array frames)
    {
        var primedPageNames = new HashSet<string>(StringComparer.Ordinal);
        foreach (var frame in frames.Cast<object>())
        {
            var spriteFrame = GetProperty<object>(frame, "Image");
            if (primedPageNames.Add(GetSpriteFrameInfo(spriteFrame).PageName))
            {
                PrimeSpritePageForFrame(window, spriteFrame);
            }
        }
    }

    private static int GetDisplayedClipFrameIndex(
        MainWindow window,
        object clip,
        Array frames)
    {
        if (!ReferenceEquals(GetRawField(window, "_activeClip"), clip))
        {
            return frames.Length;
        }

        return GetField<int>(window, "_activeFrameIndex");
    }

    private static void AssertDisplayedClipFrame(
        MainWindow window,
        Array frames,
        int displayedFrameIndex)
    {
        var expectedFrameIndex = Math.Min(displayedFrameIndex, frames.Length - 1);
        var expectedSpriteFrame = GetProperty<object>(
            frames.GetValue(expectedFrameIndex)!,
            "Image");
        Assert(Equals(GetRawField(window, "_currentSpriteFrame"), expectedSpriteFrame),
            $"生产AdvanceActiveClip索引{displayedFrameIndex}必须与实际显示的SpriteFrame一致");
    }

    private static int ResolveAbsoluteFrameIndexAtStopwatchTicks(
        IReadOnlyList<long> holdTicks,
        long elapsedStopwatchTicks,
        long deadlineToleranceTicks)
    {
        var deadline = 0L;
        for (var frameIndex = 0; frameIndex < holdTicks.Count; frameIndex++)
        {
            deadline = checked(deadline + holdTicks[frameIndex]);
            if (elapsedStopwatchTicks < deadline - deadlineToleranceTicks)
            {
                return frameIndex;
            }
        }

        return holdTicks.Count;
    }

    private static int ResolveFrameIndexFromProductionDeadline(
        IReadOnlyList<long> holdTicks,
        int currentFrameIndex,
        long currentDeadline,
        long timestamp,
        long deadlineToleranceTicks)
    {
        var resolvedFrameIndex = currentFrameIndex;
        var deadline = currentDeadline;
        while (timestamp >= deadline - deadlineToleranceTicks)
        {
            var nextFrameIndex = resolvedFrameIndex + 1;
            if (nextFrameIndex >= holdTicks.Count)
            {
                return holdTicks.Count;
            }

            resolvedFrameIndex = nextFrameIndex;
            deadline = checked(deadline + holdTicks[nextFrameIndex]);
        }

        return resolvedFrameIndex;
    }

    private static int ResolveProductionClipFrameIndex(
        MainWindow window,
        object clip,
        long elapsedTicks)
    {
        var frames = GetClipFrames(clip);
        if (frames.Length == 0)
        {
            return 0;
        }

        var firstFrame = frames.GetValue(0)!;
        var firstSpriteFrame = GetProperty<object>(firstFrame, "Image");
        SetField(window, "_edgeRoamPreloadRequested", true);
        var pinnedPageNames = GetField<HashSet<string>>(
            window,
            "_pinnedSpritePageNames");
        pinnedPageNames.UnionWith(frames
            .Cast<object>()
            .Select(frame => GetProperty<object>(frame, "Image"))
            .Select(frame => GetSpriteFrameInfo(frame).PageName));
        PrimeAllClipPagesForTest(window, frames);
        PrimeSpritePageForFrame(window, firstSpriteFrame);
        Invoke(window, "ShowStableFrame", firstSpriteFrame);
        Invoke(window, "ClearDeferredActiveClipClock");

        var startedAt = Stopwatch.GetTimestamp() + Stopwatch.Frequency;
        var firstHoldTicks = ToProductionCharacterAnimationTicks(
            GetFrameDuration(firstFrame));
        SetField(window, "_activeClip", clip);
        SetField(window, "_activeFrameIndex", 0);
        SetField(window, "_activeClipStartedTimestamp", startedAt);
        SetField(window, "_activeFrameDeadlineTimestamp", startedAt + firstHoldTicks);
        Invoke(window, "AdvanceActiveClip", startedAt + Math.Max(0, elapsedTicks));

        var resolvedIndex = GetField<int>(window, "_activeFrameIndex");
        if (resolvedIndex < 0)
        {
            resolvedIndex = frames.Length;
        }

        SetField(window, "_activeClip", null);
        SetField(window, "_activeFrameIndex", -1);
        SetField(window, "_activeClipStartedTimestamp", 0L);
        SetField(window, "_activeFrameDeadlineTimestamp", 0L);
        SetField(window, "_edgeRoamPreloadRequested", false);
        pinnedPageNames.IntersectWith(
            GetExpectedPinnedSpritePageNames(window));
        Invoke(window, "ClearDeferredActiveClipClock");
        Invoke(window, "TrimResidentSpritePagesToBudget", (object?)null);
        Invoke(window, "UpdateVisualClockSubscription");
        return resolvedIndex;
    }

    private static void AssertMainRenderingTimeDedupContract(MainWindow window)
    {
        var clip = GetField<Array>(window, "_reactionClips").GetValue(0)!;
        var frames = GetClipFrames(clip);
        var firstHoldTicks = ToProductionCharacterAnimationTicks(
            GetFrameDuration(frames.GetValue(0)!));
        foreach (var refreshRate in new[] { 59d, 60d, 120d, 144d })
        {
            var startedAt = Stopwatch.GetTimestamp();
            PrepareProductionClipClockSimulation(
                window,
                clip,
                frames,
                startedAt,
                firstHoldTicks);
            SetField(window, "_activeFrameDeadlineTimestamp", long.MaxValue);
            SetField(window, "_lastVisualRenderingTime", TimeSpan.MinValue);
            var renderingTime = TimeSpan.FromSeconds(10);
            Invoke(
                window,
                "VisualClock_Rendering",
                null,
                CreateRenderingEventArgs(renderingTime));
            Assert(GetField<int>(window, "_activeFrameIndex") == 0,
                $"{refreshRate:F2}Hz VisualClock基准回调不得在首个RenderingTime提前推进");

            SetField(
                window,
                "_activeFrameDeadlineTimestamp",
                Stopwatch.GetTimestamp() - firstHoldTicks * 2);
            Invoke(
                window,
                "VisualClock_Rendering",
                null,
                CreateRenderingEventArgs(renderingTime));
            Assert(GetField<int>(window, "_activeFrameIndex") == 0,
                $"{refreshRate:F2}Hz相同RenderingTime重复回调必须被VisualClock去重");

            Invoke(
                window,
                "VisualClock_Rendering",
                null,
                CreateRenderingEventArgs(
                    renderingTime + TimeSpan.FromSeconds(1d / refreshRate)));
            var displayedFrameIndex = GetField<int>(window, "_activeFrameIndex");
            Assert(displayedFrameIndex >= 2,
                $"{refreshRate:F0}Hz真实VisualClock不得把1.25倍动画锁成一回调一姿势；" +
                "过期deadline应在一次回调直接定位最终姿势");

            AssertDisplayedClipFrame(window, frames, displayedFrameIndex);
            CleanupProductionClipClockSimulation(window);
        }

        RestoreIdleAfterClipClockSimulation(window);
    }

    private static void AssertRenderingCadenceClassificationContract(
        string mainWindowSource)
    {
        foreach (var refreshRate in new[] { 59d, 60d, 120d, 144d })
        {
            var shouldLock = (bool)InvokeStatic(
                typeof(MainWindow),
                "ShouldSynchronizeActiveClipToRenderingCadence",
                TimeSpan.FromSeconds(1d / refreshRate))!;
            Assert(!shouldLock,
                $"{refreshRate:F0}Hz不得把1.25倍代码速度误锁成一回调一姿势，" +
                "必须保持ToCharacterAnimationTicks绝对时间轴");
        }

        foreach (var refreshRate in new[] { 59d, 59.94d, 60d })
        {
            var shouldSynchronizeEdgePeek = (bool)InvokeStatic(
                typeof(MainWindow),
                "ShouldSynchronizeEdgePeekToRenderingCadence",
                TimeSpan.FromSeconds(1d / refreshRate))!;
            Assert(shouldSynchronizeEdgePeek,
                $"{refreshRate:F2}Hz必须启用边缘探头逐合成同步，避免原生60fps姿势漏帧");
        }

        foreach (var refreshRate in new[] { 120d, 144d })
        {
            var shouldSynchronizeEdgePeek = (bool)InvokeStatic(
                typeof(MainWindow),
                "ShouldSynchronizeEdgePeekToRenderingCadence",
                TimeSpan.FromSeconds(1d / refreshRate))!;
            Assert(!shouldSynchronizeEdgePeek,
                $"{refreshRate:F0}Hz边缘探头必须保留绝对deadline模型");
        }

        var shouldSynchronizeAfterGap = (bool)InvokeStatic(
            typeof(MainWindow),
            "ShouldSynchronizeEdgePeekToRenderingCadence",
            TimeSpan.FromMilliseconds(250))!;
        Assert(!shouldSynchronizeAfterGap,
            "250ms合成gap不得误判为健康近60Hz节拍");

        var edgeCadenceHelperSource = ExtractPrivateMethodSource(
            mainWindowSource,
            "ShouldSynchronizeEdgePeekToRenderingCadence");
        Assert(!edgeCadenceHelperSource.Contains(
                   "AnimationPlaybackSpeed",
                   StringComparison.Ordinal),
            "边缘探头节拍分类必须独立于全局点击动作AnimationPlaybackSpeed");
    }

    private static int ResolveAbsoluteFrameIndex(IReadOnlyList<TimeSpan> durations, TimeSpan elapsed)
    {
        var cursor = TimeSpan.Zero;
        for (var index = 0; index < durations.Count; index++)
        {
            cursor += durations[index];
            if (elapsed < cursor)
            {
                return index;
            }
        }

        return durations.Count;
    }

    private static double SnapForSimulation(double value, double dpiScale) =>
        Math.Round(value * dpiScale, MidpointRounding.AwayFromZero) / dpiScale;

    private static double IntegrateBoundedMovement(double elapsedSeconds, double speed) =>
        elapsedSeconds is > 0 and <= 0.250 ? elapsedSeconds * speed : 0;

    private static long StopwatchTicksFromMilliseconds(double milliseconds) =>
        (long)Math.Round(milliseconds * Stopwatch.Frequency / 1000d);

    private static long ToProductionCharacterAnimationTicks(TimeSpan baseDuration) =>
        (long)(InvokeStatic(
            typeof(MainWindow),
            "ToCharacterAnimationTicks",
            baseDuration) ?? throw new InvalidOperationException(
            "生产ToCharacterAnimationTicks未返回运行时截止点"));

    private static long ToProductionStopwatchTicks(TimeSpan duration) =>
        (long)(InvokeStatic(
            typeof(MainWindow),
            "ToStopwatchTicks",
            duration) ?? throw new InvalidOperationException(
            "生产ToStopwatchTicks未返回运行时截止点"));

    private static void AdvanceEdgePeekForControlledClock(
        MainWindow window,
        long timestamp)
    {
        // Production sleeps the compositor subscription during long endpoint
        // holds. Deterministic clock tests stop that wake timer before manually
        // supplying their synthetic absolute timestamp.
        GetField<DispatcherTimer>(window, "_edgePeekHoldTimer").Stop();
        Invoke(window, "AdvanceEdgePeek", timestamp);
        Invoke(window, "UpdateVisualClockSubscription");
    }

    private static double StopwatchTicksToMilliseconds(long ticks) =>
        ticks * 1000d / Stopwatch.Frequency;

    private static void AssertEdgeRoamingRouteMathContract()
    {
        // A negative-coordinate secondary monitor exercises the same geometry
        // used by per-monitor DPI layouts without requiring a physical second
        // display on the test machine.
        var routeBounds = new Rect(-2548, -168, 2346, 1174);
        var radius = (double)InvokeStatic(
            typeof(MainWindow),
            "GetEdgeRoamCornerRadius",
            routeBounds)!;
        var routeLength = (double)InvokeStatic(
            typeof(MainWindow),
            "GetEdgeRoamRouteLength",
            routeBounds,
            radius)!;
        var horizontal = routeBounds.Width - radius * 2;
        var vertical = routeBounds.Height - radius * 2;
        var quarterArc = Math.PI * radius / 2;
        Assert(radius > 0 &&
               radius <= Math.Min(routeBounds.Width, routeBounds.Height) / 2,
            $"熊猫坐骑圆角半径必须适配当前副屏工作区，实际 {radius:F3}");
        AssertClose(
            routeLength,
            horizontal * 2 + vertical * 2 + Math.PI * radius * 2,
            "熊猫坐骑完整一圈必须覆盖四条直线和四个圆角且只计算一次");

        var checkpoints = new[]
        {
            (
                Distance: 0d,
                Expected: new Point(routeBounds.Left + radius, routeBounds.Top),
                Stage: "顶部左侧起点"),
            (
                Distance: horizontal,
                Expected: new Point(routeBounds.Right - radius, routeBounds.Top),
                Stage: "顶部右圆角入口"),
            (
                Distance: horizontal + quarterArc,
                Expected: new Point(routeBounds.Right, routeBounds.Top + radius),
                Stage: "右边直线入口"),
            (
                Distance: horizontal + quarterArc + vertical,
                Expected: new Point(routeBounds.Right, routeBounds.Bottom - radius),
                Stage: "右下圆角入口"),
            (
                Distance: horizontal + quarterArc * 2 + vertical,
                Expected: new Point(routeBounds.Right - radius, routeBounds.Bottom),
                Stage: "底边右侧入口"),
            (
                Distance: horizontal * 2 + quarterArc * 2 + vertical,
                Expected: new Point(routeBounds.Left + radius, routeBounds.Bottom),
                Stage: "左下圆角入口"),
            (
                Distance: horizontal * 2 + quarterArc * 3 + vertical,
                Expected: new Point(routeBounds.Left, routeBounds.Bottom - radius),
                Stage: "左边直线入口"),
            (
                Distance: horizontal * 2 + quarterArc * 3 + vertical * 2,
                Expected: new Point(routeBounds.Left, routeBounds.Top + radius),
                Stage: "左上圆角入口")
        };
        foreach (var checkpoint in checkpoints)
        {
            var actual = (Point)InvokeStatic(
                typeof(MainWindow),
                "GetEdgeRoamRoutePoint",
                routeBounds,
                radius,
                checkpoint.Distance)!;
            AssertClose(actual.X, checkpoint.Expected.X, $"{checkpoint.Stage} X");
            AssertClose(actual.Y, checkpoint.Expected.Y, $"{checkpoint.Stage} Y");
            Assert(actual.X >= routeBounds.Left - 0.01 &&
                   actual.X <= routeBounds.Right + 0.01 &&
                   actual.Y >= routeBounds.Top - 0.01 &&
                   actual.Y <= routeBounds.Bottom + 0.01,
                $"{checkpoint.Stage}不得离开当前显示器独立WorkArea路线");
        }

        var start = (Point)InvokeStatic(
            typeof(MainWindow),
            "GetEdgeRoamRoutePoint",
            routeBounds,
            radius,
            0d)!;
        var completedLap = (Point)InvokeStatic(
            typeof(MainWindow),
            "GetEdgeRoamRoutePoint",
            routeBounds,
            radius,
            routeLength)!;
        var reverseLap = (Point)InvokeStatic(
            typeof(MainWindow),
            "GetEdgeRoamRoutePoint",
            routeBounds,
            radius,
            -routeLength)!;
        AssertClose(completedLap.X, start.X, "顺时针整圈必须回到同一逻辑X");
        AssertClose(completedLap.Y, start.Y, "顺时针整圈必须回到同一逻辑Y");
        AssertClose(reverseLap.X, start.X, "逆时针整圈必须回到同一逻辑X");
        AssertClose(reverseLap.Y, start.Y, "逆时针整圈必须回到同一逻辑Y");

        var topMiddle = new Point(
            routeBounds.Left + radius + horizontal / 2,
            routeBounds.Top);
        var rightMiddle = new Point(
            routeBounds.Right,
            routeBounds.Top + radius + vertical / 2);
        var bottomMiddle = new Point(
            routeBounds.Left + radius + horizontal / 2,
            routeBounds.Bottom);
        var leftMiddle = new Point(
            routeBounds.Left,
            routeBounds.Top + radius + vertical / 2);
        AssertClose(
            ResolveProductionEdgeRoamFacing(
                topMiddle,
                new Point(topMiddle.X + 2, topMiddle.Y),
                routeBounds,
                radius),
            1,
            "顶部向右移动时左朝向原画必须镜像");
        AssertClose(
            ResolveProductionEdgeRoamFacing(
                topMiddle,
                new Point(topMiddle.X - 2, topMiddle.Y),
                routeBounds,
                radius),
            -1,
            "顶部向左移动时左朝向原画必须保持原向");
        AssertClose(
            ResolveProductionEdgeRoamFacing(
                bottomMiddle,
                new Point(bottomMiddle.X - 2, bottomMiddle.Y),
                routeBounds,
                radius),
            1,
            "底部向左移动时左朝向原画必须保持原向");
        AssertClose(
            ResolveProductionEdgeRoamFacing(
                bottomMiddle,
                new Point(bottomMiddle.X + 2, bottomMiddle.Y),
                routeBounds,
                radius),
            -1,
            "底部向右移动时左朝向原画必须镜像");
        AssertClose(
            ResolveProductionEdgeRoamFacing(
                leftMiddle,
                new Point(leftMiddle.X, leftMiddle.Y - 2),
                routeBounds,
                radius),
            1,
            "左侧向上时必须保持原镜像，使头向跟随运动且人物上方朝屏幕内部");
        AssertClose(
            ResolveProductionEdgeRoamFacing(
                leftMiddle,
                new Point(leftMiddle.X, leftMiddle.Y + 2),
                routeBounds,
                radius),
            -1,
            "左侧向下时必须镜像，使头向跟随运动且人物上方朝屏幕内部");
        AssertClose(
            ResolveProductionEdgeRoamFacing(
                rightMiddle,
                new Point(rightMiddle.X, rightMiddle.Y + 2),
                routeBounds,
                radius),
            1,
            "右侧向下时必须保持原镜像，使头向跟随运动且人物上方朝屏幕内部");
        AssertClose(
            ResolveProductionEdgeRoamFacing(
                rightMiddle,
                new Point(rightMiddle.X, rightMiddle.Y - 2),
                routeBounds,
                radius),
            -1,
            "右侧向上时必须镜像，使头向跟随运动且人物上方朝屏幕内部");
    }

    private static void AssertEdgeRoamRotationContract()
    {
        var routeBounds = new Rect(-1600, 0, 1600, 960);
        var radius = (double)InvokeStatic(
            typeof(MainWindow),
            "GetEdgeRoamCornerRadius",
            routeBounds)!;
        var left = new Point(-1600, 480);
        var right = new Point(0, 480);
        var verticalCases = new[]
        {
            (
                Position: left,
                LookAhead: new Point(left.X, left.Y - 2),
                ExpectedScaleX: 1d,
                ExpectedAngle: 90d,
                ExpectedHeading: new Vector(0, -1),
                ExpectedUp: new Vector(1, 0),
                Stage: "左侧向上"),
            (
                Position: right,
                LookAhead: new Point(right.X, right.Y - 2),
                ExpectedScaleX: -1d,
                ExpectedAngle: -90d,
                ExpectedHeading: new Vector(0, -1),
                ExpectedUp: new Vector(-1, 0),
                Stage: "右侧向上"),
            (
                Position: left,
                LookAhead: new Point(left.X, left.Y + 2),
                ExpectedScaleX: -1d,
                ExpectedAngle: 90d,
                ExpectedHeading: new Vector(0, 1),
                ExpectedUp: new Vector(1, 0),
                Stage: "左侧向下"),
            (
                Position: right,
                LookAhead: new Point(right.X, right.Y + 2),
                ExpectedScaleX: 1d,
                ExpectedAngle: -90d,
                ExpectedHeading: new Vector(0, 1),
                ExpectedUp: new Vector(-1, 0),
                Stage: "右侧向下")
        };
        foreach (var edgeCase in verticalCases)
        {
            var scaleX = ResolveProductionEdgeRoamFacing(
                edgeCase.Position,
                edgeCase.LookAhead,
                routeBounds,
                radius);
            var angle = ResolveProductionEdgeRoamRotation(
                edgeCase.Position,
                edgeCase.LookAhead,
                routeBounds,
                scaleX,
                0);
            AssertClose(
                scaleX,
                edgeCase.ExpectedScaleX,
                $"{edgeCase.Stage}镜像符号");
            AssertClose(
                angle,
                edgeCase.ExpectedAngle,
                $"{edgeCase.Stage}必须使用与镜像组合正确的竖边旋转角");
            var transformedHeading = TransformAuthoredRoamHeading(
                scaleX,
                angle);
            var transformedUp = TransformAuthoredRoamUp(
                scaleX,
                angle);
            AssertClose(
                transformedHeading.X,
                edgeCase.ExpectedHeading.X,
                $"{edgeCase.Stage}变换后的头向 X");
            AssertClose(
                transformedHeading.Y,
                edgeCase.ExpectedHeading.Y,
                $"{edgeCase.Stage}变换后的头向 Y 必须指向运动方向");
            AssertClose(
                transformedUp.X,
                edgeCase.ExpectedUp.X,
                $"{edgeCase.Stage}变换后人物上方 X 必须朝屏幕内部");
            AssertClose(
                transformedUp.Y,
                edgeCase.ExpectedUp.Y,
                $"{edgeCase.Stage}变换后人物上方 Y");
        }

        var negativeMonitorOffset = new Vector(-2880, -800);
        var translatedRouteBounds = new Rect(
            routeBounds.X + negativeMonitorOffset.X,
            routeBounds.Y + negativeMonitorOffset.Y,
            routeBounds.Width,
            routeBounds.Height);
        foreach (var edgeCase in verticalCases)
        {
            var translatedPosition =
                edgeCase.Position + negativeMonitorOffset;
            var translatedLookAhead =
                edgeCase.LookAhead + negativeMonitorOffset;
            var scaleX = ResolveProductionEdgeRoamFacing(
                translatedPosition,
                translatedLookAhead,
                translatedRouteBounds,
                radius);
            var angle = ResolveProductionEdgeRoamRotation(
                translatedPosition,
                translatedLookAhead,
                translatedRouteBounds,
                scaleX,
                -edgeCase.ExpectedAngle);
            AssertClose(
                scaleX,
                edgeCase.ExpectedScaleX,
                $"{edgeCase.Stage}平移到负坐标副屏后镜像不得变化");
            AssertClose(
                angle,
                edgeCase.ExpectedAngle,
                $"{edgeCase.Stage}平移到负坐标副屏后角度不得变化");
            var transformedHeading = TransformAuthoredRoamHeading(
                scaleX,
                angle);
            var transformedUp = TransformAuthoredRoamUp(
                scaleX,
                angle);
            AssertClose(
                transformedHeading.X,
                edgeCase.ExpectedHeading.X,
                $"{edgeCase.Stage}负坐标副屏头向 X");
            AssertClose(
                transformedHeading.Y,
                edgeCase.ExpectedHeading.Y,
                $"{edgeCase.Stage}负坐标副屏头向 Y");
            AssertClose(
                transformedUp.X,
                edgeCase.ExpectedUp.X,
                $"{edgeCase.Stage}负坐标副屏人物上方 X");
            AssertClose(
                transformedUp.Y,
                edgeCase.ExpectedUp.Y,
                $"{edgeCase.Stage}负坐标副屏人物上方 Y");
        }

        var top = new Point(routeBounds.Left + routeBounds.Width / 2, routeBounds.Top);
        var bottom = new Point(
            routeBounds.Left + routeBounds.Width / 2,
            routeBounds.Bottom);
        var horizontalCases = new[]
        {
            (
                Position: bottom,
                LookAhead: bottom + new Vector(2, 0),
                ScaleX: -1d,
                ExpectedAngle: 0d,
                ExpectedHeading: new Vector(1, 0),
                ExpectedUp: new Vector(0, -1),
                Stage: "bottom moving right"),
            (
                Position: bottom,
                LookAhead: bottom + new Vector(-2, 0),
                ScaleX: 1d,
                ExpectedAngle: 0d,
                ExpectedHeading: new Vector(-1, 0),
                ExpectedUp: new Vector(0, -1),
                Stage: "bottom moving left"),
            (
                Position: top,
                LookAhead: top + new Vector(2, 0),
                ScaleX: 1d,
                ExpectedAngle: 180d,
                ExpectedHeading: new Vector(1, 0),
                ExpectedUp: new Vector(0, 1),
                Stage: "top moving right"),
            (
                Position: top,
                LookAhead: top + new Vector(-2, 0),
                ScaleX: -1d,
                ExpectedAngle: 180d,
                ExpectedHeading: new Vector(-1, 0),
                ExpectedUp: new Vector(0, 1),
                Stage: "top moving left")
        };
        foreach (var edgeCase in horizontalCases)
        {
            var scaleX = ResolveProductionEdgeRoamFacing(
                edgeCase.Position,
                edgeCase.LookAhead,
                routeBounds,
                radius);
            var angle = ResolveProductionEdgeRoamRotation(
                edgeCase.Position,
                edgeCase.LookAhead,
                routeBounds,
                scaleX,
                edgeCase.ExpectedAngle);
            AssertClose(
                scaleX,
                edgeCase.ScaleX,
                $"{edgeCase.Stage} mirror");
            AssertClose(
                angle,
                edgeCase.ExpectedAngle,
                $"{edgeCase.Stage} must keep the edge under the feet");
            var transformedHeading = TransformAuthoredRoamHeading(
                scaleX,
                angle);
            var transformedUp = TransformAuthoredRoamUp(scaleX, angle);
            AssertClose(
                transformedHeading.X,
                edgeCase.ExpectedHeading.X,
                $"{edgeCase.Stage} heading X");
            AssertClose(
                transformedHeading.Y,
                edgeCase.ExpectedHeading.Y,
                $"{edgeCase.Stage} heading Y");
            AssertClose(
                transformedUp.X,
                edgeCase.ExpectedUp.X,
                $"{edgeCase.Stage} inward-up X");
            AssertClose(
                transformedUp.Y,
                edgeCase.ExpectedUp.Y,
                $"{edgeCase.Stage} inward-up Y");
        }

        var routeLength = (double)InvokeStatic(
            typeof(MainWindow),
            "GetEdgeRoamRouteLength",
            routeBounds,
            radius)!;
        const int sampleCount = 512;
        foreach (var direction in new[] { 1, -1 })
        {
            var previousAngle = direction > 0 ? 179d : -179d;
            double? firstAngle = null;
            for (var sample = 0; sample <= sampleCount; sample++)
            {
                var directedDistance =
                    direction * routeLength * sample / sampleCount;
                var position = (Point)InvokeStatic(
                    typeof(MainWindow),
                    "GetEdgeRoamRoutePoint",
                    routeBounds,
                    radius,
                    directedDistance)!;
                var lookAhead = (Point)InvokeStatic(
                    typeof(MainWindow),
                    "GetEdgeRoamRoutePoint",
                    routeBounds,
                    radius,
                    directedDistance + direction)!;
                var scaleX = ResolveProductionEdgeRoamFacing(
                    position,
                    lookAhead,
                    routeBounds,
                    radius);
                var angle = ResolveProductionEdgeRoamRotation(
                    position,
                    lookAhead,
                    routeBounds,
                    scaleX,
                    previousAngle);
                firstAngle ??= angle;
                Assert(
                    Math.Abs(angle - previousAngle) < 20,
                    $"rounded-corner rotation must stay unwrapped and continuous; " +
                    $"direction={direction}, sample={sample}, previous={previousAngle:F3}, actual={angle:F3}");
                AssertClose(
                    scaleX,
                    direction > 0 ? 1 : -1,
                    $"reverse route must be the exact mirror at sample {sample}");

                var motion = lookAhead - position;
                motion.Normalize();
                var heading = TransformAuthoredRoamHeading(scaleX, angle);
                Assert(
                    Vector.Multiply(heading, motion) > 0.999,
                    $"character heading must follow route tangent at sample {sample}");

                var expectedUp = GetExpectedEdgeRoamInwardNormal(
                    position,
                    routeBounds,
                    radius);
                var transformedUp = TransformAuthoredRoamUp(scaleX, angle);
                Assert(
                    Vector.Multiply(transformedUp, expectedUp) > 0.999,
                    $"all four edges and rounded corners must remain ground at sample {sample}");
                previousAngle = angle;
            }

            AssertClose(
                previousAngle - firstAngle!.Value,
                direction * 360,
                $"a complete {(direction > 0 ? "clockwise" : "counter-clockwise")} lap must unwrap by one turn");
        }

        var straightenDuration =
            (TimeSpan)(typeof(MainWindow).GetField(
                "EdgeRoamDisembarkStraightenDuration",
                StaticFlags)!.GetValue(null) ??
                throw new InvalidOperationException(
                    "找不到退场转正时长"));
        var halfDurationSeconds =
            straightenDuration.TotalSeconds / 2;
        AssertClose(
            ResolveProductionEdgeRoamDisembarkRotation(90, 0),
            90,
            "竖边退场第一帧必须保留完整旋转，不得直接清零");
        AssertClose(
            ResolveProductionEdgeRoamDisembarkRotation(
                90,
                halfDurationSeconds),
            45,
            "正角竖边退场中点必须平滑转正");
        AssertClose(
            ResolveProductionEdgeRoamDisembarkRotation(
                -90,
                halfDurationSeconds),
            -45,
            "负角竖边退场中点必须平滑转正");
        AssertClose(
            ResolveProductionEdgeRoamDisembarkRotation(
                90,
                straightenDuration.TotalSeconds),
            0,
            "竖边退场达到转正时长后必须回到零度");
        AssertClose(
            ResolveProductionEdgeRoamDisembarkRotation(270, 0),
            270,
            "disembark must not clamp a continuous-lap angle into [-90,90]");
        AssertClose(
            ResolveProductionEdgeRoamDisembarkRotation(
                270,
                halfDurationSeconds),
            315,
            "270 degrees must straighten toward its nearest 360-degree upright");
        AssertClose(
            ResolveProductionEdgeRoamDisembarkRotation(
                270,
                straightenDuration.TotalSeconds),
            360,
            "270 degrees must finish at the equivalent 360-degree upright");
        AssertClose(
            ResolveProductionEdgeRoamDisembarkRotation(
                450,
                halfDurationSeconds),
            405,
            "450 degrees must take the short path back to 360 degrees");
        AssertClose(
            ResolveProductionEdgeRoamDisembarkRotation(
                -270,
                halfDurationSeconds),
            -315,
            "negative unwrapped angles must take the mirrored short path");
        AssertClose(
            ResolveProductionEdgeRoamDisembarkRotation(
                -270,
                straightenDuration.TotalSeconds),
            -360,
            "negative unwrapped angles must finish at the equivalent upright");

        AssertEdgeRoamSupportAnchorContract();
    }

    private static Vector GetExpectedEdgeRoamInwardNormal(
        Point position,
        Rect routeBounds,
        double radius)
    {
        var cornerCenter = new Point(
            Math.Clamp(
                position.X,
                routeBounds.Left + radius,
                routeBounds.Right - radius),
            Math.Clamp(
                position.Y,
                routeBounds.Top + radius,
                routeBounds.Bottom - radius));
        var inward = cornerCenter - position;
        if (inward.LengthSquared > 1e-9)
        {
            inward.Normalize();
            return inward;
        }

        var candidates = new[]
        {
            (
                Distance: Math.Abs(position.Y - routeBounds.Top),
                Normal: new Vector(0, 1)),
            (
                Distance: Math.Abs(routeBounds.Right - position.X),
                Normal: new Vector(-1, 0)),
            (
                Distance: Math.Abs(routeBounds.Bottom - position.Y),
                Normal: new Vector(0, -1)),
            (
                Distance: Math.Abs(position.X - routeBounds.Left),
                Normal: new Vector(1, 0))
        };
        return candidates.MinBy(candidate => candidate.Distance).Normal;
    }

    private static void AssertEdgeRoamSupportAnchorContract()
    {
        const double displayedWidth = 190;
        const double displayedHeight = 242;
        const double originXRatio = 0.5;
        const double originYRatio = 0.5371900826446281;
        const double supportAnchorYRatio = 457d / 509d;
        var origin = new Point(
            displayedWidth * originXRatio,
            displayedHeight * originYRatio);
        var authoredSupport = new Point(
            displayedWidth * 0.5,
            displayedHeight * supportAnchorYRatio);
        var supportDelta = authoredSupport - origin;
        var supportCases = new[]
        {
            (
                Angle: 0d,
                SupportScreen: new Point(460.25, 900.75),
                Edge: "bottom"),
            (
                Angle: 90d,
                SupportScreen: new Point(-1588.25, 420.75),
                Edge: "left"),
            (
                Angle: 180d,
                SupportScreen: new Point(460.25, 12.75),
                Edge: "top"),
            (
                Angle: -90d,
                SupportScreen: new Point(-12.25, 420.75),
                Edge: "right")
        };

        var window = new MainWindow
        {
            Left = 0,
            Top = 0,
            ShowActivated = false
        };
        SetField(window, "_petSizeScale", 1d);
        foreach (var supportCase in supportCases)
        {
            var radians = supportCase.Angle * Math.PI / 180;
            var expectedOffset = new Point(
                origin.X +
                supportDelta.X * Math.Cos(radians) -
                supportDelta.Y * Math.Sin(radians),
                origin.Y +
                supportDelta.X * Math.Sin(radians) +
                supportDelta.Y * Math.Cos(radians));
            var actualOffset = (Point)InvokeStatic(
                typeof(MainWindow),
                "GetEdgeRoamSupportOffset",
                displayedWidth,
                displayedHeight,
                supportCase.Angle)!;
            AssertClose(
                actualOffset.X,
                expectedOffset.X,
                $"{supportCase.Edge} support-anchor X");
            AssertClose(
                actualOffset.Y,
                expectedOffset.Y,
                $"{supportCase.Edge} support-anchor Y");

            SetField(
                window,
                "_edgeRoamRotationDegrees",
                supportCase.Angle);
            var visibleBoundsBefore = (Rect)Invoke(
                window,
                "GetPetViewboxBoundsInScreenDips")!;
            var visibleOffsetX = visibleBoundsBefore.Left - window.Left;
            var visibleOffsetY = visibleBoundsBefore.Top - window.Top;
            Invoke(
                window,
                "ApplyEdgeRoamingPosition",
                supportCase.SupportScreen.X,
                supportCase.SupportScreen.Y);
            var logicalLeft = GetField<double>(
                window,
                "_edgeRoamLogicalLeft");
            var logicalTop = GetField<double>(
                window,
                "_edgeRoamLogicalTop");
            AssertClose(
                logicalLeft,
                supportCase.SupportScreen.X -
                expectedOffset.X -
                visibleOffsetX,
                $"{supportCase.Edge} support-screen to Left conversion");
            AssertClose(
                logicalTop,
                supportCase.SupportScreen.Y -
                expectedOffset.Y -
                visibleOffsetY,
                $"{supportCase.Edge} support-screen to Top conversion");
            AssertClose(
                logicalLeft + visibleOffsetX + actualOffset.X,
                supportCase.SupportScreen.X,
                $"{supportCase.Edge} transformed 457/509 foot X contact");
            AssertClose(
                logicalTop + visibleOffsetY + actualOffset.Y,
                supportCase.SupportScreen.Y,
                $"{supportCase.Edge} transformed 457/509 foot Y contact");
            Assert(
                Math.Abs(window.Left - logicalLeft) <= 0.5 &&
                Math.Abs(window.Top - logicalTop) <= 0.5,
                $"{supportCase.Edge} Left/Top may only differ from logical support placement by pixel snapping");
        }
    }

    private static Vector TransformAuthoredRoamHeading(
        double scaleX,
        double rotationDegrees)
        => TransformAuthoredRoamVector(
            new Vector(-1, 0),
            scaleX,
            rotationDegrees);

    private static Vector TransformAuthoredRoamUp(
        double scaleX,
        double rotationDegrees)
        => TransformAuthoredRoamVector(
            new Vector(0, -1),
            scaleX,
            rotationDegrees);

    private static Vector TransformAuthoredRoamVector(
        Vector authoredVector,
        double scaleX,
        double rotationDegrees)
    {
        var transform = new TransformGroup();
        transform.Children.Add(new ScaleTransform(scaleX, 1));
        transform.Children.Add(new RotateTransform(rotationDegrees));
        var transformed = transform.Value.Transform(authoredVector);
        transformed.Normalize();
        return transformed;
    }

    private static double ResolveProductionEdgeRoamRotation(
        Point position,
        Point lookAhead,
        Rect routeBounds,
        double facingScaleX,
        double currentRotationDegrees) =>
        (double)(InvokeStatic(
            typeof(MainWindow),
            "ResolveEdgeRoamRotationDegrees",
            position,
            lookAhead,
            routeBounds,
            facingScaleX,
            currentRotationDegrees) ?? throw new InvalidOperationException(
            "生产绕屏旋转函数未返回角度"));

    private static double ResolveProductionEdgeRoamDisembarkRotation(
        double startRotationDegrees,
        double elapsedSeconds) =>
        (double)(InvokeStatic(
            typeof(MainWindow),
            "ResolveEdgeRoamDisembarkRotationDegrees",
            startRotationDegrees,
            elapsedSeconds) ?? throw new InvalidOperationException(
            "生产绕屏退场转正函数未返回角度"));

    private static double ResolveProductionEdgeRoamFacing(
        Point position,
        Point lookAhead,
        Rect routeBounds,
        double radius) =>
        (double)(InvokeStatic(
            typeof(MainWindow),
            "ResolveEdgeRoamFacingScaleX",
            position,
            lookAhead,
            routeBounds,
            radius,
            1d) ?? throw new InvalidOperationException(
            "生产绕屏朝向函数未返回缩放值"));

    private static void AssertEdgeRoamInteractionContract(MainWindow window)
    {
        if (!window.IsVisible)
        {
            window.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(40));
        }

        var todoWindow = GetField<TodoWindow>(window, "_todoWindow");
        var petHost = GetField<FrameworkElement>(window, "PetHost");
        var petSizeViewbox = GetField<Viewbox>(window, "PetSizeViewbox");
        var monitorWorkAreaType = typeof(MainWindow).Assembly.GetType(
            "LubanDesktopPet.MonitorWorkArea",
            throwOnError: true)!;
        var idleFrame = GetRawField(window, "_idleFrame")
            ?? throw new InvalidOperationException("找不到待机帧");
        var boardingFrames = GetField<Array>(window, "_roamBoardingFrames");
        var flightFrames = GetField<Array>(window, "_roamFlightFrames");
        var flightFrame = flightFrames.GetValue(0)
            ?? throw new InvalidOperationException("找不到熊猫巡游首帧");
        var travelingPhase = GetNestedEnum("EdgeRoamPhase", "Traveling");
        var noneBubbleMode = GetNestedEnum("BubbleMode", "None");
        Point? nativePointerScreenPoint = new Point(-1400, 260);
        Func<Point?> nativePointerProvider = () => nativePointerScreenPoint;
        SetField(
            window,
            "_pointerScreenPointProviderForTesting",
            nativePointerProvider);

        Assert(!(bool)InvokeStatic(
                   typeof(MainWindow),
                   "HasExceededPetDragThreshold",
                   new Point(20, 30),
                   new Point(68, 74),
                   new Point(-1400, 260),
                   new Point(-1400, 260),
                   new Vector(1.5, 1.5),
                   false,
                   4d,
                   4d)! &&
               !(bool)InvokeStatic(
                   typeof(MainWindow),
                   "HasExceededPetDragThreshold",
                   new Point(20, 30),
                   new Point(20, 30),
                   new Point(-1400, 260),
                   new Point(-1394.1, 260),
                   new Vector(1.5, 1.5),
                   false,
                   4d,
                   4d)! &&
               (bool)InvokeStatic(
                   typeof(MainWindow),
                   "HasExceededPetDragThreshold",
                   new Point(20, 30),
                   new Point(20, 30),
                   new Point(-1400, 260),
                   new Point(-1394, 260),
                   new Vector(1.5, 1.5),
                   false,
                   4d,
                   4d)!,
            "拖动阈值必须锁定按下时DPI并使用物理屏幕位移；" +
            "HWND转正造成的局部坐标漂移不得冒充鼠标拖动");

        void PrepareTravelState(Point startPoint, Point currentPoint, double rotation)
        {
            Invoke(window, "CancelTodoOpenAfterEdgeRoamStop");
            Invoke(window, "SetBubbleMode", noneBubbleMode);
            Invoke(window, "ExitEdgePeek", false, true);
            PrimeSpritePageForFrame(window, flightFrame);
            Invoke(window, "ShowStableFrame", flightFrame);
            SetField(window, "_activeClip", null);
            SetField(window, "_isEdgeRoaming", true);
            SetField(window, "_edgeRoamPhase", travelingPhase);
            SetField(window, "_edgeRoamStartPoint", startPoint);
            SetField(window, "_edgeRoamCurrentSupportPoint", currentPoint);
            SetField(window, "_edgeRoamDisembarkSupportPoint", startPoint);
            SetField(window, "_edgeRoamCurrentSupportPointValid", true);
            SetField(window, "_edgeRoamStopScheduleNext", false);
            SetField(window, "_edgeRoamStopInterrupted", false);
            SetField(window, "_edgeRoamBoardingReverse", false);
            SetField(window, "_edgeRoamRotationDegrees", rotation);
            GetField<RotateTransform>(window, "PetRoamRotate").Angle = rotation;
        }

        var firstSupportPoint = new Point(window.Left + 148, window.Top + 203);
        PrepareTravelState(
            new Point(firstSupportPoint.X - 500, firstSupportPoint.Y - 300),
            firstSupportPoint,
            90);
        foreach (var boardingFrame in boardingFrames.Cast<object>()
                     .GroupBy(frame => GetSpriteFrameInfo(frame).PageName)
                     .Select(group => group.First()))
        {
            PrimeSpritePageForFrame(window, boardingFrame);
        }
        var leftBefore = window.Left;
        var topBefore = window.Top;
        var leftDown = new MouseButtonEventArgs(
            Mouse.PrimaryDevice,
            Environment.TickCount,
            MouseButton.Left)
        {
            RoutedEvent = UIElement.MouseLeftButtonDownEvent,
            Source = petHost
        };
        Invoke(window, "PetHost_MouseLeftButtonDown", petHost, leftDown);
        var pointerDownLocal = GetField<Point>(
            window,
            "_pointerDownPosition");
        var pointerDownScreen = GetField<Point>(
            window,
            "_pointerDownScreenPosition");
        Invoke(window, "MoveMainWindowTo", leftBefore + 48, topBefore + 48);
        var locallyDriftedPosition = new Point(
            pointerDownLocal.X + 48,
            pointerDownLocal.Y + 48);
        var authoritativeStationaryPoint = (Point)Invoke(
            window,
            "GetPointerScreenPointOrFallback",
            locallyDriftedPosition,
            pointerDownScreen,
            false)!;
        var stationaryRoamDragStarted = (bool)Invoke(
            window,
            "TryBeginPetPointerDrag",
            locallyDriftedPosition,
            authoritativeStationaryPoint)!;
        nativePointerScreenPoint = null;
        var failedNativePoint = (Point)Invoke(
            window,
            "GetPointerScreenPointOrFallback",
            locallyDriftedPosition,
            pointerDownScreen,
            false)!;
        var failedNativeRoamDragStarted = (bool)Invoke(
            window,
            "TryBeginPetPointerDrag",
            locallyDriftedPosition,
            failedNativePoint)!;
        nativePointerScreenPoint = pointerDownScreen;
        Invoke(window, "MoveMainWindowTo", leftBefore, topBefore);
        Assert(leftDown.Handled &&
               !stationaryRoamDragStarted &&
               !failedNativeRoamDragStarted &&
               authoritativeStationaryPoint == pointerDownScreen &&
               failedNativePoint == pointerDownScreen &&
               GetField<bool>(window, "_isEdgeRoaming") &&
               GetField<object>(window, "_edgeRoamPhase").ToString() == "Disembarking" &&
               GetField<bool>(window, "_pointerDown") &&
               !GetField<bool>(window, "_dragStarted") &&
               GetField<Point>(window, "_edgeRoamDisembarkSupportPoint") == firstSupportPoint &&
               Math.Abs(window.Left - leftBefore) <= 0.01 &&
               Math.Abs(window.Top - topBefore) <= 0.01 &&
               GetField<bool>(window, "_suppressClickReactionAfterRoamInterruption"),
            "巡游中左键按下必须在最后呈现支撑点原地开始退场，不能立即硬切或跳回路线起点");

        var leftUp = new MouseButtonEventArgs(
            Mouse.PrimaryDevice,
            Environment.TickCount,
            MouseButton.Left)
        {
            RoutedEvent = UIElement.MouseLeftButtonUpEvent,
            Source = petHost
        };
        Invoke(window, "PetHost_MouseLeftButtonUp", petHost, leftUp);
        Assert(leftUp.Handled &&
               GetField<bool>(window, "_isEdgeRoaming") &&
               GetField<object>(window, "_edgeRoamPhase").ToString() == "Disembarking" &&
               !GetField<bool>(window, "_pointerDown") &&
               !GetField<bool>(window, "_dragStarted"),
            "巡游点击抬起时即使退场尚未播完，也不得被移动中的HWND误判为拖动");
        var disembarkResidentBytesBefore = GetField<long>(
            window,
            "_residentSpritePageBytes");
        var disembarkResidentNamesBefore = GetDictionaryEntries(
                GetField<IDictionary>(window, "_residentSpritePages"))
            .Select(entry => (string)entry.Key)
            .ToHashSet(StringComparer.Ordinal);
        var naturalDisembarkStart = Stopwatch.GetTimestamp();
        SetField(window, "_isInsideVisualRenderingCallback", true);
        try
        {
            for (var refresh = 0;
                 refresh < 180 && GetField<bool>(window, "_isEdgeRoaming");
                 refresh++)
            {
                Invoke(
                    window,
                    "AdvanceEdgeRoaming",
                    checked(
                        naturalDisembarkStart +
                        refresh * Stopwatch.Frequency / 60));
            }
        }
        finally
        {
            SetField(window, "_isInsideVisualRenderingCallback", false);
        }
        var immediateIdleTrimTimer = GetField<DispatcherTimer>(
            window,
            "_spritePageIdleTrimTimer");
        Assert(leftUp.Handled &&
               !GetField<bool>(window, "_isEdgeRoaming") &&
               GetField<object>(window, "_edgeDock").ToString() == "None" &&
               GetRawField(window, "_activeClip") is null &&
               Equals(GetRawField(window, "_currentSpriteFrame"), idleFrame) &&
               !todoWindow.IsVisible &&
               !GetField<bool>(window, "_suppressClickReactionAfterRoamInterruption") &&
               immediateIdleTrimTimer.IsEnabled &&
               immediateIdleTrimTimer.Interval == TimeSpan.Zero &&
               GetField<long>(window, "_residentSpritePageBytes") ==
               disembarkResidentBytesBefore &&
               disembarkResidentNamesBefore.SetEquals(
                   GetDictionaryEntries(
                           GetField<IDictionary>(window, "_residentSpritePages"))
                       .Select(entry => (string)entry.Key)),
            "巡游中左键单击完成退场后必须稳定待机，不能追加四种点击动作或打开任务面板：" +
            $"roaming={GetField<bool>(window, "_isEdgeRoaming")}, " +
            $"phase={GetField<object>(window, "_edgeRoamPhase")}, " +
            $"dock={GetField<object>(window, "_edgeDock")}, " +
            $"active={GetRawField(window, "_activeClip") is not null}, " +
            $"idle={Equals(GetRawField(window, "_currentSpriteFrame"), idleFrame)}, " +
            $"todo={todoWindow.IsVisible}, suppress=" +
            GetField<bool>(window, "_suppressClickReactionAfterRoamInterruption") +
            $", pagesReady={GetField<bool>(window, "_edgeRoamBoardingPagesReady")}, " +
            $"clock={GetField<bool>(window, "_edgeRoamClockStarted")}, " +
            $"startIndex={GetField<int>(window, "_edgeRoamBoardingStartIndex")}, " +
            $"current={GetSpriteFrameInfo(GetField<object>(window, "_currentSpriteFrame")).Name}");
        Invoke(window, "StopIdleSpritePageTrim");

        var dragSupportPoint = new Point(window.Left + 228, window.Top + 188);
        PrepareTravelState(
            new Point(dragSupportPoint.X - 360, dragSupportPoint.Y + 240),
            dragSupportPoint,
            90);
        var petHostCenter = petHost.PointToScreen(
            new Point(
                Math.Max(1, petHost.ActualWidth) / 2,
                Math.Max(1, petHost.ActualHeight) / 2));
        nativePointerScreenPoint = petHostCenter;
        var dragDown = new MouseButtonEventArgs(
            Mouse.PrimaryDevice,
            Environment.TickCount,
            MouseButton.Left)
        {
            RoutedEvent = UIElement.MouseLeftButtonDownEvent,
            Source = petHost
        };
        Invoke(window, "PetHost_MouseLeftButtonDown", petHost, dragDown);
        var dragDownLocal = GetField<Point>(window, "_pointerDownPosition");
        var dragDownScreen = GetField<Point>(window, "_pointerDownScreenPosition");
        var pixelsPerDip = GetField<Vector>(window, "_pointerDownPixelsPerDip");
        var physicalThreshold = Math.Ceiling(
            SystemParameters.MinimumHorizontalDragDistance *
            Math.Max(1d, pixelsPerDip.X));
        nativePointerScreenPoint = new Point(
            dragDownScreen.X + physicalThreshold,
            dragDownScreen.Y);
        var authoritativeMovedPoint = (Point)Invoke(
            window,
            "GetPointerScreenPointOrFallback",
            dragDownLocal,
            dragDownScreen,
            false)!;
        var physicalRoamDragStarted = (bool)Invoke(
            window,
            "TryBeginPetPointerDrag",
            dragDownLocal,
            authoritativeMovedPoint)!;
        Assert(dragDown.Handled &&
               physicalRoamDragStarted &&
               GetField<bool>(window, "_dragStarted") &&
               !GetField<bool>(window, "_isEdgeRoaming") &&
               Math.Abs(authoritativeMovedPoint.X - dragDownScreen.X -
                        physicalThreshold) <= 0.01,
            "巡游手势必须忽略 HWND 造成的局部坐标漂移，但 Win32 光标真的越过" +
            "按下时 DPI 对应的物理阈值后仍要立即交给拖动。");
        Invoke(window, "CompleteDirectPetDrag", false);

        // Exercise the production MouseUp path without an intervening
        // MouseMove. Windows can coalesce a fast press-move-release, so the
        // release sample itself must still cross the physical threshold,
        // transfer ownership to direct dragging, and run release docking.
        var releaseOnlyOriginalLeft = window.Left;
        var releaseOnlyOriginalTop = window.Top;
        var releaseOnlySupportPoint = new Point(
            window.Left + 238,
            window.Top + 198);
        PrepareTravelState(
            new Point(
                releaseOnlySupportPoint.X - 420,
                releaseOnlySupportPoint.Y + 220),
            releaseOnlySupportPoint,
            90);
        nativePointerScreenPoint = petHost.PointToScreen(
            new Point(
                Math.Max(1, petHost.ActualWidth) / 2,
                Math.Max(1, petHost.ActualHeight) / 2));
        var releaseOnlyDown = new MouseButtonEventArgs(
            Mouse.PrimaryDevice,
            Environment.TickCount,
            MouseButton.Left)
        {
            RoutedEvent = UIElement.MouseLeftButtonDownEvent,
            Source = petHost
        };
        Invoke(
            window,
            "PetHost_MouseLeftButtonDown",
            petHost,
            releaseOnlyDown);
        var releaseOnlyDownScreen = GetField<Point>(
            window,
            "_pointerDownScreenPosition");
        var releaseOnlyPixelsPerDip = GetField<Vector>(
            window,
            "_pointerDownPixelsPerDip");
        var releaseOnlyWorkArea = (Rect)InvokeStatic(
            monitorWorkAreaType,
            "GetForVisual",
            window,
            petSizeViewbox)!;
        var releaseOnlyBounds = (Rect)Invoke(
            window,
            "GetPetViewboxBoundsInScreenDips")!;
        var releaseOnlyMinimumPhysicalThreshold = Math.Ceiling(
            SystemParameters.MinimumVerticalDragDistance *
            Math.Max(1d, releaseOnlyPixelsPerDip.Y));
        var releaseOnlyPhysicalDeltaY = Math.Ceiling(
            Math.Max(
                SystemParameters.MinimumVerticalDragDistance + 1,
                releaseOnlyWorkArea.Bottom -
                releaseOnlyBounds.Bottom + 24) *
            Math.Max(1d, releaseOnlyPixelsPerDip.Y));
        nativePointerScreenPoint = new Point(
            releaseOnlyDownScreen.X,
            releaseOnlyDownScreen.Y + releaseOnlyPhysicalDeltaY);
        var releaseOnlyUp = new MouseButtonEventArgs(
            Mouse.PrimaryDevice,
            Environment.TickCount,
            MouseButton.Left)
        {
            RoutedEvent = UIElement.MouseLeftButtonUpEvent,
            Source = petHost
        };
        Invoke(
            window,
            "PetHost_MouseLeftButtonUp",
            petHost,
            releaseOnlyUp);
        var releaseOnlyDockedBounds = (Rect)Invoke(
            window,
            "GetPetViewboxBoundsInScreenDips")!;
        Assert(releaseOnlyDown.Handled && releaseOnlyUp.Handled &&
               releaseOnlyPhysicalDeltaY >=
               releaseOnlyMinimumPhysicalThreshold &&
               !GetField<bool>(window, "_dragStarted") &&
               !GetField<bool>(window, "_dragInteractionActive") &&
               !GetField<bool>(window, "_pointerDown") &&
               !GetField<bool>(window, "_isEdgeRoaming") &&
               GetField<object>(window, "_edgeDock").ToString() == "Bottom" &&
               !GetField<bool>(
                   window,
                   "_suppressClickReactionAfterRoamInterruption") &&
               !petHost.IsMouseCaptured &&
               Math.Abs(
                   releaseOnlyDockedBounds.Bottom -
                   releaseOnlyWorkArea.Bottom) <= 1.01,
            "A roaming press/release with no MouseMove must use the native " +
            "MouseUp point for the final physical threshold check, complete " +
            "direct dragging, and dock at Bottom without becoming a click. " +
            $"delta={releaseOnlyPhysicalDeltaY:F0}, " +
            $"threshold={releaseOnlyMinimumPhysicalThreshold:F0}, " +
            $"dock={GetField<object>(window, "_edgeDock")}, " +
            $"bottom={releaseOnlyDockedBounds.Bottom:F2}/" +
            $"{releaseOnlyWorkArea.Bottom:F2}");
        Invoke(window, "ExitEdgePeek", false, true);
        Invoke(
            window,
            "MoveMainWindowTo",
            releaseOnlyOriginalLeft,
            releaseOnlyOriginalTop);

        var secondSupportPoint = new Point(window.Left + 310, window.Top + 126);
        PrepareTravelState(
            new Point(secondSupportPoint.X + 640, secondSupportPoint.Y + 420),
            secondSupportPoint,
            -90);
        var rightUp = new MouseButtonEventArgs(
            Mouse.PrimaryDevice,
            Environment.TickCount,
            MouseButton.Right)
        {
            RoutedEvent = UIElement.MouseRightButtonUpEvent,
            Source = petHost
        };
        Invoke(window, "PetHost_MouseRightButtonUp", petHost, rightUp);
        Assert(rightUp.Handled &&
               GetField<bool>(window, "_isEdgeRoaming") &&
               GetField<object>(window, "_edgeRoamPhase").ToString() == "Disembarking" &&
               GetField<Point>(window, "_edgeRoamDisembarkSupportPoint") == secondSupportPoint &&
               GetField<bool>(window, "_openTodoAfterEdgeRoamStopRequested") &&
               !todoWindow.IsVisible,
            "巡游中右键必须先在当前位置平滑退场，退场完成前不得抢先显示待办窗口");

        Invoke(window, "CompleteEdgeRoamStop", true);
        Assert(!todoWindow.IsVisible &&
               GetField<bool>(window, "_todoOpenAfterEdgeRoamStopQueued"),
            "退场完成时只能排队一次待办打开请求，不能在Rendering回调内同步Show");
        PumpDispatcher(TimeSpan.FromMilliseconds(50));
        var todoPage = GetField<Grid>(todoWindow, "TodoPage");
        Assert(todoWindow.IsVisible &&
               todoPage.Visibility == Visibility.Visible &&
               GetField<object>(window, "_bubbleMode").ToString() == "Todo" &&
               !GetField<bool>(window, "_todoOpenAfterEdgeRoamStopQueued") &&
               !GetField<bool>(window, "_openTodoAfterEdgeRoamStopRequested"),
            "巡游中右键退场后必须只打开一次默认待办页，并清除所有延迟意图");

        Invoke(window, "SetBubbleMode", noneBubbleMode);
        SetField(window, "_pointerScreenPointProviderForTesting", null);
        PumpDispatcher(TimeSpan.FromMilliseconds(20));
    }

    private static void AssertExactEdgeContactContract()
    {
        var workArea = new Rect(0, 0, 1920, 1080);
        var activationDistance = (double)(typeof(MainWindow).GetField(
                "EdgeDockActivationDistance",
                StaticFlags)!.GetValue(null) ?? double.NaN);
        const double width = 190;
        const double height = 242;
        const double safeX = 500;
        const double safeY = 300;
        AssertClose(
            activationDistance,
            12,
            "手动边缘吸附必须提供 12 DIP 的可命中磁吸区，不能退回 ±1 DIP 的像素窄带");

        var cases = new[]
        {
            new EdgeCase(
                "Left",
                new Rect(activationDistance + 0.1, safeY, width, height),
                new Rect(activationDistance, safeY, width, height)),
            new EdgeCase(
                "Right",
                new Rect(
                    workArea.Right - width - activationDistance - 0.1,
                    safeY,
                    width,
                    height),
                new Rect(
                    workArea.Right - width - activationDistance,
                    safeY,
                    width,
                    height)),
            new EdgeCase(
                "Bottom",
                new Rect(
                    safeX,
                    workArea.Bottom - height - activationDistance - 0.1,
                    width,
                    height),
                new Rect(
                    safeX,
                    workArea.Bottom - height - activationDistance,
                    width,
                    height))
        };

        foreach (var edgeCase in cases)
        {
            var near = InvokeStatic(
                typeof(MainWindow),
                "FindTouchedEdge",
                workArea,
                edgeCase.NearBounds,
                activationDistance)!;
            Assert(near.ToString() == "None",
                $"{edgeCase.Edge} 超出 12 DIP 磁吸区后不得提前吸附");

            var touching = InvokeStatic(
                typeof(MainWindow),
                "FindTouchedEdge",
                workArea,
                edgeCase.TouchingBounds,
                activationDistance)!;
            Assert(touching.ToString() == edgeCase.Edge,
                $"{edgeCase.Edge} 进入 12 DIP 磁吸区时必须稳定吸附");
        }

        var crossedLeft = InvokeStatic(
            typeof(MainWindow),
            "FindTouchedEdge",
            workArea,
            new Rect(-20, safeY, width, height),
            activationDistance)!;
        var fullyOutsideLeft = InvokeStatic(
            typeof(MainWindow),
            "FindTouchedEdge",
            workArea,
            new Rect(-width - 0.1, safeY, width, height),
            activationDistance)!;
        var exactlyOutsideLeft = InvokeStatic(
            typeof(MainWindow),
            "FindTouchedEdge",
            workArea,
            new Rect(-width, safeY, width, height),
            activationDistance)!;
        var crossedRight = InvokeStatic(
            typeof(MainWindow),
            "FindTouchedEdge",
            workArea,
            new Rect(workArea.Right - width + 20, safeY, width, height),
            activationDistance)!;
        var crossedBottom = InvokeStatic(
            typeof(MainWindow),
            "FindTouchedEdge",
            workArea,
            new Rect(
                safeX,
                workArea.Bottom - height + 20,
                width,
                height),
            activationDistance)!;
        var fullyOutsideBottom = InvokeStatic(
            typeof(MainWindow),
            "FindTouchedEdge",
            workArea,
            new Rect(safeX, workArea.Bottom + 0.1, width, height),
            activationDistance)!;
        var exactlyOutsideBottom = InvokeStatic(
            typeof(MainWindow),
            "FindTouchedEdge",
            workArea,
            new Rect(safeX, workArea.Bottom, width, height),
            activationDistance)!;
        Assert(crossedLeft.ToString() == "Left" &&
               crossedRight.ToString() == "Right" &&
               crossedBottom.ToString() == "Bottom" &&
               fullyOutsideLeft.ToString() == "None" &&
               exactlyOutsideLeft.ToString() == "None" &&
               fullyOutsideBottom.ToString() == "None" &&
               exactlyOutsideBottom.ToString() == "None",
            "快速拖动越过外边缘后仍必须吸附，但人物已经完全离开工作区时不得错误夹回");

        var sharedSeamCornerCandidates = ((IEnumerable)InvokeStatic(
                typeof(MainWindow),
                "FindTouchedEdges",
                workArea,
                new Rect(
                    workArea.Right - width - 1,
                    workArea.Bottom - height - 5,
                    width,
                    height),
                activationDistance)!)
            .Cast<object>()
            .Select(candidate => candidate.ToString())
            .ToArray();
        Assert(sharedSeamCornerCandidates.Length >= 2 &&
               sharedSeamCornerCandidates[0] == "Right" &&
               sharedSeamCornerCandidates[1] == "Bottom",
            "双屏共享右缝比底边更近时必须保留 Bottom 作为后备外边缘候选");

        var sweptBottomCandidates = ((IEnumerable)InvokeStatic(
                typeof(MainWindow),
                "FindSweptTouchedEdges",
                workArea,
                new Rect(workArea.Right - width, safeY, width, height),
                new Rect(
                    workArea.Right - width,
                    workArea.Bottom - 1,
                    width,
                    height),
                new Rect(
                    workArea.Right - width + 4,
                    safeY + 40,
                    width - 8,
                    height - 80),
                new Rect(
                    workArea.Right - width + 4,
                    workArea.Bottom + 1,
                    width - 8,
                    height - 80))!)
            .Cast<object>()
            .Select(candidate => candidate.ToString())
            .ToArray();
        Assert(sweptBottomCandidates.SequenceEqual(["Bottom"]),
            "有效拖拽从屏内向下甩过底边时，即使最终可见精灵已完全越界，也必须由扫掠轨迹补回 Bottom 候选");

        var mainSource = File.ReadAllText(FindWorkspaceFile("MainWindow.xaml.cs"));
        var updateDock = ExtractPrivateMethodSource(
            mainSource,
            "UpdateEdgeDockAfterDrag");
        var visibleContact = ExtractPrivateMethodSource(
            mainSource,
            "GetPetContactBounds");
        var visibleContactForFrame = ExtractPrivateMethodSource(
            mainSource,
            "GetPetContactBoundsForFrame");
        var findTouchedEdge = ExtractPrivateMethodSource(
            mainSource,
            "FindTouchedEdge");
        var findTouchedEdges = ExtractPrivateMethodSource(
            mainSource,
            "FindTouchedEdges");
        var monitorSource = File.ReadAllText(
            FindWorkspaceFile("MonitorWorkArea.cs"));
        var externalEdge = ExtractPrivateMethodSource(
            monitorSource,
            "IsExternalWorkAreaEdgeAt");
        Assert(updateDock.Contains(
                   "GetDragReleaseContactBounds(",
                   StringComparison.Ordinal) &&
               updateDock.Contains(
                   "FindSweptTouchedEdges(",
                   StringComparison.Ordinal) &&
               updateDock.Contains(
                   "PrioritizeTouchedEdgesAfterDrag(",
                   StringComparison.Ordinal) &&
               updateDock.Contains(
                   "EdgeDockActivationDistance",
                   StringComparison.Ordinal) &&
               updateDock.Contains(
                   "foreach (var candidate in PrioritizeTouchedEdgesAfterDrag(",
                   StringComparison.Ordinal) &&
               updateDock.Contains(
                   "IsExternalWorkAreaEdgeAt(",
                   StringComparison.Ordinal) &&
               updateDock.Contains(
                   "continue;",
                   StringComparison.Ordinal) &&
               findTouchedEdges.Contains(
                   "candidate.Gap <= activationDistance",
                   StringComparison.Ordinal) &&
               findTouchedEdges.Contains(
                   "candidate.StillVisible",
                   StringComparison.Ordinal) &&
               !findTouchedEdges.Contains(
                   "Math.Abs(candidate.Gap) <= activationDistance",
                   StringComparison.Ordinal) &&
               findTouchedEdge.Contains(
                   ".DefaultIfEmpty(EdgeDock.None)",
                   StringComparison.Ordinal) &&
               visibleContact.Contains(
                   "GetPetContactBoundsForFrame(",
                   StringComparison.Ordinal) &&
               visibleContactForFrame.Contains(
                   "frame.DestinationX",
                   StringComparison.Ordinal) &&
               visibleContactForFrame.Contains(
                   "frame.DestinationY",
                   StringComparison.Ordinal) &&
               externalEdge.Contains(
                   "EnumDisplayMonitors(",
                   StringComparison.Ordinal) &&
               externalEdge.Contains(
                   "hasAdjacentMonitor",
                   StringComparison.Ordinal) &&
               externalEdge.Contains(
                   "return !hasAdjacentMonitor",
                   StringComparison.Ordinal),
            "边缘接触必须使用精灵可见像素边界，并在共享双屏接缝处拒绝假吸附");

        var topCenter = InvokeStatic(
            typeof(MainWindow),
            "FindTouchedEdge",
            workArea,
            new Rect(safeX, 0, width, height),
            activationDistance)!;
        Assert(topCenter.ToString() == "None",
            "顶部中心即使完全接触屏幕边缘也不得吸附或进入探头状态");

        var topLeftCorner = InvokeStatic(
            typeof(MainWindow),
            "FindTouchedEdge",
            workArea,
            new Rect(0, 0, width, height),
            activationDistance)!;
        var topRightCorner = InvokeStatic(
            typeof(MainWindow),
            "FindTouchedEdge",
            workArea,
            new Rect(workArea.Right - width, 0, width, height),
            activationDistance)!;
        Assert(topLeftCorner.ToString() == "Left" &&
               topRightCorner.ToString() == "Right",
            "顶部左右角仍应分别保留左、右吸附");

        foreach (var dpiScale in new[] { 1d, 1.25d, 1.5d })
        {
            var contactTopOffset = Math.Round(314 * dpiScale);
            var pointerOffset = new Vector(
                Math.Round(200 * dpiScale),
                Math.Round(330 * dpiScale));
            var pointerAtTop = new Point(1000, workArea.Top);
            var target = (Point)InvokeStatic(
                typeof(MainWindow),
                "CalculateDirectPetDragPosition",
                pointerAtTop,
                pointerOffset,
                contactTopOffset,
                workArea,
                false)!;
            Assert(Math.Abs(target.Y + contactTopOffset - workArea.Top) <= 0.01,
                $"{dpiScale * 100:0}% DPI 捕获式拖动必须让人物可见像素以物理像素贴到顶沿");

            var reboundPointerOffset = new Vector(
                pointerOffset.X,
                pointerAtTop.Y - target.Y);
            var targetAfterMovingDown = (Point)InvokeStatic(
                typeof(MainWindow),
                "CalculateDirectPetDragPosition",
                new Point(pointerAtTop.X, pointerAtTop.Y + 1),
                reboundPointerOffset,
                contactTopOffset,
                workArea,
                false)!;
            Assert(Math.Abs(
                       targetAfterMovingDown.Y + contactTopOffset -
                       (workArea.Top + 1)) <= 0.01,
                $"{dpiScale * 100:0}% DPI 到顶重锚后向下1像素就必须立即离开，不能粘住");

            var changedFrameContactTopOffset = contactTopOffset + 2;
            var targetAfterFrameContactShift = (Point)InvokeStatic(
                typeof(MainWindow),
                "CalculateDirectPetDragPosition",
                pointerAtTop,
                reboundPointerOffset,
                changedFrameContactTopOffset,
                workArea,
                true)!;
            Assert(Math.Abs(
                       targetAfterFrameContactShift.Y +
                       changedFrameContactTopOffset -
                       workArea.Top) <= 0.01,
                $"{dpiScale * 100:0}% DPI 已触顶时动画帧接触偏移变化仍必须保持0像素贴顶");
        }

        var negativeMonitorWorkArea = new Rect(-2560, -1440, 2560, 1400);
        var negativeTarget = (Point)InvokeStatic(
            typeof(MainWindow),
            "CalculateDirectPetDragPosition",
            new Point(-900, negativeMonitorWorkArea.Top),
            new Vector(180, 340),
            318d,
            negativeMonitorWorkArea,
            false)!;
        Assert(Math.Abs(
                   negativeTarget.Y + 318d -
                   negativeMonitorWorkArea.Top) <= 0.01 &&
               negativeTarget.X == -1080,
            "负坐标副屏必须全程使用物理坐标，顶部可见像素贴边时水平位置不能漂移");

        var dragMoveSource = ExtractPrivateMethodSource(
            mainSource,
            "PetHost_MouseMove");
        var tryBeginDragSource = ExtractPrivateMethodSource(
            mainSource,
            "TryBeginPetPointerDrag");
        var beginDragSource = ExtractPrivateMethodSource(
            mainSource,
            "BeginDirectPetDrag");
        var dragDownSource = ExtractPrivateMethodSource(
            mainSource,
            "PetHost_MouseLeftButtonDown");
        var directMoveSource = ExtractPrivateMethodSource(
            mainSource,
            "ContinueDirectPetDrag");
        var completeDragSource = ExtractPrivateMethodSource(
            mainSource,
            "CompleteDirectPetDrag");
        var physicalPositionerSource = ExtractPrivateMethodSource(
            File.ReadAllText(FindWorkspaceFile("OwnedWindowPositioner.cs")),
            "TrySetPhysicalPosition");
        var physicalWorkAreaSource = ExtractPrivateMethodSource(
            monitorSource,
            "TryGetPhysicalWorkAreaAt");
        var dragOriginCapture = beginDragSource.IndexOf(
            "var dragOriginDock = _edgeDock;",
            StringComparison.Ordinal);
        var edgeExit = beginDragSource.IndexOf(
            "ExitEdgePeek(",
            StringComparison.Ordinal);
        var dragContextCapture = beginDragSource.IndexOf(
            "_edgeDockDragContext = new EdgeDockDragContext(",
            StringComparison.Ordinal);
        var prepareDirectDrag = beginDragSource.IndexOf(
            "TryPrepareDirectPetDragGeometry(",
            StringComparison.Ordinal);
        Assert(dragOriginCapture >= 0 &&
               edgeExit > dragOriginCapture &&
               dragContextCapture > edgeExit &&
               prepareDirectDrag > dragContextCapture &&
               dragMoveSource.Contains(
                   "TryBeginPetPointerDrag(",
                   StringComparison.Ordinal) &&
               tryBeginDragSource.Contains(
                   "BeginDirectPetDrag(",
                   StringComparison.Ordinal) &&
               beginDragSource.Contains(
                   "ContinueDirectPetDrag(",
                   StringComparison.Ordinal) &&
               !beginDragSource.Contains("DragMove(", StringComparison.Ordinal) &&
               directMoveSource.Contains(
                   "TryGetPhysicalBounds(",
                   StringComparison.Ordinal) &&
               directMoveSource.Contains(
                   "TryGetPhysicalWorkAreaAt(",
                   StringComparison.Ordinal) &&
               directMoveSource.Contains(
                   "TrySetPhysicalPosition(",
                   StringComparison.Ordinal) &&
               directMoveSource.Contains(
                   "PointFromScreen(",
                   StringComparison.Ordinal) &&
               directMoveSource.Contains(
                   "_directDragTopClamped",
                   StringComparison.Ordinal) &&
               directMoveSource.Contains(
                   "positionedPhysicalBounds",
                   StringComparison.Ordinal) &&
               !directMoveSource.Contains(
                   "grabScreenPoint",
                   StringComparison.Ordinal) &&
               dragDownSource.Contains(
                   "if (!PetHost.CaptureMouse())",
                   StringComparison.Ordinal) &&
               dragDownSource.Contains(
                   "_dragInteractionActive = false",
                   StringComparison.Ordinal) &&
               dragDownSource.Contains(
                   "RestartAutomaticCountdown()",
                   StringComparison.Ordinal) &&
               !directMoveSource.Contains(
                   "CompositionTarget.Rendering",
                   StringComparison.Ordinal) &&
               completeDragSource.Contains(
                   "UpdateEdgeDockAfterDrag();",
                   StringComparison.Ordinal) &&
               completeDragSource.IndexOf(
                   "UpdateEdgeDockAfterDrag();",
                   StringComparison.Ordinal) <
               completeDragSource.IndexOf(
                   "_edgeDockDragContext = null;",
                   StringComparison.Ordinal) &&
               physicalPositionerSource.Contains(
                   "SetWindowPos(",
                   StringComparison.Ordinal) &&
               !physicalPositionerSource.Contains(
                   "TransformToDevice",
                   StringComparison.Ordinal) &&
               physicalWorkAreaSource.Contains(
                   "MonitorFromPoint(",
                   StringComparison.Ordinal) &&
               physicalWorkAreaSource.Contains(
                   "GetMonitorInfo(",
                   StringComparison.Ordinal),
            "拖动必须保留来源边轨迹、持续捕获鼠标并直接用物理工作区与SetWindowPos移动；不得再交给系统DragMove或渲染时钟");

        var lostCaptureSource = ExtractPrivateMethodSource(
            mainSource,
            "PetHost_LostMouseCapture");
        Assert(lostCaptureSource.Contains(
                   "CompleteDirectPetDrag(",
                   StringComparison.Ordinal) &&
               lostCaptureSource.Contains(
                   "updateEdgeDock: true",
                   StringComparison.Ordinal) &&
               lostCaptureSource.Contains(
                   "if (!_dragInteractionActive)",
                   StringComparison.Ordinal),
            "捕获式拖动意外失去鼠标捕获时必须完成一次释放吸附并清理状态，不能永久卡在拖动中");
    }

    private static void AssertSupportedEdgeDockIntegration(MainWindow window)
    {
        var edgeMotionFrameInterval = (TimeSpan)(typeof(MainWindow).GetField(
                "EdgePeekMotionFrameInterval",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var edgeFullyPeekedHold = (TimeSpan)(typeof(MainWindow).GetField(
                "EdgePeekFullyPeekedHold",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var edgeCycleInterval = (TimeSpan)(typeof(MainWindow).GetField(
                "EdgePeekCycleInterval",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var edgeBlendDuration = (TimeSpan)(typeof(MainWindow).GetField(
                "EdgeFrameBlendDuration",
                StaticFlags)!.GetValue(null) ?? TimeSpan.MinValue);
        Assert(edgeMotionFrameInterval == TimeSpan.FromTicks(TimeSpan.TicksPerSecond / 60) &&
               edgeFullyPeekedHold == TimeSpan.FromMilliseconds(650) &&
               edgeCycleInterval == TimeSpan.FromSeconds(10) &&
               edgeBlendDuration == TimeSpan.Zero &&
               typeof(MainWindow).GetField("EdgePeekFrameInterval", StaticFlags) is null &&
               typeof(MainWindow).GetField("_edgePeekFrameDirection", InstanceFlags) is null,
            "边缘探头必须使用不受全局倍速影响的精确60fps间隔、650ms开心探头、800ms缩回休息、禁用整图淡化，" +
            "并彻底删除70ms及ping-pong方向状态");

        if (!window.IsVisible)
        {
            window.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
        }

        var monitorType = typeof(MainWindow).Assembly.GetType(
            "LubanDesktopPet.MonitorWorkArea",
            throwOnError: true)!;
        AssertWindowBoundaryDockActivation(window, monitorType);
        var petSizeViewbox = GetField<Viewbox>(window, "PetSizeViewbox");
        var workArea = (Rect)InvokeStatic(
            monitorType,
            "GetForVisual",
            window,
            petSizeViewbox)!;
        var visiblePetBounds = (Rect)Invoke(
            window,
            "GetPetViewboxBoundsInScreenDips")!;
        var width = visiblePetBounds.Width;
        var height = visiblePetBounds.Height;
        var safeLeft = workArea.Left + Math.Max(20, (workArea.Width - width) / 2);
        var safeTop = workArea.Top + Math.Max(20, (workArea.Height - height) / 2);

        foreach (var edge in new[] { "Left", "Right", "Bottom" })
        {
            var edgeFrames = edge is "Left" or "Right"
                ? GetField<Array>(window, "_edgeLeftFrames")
                : GetField<Array>(window, "_edgeBottomFrames");
            var restFrameIndex = edgeFrames.Length - 1;
            var expectedEntryFrameIndex = restFrameIndex;
            var fullyPeekedFrameIndex = edgeFrames.Length / 2 - 1;
            var edgeRestHold = (TimeSpan)InvokeStatic(
                typeof(MainWindow),
                "GetEdgePeekRestHoldDuration",
                edgeFrames.Length)!;
            PrimeSpritePageForFrame(
                window,
                edgeFrames.GetValue(expectedEntryFrameIndex)!);
            var currentVisibleBounds = (Rect)Invoke(
                window,
                "GetPetViewboxBoundsInScreenDips")!;
            window.Left += safeLeft - currentVisibleBounds.Left;
            window.Top += safeTop - currentVisibleBounds.Top;
            window.UpdateLayout();
            var initialWindowBounds = (Rect)Invoke(
                window,
                "GetPetViewboxBoundsInScreenDips")!;
            var initialContactBounds = (Rect)Invoke(
                window,
                "GetPetContactBounds",
                initialWindowBounds)!;
            if (edge == "Left")
            {
                window.Left += workArea.Left - initialContactBounds.Left;
            }
            else if (edge == "Right")
            {
                window.Left += workArea.Right - initialContactBounds.Right;
            }
            else
            {
                window.Top += workArea.Bottom - initialContactBounds.Bottom;
            }
            var edgeStartTimestamp = Stopwatch.GetTimestamp();
            Invoke(window, "UpdateEdgeDockAfterDrag");
            var deadline = GetField<long>(window, "_edgePeekFrameDeadlineTimestamp");
            var edgePeekHoldTimer = GetField<DispatcherTimer>(
                window,
                "_edgePeekHoldTimer");
            Assert(GetField<object>(window, "_edgeDock").ToString() == edge &&
                   GetField<int>(window, "_edgePeekFrameIndex") ==
                   expectedEntryFrameIndex &&
                   Equals(
                       GetRawField(window, "_currentSpriteFrame"),
                       edgeFrames.GetValue(expectedEntryFrameIndex)) &&
                   deadline > edgeStartTimestamp &&
                   deadline != long.MaxValue &&
                   edgePeekHoldTimer.IsEnabled &&
                   !GetField<bool>(window, "_isVisualClockSubscribed") &&
                   GetField<ScaleTransform>(window, "PetFacingScale").ScaleX ==
                   (edge == "Right" ? -1 : 1),
                $"真实拖拽落点贴住{edge}边缘时必须从末尾休息姿势进入；" +
                "三边统一恢复v1.0.57的rest-first节奏，静止时暂停Rendering，右侧仅镜像左侧序列");

            edgePeekHoldTimer.Stop();
            AdvanceEdgePeekForControlledClock(window, deadline);
            var nextDeadline = GetField<long>(window, "_edgePeekFrameDeadlineTimestamp");
            var expectedFirstAdvanceIndex =
                (expectedEntryFrameIndex + 1) % edgeFrames.Length;
            Assert(GetField<int>(window, "_edgePeekFrameIndex") ==
                   expectedFirstAdvanceIndex,
                $"{edge} 入口hold后必须按单向序列推进到正确姿势");
            AssertClose(
                StopwatchTicksToMilliseconds(nextDeadline - deadline),
                StopwatchTicksToMilliseconds(
                    ToProductionStopwatchTicks(edgeMotionFrameInterval)),
                $"{edge} 入口hold后的探头必须按原生60fps运行时钟换帧");

            while (GetField<int>(window, "_edgePeekFrameIndex") !=
                   fullyPeekedFrameIndex)
            {
                deadline = nextDeadline;
                AdvanceEdgePeekForControlledClock(window, deadline);
                nextDeadline = GetField<long>(window, "_edgePeekFrameDeadlineTimestamp");
                var frameIndex = GetField<int>(window, "_edgePeekFrameIndex");
                var expectedHold = frameIndex == fullyPeekedFrameIndex
                    ? edgeFullyPeekedHold
                    : edgeMotionFrameInterval;
                AssertClose(
                    StopwatchTicksToMilliseconds(nextDeadline - deadline),
                    StopwatchTicksToMilliseconds(
                        ToProductionStopwatchTicks(expectedHold)),
                    $"{edge} 探头升序姿势 {frameIndex + 1:000} 的hold必须匹配动态四阶段时钟");
            }

            Assert(Equals(
                       GetRawField(window, "_currentSpriteFrame"),
                       edgeFrames.GetValue(fullyPeekedFrameIndex)),
                $"{edge} 探头必须在1/2阶段显示开心完全探头姿势并停留650ms");
            Assert(edgePeekHoldTimer.IsEnabled &&
                   !GetField<bool>(window, "_isVisualClockSubscribed"),
                $"{edge} 完全探头650ms静止段必须暂停Rendering并由hold timer唤醒");
            edgePeekHoldTimer.Stop();
            SetField(
                window,
                "_edgePeekFrameDeadlineTimestamp",
                Stopwatch.GetTimestamp() - 1);
            Invoke(window, "EdgePeekHoldTimer_Tick", null, EventArgs.Empty);
            nextDeadline = GetField<long>(
                window,
                "_edgePeekFrameDeadlineTimestamp");
            Assert(GetField<int>(window, "_edgePeekFrameIndex") ==
                       fullyPeekedFrameIndex + 1 &&
                   !edgePeekHoldTimer.IsEnabled &&
                   GetField<bool>(window, "_isVisualClockSubscribed"),
                $"{edge} hold timer到点后必须只推进一个运动姿势并恢复Rendering");
            while (GetField<int>(window, "_edgePeekFrameIndex") != restFrameIndex)
            {
                deadline = nextDeadline;
                AdvanceEdgePeekForControlledClock(window, deadline);
                nextDeadline = GetField<long>(window, "_edgePeekFrameDeadlineTimestamp");
            }

            AssertClose(
                StopwatchTicksToMilliseconds(nextDeadline - deadline),
                StopwatchTicksToMilliseconds(
                    ToProductionStopwatchTicks(edgeRestHold)),
                $"{edge} 探头回到末尾害羞缩回姿势后必须使用10秒周期剩余的长休息hold");
            deadline = nextDeadline;
            AdvanceEdgePeekForControlledClock(window, deadline);
            nextDeadline = GetField<long>(window, "_edgePeekFrameDeadlineTimestamp");
            Assert(GetField<int>(window, "_edgePeekFrameIndex") == 0,
                $"{edge} 探头末帧必须单向闭环回第001帧，不能ping-pong");
            AssertClose(
                StopwatchTicksToMilliseconds(nextDeadline - deadline),
                StopwatchTicksToMilliseconds(
                    ToProductionStopwatchTicks(edgeMotionFrameInterval)),
                $"{edge} 探头新一轮必须继续保持原生60fps绝对时钟");
            Invoke(window, "ExitEdgePeek", false, true);
            Assert(GetField<long>(window, "_edgePeekFrameDeadlineTimestamp") == 0 &&
                   !edgePeekHoldTimer.IsEnabled,
                $"退出{edge}探头后必须清除绝对时间截止点");
        }

        var directDragContextType = typeof(MainWindow).GetNestedType(
                "EdgeDockDragContext",
                BindingFlags.NonPublic)
            ?? throw new InvalidOperationException(
                "找不到 MainWindow.EdgeDockDragContext");
        var directNoDock = GetNestedEnum("EdgeDock", "None");
        foreach (var petScale in new[] { 0.75d, 1d, 1.25d, 1.4d })
        {
            Invoke(window, "ApplyPetSizeScale", petScale, false, false);
            PumpDispatcher(TimeSpan.FromMilliseconds(15));
            var directWorkArea = (Rect)InvokeStatic(
                monitorType,
                "GetForVisual",
                window,
                petSizeViewbox)!;
            var directBounds = (Rect)Invoke(
                window,
                "GetPetViewboxBoundsInScreenDips")!;
            var directSafeLeft = directWorkArea.Left +
                                 Math.Max(
                                     20,
                                     (directWorkArea.Width - directBounds.Width) / 2);
            var directSafeTop = directWorkArea.Top +
                                Math.Max(
                                    20,
                                    (directWorkArea.Height - directBounds.Height) / 2);
            window.Left += directSafeLeft - directBounds.Left;
            window.Top += directSafeTop - directBounds.Top;
            window.UpdateLayout();
            directBounds = (Rect)Invoke(
                window,
                "GetPetViewboxBoundsInScreenDips")!;
            var directContact = (Rect)Invoke(
                window,
                "GetDragReleaseContactBounds",
                directBounds,
                directNoDock)!;
            var directDragContext = Activator.CreateInstance(
                    directDragContextType,
                    InstanceFlags,
                    binder: null,
                    args:
                    [
                        directNoDock,
                        directWorkArea,
                        directBounds,
                        directContact
                    ],
                    culture: null)
                ?? throw new InvalidOperationException(
                    $"无法创建 {petScale:P0} 捕获式拖拽上下文");
            var grabLocalPoint = new Point(
                directContact.Left + directContact.Width / 2 - window.Left,
                directContact.Top + Math.Min(12, directContact.Height / 2) -
                window.Top);
            var grabScreenPoint = window.PointToScreen(grabLocalPoint);
            SetField(window, "_pointerDownPosition", grabLocalPoint);
            SetField(window, "_pointerDownScreenPosition", grabScreenPoint);
            SetField(window, "_latestDragScreenPosition", grabScreenPoint);
            SetField(window, "_edgeDockDragContext", directDragContext);
            SetField(window, "_dragStarted", true);
            SetField(window, "_dragInteractionActive", true);
            var prepared = (bool)Invoke(
                window,
                "TryPrepareDirectPetDragGeometry",
                directBounds,
                directNoDock)!;
            SetField(
                window,
                "_directDragPhysicalGeometryReady",
                prepared);
            var physicalWorkTop = window.PointToScreen(
                new Point(0, directWorkArea.Top - window.Top)).Y;
            var pointerAtTop = new Point(grabScreenPoint.X, physicalWorkTop);
            var pointerAtTopLocal = window.PointFromScreen(pointerAtTop);
            Invoke(
                window,
                "ContinueDirectPetDrag",
                pointerAtTopLocal,
                pointerAtTop);
            PumpDispatcher(TimeSpan.FromMilliseconds(15));
            var directAlignedBounds = (Rect)Invoke(
                window,
                "GetPetViewboxBoundsInScreenDips")!;
            var directAlignedContact = (Rect)Invoke(
                window,
                "GetDragReleaseContactBounds",
                directAlignedBounds,
                directNoDock)!;
            var physicalContactTop = window.PointToScreen(
                new Point(0, directAlignedContact.Top - window.Top)).Y;
            Assert(
                prepared &&
                Math.Abs(physicalContactTop - physicalWorkTop) <= 1.01 &&
                GetField<object>(window, "_edgeDock").ToString() == "None" &&
                GetField<long>(window, "_edgePeekFrameDeadlineTimestamp") == 0,
                $"{petScale:P0} 捕获式原生拖动必须让真实HWND越过透明包络限制，人物像素在一个物理像素内贴顶且不进入顶部吸附");
            SetField(window, "_dragStarted", false);
            SetField(window, "_dragInteractionActive", false);
            SetField(window, "_directDragPhysicalGeometryReady", false);
            SetField(window, "_directDragTopClamped", false);
            SetField(
                window,
                "_directDragTopClampPointerYInPhysicalPixels",
                double.NaN);
            SetField(window, "_edgeDockDragContext", null);
            var restoredBounds = (Rect)Invoke(
                window,
                "GetPetViewboxBoundsInScreenDips")!;
            window.Left += directSafeLeft - restoredBounds.Left;
            window.Top += directSafeTop - restoredBounds.Top;
        }

        Invoke(window, "ApplyPetSizeScale", 1d, false, false);
        PumpDispatcher(TimeSpan.FromMilliseconds(15));
    }

    private static void AssertEdgePeekClosesTaskPanel(MainWindow window)
    {
        if (!window.IsVisible)
        {
            window.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
        }

        var todoWindow = GetField<TodoWindow>(window, "_todoWindow");
        var originalSuppressDeactivate =
            GetField<bool>(window, "_suppressTodoWindowDeactivate");
        var originalLeft = window.Left;
        var originalTop = window.Top;
        var processOutsideClose = ExtractPrivateMethodSource(
            File.ReadAllText(FindWorkspaceFile("MainWindow.xaml.cs")),
            "ProcessOutsideTodoClose");
        Assert(processOutsideClose.Contains(
                "SetBubbleMode(BubbleMode.None)",
                StringComparison.Ordinal),
            "外部点击收起必须继续汇入统一的 Todo→None 状态切换，不能绕过待办提交与隐藏逻辑");

        try
        {
            SetField(window, "_suppressTodoWindowDeactivate", true);
            Invoke(window, "SetBubbleMode", GetNestedEnum("BubbleMode", "None"));
            Invoke(window, "ExitEdgePeek", false, true);

            foreach (var edge in new[] { "Left", "Right", "Bottom" })
            {
                var edgeFrames = edge is "Left" or "Right"
                    ? GetField<Array>(window, "_edgeLeftFrames")
                    : GetField<Array>(window, "_edgeBottomFrames");
                var entryFrameIndex = edgeFrames.Length - 1;
                var entryFrame = edgeFrames.GetValue(entryFrameIndex)!;
                var showScheduledTasks = edge != "Left";

                Invoke(window, "SetBubbleMode", GetNestedEnum("BubbleMode", "Todo"));
                Invoke(
                    todoWindow,
                    "SelectTaskPage",
                    showScheduledTasks,
                    false);
                PumpDispatcher(TimeSpan.FromMilliseconds(20));
                Assert(todoWindow.IsVisible &&
                       GetField<object>(window, "_bubbleMode").ToString() == "Todo" &&
                       GetField<RadioButton>(
                           todoWindow,
                           showScheduledTasks
                               ? "ScheduledTaskTabButton"
                               : "TodoTabButton").IsChecked == true,
                    $"{edge} 吸附回归的前置条件必须真实打开" +
                    (showScheduledTasks ? "定时任务" : "待办事项") + "页面");

                // Opening Todo can trim an unprotected edge page after earlier
                // cache-pressure checks. Pin the exact entry pose only after
                // the panel has completed that state transition.
                PrimeSpritePageForFrame(window, entryFrame);
                SetField(window, "_openTodoAfterEdgeRoamStopRequested", true);
                Invoke(window, "QueueTodoOpenAfterEdgeRoamStop");
                SetField(window, "_openTodoAfterWorkExitRequested", true);
                Invoke(window, "QueueTodoOpenAfterWorkExit");
                var edgeEntryTimestamp = Stopwatch.GetTimestamp();
                Invoke(window, "EnterEdgePeek", GetNestedEnum("EdgeDock", edge));
                PumpDispatcher(TimeSpan.FromMilliseconds(30));
                var deadlineBeforeClose =
                    GetField<long>(window, "_edgePeekFrameDeadlineTimestamp");
                Assert(!todoWindow.IsVisible &&
                       GetField<object>(window, "_bubbleMode").ToString() == "None" &&
                       !GetField<bool>(
                           window,
                           "_openTodoAfterEdgeRoamStopRequested") &&
                       !GetField<bool>(window, "_openTodoAfterWorkExitRequested") &&
                       GetField<object>(window, "_edgeDock").ToString() == edge &&
                       deadlineBeforeClose > edgeEntryTimestamp &&
                       deadlineBeforeClose != long.MaxValue &&
                       GetRawField(window, "_activeClip") is null &&
                       Equals(GetRawField(window, "_currentSpriteFrame"), entryFrame) &&
                       GetField<DispatcherTimer>(
                           window,
                           "_edgePeekHoldTimer").IsEnabled &&
                       !GetField<bool>(window, "_isVisualClockSubscribed"),
                    $"进入 {edge} 吸附必须立即关闭任务面板、取消迟到重开请求，" +
                    "并从v1.0.57末尾休息姿势取得视觉所有权；" +
                    $"visible={todoWindow.IsVisible}, " +
                    $"bubble={GetField<object>(window, "_bubbleMode")}, " +
                    $"edge={GetField<object>(window, "_edgeDock")}, " +
                    $"deadline={deadlineBeforeClose}/{edgeEntryTimestamp}, " +
                    $"frame={Equals(GetRawField(window, "_currentSpriteFrame"), entryFrame)}, " +
                    $"clip={GetRawField(window, "_activeClip") is not null}, " +
                    $"hold={GetField<DispatcherTimer>(window, "_edgePeekHoldTimer").IsEnabled}, " +
                    $"render={GetField<bool>(window, "_isVisualClockSubscribed")}, " +
                    $"roamReq={GetField<bool>(window, "_openTodoAfterEdgeRoamStopRequested")}/" +
                    $"{GetField<bool>(window, "_todoOpenAfterEdgeRoamStopQueued")}, " +
                    $"workReq={GetField<bool>(window, "_openTodoAfterWorkExitRequested")}/" +
                    $"{GetField<bool>(window, "_todoOpenAfterWorkExitQueued")}");

                Invoke(window, "ProcessTodoOpenAfterEdgeRoamStop");
                Invoke(window, "ProcessTodoOpenAfterWorkExit");
                Assert(!todoWindow.IsVisible &&
                       !GetField<bool>(window, "_todoOpenAfterEdgeRoamStopQueued") &&
                       !GetField<bool>(window, "_todoOpenAfterWorkExitQueued"),
                    $"{edge} 吸附后的迟到Dispatcher回调必须只清除队列标记，" +
                    "不能重新打开待办或定时任务页面");

                // The normal outside-close endpoint remains idempotent after
                // docking has already closed the owned task panel.
                Invoke(window, "SetBubbleMode", GetNestedEnum("BubbleMode", "None"));
                PumpDispatcher(TimeSpan.FromMilliseconds(10));

                var preservedDeadline =
                    GetField<long>(window, "_edgePeekFrameDeadlineTimestamp");
                var facingScale = GetField<ScaleTransform>(window, "PetFacingScale");
                Assert(!todoWindow.IsVisible &&
                       GetField<object>(window, "_bubbleMode").ToString() == "None" &&
                       GetField<object>(window, "_edgeDock").ToString() == edge &&
                       preservedDeadline > 0 &&
                       preservedDeadline != long.MaxValue &&
                       GetRawField(window, "_activeClip") is null &&
                       GetField<long>(window, "_activeFrameDeadlineTimestamp") == 0 &&
                       edgeFrames.Cast<object>().Contains(
                           GetRawField(window, "_currentSpriteFrame")) &&
                       (GetField<bool>(window, "_isVisualClockSubscribed") ||
                        GetField<DispatcherTimer>(
                            window,
                            "_edgePeekHoldTimer").IsEnabled) &&
                       !GetField<DispatcherTimer>(window, "_automaticTimer").IsEnabled &&
                       Math.Abs(
                           facingScale.ScaleX - (edge == "Right" ? -1 : 1)) <=
                       0.000001,
                    $"任务面板自动关闭后必须保留 {edge} 吸附、朝向、边缘帧和视觉时钟，不能播放 todo-close 回待机");

                GetField<DispatcherTimer>(window, "_edgePeekHoldTimer").Stop();
                AdvanceEdgePeekForControlledClock(window, preservedDeadline);
                Assert(GetField<object>(window, "_edgeDock").ToString() == edge &&
                       GetField<long>(window, "_edgePeekFrameDeadlineTimestamp") >
                       preservedDeadline &&
                       edgeFrames.Cast<object>().Contains(
                           GetRawField(window, "_currentSpriteFrame")),
                    $"关闭任务面板后 {edge} 边缘动画必须继续推进，不能只留下僵死的吸附枚举");

                Invoke(window, "ExitEdgePeek", false, true);
            }
        }
        finally
        {
            Invoke(window, "SetBubbleMode", GetNestedEnum("BubbleMode", "None"));
            Invoke(window, "ExitEdgePeek", false, true);
            SetField(
                window,
                "_suppressTodoWindowDeactivate",
                originalSuppressDeactivate);
            window.Left = originalLeft;
            window.Top = originalTop;
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
        }
    }

    private static void AssertWindowBoundaryDockActivation(
        MainWindow window,
        Type monitorType)
    {
        var originalScale = GetField<double>(window, "_petSizeScale");
        var originalLeft = window.Left;
        var originalTop = window.Top;
        var edgeLeftFrames = GetField<Array>(window, "_edgeLeftFrames");
        var edgeBottomFrames = GetField<Array>(window, "_edgeBottomFrames");
        var petSizeViewbox = GetField<Viewbox>(window, "PetSizeViewbox");
        PrimeSpritePageForFrame(
            window,
            edgeLeftFrames.GetValue(edgeLeftFrames.Length - 1)!);
        PrimeSpritePageForFrame(
            window,
            edgeBottomFrames.GetValue(edgeBottomFrames.Length - 1)!);

        try
        {
            foreach (var scale in new[] { 0.75d, 1d, 1.25d, 1.4d })
            {
                Invoke(window, "ApplyPetSizeScale", scale, false, false);
                PumpDispatcher(TimeSpan.FromMilliseconds(20));
                window.UpdateLayout();
                var workArea = (Rect)InvokeStatic(
                    monitorType,
                    "GetForVisual",
                    window,
                    petSizeViewbox)!;
                var initialVisibleBounds = (Rect)Invoke(
                    window,
                    "GetPetViewboxBoundsInScreenDips")!;
                var width = initialVisibleBounds.Width;
                var height = initialVisibleBounds.Height;
                var safeLeft =
                    workArea.Left + Math.Max(20, (workArea.Width - width) / 2);
                var safeTop =
                    workArea.Top + Math.Max(20, (workArea.Height - height) / 2);

                foreach (var edge in new[] { "Left", "Right", "Bottom" })
                {
                    Invoke(window, "ExitEdgePeek", false, true);
                    var currentVisibleBounds = (Rect)Invoke(
                        window,
                        "GetPetViewboxBoundsInScreenDips")!;
                    var desiredVisibleLeft = edge switch
                    {
                        "Left" => workArea.Left,
                        "Right" => workArea.Right - width,
                        _ => safeLeft
                    };
                    var desiredVisibleTop = edge == "Bottom"
                        ? workArea.Bottom - height
                        : safeTop;
                    window.Left +=
                        desiredVisibleLeft - currentVisibleBounds.Left;
                    window.Top +=
                        desiredVisibleTop - currentVisibleBounds.Top;
                    PumpDispatcher(TimeSpan.FromMilliseconds(10));

                    var visibleBounds = (Rect)Invoke(
                        window,
                        "GetPetViewboxBoundsInScreenDips")!;
                    var contactBounds = (Rect)Invoke(
                        window,
                        "GetPetContactBounds",
                        visibleBounds)!;
                    var visibleGap = edge switch
                    {
                        "Left" => contactBounds.Left - workArea.Left,
                        "Right" => workArea.Right - contactBounds.Right,
                        _ => workArea.Bottom - contactBounds.Bottom
                    };
                    Assert(visibleGap > 1 && visibleGap <= 12,
                        $"{scale:P0} 桌宠的 {edge} 可见边距应复现旧版超过 1 DIP、" +
                        $"但落在 12 DIP 磁吸区内的真实窗口贴边场景；gap={visibleGap:F3}");

                    Invoke(window, "UpdateEdgeDockAfterDrag");
                    var snappedVisibleBounds = (Rect)Invoke(
                        window,
                        "GetPetViewboxBoundsInScreenDips")!;
                    var snappedToBoundary = edge switch
                    {
                        "Left" => Math.Abs(
                            snappedVisibleBounds.Left -
                            workArea.Left) <= 0.5,
                        "Right" => Math.Abs(
                            snappedVisibleBounds.Right -
                            workArea.Right) <= 0.5,
                        _ => Math.Abs(
                            snappedVisibleBounds.Bottom -
                            workArea.Bottom) <= 0.5
                    };
                    Assert(GetField<object>(window, "_edgeDock").ToString() == edge &&
                           snappedToBoundary,
                        $"{scale:P0} 桌宠 HWND 自然贴住 {edge} 边缘时必须吸附，" +
                        $"不能要求用户精确拖出屏幕 2～4 DIP");
                }

                var overshoot = Math.Min(40, Math.Min(width, height) / 3);
                foreach (var edge in new[] { "Left", "Right", "Bottom" })
                {
                    Invoke(window, "ExitEdgePeek", false, true);
                    var currentVisibleBounds = (Rect)Invoke(
                        window,
                        "GetPetViewboxBoundsInScreenDips")!;
                    var desiredVisibleLeft = edge switch
                    {
                        "Left" => workArea.Left - overshoot,
                        "Right" => workArea.Right - width + overshoot,
                        _ => safeLeft
                    };
                    var desiredVisibleTop = edge == "Bottom"
                        ? workArea.Bottom - height + overshoot
                        : safeTop;
                    window.Left +=
                        desiredVisibleLeft - currentVisibleBounds.Left;
                    window.Top +=
                        desiredVisibleTop - currentVisibleBounds.Top;
                    PumpDispatcher(TimeSpan.FromMilliseconds(10));
                    Invoke(window, "UpdateEdgeDockAfterDrag");
                    var snappedVisibleBounds = (Rect)Invoke(
                        window,
                        "GetPetViewboxBoundsInScreenDips")!;
                    var snappedToBoundary = edge switch
                    {
                        "Left" => Math.Abs(
                            snappedVisibleBounds.Left -
                            workArea.Left) <= 0.5,
                        "Right" => Math.Abs(
                            snappedVisibleBounds.Right -
                            workArea.Right) <= 0.5,
                        _ => Math.Abs(
                            snappedVisibleBounds.Bottom -
                            workArea.Bottom) <= 0.5
                    };
                    Assert(GetField<object>(window, "_edgeDock").ToString() == edge &&
                           snappedToBoundary,
                        $"{scale:P0} 桌宠快速越过 {edge} 外边缘后仍必须吸附并夹回准确边界");
                }
            }

            AssertRightToBottomFastToss(
                window,
                monitorType,
                edgeLeftFrames,
                edgeBottomFrames);
        }
        finally
        {
            SetField(window, "_dragStarted", false);
            SetField(window, "_dragInteractionActive", false);
            SetField(window, "_edgeDockDragContext", null);
            Invoke(window, "ExitEdgePeek", false, true);
            Invoke(window, "ApplyPetSizeScale", originalScale, false, false);
            window.Left = originalLeft;
            window.Top = originalTop;
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
        }
    }

    private static void AssertRightToBottomFastToss(
        MainWindow window,
        Type monitorType,
        Array edgeLeftFrames,
        Array edgeBottomFrames)
    {
        Invoke(window, "ApplyPetSizeScale", 1d, false, false);
        PumpDispatcher(TimeSpan.FromMilliseconds(20));
        var petSizeViewbox = GetField<Viewbox>(window, "PetSizeViewbox");
        var workArea = (Rect)InvokeStatic(
            monitorType,
            "GetForVisual",
            window,
            petSizeViewbox)!;
        var initialVisibleBounds = (Rect)Invoke(
            window,
            "GetPetViewboxBoundsInScreenDips")!;
        var width = initialVisibleBounds.Width;
        var height = initialVisibleBounds.Height;
        var desiredStartWindowBounds = new Rect(
            workArea.Right - width,
            workArea.Top + Math.Max(20, (workArea.Height - height) / 2),
            width,
            height);
        window.Left += desiredStartWindowBounds.Left - initialVisibleBounds.Left;
        window.Top += desiredStartWindowBounds.Top - initialVisibleBounds.Top;
        window.UpdateLayout();
        var startWindowBounds = (Rect)Invoke(
            window,
            "GetPetViewboxBoundsInScreenDips")!;

        var rightDock = GetNestedEnum("EdgeDock", "Right");
        var rightEntryFrame = edgeLeftFrames.GetValue(0)!;
        var bottomRestFrame = edgeBottomFrames.GetValue(edgeBottomFrames.Length - 1)!;
        PrimeSpritePageForFrame(window, rightEntryFrame);
        Invoke(window, "EnterEdgePeek", rightDock);
        Assert(GetField<object>(window, "_edgeDock").ToString() == "Right",
            "右→下快速甩动回归必须先真实进入 Right 吸附状态");

        var startContactBounds = (Rect)Invoke(
            window,
            "GetDragReleaseContactBounds",
            startWindowBounds,
            rightDock)!;
        Invoke(window, "ExitEdgePeek", false, true);
        PrimeSpritePageForFrame(window, bottomRestFrame);

        var dragContextType = typeof(MainWindow).GetNestedType(
                "EdgeDockDragContext",
                BindingFlags.NonPublic)
            ?? throw new InvalidOperationException(
                "找不到 MainWindow.EdgeDockDragContext");
        var dragContext = Activator.CreateInstance(
                dragContextType,
                InstanceFlags,
                binder: null,
                args:
                [
                    rightDock,
                    workArea,
                    startWindowBounds,
                    startContactBounds
                ],
                culture: null)
            ?? throw new InvalidOperationException(
                "无法创建右→下拖拽上下文");
        SetField(window, "_edgeDockDragContext", dragContext);
        SetField(window, "_dragStarted", true);
        SetField(window, "_dragInteractionActive", true);

        var desiredFinalWindowBounds = new Rect(
            workArea.Right - width,
            workArea.Bottom - height + 20,
            width,
            height);
        var beforeFinalVisibleBounds = (Rect)Invoke(
            window,
            "GetPetViewboxBoundsInScreenDips")!;
        window.Left +=
            desiredFinalWindowBounds.Left - beforeFinalVisibleBounds.Left;
        window.Top +=
            desiredFinalWindowBounds.Top - beforeFinalVisibleBounds.Top;
        window.UpdateLayout();
        var finalWindowBounds = (Rect)Invoke(
            window,
            "GetPetViewboxBoundsInScreenDips")!;
        var finalContactBounds = (Rect)Invoke(
            window,
            "GetDragReleaseContactBounds",
            finalWindowBounds,
            rightDock)!;
        var rawCandidates = ((IEnumerable)InvokeStatic(
                typeof(MainWindow),
                "FindTouchedEdges",
                workArea,
                finalContactBounds,
                12d)!)
            .Cast<object>()
            .Select(candidate => candidate.ToString())
            .ToArray();
        Assert(rawCandidates.Length >= 2 &&
               rawCandidates[0] == "Right" &&
               rawCandidates[1] == "Bottom",
            "右下角回归前置必须复现旧算法优先 Right、Bottom 仅为后备的候选竞争");

        var cornerCandidates = Array.CreateInstance(rightDock.GetType(), 2);
        cornerCandidates.SetValue(rightDock, 0);
        cornerCandidates.SetValue(GetNestedEnum("EdgeDock", "Bottom"), 1);
        var downPriority = ((IEnumerable)InvokeStatic(
                typeof(MainWindow),
                "PrioritizeTouchedEdgesAfterDrag",
                cornerCandidates,
                dragContext,
                finalWindowBounds)!)
            .Cast<object>()
            .Select(candidate => candidate.ToString())
            .ToArray();
        var upwardPriority = ((IEnumerable)InvokeStatic(
                typeof(MainWindow),
                "PrioritizeTouchedEdgesAfterDrag",
                cornerCandidates,
                dragContext,
                new Rect(
                    startWindowBounds.Left,
                    startWindowBounds.Top - 20,
                    width,
                    height))!)
            .Cast<object>()
            .Select(candidate => candidate.ToString())
            .ToArray();
        Assert(downPriority.SequenceEqual(["Bottom", "Right"]) &&
               upwardPriority.SequenceEqual(["Right", "Bottom"]),
            "Right 角落候选必须按实际向下手势切换 Bottom；向上或无向下证据时仍保留 Right");

        var dockStartTimestamp = Stopwatch.GetTimestamp();
        Invoke(window, "UpdateEdgeDockAfterDrag");
        var deadline =
            GetField<long>(window, "_edgePeekFrameDeadlineTimestamp");
        var snappedVisibleBounds = (Rect)Invoke(
            window,
            "GetPetViewboxBoundsInScreenDips")!;
        Assert(GetField<object>(window, "_edgeDock").ToString() == "Bottom" &&
               Math.Abs(snappedVisibleBounds.Bottom -
                        workArea.Bottom) <= 0.5 &&
               Math.Abs(
                   GetField<ScaleTransform>(window, "PetFacingScale").ScaleX -
                   1) <= 0.000001 &&
                Equals(
                    GetRawField(window, "_currentSpriteFrame"),
                    bottomRestFrame) &&
               GetRawField(window, "_pendingSpriteFrame") is null &&
               deadline > dockStartTimestamp &&
               deadline != long.MaxValue,
            "从 Right 吸附沿右边向下甩到右下角时必须切换为 Bottom，" +
            "并使用底边末帧休息姿势和有限的新时钟");
        SetField(window, "_dragStarted", false);
        SetField(window, "_dragInteractionActive", false);
        SetField(window, "_edgeDockDragContext", null);
        Invoke(window, "ExitEdgePeek", false, true);
    }

    private static void AssertAutomaticDeadlineContract(MainWindow window)
    {
        var automaticInterval = (TimeSpan)(typeof(MainWindow).GetField(
                "AutomaticAnimationInterval",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var roamInterval = (TimeSpan)(typeof(MainWindow).GetField(
                "EdgeRoamInterval",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var roamPreloadLeadTime = (TimeSpan)(typeof(MainWindow).GetField(
                "EdgeRoamPreloadLeadTime",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var timer = GetField<DispatcherTimer>(window, "_automaticTimer");
        var timerWasEnabled = timer.IsEnabled;
        var originalTimerInterval = timer.Interval;
        var originalClosing = GetField<bool>(window, "_isClosing");
        var originalSessionInactive = GetField<bool>(window, "_sessionInactive");
        var originalAutomaticEnabled = GetField<bool>(
            window,
            "_automaticAnimationEnabled");
        var originalRoamingEnabled = GetField<bool>(
            window,
            "_edgeRoamingEnabled");
        var originalReminderActive = GetField<bool>(window, "_isReminderActive");
        var originalDragActive = GetField<bool>(window, "_dragInteractionActive");
        var originalRoaming = GetField<bool>(window, "_isEdgeRoaming");
        var originalRoamPreloadRequested =
            GetField<bool>(window, "_edgeRoamPreloadRequested");
        var originalActiveClip = GetRawField(window, "_activeClip");
        var originalBubbleMode = GetRawField(window, "_bubbleMode")!;
        var originalEdgeDock = GetRawField(window, "_edgeDock")!;
        var originalActivityDue = GetField<long>(
            window,
            "_nextAutomaticActivityDueTimestamp");
        var originalRoamDue = GetField<long>(
            window,
            "_nextEdgeRoamDueTimestamp");
        var originalPillowDue = GetField<long>(
            window,
            "_pillowBreathingDueTimestamp");

        try
        {
            timer.Stop();
            SetField(window, "_isClosing", false);
            SetField(window, "_sessionInactive", false);
            SetField(window, "_automaticAnimationEnabled", true);
            SetField(window, "_edgeRoamingEnabled", true);
            SetField(window, "_isReminderActive", false);
            SetField(window, "_dragInteractionActive", false);
            SetField(window, "_isEdgeRoaming", false);
            SetField(window, "_edgeRoamPreloadRequested", false);
            SetField(window, "_activeClip", null);
            SetField(window, "_bubbleMode", GetNestedEnum("BubbleMode", "None"));
            SetField(window, "_edgeDock", GetNestedEnum("EdgeDock", "None"));
            SetField(window, "_pillowBreathingDueTimestamp", 0L);

            var timestamp = Stopwatch.GetTimestamp();
            var activitySentinel = checked(
                timestamp + ToProductionStopwatchTicks(TimeSpan.FromSeconds(33)));
            SetField(
                window,
                "_nextAutomaticActivityDueTimestamp",
                activitySentinel);
            Invoke(window, "ScheduleNextEdgeRoam", timestamp, roamInterval);
            Assert(GetField<long>(
                       window,
                       "_nextAutomaticActivityDueTimestamp") ==
                       activitySentinel &&
                   GetField<long>(window, "_nextEdgeRoamDueTimestamp") ==
                       checked(timestamp +
                               ToProductionStopwatchTicks(roamInterval)),
                "安排 10 分钟绕屏不得改写普通动作的独立截止时间");

            var roamSentinel = checked(
                timestamp + ToProductionStopwatchTicks(TimeSpan.FromSeconds(45)));
            SetField(window, "_nextEdgeRoamDueTimestamp", roamSentinel);
            var restartBefore = Stopwatch.GetTimestamp();
            Invoke(window, "RestartAutomaticCountdown");
            var restartAfter = Stopwatch.GetTimestamp();
            var activityDue = GetField<long>(
                window,
                "_nextAutomaticActivityDueTimestamp");
            Assert(activityDue >= checked(
                       restartBefore +
                       ToProductionStopwatchTicks(automaticInterval)) &&
                   activityDue <= checked(
                       restartAfter +
                       ToProductionStopwatchTicks(automaticInterval)) &&
                   GetField<long>(window, "_nextEdgeRoamDueTimestamp") ==
                       roamSentinel,
                "重启 1 分钟普通动作倒计时不得推迟独立的绕屏截止时间");

            var stopSentinel = checked(
                Stopwatch.GetTimestamp() +
                ToProductionStopwatchTicks(TimeSpan.FromSeconds(37)));
            SetField(window, "_isEdgeRoaming", false);
            SetField(window, "_nextEdgeRoamDueTimestamp", stopSentinel);
            Invoke(
                window,
                "StopEdgeRoaming",
                true,
                false,
                false,
                false);
            Assert(
                GetField<long>(window, "_nextEdgeRoamDueTimestamp") ==
                stopSentinel,
                "普通停止绕屏时，如果已有下一次到期时间就必须保持不变");

            SetField(
                window,
                "_nextAutomaticActivityDueTimestamp",
                checked(timestamp +
                        ToProductionStopwatchTicks(TimeSpan.FromSeconds(20))));
            SetField(
                window,
                "_nextEdgeRoamDueTimestamp",
                checked(timestamp +
                        ToProductionStopwatchTicks(TimeSpan.FromSeconds(40))));
            Invoke(window, "ArmAutomaticWakeTimer", timestamp);
            Assert(timer.IsEnabled &&
                   Math.Abs(
                       timer.Interval.TotalSeconds -
                       TimeSpan.FromSeconds(20).TotalSeconds) < 0.01,
                "共享唤醒 timer 必须选择较早的普通动作绝对截止时间");

            SetField(
                window,
                "_nextAutomaticActivityDueTimestamp",
                checked(timestamp +
                        ToProductionStopwatchTicks(TimeSpan.FromSeconds(50))));
            SetField(
                window,
                "_nextEdgeRoamDueTimestamp",
                checked(timestamp +
                        ToProductionStopwatchTicks(TimeSpan.FromSeconds(25))));
            Invoke(window, "ArmAutomaticWakeTimer", timestamp);
            Assert(timer.IsEnabled &&
                   Math.Abs(
                       timer.Interval.TotalSeconds -
                       (TimeSpan.FromSeconds(25) -
                        roamPreloadLeadTime).TotalSeconds) < 0.01,
                "共享唤醒 timer 必须在绕屏截止前按预加载提前量唤醒");
        }
        finally
        {
            timer.Stop();
            SetField(window, "_isClosing", originalClosing);
            SetField(window, "_sessionInactive", originalSessionInactive);
            SetField(
                window,
                "_automaticAnimationEnabled",
                originalAutomaticEnabled);
            SetField(window, "_edgeRoamingEnabled", originalRoamingEnabled);
            SetField(window, "_isReminderActive", originalReminderActive);
            SetField(window, "_dragInteractionActive", originalDragActive);
            SetField(window, "_isEdgeRoaming", originalRoaming);
            SetField(
                window,
                "_edgeRoamPreloadRequested",
                originalRoamPreloadRequested);
            SetField(window, "_activeClip", originalActiveClip);
            SetField(window, "_bubbleMode", originalBubbleMode);
            SetField(window, "_edgeDock", originalEdgeDock);
            SetField(
                window,
                "_nextAutomaticActivityDueTimestamp",
                originalActivityDue);
            SetField(window, "_nextEdgeRoamDueTimestamp", originalRoamDue);
            SetField(
                window,
                "_pillowBreathingDueTimestamp",
                originalPillowDue);
            timer.Interval = originalTimerInterval;
            if (timerWasEnabled)
            {
                timer.Start();
            }
        }
    }

    private static void AssertRandomActivityBag(MainWindow window)
    {
        var activityCount = GetField<Array>(window, "_automaticActivities").Length;
        Assert(activityCount == 5, "自动活动袋应包含 4 个角色动作和 1 个待机动作");

        var firstBag = DrainActivityBag(window, activityCount);
        var secondBag = DrainActivityBag(window, activityCount);
        var expected = Enumerable.Range(0, activityCount).ToArray();
        Assert(firstBag.Order().SequenceEqual(expected),
            "随机活动袋第一轮必须完整且无重复");
        Assert(secondBag.Order().SequenceEqual(expected),
            "随机活动袋第二轮必须完整且无重复");
        Assert(secondBag[0] != firstBag[^1],
            "相邻随机袋边界不得立即重复同一活动");

        var pillowDuration = (TimeSpan)(typeof(MainWindow).GetField(
                "PillowAnimationDuration",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var automaticTimer = GetField<DispatcherTimer>(window, "_automaticTimer");
        var petScale = GetField<ScaleTransform>(window, "PetScale");
        var mainSource = File.ReadAllText(FindWorkspaceFile("MainWindow.xaml.cs"));
        var startPillowSource = ExtractPrivateMethodSource(
            mainSource,
            "StartPillowBreathing");
        var beginAnimationCalls = mainSource
            .Split("BeginAnimation(", StringSplitOptions.None)
            .Skip(1)
            .Select(fragment => fragment[..fragment.IndexOf(';')])
            .ToArray();
        Assert(pillowDuration == TimeSpan.FromSeconds(5) &&
               startPillowSource.Contains(
                   "_pillowBreathingDueTimestamp = checked(",
                   StringComparison.Ordinal) &&
               startPillowSource.Contains(
                   "ArmAutomaticWakeTimer(timestamp)",
                   StringComparison.Ordinal) &&
               !startPillowSource.Contains("DoubleAnimation", StringComparison.Ordinal) &&
               !startPillowSource.Contains("BeginAnimation", StringComparison.Ordinal) &&
               beginAnimationCalls.All(call => call.Contains(", null)", StringComparison.Ordinal)),
            "枕头待机必须仅用automaticTimer占位5秒；自身不得创建DoubleAnimation，有BeginAnimation也只能传null清理旧动画");

        Invoke(window, "StartPillowBreathing");
        Assert(GetField<bool>(window, "_isPillowBreathing") &&
               automaticTimer.IsEnabled &&
               automaticTimer.Interval > TimeSpan.Zero &&
               automaticTimer.Interval <= TimeSpan.FromSeconds(5) &&
               GetField<long>(window, "_pillowBreathingDueTimestamp") >
                   Stopwatch.GetTimestamp() &&
               !petScale.HasAnimatedProperties &&
               Math.Abs(petScale.ScaleX - 1) < 0.000001 &&
               Math.Abs(petScale.ScaleY - 1) < 0.000001,
            "枕头待机占位启动后必须只运行5秒automaticTimer，视觉缩放保持静止且零动画属性");
        Invoke(window, "StopPillowBreathing");
        Assert(!GetField<bool>(window, "_isPillowBreathing") &&
               GetField<long>(window, "_pillowBreathingDueTimestamp") == 0 &&
               !automaticTimer.IsEnabled &&
               !petScale.HasAnimatedProperties,
            "停止枕头待机占位后必须关闭automaticTimer且不遗留WPF动画");
    }

    private static void AssertSnoreBubbleAnimationContract(MainWindow window)
    {
        if (!window.IsVisible)
        {
            window.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
        }

        // The full suite deliberately exercises clips, edge ownership and
        // deferred page work before this check.  Establish the idle endpoint
        // explicitly so this contract measures the bubble composition clock,
        // not whichever prior test happened to leave the visual clock active.
        PrepareWorkModeIdleState(window);

        var xaml = File.ReadAllText(FindWorkspaceFile("MainWindow.xaml"));
        var mainSource = File.ReadAllText(FindWorkspaceFile("MainWindow.xaml.cs"));
        var rendering = ExtractPrivateMethodSource(
            mainSource,
            "VisualClock_Rendering");
        var updateClock = ExtractPrivateMethodSource(
            mainSource,
            "UpdateVisualClockSubscription");
        var createBubbleClock = ExtractPrivateMethodSource(
            mainSource,
            "CreateSnoreBubbleScaleClock");
        var refreshBubble = ExtractPrivateMethodSource(
            mainSource,
            "RefreshSnoreBubbleAnimationState");
        XNamespace xamlNamespace =
            "http://schemas.microsoft.com/winfx/2006/xaml";
        var snoreBubbleElement = XDocument.Parse(xaml)
            .Descendants()
            .Single(element =>
                string.Equals(
                    (string?)element.Attribute(xamlNamespace + "Name"),
                    "SnoreBubbleHost",
                    StringComparison.Ordinal));
        var snoreBubbleAlphaValues = snoreBubbleElement
            .DescendantsAndSelf()
            .Attributes()
            .Where(attribute =>
                attribute.Name.LocalName is "Color" or "Fill" or "Stroke")
            .Select(attribute => attribute.Value)
            .Where(value => value.Length == 9 && value[0] == '#')
            .Select(value => byte.Parse(
                value.AsSpan(1, 2),
                NumberStyles.HexNumber,
                CultureInfo.InvariantCulture))
            .ToArray();
        Assert(
            xaml.Contains("x:Name=\"SnoreBubbleHost\"", StringComparison.Ordinal) &&
            xaml.Contains("x:Name=\"SnoreBubbleScale\"", StringComparison.Ordinal) &&
            xaml.Contains("RenderTransformOrigin=\"0.88,0.52\"", StringComparison.Ordinal) &&
            snoreBubbleElement
                .Descendants()
                .Count(element => element.Name.LocalName == "Ellipse") == 1 &&
            snoreBubbleAlphaValues.Length >= 4 &&
            snoreBubbleAlphaValues.All(alpha => alpha is > 0 and < byte.MaxValue) &&
            createBubbleClock.Contains("new DoubleAnimation", StringComparison.Ordinal) &&
            createBubbleClock.Contains("new SineEase", StringComparison.Ordinal) &&
            createBubbleClock.Contains("AutoReverse = true", StringComparison.Ordinal) &&
            createBubbleClock.Contains("RepeatBehavior.Forever", StringComparison.Ordinal) &&
            refreshBubble.Contains("ApplyAnimationClock", StringComparison.Ordinal) &&
            !rendering.Contains("SnoreBubble", StringComparison.Ordinal) &&
            !updateClock.Contains("_isSnoreBubbleAnimating", StringComparison.Ordinal),
            "呼噜泡泡必须交给WPF组合动画线程；稳定待机不能保持CompositionTarget.Rendering托管逐帧回调");

        var cycle = (TimeSpan)(typeof(MainWindow).GetField(
                "SnoreBubbleCycleDuration",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var minimum = (double)(typeof(MainWindow).GetField(
                "SnoreBubbleMinimumScale",
                StaticFlags)!.GetValue(null) ?? 0d);
        var maximum = (double)(typeof(MainWindow).GetField(
                "SnoreBubbleMaximumScale",
                StaticFlags)!.GetValue(null) ?? 0d);
        Assert(cycle > TimeSpan.Zero &&
               minimum >= 1 &&
               maximum > minimum,
            "覆盖原鼻泡的独立图层必须从原大小平滑放大后再缩回");

        Invoke(window, "RefreshSnoreBubbleAnimationState");
        var petScale = GetField<ScaleTransform>(window, "PetScale");
        var bubbleScale = GetField<ScaleTransform>(window, "SnoreBubbleScale");
        var bubbleHost = GetField<FrameworkElement>(window, "SnoreBubbleHost");
        var bubbleClock = GetField<AnimationClock>(
            window,
            "_snoreBubbleScaleClock");
        var bubbleAnimation = (DoubleAnimation)bubbleClock.Timeline;
        Assert(GetField<bool>(window, "_isSnoreBubbleAnimating") &&
               bubbleHost.Opacity > 0.99 &&
               bubbleScale.HasAnimatedProperties &&
               !GetField<bool>(window, "_isVisualClockSubscribed") &&
               !petScale.HasAnimatedProperties &&
               Math.Abs(petScale.ScaleX - 1) < 0.000001 &&
               Math.Abs(petScale.ScaleY - 1) < 0.000001,
            "稳定待机时必须只让鼻泡持续呼吸，人物和枕头尺寸保持完全不变");
        Assert(bubbleAnimation.From == minimum &&
               bubbleAnimation.To == maximum &&
               bubbleAnimation.Duration.HasTimeSpan &&
               bubbleAnimation.Duration.TimeSpan == TimeSpan.FromTicks(cycle.Ticks / 2) &&
               bubbleAnimation.AutoReverse &&
               bubbleAnimation.RepeatBehavior == RepeatBehavior.Forever &&
               bubbleAnimation.EasingFunction is SineEase
               {
                   EasingMode: EasingMode.EaseInOut
               },
            "WPF组合动画必须保持原有1.0到1.58的正弦往返呼吸节奏");

        bubbleHost.UpdateLayout();
        var bubbleEllipse =
            (System.Windows.Shapes.Ellipse)VisualTreeHelper.GetChild(
                bubbleHost,
                0);
        var bubbleStroke =
            (SolidColorBrush)bubbleEllipse.Stroke;
        var bubbleFill =
            (RadialGradientBrush)bubbleEllipse.Fill;
        Assert(bubbleStroke.Color.A is > 0 and < byte.MaxValue &&
               bubbleFill.GradientStops.Count >= 3 &&
               bubbleFill.GradientStops.All(stop =>
                   stop.Color.A is > 0 and < byte.MaxValue),
            "运行时唯一呼噜泡泡的描边和全部渐变色阶都必须保持半透明");

        SetField(window, "_isEdgeRoaming", true);
        Invoke(window, "RefreshSnoreBubbleAnimationState");
        Assert(!GetField<bool>(window, "_isSnoreBubbleAnimating") &&
               bubbleHost.Opacity == 0 &&
               !bubbleScale.HasAnimatedProperties &&
               Math.Abs(bubbleScale.ScaleX - minimum) < 0.000001 &&
               Math.Abs(bubbleScale.ScaleY - minimum) < 0.000001,
            "离开待机进入绕屏时必须原子隐藏、停止并复位泡泡层");

        // Keep the production animation detached while comparing the two
        // authored scale endpoints, but make the isolated bubble layer visible
        // for this render-only geometry assertion.
        bubbleHost.Opacity = 1;
        var viewport = GetField<FrameworkElement>(window, "PetFrameViewport");
        bubbleScale.ScaleX = minimum;
        bubbleScale.ScaleY = minimum;
        var minimumPixels = RenderPetViewport(viewport);
        bubbleScale.ScaleX = maximum;
        bubbleScale.ScaleY = maximum;
        var maximumPixels = RenderPetViewport(viewport);
        var difference = FindPbgraDifferenceBounds(
            minimumPixels,
            maximumPixels,
            RenderPixelWidth,
            RenderPixelHeight);
        Assert(difference.PixelCount >= 100 &&
               difference.Left >= 85 &&
               difference.Right <= 185 &&
               difference.Top >= 335 &&
               difference.Bottom <= 440,
            $"泡泡最小/最大实渲染差异必须只落在鼻尖附近，实际 " +
            $"{difference.Left},{difference.Top}-{difference.Right},{difference.Bottom}，" +
            $"{difference.PixelCount} pixels");

        SetField(window, "_isEdgeRoaming", false);
        Invoke(window, "RefreshSnoreBubbleAnimationState");
        Assert(GetField<bool>(window, "_isSnoreBubbleAnimating") &&
               bubbleHost.Opacity > 0.99 &&
               bubbleScale.HasAnimatedProperties,
            "回到稳定待机后泡泡必须重新从最小尺寸开始呼吸");
    }

    private static byte[] RenderPetViewport(FrameworkElement viewport)
    {
        viewport.UpdateLayout();
        var bitmap = new RenderTargetBitmap(
            RenderPixelWidth,
            RenderPixelHeight,
            96d * RenderPixelWidth / LogicalPetWidth,
            96d * RenderPixelHeight / LogicalPetHeight,
            PixelFormats.Pbgra32);
        bitmap.Render(viewport);
        var pixels = new byte[RenderPixelWidth * RenderPixelHeight * 4];
        bitmap.CopyPixels(
            pixels,
            RenderPixelWidth * 4,
            offset: 0);
        return pixels;
    }

    private static PixelDifferenceBounds FindPbgraDifferenceBounds(
        byte[] first,
        byte[] second,
        int width,
        int height)
    {
        Assert(first.Length == second.Length &&
               first.Length == width * height * 4,
            "Pbgra实渲染差异缓冲尺寸必须一致");
        var left = width;
        var top = height;
        var right = -1;
        var bottom = -1;
        var pixelCount = 0;
        for (var y = 0; y < height; y++)
        {
            for (var x = 0; x < width; x++)
            {
                var offset = (y * width + x) * 4;
                var difference =
                    Math.Abs(first[offset] - second[offset]) +
                    Math.Abs(first[offset + 1] - second[offset + 1]) +
                    Math.Abs(first[offset + 2] - second[offset + 2]) +
                    Math.Abs(first[offset + 3] - second[offset + 3]);
                if (difference <= 8)
                {
                    continue;
                }

                pixelCount++;
                left = Math.Min(left, x);
                top = Math.Min(top, y);
                right = Math.Max(right, x);
                bottom = Math.Max(bottom, y);
            }
        }

        return new PixelDifferenceBounds(left, top, right, bottom, pixelCount);
    }

    private static int[] DrainActivityBag(MainWindow window, int count)
    {
        var result = new int[count];
        for (var index = 0; index < count; index++)
        {
            Invoke(window, "GetNextAutomaticActivity");
            result[index] = GetField<int>(window, "_lastAutomaticActivityIndex");
        }

        return result;
    }

    private static void AssertMonitorWorkAreaContract(MainWindow window)
    {
        _ = new WindowInteropHelper(window).EnsureHandle();
        var monitorType = typeof(MainWindow).Assembly.GetType(
            "LubanDesktopPet.MonitorWorkArea",
            throwOnError: true)!;
        var workArea = (Rect)InvokeStatic(monitorType, "GetForWindow", window)!;
        AssertValidRect(workArea, "当前显示器工作区");

        var nativeRectType = monitorType.GetNestedType("NativeRect", BindingFlags.NonPublic)
            ?? throw new InvalidOperationException("找不到 MonitorWorkArea.NativeRect");
        var nativeRect = Activator.CreateInstance(nativeRectType)!;
        SetField(nativeRect, "Left", -1920);
        SetField(nativeRect, "Top", 0);
        SetField(nativeRect, "Right", 0);
        SetField(nativeRect, "Bottom", 1040);
        var arguments = new object?[] { window, nativeRect, null };
        var converted = (bool)(monitorType.GetMethod(
                "TryConvertToWindowDips",
                StaticFlags)!
            .Invoke(null, arguments) ?? false);
        Assert(converted && arguments[2] is Rect negativeWorkArea,
            "多屏物理工作区应能转换成 WPF DIP");
        AssertValidRect(negativeWorkArea, "负坐标副屏工作区");
        Assert(negativeWorkArea.Left < 0,
            "位于主屏左侧的副屏必须保留负坐标，不能钳制到主屏");

        Assert(monitorType.GetMethod("MonitorFromWindow", StaticFlags) is not null &&
               monitorType.GetMethod("GetMonitorInfo", StaticFlags) is not null,
            "工作区解析必须基于窗口当前所在显示器及其独立 rcWork");
    }

    private static void AssertDisplaySettingsChangeRecovery(MainWindow window)
    {
        if (!window.IsVisible)
        {
            window.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
        }

        var mainSource = File.ReadAllText(FindWorkspaceFile("MainWindow.xaml.cs"));
        var loadedSource = ExtractPrivateMethodSource(mainSource, "Window_Loaded");
        var closedSource = ExtractPrivateMethodSource(mainSource, "Window_Closing");
        var sessionSwitchSource = ExtractPrivateMethodSource(
            mainSource,
            "SystemEvents_SessionSwitch");
        var powerModeSource = ExtractPrivateMethodSource(
            mainSource,
            "SystemEvents_PowerModeChanged");
        var preferenceSource = ExtractPrivateMethodSource(
            mainSource,
            "SystemEvents_UserPreferenceChanged");
        var recoverySource = ExtractPrivateMethodSource(
            mainSource,
            "ProcessSystemRecovery");
        var recoverTodoGeometry = recoverySource.IndexOf(
            "_todoWindow.RecoverAfterSystemResume();",
            StringComparison.Ordinal);
        var visibleTodoGuard = recoverySource.IndexOf(
            "if (_todoWindow.IsVisible)",
            StringComparison.Ordinal);
        var positionerSource = File.ReadAllText(
            FindWorkspaceFile("OwnedWindowPositioner.cs"));
        var liveChildRead = positionerSource.IndexOf(
            "GetWindowRect(cache._childHandle, out var childRect)",
            StringComparison.Ordinal);
        var unchangedPositionGuard = positionerSource.IndexOf(
            "childRect.Left == desiredPosition.X",
            StringComparison.Ordinal);
        Assert(loadedSource.Contains(
                   "SystemEvents.SessionSwitch +=",
                   StringComparison.Ordinal) &&
               loadedSource.Contains(
                   "SystemEvents.PowerModeChanged +=",
                   StringComparison.Ordinal) &&
               loadedSource.Contains(
                   "SystemEvents.UserPreferenceChanged +=",
                   StringComparison.Ordinal) &&
               closedSource.Contains(
                   "SystemEvents.SessionSwitch -=",
                   StringComparison.Ordinal) &&
               closedSource.Contains(
                   "SystemEvents.PowerModeChanged -=",
                   StringComparison.Ordinal) &&
               closedSource.Contains(
                   "SystemEvents.UserPreferenceChanged -=",
                   StringComparison.Ordinal) &&
               sessionSwitchSource.Contains(
                   "QueueSystemRecovery()",
                   StringComparison.Ordinal) &&
               powerModeSource.Contains(
                   "PowerModes.Resume",
                   StringComparison.Ordinal) &&
               powerModeSource.Contains(
                   "QueueSystemRecovery()",
                   StringComparison.Ordinal) &&
               preferenceSource.Contains(
                   "QueueSystemRecovery()",
                   StringComparison.Ordinal) &&
                recoverTodoGeometry >= 0 &&
                visibleTodoGuard > recoverTodoGeometry &&
               recoverySource.Contains(
                   "_todoWindowPositionCache.InvalidateGeometry()",
                   StringComparison.Ordinal) &&
               positionerSource.Contains(
                   "MonitorFromPoint(anchorCenter, MonitorDefaultToNearest)",
                   StringComparison.Ordinal) &&
               liveChildRead >= 0 &&
               unchangedPositionGuard > liveChildRead,
            "解锁、恢复、电源与桌面首选项变化必须统一恢复；待办定位每次都要读取实时 HWND 矩形，不能信任旧坐标缓存");

        SetField(window, "_edgeDock", GetNestedEnum("EdgeDock", "None"));
        SetField(window, "_activeClip", null);
        SetField(window, "_isPillowBreathing", false);
        SetField(window, "_dragInteractionActive", false);
        SetField(window, "_bubbleMode", GetNestedEnum("BubbleMode", "None"));

        var monitorType = typeof(MainWindow).Assembly.GetType(
            "LubanDesktopPet.MonitorWorkArea",
            throwOnError: true)!;
        var recoveryPetViewbox = GetField<Viewbox>(
            window,
            "PetSizeViewbox");
        var originalWorkArea = (Rect)InvokeStatic(
            monitorType,
            "GetForVisual",
            window,
            recoveryPetViewbox)!;
        window.Left = originalWorkArea.Left;
        window.Top = Math.Clamp(
            originalWorkArea.Top + 40,
            originalWorkArea.Top,
            originalWorkArea.Bottom - window.ActualHeight);
        var recoveryWindowBounds = (Rect)Invoke(
            window,
            "GetPetViewboxBoundsInScreenDips")!;
        var recoveryContactBounds = (Rect)Invoke(
            window,
            "GetPetContactBounds",
            recoveryWindowBounds)!;
        window.Left += originalWorkArea.Left - recoveryContactBounds.Left;
        Invoke(window, "UpdateEdgeDockAfterDrag");
        Assert(GetField<object>(window, "_edgeDock").ToString() == "Left",
            "显示器变化回归测试必须先进入真实手动边缘探头状态");

        window.Left = originalWorkArea.Left - originalWorkArea.Width * 3;
        window.Top = originalWorkArea.Top - originalWorkArea.Height * 3;
        Invoke(window, "SystemEvents_DisplaySettingsChanged", null, EventArgs.Empty);
        PumpDispatcher(TimeSpan.FromMilliseconds(120));

        Assert(GetField<object>(window, "_edgeDock").ToString() == "None",
            "显示器切换或断开后必须终止旧显示器的手动边缘探头状态");
        var recoveredWorkArea = (Rect)InvokeStatic(
            monitorType,
            "GetForVisual",
            window,
            recoveryPetViewbox)!;
        var recoveredVisibleBounds = (Rect)Invoke(
            window,
            "GetPetViewboxBoundsInScreenDips")!;
        Assert(recoveredVisibleBounds.Left >= recoveredWorkArea.Left - 0.5 &&
               recoveredVisibleBounds.Right <= recoveredWorkArea.Right + 0.5 &&
               recoveredVisibleBounds.Top >= recoveredWorkArea.Top - 0.5 &&
               recoveredVisibleBounds.Bottom <= recoveredWorkArea.Bottom + 0.5,
             "显示器切换或断开后桌宠必须被重新夹取到仍有效的工作区内");
    }

    private static void AssertHiddenTodoWindowRecoveryContract(
        MainWindow window)
    {
        const double expectedLogicalWidth = 292;
        const double expectedLogicalHeight = 414;
        if (!window.IsVisible)
        {
            window.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(40));
        }

        var todoWindow = GetField<TodoWindow>(window, "_todoWindow");
        var petAnchor = GetField<Viewbox>(window, "PetSizeViewbox");
        var positionCache = GetRawField(
            window,
            "_todoWindowPositionCache")!;
        var positionerType = typeof(MainWindow).Assembly.GetType(
            "LubanDesktopPet.OwnedWindowPositioner",
            throwOnError: true)!;
        var tryGetPhysicalBounds = positionerType.GetMethod(
            "TryGetPhysicalBounds",
            StaticFlags)
            ?? throw new InvalidOperationException(
                "找不到OwnedWindowPositioner.TryGetPhysicalBounds");
        var todoMode = GetNestedEnum("BubbleMode", "Todo");
        var noneMode = GetNestedEnum("BubbleMode", "None");

        (int Left, int Top, int Right, int Bottom) ReadNativeBounds()
        {
            var arguments = new object?[] { todoWindow, null };
            var success = (bool)(tryGetPhysicalBounds.Invoke(
                null,
                arguments) ?? false);
            Assert(success && arguments[1] is not null,
                "必须能读取TodoWindow真实原生矩形");
            var nativeBounds = arguments[1]!;
            return (
                GetField<int>(nativeBounds, "Left"),
                GetField<int>(nativeBounds, "Top"),
                GetField<int>(nativeBounds, "Right"),
                GetField<int>(nativeBounds, "Bottom"));
        }

        SetField(window, "_suppressTodoWindowDeactivate", true);
        try
        {
            SetField(window, "_sessionInactive", false);
            SetField(window, "_edgeDock", GetNestedEnum("EdgeDock", "None"));
            SetField(window, "_activeClip", null);
            SetField(window, "_bubbleMode", noneMode);
            if (!todoWindow.IsVisible)
            {
                todoWindow.Opacity = 0;
                todoWindow.Show();
                todoWindow.UpdateLayout();
                PumpDispatcher(TimeSpan.FromMilliseconds(30));
            }

            Invoke(positionCache, "InvalidateGeometry");
            Invoke(window, "UpdateTodoWindowPosition");
            todoWindow.Opacity = 0;
            PumpDispatcher(TimeSpan.FromMilliseconds(20));

            // Exercise the native expected-size branch directly while the
            // layered HWND is materialized. Do not call the logical recovery
            // helper here: UpdateTodoWindowPosition itself must repair a bad
            // native size using the anchor monitor's current DPI.
            var directDamageDpi = VisualTreeHelper.GetDpi(petAnchor);
            var directExpectedWidth = (int)Math.Round(
                expectedLogicalWidth * directDamageDpi.DpiScaleX,
                MidpointRounding.AwayFromZero);
            var directExpectedHeight = (int)Math.Round(
                expectedLogicalHeight * directDamageDpi.DpiScaleY,
                MidpointRounding.AwayFromZero);
            var positionUpdateQueuedBefore = GetField<bool>(
                window,
                "_todoPositionUpdateQueued");
            SetField(window, "_todoPositionUpdateQueued", true);
            bool directDamageApplied;
            bool directDamageMoved;
            (int Left, int Top, int Right, int Bottom) directDamagedBounds;
            try
            {
                directDamageApplied = (bool)InvokeStatic(
                    positionerType,
                    "TrySetBounds",
                    todoWindow,
                    new Rect(
                        todoWindow.Left,
                        todoWindow.Top,
                        expectedLogicalWidth / 2,
                        expectedLogicalHeight / 2))!;
                directDamageMoved = (bool)InvokeStatic(
                    positionerType,
                    "TrySetPhysicalPosition",
                    todoWindow,
                    -25000,
                    -25000)!;
                directDamagedBounds = ReadNativeBounds();
            }
            finally
            {
                SetField(
                    window,
                    "_todoPositionUpdateQueued",
                    positionUpdateQueuedBefore);
            }
            Assert(directDamageApplied && directDamageMoved &&
                   directDamagedBounds.Right - directDamagedBounds.Left <
                       directExpectedWidth,
                "隔离回归必须先把已物化Todo HWND压成半宽，才能验证定位器自身的尺寸修复");
            Invoke(positionCache, "InvalidateGeometry");
            Invoke(window, "UpdateTodoWindowPosition");
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            var directRecoveredBounds = ReadNativeBounds();
            var directWorkArea = GetRawField(positionCache, "_workArea")!;
            Assert(directRecoveredBounds.Right - directRecoveredBounds.Left ==
                       directExpectedWidth &&
                   directRecoveredBounds.Bottom - directRecoveredBounds.Top ==
                       directExpectedHeight &&
                   directRecoveredBounds.Left >=
                       GetField<int>(directWorkArea, "Left") &&
                   directRecoveredBounds.Top >=
                       GetField<int>(directWorkArea, "Top") &&
                   directRecoveredBounds.Right <=
                       GetField<int>(directWorkArea, "Right") &&
                   directRecoveredBounds.Bottom <=
                       GetField<int>(directWorkArea, "Bottom"),
                "UpdateTodoWindowPosition必须独立把错误原生尺寸恢复为当前锚点DPI下的完整尺寸并夹入工作区");

            todoWindow.Opacity = 1;
            todoWindow.Hide();
            PumpDispatcher(TimeSpan.FromMilliseconds(20));

            var damaged = (bool)InvokeStatic(
                positionerType,
                "TrySetBounds",
                todoWindow,
                new Rect(
                    todoWindow.Left,
                    todoWindow.Top,
                    expectedLogicalWidth / 2,
                    expectedLogicalHeight / 2))!;
            var movedOffscreen = (bool)InvokeStatic(
                positionerType,
                "TrySetPhysicalPosition",
                todoWindow,
                -30000,
                -30000)!;
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
            var damagedBounds = ReadNativeBounds();
            var damageDpi = VisualTreeHelper.GetDpi(petAnchor);
            var fullNativeWidth = (int)Math.Round(
                expectedLogicalWidth * damageDpi.DpiScaleX,
                MidpointRounding.AwayFromZero);
            Assert(damaged && movedOffscreen &&
                   damagedBounds.Right - damagedBounds.Left <
                       fullNativeWidth &&
                   damagedBounds.Left <= -30000 &&
                   damagedBounds.Top <= -30000 &&
                   !todoWindow.IsVisible,
                "回归必须先构造锁屏/拓扑变化后隐藏Todo HWND窄成半宽且离屏的现场：" +
                $"setBounds={damaged}, moved={movedOffscreen}, visible={todoWindow.IsVisible}, " +
                $"native=({damagedBounds.Left},{damagedBounds.Top})-" +
                $"({damagedBounds.Right},{damagedBounds.Bottom})");

            Invoke(window, "ProcessSystemRecovery");
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
            Assert(!todoWindow.IsVisible &&
                   todoWindow.WindowState == WindowState.Normal &&
                   Math.Abs(
                       todoWindow.Width -
                       expectedLogicalWidth) <= 0.01 &&
                   Math.Abs(
                       todoWindow.Height -
                       expectedLogicalHeight) <= 0.01,
                "解锁恢复隐藏TodoWindow的逻辑尺寸时不能提前显示窗口");

            Invoke(window, "OpenTodoFromPetRightClick");
            PumpDispatcher(TimeSpan.FromMilliseconds(80));
            todoWindow.UpdateLayout();
            var recoveredBounds = ReadNativeBounds();
            var anchorDpi = VisualTreeHelper.GetDpi(petAnchor);
            var expectedWidth = (int)Math.Round(
                expectedLogicalWidth * anchorDpi.DpiScaleX,
                MidpointRounding.AwayFromZero);
            var expectedHeight = (int)Math.Round(
                expectedLogicalHeight * anchorDpi.DpiScaleY,
                MidpointRounding.AwayFromZero);
            var workArea = GetRawField(positionCache, "_workArea")!;
            var workLeft = GetField<int>(workArea, "Left");
            var workTop = GetField<int>(workArea, "Top");
            var workRight = GetField<int>(workArea, "Right");
            var workBottom = GetField<int>(workArea, "Bottom");
            Assert(todoWindow.IsVisible &&
                   recoveredBounds.Right - recoveredBounds.Left ==
                       expectedWidth &&
                   recoveredBounds.Bottom - recoveredBounds.Top ==
                       expectedHeight &&
                   recoveredBounds.Left >= workLeft &&
                   recoveredBounds.Top >= workTop &&
                   recoveredBounds.Right <= workRight &&
                   recoveredBounds.Bottom <= workBottom,
                "隐藏TodoWindow在解锁/多屏恢复后重新右键打开时必须原子恢复完整尺寸并落在当前工作区：" +
                $"actual=({recoveredBounds.Left},{recoveredBounds.Top})-" +
                $"({recoveredBounds.Right},{recoveredBounds.Bottom}), " +
                $"expected={expectedWidth}x{expectedHeight}, " +
                $"work=({workLeft},{workTop})-({workRight},{workBottom})");

            var mainSource = File.ReadAllText(
                FindWorkspaceFile("MainWindow.xaml.cs"));
            var showBubbleSource = ExtractPrivateMethodSource(
                mainSource,
                "ShowBubbleVisuals");
            var positionerSource = File.ReadAllText(
                FindWorkspaceFile("OwnedWindowPositioner.cs"));
            var recoverBeforeShowIndex = showBubbleSource.IndexOf(
                "_todoWindow.RecoverAfterSystemResume();",
                StringComparison.Ordinal);
            var showRecoveredTodoIndex = showBubbleSource.IndexOf(
                "_todoWindow.Show();",
                StringComparison.Ordinal);
            Assert(recoverBeforeShowIndex >= 0 &&
                   showRecoveredTodoIndex > recoverBeforeShowIndex &&
                   positionerSource.Contains(
                       "Size? expectedLogicalSize = null",
                       StringComparison.Ordinal) &&
                   positionerSource.Contains(
                       "VisualTreeHelper.GetDpi(anchor)",
                       StringComparison.Ordinal) &&
                   positionerSource.Contains(
                       "childSizeMatchesTarget ? 0 : targetChildWidth",
                       StringComparison.Ordinal),
                "Todo重开必须在透明Show前恢复逻辑状态，并按宠物当前DPI纠正原生尺寸；" +
                "尺寸正常时仍须保留SWP_NOSIZE快速路径");
        }
        finally
        {
            if (todoWindow.IsVisible)
            {
                Invoke(window, "SetBubbleMode", noneMode);
                todoWindow.Hide();
            }

            var activeClip = GetRawField(window, "_activeClip");
            if (activeClip is not null)
            {
                Invoke(window, "CompleteActiveClip", activeClip);
            }

            SetField(window, "_bubbleMode", noneMode);
            SetField(window, "_suppressTodoWindowDeactivate", false);
        }
    }

    private static void AssertOwnedTodoWindowContract(MainWindow window)
    {
        var workspace = Path.GetDirectoryName(FindWorkspaceFile("DesktopPet.csproj"))!;
        var mainSource = File.ReadAllText(Path.Combine(workspace, "MainWindow.xaml.cs"));
        var rightButtonUpSource = ExtractPrivateMethodSource(
            mainSource,
            "PetHost_MouseRightButtonUp");
        var openTodoFromRightClickSource = ExtractPrivateMethodSource(
            mainSource,
            "OpenTodoFromPetRightClick");
        Assert(rightButtonUpSource.Contains(
                   "OpenTodoFromPetRightClick();",
                   StringComparison.Ordinal) &&
               openTodoFromRightClickSource.Contains(
                   "SetBubbleMode(BubbleMode.Todo);",
                   StringComparison.Ordinal),
            "普通右键入口必须继续切换到 Todo 专用 think 状态，不能随 reaction think 一起删除");
        var setBubbleModeSource = ExtractPrivateMethodSource(
            mainSource,
            "SetBubbleMode");
        var stopClockIndex = setBubbleModeSource.IndexOf(
            "StopVisualClock();",
            StringComparison.Ordinal);
        var showWindowIndex = setBubbleModeSource.IndexOf(
            "ShowBubbleVisuals(mode);",
            StringComparison.Ordinal);
        var enterTodoIndex = setBubbleModeSource.IndexOf(
            "EnterTodoVisualState();",
            StringComparison.Ordinal);
        var freezeTodoClockIndex = setBubbleModeSource.IndexOf(
            "StopVisualClock();",
            enterTodoIndex + 1,
            StringComparison.Ordinal);
        var prepareEnvelopeIndex = setBubbleModeSource.IndexOf(
            "EnsureTodoPetSizePreviewEnvelope();",
            StringComparison.Ordinal);
        var resumeClockIndex = setBubbleModeSource.IndexOf(
            "UpdateVisualClockSubscription();",
            StringComparison.Ordinal);
        Assert(stopClockIndex >= 0 &&
               enterTodoIndex > stopClockIndex &&
               freezeTodoClockIndex > enterTodoIndex &&
               prepareEnvelopeIndex > freezeTodoClockIndex &&
               showWindowIndex > prepareEnvelopeIndex &&
               resumeClockIndex > showWindowIndex,
            "显示 Owned TodoWindow 前必须先准备并冻结Todo入场首帧，再准备固定包络内的缩放会话；" +
            "Show()完成后才恢复视觉时钟，避免重入合成旧动作或跳过入场帧");

        // 这项测试会打开真实的可激活 Owned Window。测试运行期间终端或
        // 其他进程抢焦点不应被误判为用户在待办外部点击。
        var todoWindow = GetField<TodoWindow>(window, "_todoWindow");
        var originalMainHitTestVisible = window.IsHitTestVisible;
        var originalTodoHitTestVisible = todoWindow.IsHitTestVisible;
        var widthDescriptor = DependencyPropertyDescriptor.FromProperty(
            Window.WidthProperty,
            typeof(Window))
            ?? throw new InvalidOperationException("无法监听桌宠Width依赖属性");
        var heightDescriptor = DependencyPropertyDescriptor.FromProperty(
            Window.HeightProperty,
            typeof(Window))
            ?? throw new InvalidOperationException("无法监听桌宠Height依赖属性");
        var ownerWidthChangeCount = 0;
        var ownerHeightChangeCount = 0;
        EventHandler ownerWidthChanged = (_, _) => ownerWidthChangeCount++;
        EventHandler ownerHeightChanged = (_, _) => ownerHeightChangeCount++;
        window.IsHitTestVisible = false;
        todoWindow.IsHitTestVisible = false;
        SetField(window, "_suppressTodoWindowDeactivate", true);
        try
        {
            window.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(40));
            Assert(
                Math.Abs(window.Width - 454d) <= 0.51 &&
                Math.Abs(window.Height - 454d) <= 0.51,
                "主透明HWND启动后必须保持最大包络，只允许原生物理像素取整误差");
            var permanentEnvelopeWidth = window.Width;
            var permanentEnvelopeHeight = window.Height;
            widthDescriptor.AddValueChanged(window, ownerWidthChanged);
            heightDescriptor.AddValueChanged(window, ownerHeightChanged);

            Assert(ReferenceEquals(todoWindow.Owner, window),
                "待办窗口必须是 MainWindow 的 Owned Window");
            Assert(!todoWindow.IsVisible, "待办窗口不得在主窗口启动时自动显示");

            var reactionClip = GetField<Array>(window, "_reactionClips").GetValue(0)!;
            var wakeFrameCount = GetField<Array>(window, "_wakeFrames").Length;
            var reactionStarted = (bool)Invoke(
                window,
                "TryStartReaction",
                reactionClip,
                false)!;
            Assert(reactionStarted, "打开待办前应能启动一段普通动作作为抢占测试");
            Assert(GetRawField(window, "_activeClip") is not null,
                "抢占测试开始后应存在活动动作");
            var reactionActionIndex = GetProperty<int>(reactionClip, "ActionFrameIndex");
            Invoke(window, "ShowActiveClipFrame", reactionActionIndex);
            SetField(window, "_activeFrameDeadlineTimestamp", long.MaxValue);
            var requestedReactionFrame = GetProperty<object>(
                GetClipFrames(reactionClip).GetValue(reactionActionIndex)!,
                "Image");
            WaitForPrefetchedSpritePage(window, requestedReactionFrame);
            Invoke(window, "TryShowPendingSpriteFrame");
            var ordinaryActionFrame = GetField<object>(window, "_currentSpriteFrame");
            var expectedTodoEnterStartIndex = (int)Invoke(
                window,
                "GetTodoEnterStartIndex",
                ordinaryActionFrame)!;
            Assert(expectedTodoEnterStartIndex == wakeFrameCount,
                "普通动作被Todo抢占时必须从站立wake末帧继续，不能闪回趴枕头待机");

            var todoEnterClip = GetField<object>(window, "_todoEnterClip");
            var requestedTodoEntryFrame = GetProperty<object>(
                GetClipFrames(todoEnterClip).GetValue(expectedTodoEnterStartIndex)!,
                "Image");
            var requestedTodoEntryFrameInfo = GetSpriteFrameInfo(requestedTodoEntryFrame);
            // This contract inspects the first live Todo pose. Warm that one page
            // before starting the clip so background atlas decoding cannot consume
            // the entire short wake-to-think segment before the assertion runs.
            PrimeSpritePageForFrame(window, requestedTodoEntryFrame);

            var petSizeViewbox = GetField<Viewbox>(window, "PetSizeViewbox");
            var originalPetPhysicalBounds =
                GetVisualPhysicalBounds(petSizeViewbox);
            var todoVisibleSnapshotCaptured = false;
            var todoVisibleSnapshotValid = false;
            var todoVisibleSnapshotDetail = string.Empty;
            DependencyPropertyChangedEventHandler todoVisibleChanged = (_, e) =>
            {
                if (todoVisibleSnapshotCaptured ||
                    e.NewValue is not true)
                {
                    return;
                }

                todoVisibleSnapshotCaptured = true;
                var visibleClip = GetRawField(window, "_activeClip");
                var visibleFrameIndex = GetField<int>(
                    window,
                    "_activeFrameIndex");
                var visibleFrame = GetRawField(window, "_currentSpriteFrame");
                var visiblePendingFrame = GetRawField(
                    window,
                    "_pendingSpriteFrame");
                var visibleDeadline = GetField<long>(
                    window,
                    "_activeFrameDeadlineTimestamp");
                var visibleClockSubscribed = GetField<bool>(
                    window,
                    "_isVisualClockSubscribed");
                var visibleEnvelopePrepared = GetField<bool>(
                    window,
                    "_petSizeEnvelopePrepared");
                todoVisibleSnapshotValid =
                    ReferenceEquals(visibleClip, todoEnterClip) &&
                    visibleFrameIndex == expectedTodoEnterStartIndex &&
                    Equals(visibleFrame, requestedTodoEntryFrame) &&
                    visiblePendingFrame is null &&
                    visibleDeadline == long.MaxValue &&
                    !visibleClockSubscribed;
                todoVisibleSnapshotDetail =
                    $"index={visibleFrameIndex}, pending={visiblePendingFrame is not null}, " +
                    $"deadline={visibleDeadline}, clock={visibleClockSubscribed}, " +
                    $"envelope={visibleEnvelopePrepared}";
            };
            using var ownerGeometryChanges =
                new WindowPositionChangeRecorder(window);
            var ordinaryTodoStartIndex = -1;
            todoWindow.IsVisibleChanged += todoVisibleChanged;
            try
            {
                Invoke(window, "SetBubbleMode", GetNestedEnum("BubbleMode", "Todo"));
                ordinaryTodoStartIndex = GetField<int>(
                    window,
                    "_activeFrameIndex");
                PumpDispatcher(TimeSpan.FromMilliseconds(30));
            }
            finally
            {
                todoWindow.IsVisibleChanged -= todoVisibleChanged;
            }

            Assert(ReferenceEquals(GetRawField(window, "_activeClip"), todoEnterClip),
                "打开待办必须把活动片段切换为唯一的 Todo 入场片段实例");
            Assert(todoVisibleSnapshotCaptured && todoVisibleSnapshotValid,
                "Owned TodoWindow 首次可见时必须已经准备首个Todo姿势并冻结时钟；" +
                "固定最大包络由窗口启动期长期保持，不依赖尺寸预览会话：" +
                todoVisibleSnapshotDetail);
            Assert(GetField<bool>(window, "_isVisualClockSubscribed"),
                "Owned TodoWindow 的Show()返回后必须恢复Todo入场视觉时钟");
            var ownerGeometryRecords = ownerGeometryChanges.GeometryChanges;
            var ownerDpiAtOpen = VisualTreeHelper.GetDpi(window);
            var expectedEnvelopePixelWidth = (int)Math.Round(
                permanentEnvelopeWidth * ownerDpiAtOpen.DpiScaleX,
                MidpointRounding.AwayFromZero);
            var expectedEnvelopePixelHeight = (int)Math.Round(
                permanentEnvelopeHeight * ownerDpiAtOpen.DpiScaleY,
                MidpointRounding.AwayFromZero);
            Assert(ownerWidthChangeCount == 0 &&
                   ownerHeightChangeCount == 0 &&
                   ownerGeometryChanges.SizeMessageCount == 0 &&
                   Math.Abs(window.Width - permanentEnvelopeWidth) <= 0.001 &&
                   Math.Abs(window.Height - permanentEnvelopeHeight) <= 0.001 &&
                   ownerGeometryRecords.All(record =>
                       (record.Flags & WindowPositionChangeRecorder.SwpNoSize) != 0 ||
                       (record.Width == expectedEnvelopePixelWidth &&
                        record.Height == expectedEnvelopePixelHeight)),
                "右键打开待办不得再改变透明主HWND的Width/Height；" +
                $"widthChanges={ownerWidthChangeCount}, heightChanges={ownerHeightChangeCount}, " +
                $"WM_SIZE={ownerGeometryChanges.SizeMessageCount}, " +
                $"nativeChanges={ownerGeometryRecords.Count}");
            Invoke(window, "TryShowPendingSpriteFrame");

            Assert(todoWindow.IsVisible, "进入 Todo 模式应显示独立 modeless 待办窗口");
            Assert(ReferenceEquals(todoWindow.Owner, window), "显示后 Owner 关系必须保持");
            Assert(!GetField<Popup>(window, "BubblePopup").IsOpen,
                "Todo 模式不得再打开旧 BubblePopup");
            Invoke(window, "UpdateTodoWindowPosition");
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
            var tailHost = GetField<Grid>(todoWindow, "TailHost");
            var tailVerticalTransform = GetField<TranslateTransform>(
                todoWindow,
                "TailVerticalTransform");
            var petTailTopLeft =
                GetField<Viewbox>(window, "PetSizeViewbox")
                    .PointToScreen(new Point(0, 0));
            var petTailBottomRight =
                GetField<Viewbox>(window, "PetSizeViewbox")
                    .PointToScreen(new Point(
                        GetField<Viewbox>(window, "PetSizeViewbox").ActualWidth,
                        GetField<Viewbox>(window, "PetSizeViewbox").ActualHeight));
            var todoOrigin = todoWindow.PointToScreen(new Point(0, 0));
            var todoDpiScaleY = VisualTreeHelper.GetDpi(todoWindow).DpiScaleY;
            var expectedTailTop = Math.Clamp(
                ((petTailTopLeft.Y + petTailBottomRight.Y) / 2 - todoOrigin.Y) /
                    Math.Max(0.01, todoDpiScaleY) -
                9,
                18,
                Math.Max(18, todoWindow.ActualHeight - 36));
            AssertClose(
                tailVerticalTransform.Y,
                expectedTailTop,
                "待办气泡箭头必须跟随当前小鲁班垂直中心，而不是固定在窗口中间");
            AssertClose(
                tailHost.Margin.Top,
                0,
                "待办气泡箭头逐帧跟随不得再修改会触发布局的Margin.Top");
            todoWindow.SetTailPlacement(tailOnRight: true, centerY: -100);
            AssertClose(tailVerticalTransform.Y, 18, "待办箭头上边界钳制");
            todoWindow.SetTailPlacement(tailOnRight: false, centerY: 10000);
            AssertClose(
                tailVerticalTransform.Y,
                Math.Max(18, todoWindow.ActualHeight - 36),
                "待办箭头下边界钳制");
            Invoke(window, "UpdateTodoWindowPosition");
            const double expectedEnvelopeWidth = 454;
            const double expectedEnvelopeHeight = 454;
            AssertClose(
                window.Width,
                expectedEnvelopeWidth,
                "显示待办时主窗口宽度");
            AssertClose(
                window.Height,
                expectedEnvelopeHeight,
                "显示待办时主窗口高度");
            AssertPhysicalBoundsClose(
                GetVisualPhysicalBounds(petSizeViewbox),
                originalPetPhysicalBounds,
                1,
                "右键打开待办时透明包络可以避让屏幕，但可见小鲁班不得跳位");

            var idleFrame = GetSpriteFrameInfo(GetField<object>(window, "_idleFrame"));
            var todoFrameObject = GetField<object>(window, "_todoFrame");
            var todoFrame = GetSpriteFrameInfo(todoFrameObject);
            Assert((todoFrame.PageName == "action-think" ||
                    todoFrame.PageName.StartsWith(
                        "action-think-part-",
                        StringComparison.Ordinal)) &&
                   todoFrame.Name.StartsWith(
                       "Assets/luban-think-smooth-",
                       StringComparison.Ordinal),
                "Todo 状态应使用专用的全身思考姿势");
            Assert(todoFrame.Height >= idleFrame.Height + 30,
                "Todo 姿势的可见高度应显著高于趴枕头待机，不能产生突然缩小的错觉");
            Assert(GetProperty<string>(todoEnterClip, "ActionName") == "todo-open",
                "打开 Todo 必须抢占普通动作并启动平滑起身入场");
            var todoEntryDeadline =
                GetField<long>(window, "_activeFrameDeadlineTimestamp");
            var todoEntryClockSubscribed =
                GetField<bool>(window, "_isVisualClockSubscribed");
            Assert(todoEntryDeadline > 0 && todoEntryClockSubscribed,
                "Todo 起身入场期间必须登记绝对帧截止点并订阅统一视觉时钟；" +
                $"deadline={todoEntryDeadline}, subscribed={todoEntryClockSubscribed}, " +
                $"activeIndex={GetField<int>(window, "_activeFrameIndex")}, " +
                $"pending={GetRawField(window, "_pendingSpriteFrame") is not null}");
            Assert(ordinaryTodoStartIndex == expectedTodoEnterStartIndex &&
                   requestedTodoEntryFrameInfo.Name.EndsWith(
                         $"luban-wake-smooth-{wakeFrameCount:000}.png",
                         StringComparison.Ordinal),
                "普通动作抢占后的Todo入场首帧必须使用站立wake末帧；" +
                $"index={ordinaryTodoStartIndex}, requested={requestedTodoEntryFrameInfo.Name}");

            var entryIndex = GetField<int>(window, "_activeFrameIndex");
            var entryFrame = GetField<object>(window, "_currentSpriteFrame");
            var todoClipLength = GetClipFrames(todoEnterClip).Length;
            Invoke(window, "SetBubbleMode", GetNestedEnum("BubbleMode", "None"));
            var interruptedExit = GetRawField(window, "_activeClip")!;
            Assert(GetProperty<string>(interruptedExit, "ActionName") == "todo-close" &&
                   GetField<int>(window, "_activeFrameIndex") ==
                   todoClipLength - 1 - entryIndex &&
                   Equals(GetField<object>(window, "_currentSpriteFrame"), entryFrame),
                "Todo 入场中途收起必须从当前对应姿势反向播放，不能闪到站立端点");
            Invoke(window, "SetBubbleMode", GetNestedEnum("BubbleMode", "Todo"));
            Assert(GetProperty<string>(GetRawField(window, "_activeClip")!, "ActionName") ==
                   "todo-open" &&
                   GetField<int>(window, "_activeFrameIndex") == entryIndex &&
                   Equals(GetField<object>(window, "_currentSpriteFrame"), entryFrame),
                "Todo 收起中途重新打开必须映射回同一姿势，不能闪到待机端点");

            var todoEnterRemaining = TimeSpan.FromTicks(
                GetClipFrames(todoEnterClip)
                    .Cast<object>()
                    .Skip(GetField<int>(window, "_activeFrameIndex"))
                    .Sum(frame => GetFrameDuration(frame).Ticks));
            PumpDispatcher(todoEnterRemaining + TimeSpan.FromMilliseconds(250));
            var completedTodoClip = GetRawField(window, "_activeClip");
            var completedTodoDeadline = GetField<long>(window, "_activeFrameDeadlineTimestamp");
            var completedTodoClockSubscribed = GetField<bool>(window, "_isVisualClockSubscribed");
            Assert(completedTodoClip is null &&
                   completedTodoDeadline == 0 &&
                   !completedTodoClockSubscribed,
                "Todo 起身入场完成后必须停止统一视觉时钟并释放活动 clip；" +
                $"clip={completedTodoClip}, deadline={completedTodoDeadline}, " +
                $"clock={completedTodoClockSubscribed}, " +
                $"frame={GetField<int>(window, "_activeFrameIndex")}, " +
                $"blend={GetField<bool>(window, "_isFrameBlending")}");
            Assert(Equals(GetField<object>(window, "_currentSpriteFrame"), todoFrameObject),
                "Todo 起身入场完成后应稳定停在专用思考姿势");

            var facingScale = GetField<ScaleTransform>(window, "PetFacingScale");
            var petScale = GetField<ScaleTransform>(window, "PetScale");
            AssertClose(facingScale.ScaleX, 1, "Todo 状态水平朝向缩放");
            AssertClose(facingScale.ScaleY, 1, "Todo 状态垂直朝向缩放");
            AssertClose(petScale.ScaleX, 1, "Todo 状态呼吸水平缩放");
            AssertClose(petScale.ScaleY, 1, "Todo 状态呼吸垂直缩放");
            PumpDispatcher(TimeSpan.FromMilliseconds(220));
            Assert(Equals(GetField<object>(window, "_currentSpriteFrame"), todoFrameObject),
                "Todo 打开期间经过多个动作帧间隔后仍应保持专用思考姿势");

            var monitorType = typeof(MainWindow).Assembly.GetType(
                "LubanDesktopPet.MonitorWorkArea",
                throwOnError: true)!;
            var petViewbox = GetField<Viewbox>(window, "PetSizeViewbox");
            var workArea = (Rect)InvokeStatic(
                monitorType,
                "GetForVisual",
                window,
                petViewbox)!;
            var todoEdgeFrames = GetField<Array>(window, "_edgeLeftFrames");
            var todoEdgeEntryFrame =
                todoEdgeFrames.GetValue(todoEdgeFrames.Length - 1)!;
            PrimeSpritePageForFrame(window, todoEdgeEntryFrame);
            var todoWindowBounds = (Rect)Invoke(
                window,
                "GetPetViewboxBoundsInScreenDips")!;
            Invoke(
                window,
                "MoveMainWindowTo",
                window.Left + workArea.Left - todoWindowBounds.Left,
                window.Top + Math.Clamp(
                                 todoWindowBounds.Top,
                                 workArea.Top,
                                 workArea.Bottom - todoWindowBounds.Height) -
                             todoWindowBounds.Top);
            todoWindowBounds = (Rect)Invoke(
                window,
                "GetPetViewboxBoundsInScreenDips")!;
            var todoContactBounds = (Rect)Invoke(
                window,
                "GetPetContactBounds",
                todoWindowBounds)!;
            Invoke(
                window,
                "MoveMainWindowTo",
                window.Left + workArea.Left - todoContactBounds.Left,
                window.Top);
            var todoEdgeStartTimestamp = Stopwatch.GetTimestamp();
            Invoke(window, "UpdateEdgeDockAfterDrag");
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            Assert(GetField<object>(window, "_edgeDock").ToString() == "Left",
                "Todo 打开时拖到可见像素接触屏幕左边缘必须启动探头状态");
            var todoEdgeDeadline =
                GetField<long>(window, "_edgePeekFrameDeadlineTimestamp");
            Assert(todoEdgeDeadline > todoEdgeStartTimestamp &&
                   todoEdgeDeadline != long.MaxValue &&
                   !todoWindow.IsVisible &&
                   GetField<object>(window, "_bubbleMode").ToString() == "None" &&
                   Equals(
                       GetField<object>(window, "_currentSpriteFrame"),
                       todoEdgeEntryFrame) &&
                   GetField<DispatcherTimer>(
                       window,
                       "_edgePeekHoldTimer").IsEnabled &&
                   !GetField<bool>(window, "_isVisualClockSubscribed"),
                "Todo 打开时拖到左边缘必须自动关闭任务面板，并恢复v1.0.57末帧休息入口");

            var preservedTodoEdgeDeadline =
                GetField<long>(window, "_edgePeekFrameDeadlineTimestamp");
            Assert(GetRawField(window, "_activeClip") is null &&
                   GetField<object>(window, "_edgeDock").ToString() == "Left" &&
                   preservedTodoEdgeDeadline > 0 &&
                   preservedTodoEdgeDeadline != long.MaxValue &&
                   todoEdgeFrames.Cast<object>().Contains(
                       GetField<object>(window, "_currentSpriteFrame")) &&
                   (GetField<bool>(window, "_isVisualClockSubscribed") ||
                    GetField<DispatcherTimer>(
                        window,
                        "_edgePeekHoldTimer").IsEnabled),
                "自动关闭 Todo 后必须保留边缘探头状态、帧和绝对时钟");
            GetField<DispatcherTimer>(window, "_edgePeekHoldTimer").Stop();
            AdvanceEdgePeekForControlledClock(window, preservedTodoEdgeDeadline);
            Assert(GetField<object>(window, "_edgeDock").ToString() == "Left" &&
                   GetField<long>(window, "_edgePeekFrameDeadlineTimestamp") >
                   preservedTodoEdgeDeadline,
                "自动关闭 Todo 后边缘探头必须继续推进，不能回到待机或停在僵死帧");

            Invoke(window, "SetBubbleMode", GetNestedEnum("BubbleMode", "Todo"));
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            Assert(todoWindow.IsVisible,
                "贴边自动关闭后应能再次复用同一个 TodoWindow 成功打开");
            Assert(ReferenceEquals(todoWindow.Owner, window),
                "重新打开后 Owned Window 关系必须保持");
            Assert(GetField<object>(window, "_edgeDock").ToString() == "None",
                "吸附中重新打开 Todo 时仍应由思考姿势接管画面并主动退出边缘探头");
            Assert(!GetField<Popup>(window, "BubblePopup").IsOpen,
                "重新打开 TodoWindow 时旧 BubblePopup 仍不得显示");

            Invoke(window, "SetBubbleMode", GetNestedEnum("BubbleMode", "None"));
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
            Assert(!todoWindow.IsVisible, "收起 Todo 模式应隐藏而非销毁独立待办窗口");
            var finalTodoExitClip = GetRawField(window, "_activeClip")!;
            Assert(GetProperty<string>(finalTodoExitClip, "ActionName") == "todo-close",
                "右键或外部点击收起 Todo 都应播放同一段平滑过渡");
            var todoExitRemaining = TimeSpan.FromTicks(
                GetClipFrames(finalTodoExitClip)
                    .Cast<object>()
                    .Skip(GetField<int>(window, "_activeFrameIndex"))
                    .Sum(frame => GetFrameDuration(frame).Ticks));
            PumpDispatcher(todoExitRemaining + TimeSpan.FromMilliseconds(250));
            Assert(GetRawField(window, "_activeClip") is null &&
                   ownerWidthChangeCount == 0 &&
                   ownerHeightChangeCount == 0 &&
                   ownerGeometryChanges.SizeMessageCount == 0 &&
                   Math.Abs(window.Width - permanentEnvelopeWidth) <= 0.001 &&
                   Math.Abs(window.Height - permanentEnvelopeHeight) <= 0.001,
                "Todo 收起过渡完成后必须清理活动动作，且打开、收起全过程不得改变固定主HWND包络");
        }
        finally
        {
            widthDescriptor.RemoveValueChanged(window, ownerWidthChanged);
            heightDescriptor.RemoveValueChanged(window, ownerHeightChanged);
            window.IsHitTestVisible = originalMainHitTestVisible;
            todoWindow.IsHitTestVisible = originalTodoHitTestVisible;
            SetField(window, "_suppressTodoWindowDeactivate", false);
        }
    }

    private static void AssertTodoReorderPersistenceContract(MainWindow window)
    {
        var tempDirectory = Path.Combine(
            Path.GetTempPath(),
            $"xlb-pet-todo-order-{Guid.NewGuid():N}");
        var todoPath = Path.Combine(tempDirectory, "todos.json");
        var todoStore = new TodoStore(todoPath);
        var originalTodoStore = GetField<TodoStore>(window, "_todoStore");
        var todos = GetField<ObservableCollection<TodoItem>>(window, "_todos");
        var originalTodos = todos.ToArray();
        SetField(window, "_todoStore", todoStore);

        try
        {
            todos.Clear();
            var first = new TodoItem { Text = "第一项" };
            var second = new TodoItem { Text = "第二项", IsCompleted = true };
            var third = new TodoItem { Text = "第三项" };
            todos.Add(first);
            todos.Add(second);
            todos.Add(third);

            var todoWindow = GetField<TodoWindow>(window, "_todoWindow");
            Assert(ReferenceEquals(todoWindow.Todos, todos),
                "TodoWindow 必须直接绑定 MainWindow 的 ObservableCollection，拖放后界面才能立即反映新顺序");

            Invoke(window, "TodoWindow_TodoMoveRequested", third, 0);
            Assert(todos.Count == 3 &&
                   ReferenceEquals(todos[0], third) &&
                   ReferenceEquals(todos[1], first) &&
                   ReferenceEquals(todos[2], second),
                "拖拽重排必须通过 ObservableCollection.Move 更新原集合，不能复制或重建待办项");

            var persistedAfterMove = todoStore.Load();
            Assert(persistedAfterMove.Select(item => item.Text)
                    .SequenceEqual(new[] { "第三项", "第一项", "第二项" }) &&
                   persistedAfterMove[2].IsCompleted,
                "拖拽落下后必须按 ObservableCollection 的最终顺序立即保存，并保留完成状态");

            third.Text = "修改后的第三项";
            Invoke(window, "TodoWindow_TodoEdited", third);
            var persistedAfterEdit = todoStore.Load();
            Assert(persistedAfterEdit.Select(item => item.Text)
                    .SequenceEqual(new[] { "修改后的第三项", "第一项", "第二项" }),
                "独立修改窗确认事件必须立即保存修改后的文字，同时保持拖拽产生的顺序");

            var orderBeforeNoOp = todos.ToArray();
            Invoke(window, "TodoWindow_TodoMoveRequested", third, 0);
            Assert(todos.SequenceEqual(orderBeforeNoOp),
                "拖到原位置必须保持集合不变，不能制造无意义的二次移动");

            Invoke(window, "TodoWindow_TodoMoveRequested", new TodoItem { Text = "外部项" }, 1);
            Assert(todos.SequenceEqual(orderBeforeNoOp),
                "不属于当前 ObservableCollection 的外部拖放项必须被忽略");
        }
        finally
        {
            SetField(window, "_todoStore", originalTodoStore);
            todos.Clear();
            foreach (var item in originalTodos)
            {
                todos.Add(item);
            }

            try
            {
                Directory.Delete(tempDirectory, recursive: true);
            }
            catch
            {
                // 临时持久化文件的清理失败不应掩盖待办顺序契约结果。
            }
        }
    }

    private static void AssertStartupRegistrationContract()
    {
        var startupType = typeof(MainWindow).Assembly.GetType(
            "LubanDesktopPet.StartupRegistration",
            throwOnError: true)!;
        var constructor = startupType.GetConstructor(
            InstanceFlags,
            binder: null,
            [
                typeof(string),
                typeof(Func<string>),
                typeof(Action<string>),
                typeof(Action)
            ],
            modifiers: null) ??
            throw new InvalidOperationException(
                "StartupRegistration 必须提供委托后端构造函数以便无注册表测试");
        var tryReadAndRepair = startupType.GetMethod(
            "TryReadAndRepair",
            InstanceFlags) ??
            throw new InvalidOperationException(
                "StartupRegistration 缺少 TryReadAndRepair");
        var trySetEnabled = startupType.GetMethod(
            "TrySetEnabled",
            InstanceFlags) ??
            throw new InvalidOperationException(
                "StartupRegistration 缺少 TrySetEnabled");
        var buildLaunchCommand = startupType.GetMethod(
            "BuildLaunchCommand",
            StaticFlags) ??
            throw new InvalidOperationException(
                "StartupRegistration 缺少 BuildLaunchCommand");

        var executablePath = Path.Combine(
            Path.GetTempPath(),
            "小鲁班 desktop",
            "LubanDesktopPet.exe");
        var expectedCommand = (string)(buildLaunchCommand.Invoke(
            null,
            [executablePath, null]) ??
            throw new InvalidOperationException("开机启动命令不能为空"));
        Assert(expectedCommand ==
               $"\"{Path.GetFullPath(executablePath)}\" --autostart",
            "开机启动命令必须完整引用可执行文件路径并附加 --autostart");

        string? storedValue = null;
        var readCount = 0;
        var writeCount = 0;
        var deleteCount = 0;
        Func<string?> readValue = () =>
        {
            readCount++;
            return storedValue;
        };
        Action<string> writeValue = value =>
        {
            writeCount++;
            storedValue = value;
        };
        Action deleteValue = () =>
        {
            deleteCount++;
            storedValue = null;
        };
        var registration = constructor.Invoke(
            [expectedCommand, readValue, writeValue, deleteValue]);

        object?[] readArguments = [false, null];
        Assert((bool)(tryReadAndRepair.Invoke(
                   registration,
                   readArguments) ?? false) &&
               readArguments[0] is false &&
               readArguments[1] is null &&
               readCount == 1 &&
               writeCount == 0 &&
               deleteCount == 0,
            "委托后端无启动项时必须只读取一次并报告关闭，绝不能访问或写入真实注册表");

        storedValue = "\"C:\\旧目录\\LubanDesktopPet.exe\" --autostart";
        readArguments = [false, null];
        Assert((bool)(tryReadAndRepair.Invoke(
                   registration,
                   readArguments) ?? false) &&
               readArguments[0] is true &&
               readArguments[1] is null &&
               storedValue == expectedCommand &&
               writeCount == 1,
            "发现旧路径时必须通过注入的写委托修复，并重新读取验证");

        storedValue = null;
        object?[] setArguments = [true, false, null];
        Assert((bool)(trySetEnabled.Invoke(
                   registration,
                   setArguments) ?? false) &&
               setArguments[1] is true &&
               setArguments[2] is null &&
               storedValue == expectedCommand,
            "开启自启必须写入精确命令并通过假后端回读验证");
        setArguments = [false, true, null];
        Assert((bool)(trySetEnabled.Invoke(
                   registration,
                   setArguments) ?? false) &&
               setArguments[1] is false &&
               setArguments[2] is null &&
               storedValue is null &&
               deleteCount == 1,
            "关闭自启必须通过假后端删除并验证最终状态");

        storedValue = "legacy-command";
        var corruptExpectedWrite = true;
        Action<string> failingWriteValue = value =>
        {
            if (corruptExpectedWrite &&
                string.Equals(value, expectedCommand, StringComparison.Ordinal))
            {
                storedValue = "corrupt-command";
                return;
            }

            storedValue = value;
        };
        var failingRegistration = constructor.Invoke(
            [
                expectedCommand,
                (Func<string?>)(() => storedValue),
                failingWriteValue,
                (Action)(() => storedValue = null)
            ]);
        setArguments = [true, false, null];
        Assert(!(bool)(trySetEnabled.Invoke(
                    failingRegistration,
                    setArguments) ?? true) &&
               setArguments[1] is true &&
               setArguments[2] is string error &&
               error.Contains("校验失败", StringComparison.Ordinal) &&
               storedValue == "legacy-command",
            "假后端写后校验失败时必须恢复原值，并报告恢复后的真实启用状态");

        storedValue = string.Empty;
        setArguments = [true, true, null];
        Assert(!(bool)(trySetEnabled.Invoke(
                    failingRegistration,
                    setArguments) ?? true) &&
               setArguments[1] is false &&
               setArguments[2] is string emptyRestoreError &&
               emptyRestoreError.Contains("校验失败", StringComparison.Ordinal) &&
               storedValue == string.Empty,
            "空字符串也是已有注册表原值，设置失败后必须逐字恢复为空字符串，不能误删为不存在");
        corruptExpectedWrite = false;

        storedValue = null;
        var deniedRegistration = constructor.Invoke(
            [
                expectedCommand,
                (Func<string?>)(() => storedValue),
                (Action<string>)(_ =>
                    throw new UnauthorizedAccessException("无权写入测试后端")),
                (Action)(() =>
                    throw new UnauthorizedAccessException("无权删除测试后端"))
            ]);
        setArguments = [true, true, null];
        Assert(!(bool)(trySetEnabled.Invoke(
                    deniedRegistration,
                    setArguments) ?? true) &&
               setArguments[1] is false &&
               setArguments[2] is string permissionError &&
               permissionError.Contains("无权写入", StringComparison.Ordinal) &&
               storedValue is null,
            "注册表权限不足必须被转换为可展示的失败结果，程序不得崩溃或改动原状态");
    }

    private static void AssertSystemTrayContract()
    {
        var assembly = typeof(MainWindow).Assembly;
        var trayType = assembly.GetType(
            "LubanDesktopPet.TrayIconService",
            throwOnError: true)!;
        Assert(typeof(IDisposable).IsAssignableFrom(trayType),
            "系统托盘服务必须实现 IDisposable，确保退出时立即移除图标");
        Assert(trayType.GetField("_menu", InstanceFlags)?.FieldType ==
                   typeof(ContextMenu) &&
               trayType.GetField("_exitItem", InstanceFlags)?.FieldType ==
                   typeof(MenuItem),
            "托盘菜单必须使用现有WPF控件，不能重新加载Windows Forms桌面框架");
        Assert(assembly.GetManifestResourceNames().Contains(
                   "LubanDesktopPet.Assets.luban-tray.ico",
                   StringComparer.Ordinal),
            "小鲁班托盘图标必须作为程序集资源嵌入，发布单个EXE后仍可创建");

        var appSource = File.ReadAllText(FindWorkspaceFile("App.xaml.cs"));
        var appXaml = File.ReadAllText(FindWorkspaceFile("App.xaml"));
        var traySource = File.ReadAllText(
            FindWorkspaceFile("TrayIconService.cs"));
        var projectSource = File.ReadAllText(
            FindWorkspaceFile("DesktopPet.csproj"));
        var startupMethod = appSource;
        var exitMethod = appSource;
        var trayExitMethod = ExtractPrivateMethodSource(
            appSource,
            "TrayIconService_ExitRequested");
        var disposeMethod = traySource;
        var queueTrayMenu = ExtractPrivateMethodSource(
            traySource,
            "QueueTrayMenu");
        var showQueuedTrayMenu = ExtractPrivateMethodSource(
            traySource,
            "ShowQueuedTrayMenu");
        var menuClosed = ExtractPrivateMethodSource(
            traySource,
            "Menu_Closed");
        var ownerDeactivated = ExtractPrivateMethodSource(
            traySource,
            "Owner_Deactivated");

        var mutexAcquisition = startupMethod.IndexOf(
            "_singleInstanceMutex.WaitOne(0)",
            StringComparison.Ordinal);
        var duplicateExit = startupMethod.IndexOf(
            "if (!_ownsSingleInstanceMutex)",
            StringComparison.Ordinal);
        var mainWindowShow = startupMethod.IndexOf(
            "mainWindow.Show()",
            StringComparison.Ordinal);
        var trayCreation = startupMethod.IndexOf(
            "_trayIconService = new TrayIconService(mainWindow)",
            StringComparison.Ordinal);
        Assert(mutexAcquisition >= 0 &&
               duplicateExit > mutexAcquisition &&
               mainWindowShow > duplicateExit &&
               trayCreation > mainWindowShow &&
               startupMethod.Split(
                   "new TrayIconService(mainWindow)",
                   StringSplitOptions.None).Length == 2,
            "只有取得单实例锁的首个进程才能创建一个托盘图标，重复实例不得闪出图标");
        Assert(traySource.Contains(
                   "Header = \"退出小鲁班\"",
                   StringComparison.Ordinal) &&
                traySource.Contains(
                   "ExitRequested?.Invoke(this, EventArgs.Empty)",
                   StringComparison.Ordinal) &&
                traySource.Contains(
                   "new FontFamily(\"Microsoft YaHei\")",
                   StringComparison.Ordinal) &&
                traySource.Contains(
                   "MenuSelectionBrush",
                   StringComparison.Ordinal) &&
                traySource.Contains(
                   "MenuSelectionBorderBrush",
                   StringComparison.Ordinal) &&
                traySource.Contains(
                    "HorizontalAlignment.Left",
                    StringComparison.Ordinal) &&
                traySource.Contains(
                    "UseLayoutRounding = true",
                    StringComparison.Ordinal),
            "托盘菜单必须保留微软雅黑、萌橘色高亮、左对齐整像素布局和“退出小鲁班”，" +
            "点击后只发布正常退出请求");
        Assert(appXaml.Contains(
                   "ShutdownMode=\"OnMainWindowClose\"",
                   StringComparison.Ordinal) &&
               trayExitMethod.Contains(
                   "mainWindow.Close()",
                   StringComparison.Ordinal) &&
               trayExitMethod.Contains(
                   "Shutdown()",
                   StringComparison.Ordinal) &&
               trayExitMethod.Contains(
                   "Dispatcher.BeginInvoke",
                   StringComparison.Ordinal),
            "托盘退出必须回到WPF UI线程并走 MainWindow.Close；无主窗时才直接 Shutdown");
        var removeIcon = disposeMethod.IndexOf(
            "RemoveTrayIcon();",
            StringComparison.Ordinal);
        var removeHook = disposeMethod.IndexOf(
            "hwndSource.RemoveHook(_messageHook)",
            StringComparison.Ordinal);
        var destroyIcon = disposeMethod.IndexOf(
            "DestroyIcon(_iconHandle)",
            StringComparison.Ordinal);
        Assert(removeIcon >= 0 &&
               removeHook > removeIcon &&
               destroyIcon > removeHook &&
               disposeMethod.Contains(
                    "_exitItem.Click -= ExitItem_Click",
                   StringComparison.Ordinal) &&
               disposeMethod.Contains(
                    "_owner.Deactivated -= Owner_Deactivated",
                   StringComparison.Ordinal) &&
               exitMethod.Contains(
                   "trayIconService.ExitRequested -=",
                   StringComparison.Ordinal) &&
               exitMethod.Contains(
                   "trayIconService.Dispose()",
                   StringComparison.Ordinal) &&
               exitMethod.Contains(
                    "_trayIconService = null",
                    StringComparison.Ordinal),
            "应用退出必须解绑事件、NIM_DELETE移除图标、移除HWND钩子并销毁HICON，不能留下幽灵图标或重复回调");
        Assert(traySource.Contains(
                   "Shell_NotifyIconW(NimAdd",
                   StringComparison.Ordinal) &&
               traySource.Contains(
                   "Shell_NotifyIconW(NimDelete",
                   StringComparison.Ordinal) &&
               traySource.Contains(
                   "RegisterWindowMessageW(\"TaskbarCreated\")",
                   StringComparison.Ordinal) &&
               traySource.Contains(
                   "hwndSource.AddHook(_messageHook)",
                   StringComparison.Ordinal) &&
               traySource.Contains(
                   "data.uVersion = NotifyIconVersion4",
                   StringComparison.Ordinal),
            "原生托盘必须通过Shell_NotifyIcon和主窗HWND工作，并在Explorer重启后恢复图标");
        var foregroundIndex = showQueuedTrayMenu.IndexOf(
            "SetForegroundWindow(_windowHandle)",
            StringComparison.Ordinal);
        var openIndex = showQueuedTrayMenu.IndexOf(
            "_menu.IsOpen = true",
            StringComparison.Ordinal);
        Assert(queueTrayMenu.Contains(
                   "TryGetTrayMenuScreenPoint(preferCursor, out var screenPoint)",
                   StringComparison.Ordinal) &&
               queueTrayMenu.Contains("_menuOpenQueued", StringComparison.Ordinal) &&
               queueTrayMenu.Contains(
                   "DispatcherPriority.Input",
                   StringComparison.Ordinal) &&
               foregroundIndex >= 0 &&
               openIndex > foregroundIndex &&
               !showQueuedTrayMenu.Contains(
                   "_menu.IsOpen = false",
                   StringComparison.Ordinal) &&
               traySource.Contains(
                   "_owner.Deactivated += Owner_Deactivated",
                   StringComparison.Ordinal) &&
               ownerDeactivated.Contains(
                   "_menu.IsOpen = false",
                   StringComparison.Ordinal) &&
               menuClosed.Contains(
                   "Shell_NotifyIconW(NimSetFocus",
                   StringComparison.Ordinal) &&
               menuClosed.Contains("PostMessageW(", StringComparison.Ordinal) &&
               !traySource.Contains(
                   "_owner.PointToScreen(",
                   StringComparison.Ordinal) &&
               traySource.Contains(
                   "GetCursorPos(out var cursorPoint)",
                   StringComparison.Ordinal) &&
               traySource.Contains(
                   "Shell_NotifyIconGetRect(",
                   StringComparison.Ordinal) &&
               traySource.Contains(
                   "Marshal.SizeOf<NotifyIconIdentifier>()",
                   StringComparison.Ordinal) &&
               traySource.Contains(
                   "owner.PointFromScreen(screenPoint)",
                   StringComparison.Ordinal) &&
               traySource.Contains(
                   "_menu.PlacementTarget = _owner",
                   StringComparison.Ordinal) &&
               traySource.Contains(
                   "_menu.PlacementRectangle = new Rect(",
                   StringComparison.Ordinal) &&
               traySource.Contains(
                   "PlacementMode.RelativePoint",
                   StringComparison.Ordinal) &&
               !traySource.Contains(
                   "PlacementMode.MousePoint",
                   StringComparison.Ordinal),
            "托盘右键菜单必须以Win32光标屏幕坐标为锚点，转换为owner相对DIP后打开；" +
            "原生回调必须合并到Input Dispatcher，前台化owner后只打开一次；" +
            "外点/失活必须关闭，关闭后用NIM_SETFOCUS与WM_NULL归还通知区焦点；" +
            "两种原生锚点都失败时本次不打开，不能乱跳到桌宠中心或MousePoint");

        var placementOwner = new Window
        {
            Width = 120,
            Height = 90,
            Left = -10000,
            Top = -10000,
            ShowActivated = false,
            WindowStyle = WindowStyle.None
        };
        try
        {
            placementOwner.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            var expectedPlacementPoint = new Point(27, 19);
            var screenPoint = placementOwner.PointToScreen(expectedPlacementPoint);
            var actualPlacementPoint = (Point)InvokeStatic(
                trayType,
                "ConvertTrayMenuPlacementPoint",
                placementOwner,
                screenPoint)!;
            AssertClose(actualPlacementPoint.X, expectedPlacementPoint.X,
                "托盘菜单屏幕坐标转换必须保留X方向DPI位置");
            AssertClose(actualPlacementPoint.Y, expectedPlacementPoint.Y,
                "托盘菜单屏幕坐标转换必须保留Y方向DPI位置");
        }
        finally
        {
            placementOwner.Close();
        }

        Assert(!projectSource.Contains(
                   "Microsoft.WindowsDesktop.App.WindowsForms",
                   StringComparison.Ordinal) &&
               !traySource.Contains(
                   "System.Windows.Forms",
                   StringComparison.Ordinal) &&
               !traySource.Contains(
                   "System.Drawing",
                   StringComparison.Ordinal) &&
               !traySource.Contains(
                   "ToolStrip",
                   StringComparison.Ordinal) &&
                projectSource.Contains(
                    "EmbeddedResource Include=\"Assets\\luban-tray.ico\"",
                    StringComparison.Ordinal),
            "项目必须嵌入托盘ICO，同时彻底移除Windows Forms/System.Drawing依赖以降低常驻内存");
    }

    private static void AssertTodoCutContract()
    {
        var todoWindow = new TodoWindow
        {
            Left = -10000,
            Top = -10000,
            ShowActivated = false
        };
        try
        {
            todoWindow.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            var input = GetField<TextBox>(todoWindow, "TodoInput");

            input.Text = "甲乙丙";
            input.Select(0, 1);
            Assert((bool)(Invoke(
                       todoWindow,
                       "TryCutSelectedText",
                       input) ?? false),
                "TodoInput 选中首字符时必须由原子剪切路径处理");
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            Assert(input.Text == "乙丙" &&
                   input.SelectionStart == 0 &&
                   input.SelectionLength == 0 &&
                   Clipboard.GetText() == "甲",
                "TodoInput 首字符 Ctrl+X 必须复制“甲”、删除一次并把光标稳定放回索引0");

            input.Text = "甲乙丙";
            input.Select(0, 0);
            Assert(!(bool)(Invoke(
                        todoWindow,
                        "TryCutSelectedText",
                        input) ?? true) &&
                   input.Text == "甲乙丙" &&
                   input.SelectionLength == 0,
                "TodoInput 无选区 Ctrl+X 必须无操作，不能沿用 Ctrl+C 的复制全文契约");

            input.Text = "甲乙丙";
            input.Select(0, 1);
            using (HoldClipboardOpenForTest())
            {
                Assert(!(bool)(Invoke(
                            todoWindow,
                            "TryCutSelectedText",
                            input) ?? true) &&
                       input.Text == "甲乙丙" &&
                       input.SelectionStart == 0 &&
                       input.SelectionLength == 1,
                    "剪切时剪贴板被占用必须原样保留全文和首字符选区，不能先删字再异步重试");
            }

            var previewKeySource = ExtractPrivateMethodSource(
                File.ReadAllText(FindWorkspaceFile("TodoWindow.xaml.cs")),
                "TodoWindow_PreviewKeyDown");
            var effectiveKeySource = ExtractPrivateMethodSource(
                File.ReadAllText(FindWorkspaceFile("TodoWindow.xaml.cs")),
                "GetEffectiveShortcutKey");
            var tryCutSource = ExtractPrivateMethodSource(
                File.ReadAllText(FindWorkspaceFile("TodoWindow.xaml.cs")),
                "TryCutSelectedText");
            var cutIndex = previewKeySource.IndexOf(
                "TryCutSelectedText(cutTextBox)",
                StringComparison.Ordinal);
            var handledIndex = previewKeySource.LastIndexOf(
                "e.Handled = true",
                cutIndex,
                StringComparison.Ordinal);
            Assert(previewKeySource.Contains(
                       "var effectiveKey = GetEffectiveShortcutKey(e)",
                       StringComparison.Ordinal) &&
                   previewKeySource.Contains(
                       "effectiveKey == Key.X",
                       StringComparison.Ordinal) &&
                   previewKeySource.Contains(
                       "Keyboard.Modifiers == ModifierKeys.Control",
                       StringComparison.Ordinal) &&
                   handledIndex >= 0 &&
                   cutIndex > handledIndex &&
                   !previewKeySource[..cutIndex].Contains(
                       "IsImeComposing",
                       StringComparison.Ordinal) &&
                   effectiveKeySource.Contains(
                       "Key.ImeProcessed => e.ImeProcessedKey",
                       StringComparison.Ordinal) &&
                   effectiveKeySource.Contains(
                       "Key.System => e.SystemKey",
                       StringComparison.Ordinal),
                "Ctrl+X 必须识别普通、ImeProcessed 和 System 键，并在任何异步让步前同步处理显式选区");
            Assert(tryCutSource.Contains(
                       "var textSnapshot = textBox.Text",
                       StringComparison.Ordinal) &&
                   tryCutSource.Contains(
                       "if (!TryCopyTextToClipboard(selectedText))",
                       StringComparison.Ordinal) &&
                   tryCutSource.IndexOf(
                       "if (!TryCopyTextToClipboard(selectedText))",
                       StringComparison.Ordinal) <
                   tryCutSource.IndexOf(
                       "RemovePendingCutSelection(",
                       StringComparison.Ordinal) &&
                   !tryCutSource.Contains(
                       "QueueClipboardRetry",
                       StringComparison.Ordinal) &&
                   typeof(TodoWindow).GetFields(InstanceFlags)
                       .All(field => !field.Name.Contains(
                           "pendingClipboardCut",
                           StringComparison.OrdinalIgnoreCase)),
                "剪切必须先同步写剪贴板、成功后再删选区；失败不得排队延迟删除，也不得保留 pending cut 状态");

            input.Text = "甲乙丙";
            input.Select(0, 1);
            InvokeStatic(
                typeof(TodoWindow),
                "RemovePendingCutSelection",
                input,
                "甲乙丙",
                0,
                1,
                "甲",
                true);
            Assert(input.Text == "乙丙" &&
                   input.SelectionStart == 0 &&
                   input.SelectionLength == 0,
                "延迟剪切快照完全匹配时必须只删除原选区一次");

            input.Text = "甲乙丙丁";
            input.Select(0, 1);
            InvokeStatic(
                typeof(TodoWindow),
                "RemovePendingCutSelection",
                input,
                "甲乙丙",
                0,
                1,
                "甲",
                true);
            Assert(input.Text == "甲乙丙丁" &&
                   input.SelectionStart == 0 &&
                   input.SelectionLength == 1,
                "延迟重试前全文已变化时必须放弃旧剪切，不能删除新输入");

            input.Text = "甲乙丙";
            input.Select(1, 1);
            InvokeStatic(
                typeof(TodoWindow),
                "RemovePendingCutSelection",
                input,
                "甲乙丙",
                0,
                1,
                "甲",
                true);
            Assert(input.Text == "甲乙丙" &&
                   input.SelectionStart == 1 &&
                   input.SelectionLength == 1,
                "同步快照删除前选区已变化时必须放弃旧剪切");

            var item = new TodoItem { Text = "甲乙丙" };
            todoWindow.Todos = new ObservableCollection<TodoItem> { item };
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            var list = GetField<ListBox>(todoWindow, "TodoItemsControl");
            todoWindow.UpdateLayout();
            list.UpdateLayout();
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
            var container = list.ItemContainerGenerator.ContainerFromIndex(0)
                as DependencyObject ??
                throw new InvalidOperationException("剪切回归找不到待办列表行");
            var editor = FindVisualDescendant<TextBox>(container) ??
                throw new InvalidOperationException("剪切回归找不到待办行 TextBox");
            Assert(editor.IsReadOnly &&
                   !(bool)(Invoke(
                       todoWindow,
                       "IsEditableTextSource",
                       editor) ?? true),
                "只读待办行不得进入自定义 Ctrl+X 路径");

            var editorSource = PresentationSource.FromVisual(editor)
                ?? throw new InvalidOperationException("F2 待办编辑没有输入源");
            var f2 = CreateKeyEvent(editorSource, Key.F2);
            Invoke(
                todoWindow,
                "TodoEditTextBox_PreviewKeyDown",
                editor,
                f2);
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            var independentEditor = GetField<TaskTextEditWindow>(
                todoWindow,
                "_taskTextEditWindow");
            var independentTextBox = GetField<TextBox>(
                independentEditor,
                "EditorTextBox");
            independentTextBox.Select(0, 1);
            Assert(f2.Handled &&
                   editor.IsReadOnly &&
                   independentEditor.IsVisible &&
                   ApplicationCommands.Cut.CanExecute(
                       parameter: null,
                       target: independentTextBox),
                "F2 必须打开独立修改窗；列表行保持只读，独立 TextBox 继续使用原生 Ctrl+X");
            independentEditor.CloseWithoutSaving();
        }
        finally
        {
            todoWindow.CloseForApplication();
        }
    }

    private static void AssertDeleteConfirmationFlowContract()
    {
        var todoWindow = new TodoWindow
        {
            Left = -10000,
            Top = -10000,
            ShowActivated = false,
            Todos = new ObservableCollection<TodoItem>()
        };
        var deletedItems = new List<TodoItem>();
        todoWindow.DeleteRequested += deletedItems.Add;
        todoWindow.Show();
        PumpDispatcher(TimeSpan.FromMilliseconds(20));

        Exception? dialogCallbackFailure = null;
        void InvokeDeleteWithDialog(
            TodoItem item,
            Action<CuteConfirmationWindow> interact)
        {
            dialogCallbackFailure = null;
            _ = todoWindow.Dispatcher.BeginInvoke(
                DispatcherPriority.ApplicationIdle,
                new Action(() =>
                {
                    try
                    {
                        var dialog = Application.Current.Windows
                            .OfType<CuteConfirmationWindow>()
                            .Single(window => window.IsVisible);
                        if (dialog.Theme !=
                            CuteConfirmationTheme.TodoBlue)
                        {
                            throw new InvalidOperationException(
                                "真实待办删除确认窗没有使用独立蓝色主题");
                        }

                        if (!todoWindow.IsTransientPopupOpen)
                        {
                            throw new InvalidOperationException(
                                "真实删除确认窗显示时 TodoWindow 未进入临时交互状态");
                        }

                        interact(dialog);
                    }
                    catch (Exception exception)
                    {
                        dialogCallbackFailure = exception;
                        foreach (var dialog in Application.Current.Windows
                                     .OfType<CuteConfirmationWindow>()
                                     .Where(window => window.IsVisible)
                                     .ToArray())
                        {
                            dialog.Close();
                        }
                    }
                }));
            Invoke(
                todoWindow,
                "DeleteButton_Click",
                new Button { Tag = item },
                new RoutedEventArgs(ButtonBase.ClickEvent));
            if (dialogCallbackFailure is not null)
            {
                throw new InvalidOperationException(
                    "删除确认模态交互回调失败",
                    dialogCallbackFailure);
            }
        }

        try
        {
            var cancelledItem = new TodoItem { Text = "取消删除" };
            InvokeDeleteWithDialog(
                cancelledItem,
                dialog =>
                {
                    var cancelButton =
                        FindVisualDescendants<Button>(dialog)
                            .Single(button =>
                                Equals(button.Content, "再想想"));
                    cancelButton.RaiseEvent(
                        new RoutedEventArgs(
                            ButtonBase.ClickEvent,
                            cancelButton));
                });
            Assert(deletedItems.Count == 0 &&
                   todoWindow.IsVisible &&
                   GetRawField(
                       todoWindow,
                       "_suppressDeleteConfirmationForSession") is false,
                "取消真实删除确认必须保留项目和待办面板，且不能开启本次运行免确认");

            var confirmedItem = new TodoItem { Text = "确认删除" };
            InvokeDeleteWithDialog(
                confirmedItem,
                dialog =>
                {
                    var confirmButton = GetField<Button>(
                        dialog,
                        "ConfirmButton");
                    confirmButton.RaiseEvent(
                        new RoutedEventArgs(
                            ButtonBase.ClickEvent,
                            confirmButton));
                });
            Assert(deletedItems.SequenceEqual([confirmedItem]) &&
                   GetRawField(
                       todoWindow,
                       "_suppressDeleteConfirmationForSession") is false,
                "未勾选免确认时点击删除必须只删除当前项目，下次仍需提示");

            var suppressedItem = new TodoItem { Text = "确认并本次免提示" };
            InvokeDeleteWithDialog(
                suppressedItem,
                dialog =>
                {
                    GetField<CheckBox>(
                            dialog,
                            "SessionSuppressionCheckBox")
                        .IsChecked = true;
                    var confirmButton = GetField<Button>(
                        dialog,
                        "ConfirmButton");
                    confirmButton.RaiseEvent(
                        new RoutedEventArgs(
                            ButtonBase.ClickEvent,
                            confirmButton));
                });
            Assert(deletedItems.SequenceEqual(
                       [confirmedItem, suppressedItem]) &&
                   GetRawField(
                       todoWindow,
                       "_suppressDeleteConfirmationForSession") is true,
                "勾选“本次运行不再提示”并确认后必须仅在当前 TodoWindow 会话生效");

            var noDialogItem = new TodoItem { Text = "本次直接删除" };
            Invoke(
                todoWindow,
                "DeleteButton_Click",
                new Button { Tag = noDialogItem },
                new RoutedEventArgs(ButtonBase.ClickEvent));
            Assert(deletedItems.SequenceEqual(
                       [confirmedItem, suppressedItem, noDialogItem]) &&
                   !Application.Current.Windows
                       .OfType<CuteConfirmationWindow>()
                       .Any(window => window.IsVisible),
                "本次运行免提示开启后，后续删除不得再创建模态确认窗");
        }
        finally
        {
            todoWindow.CloseForApplication();
        }

        var restartedWindow = new TodoWindow();
        try
        {
            Assert(GetRawField(
                       restartedWindow,
                       "_suppressDeleteConfirmationForSession") is false,
                "新启动会话必须恢复删除确认，免提示状态不得写入设置");
        }
        finally
        {
            restartedWindow.CloseForApplication();
        }
    }

    private static void CompleteCurrentPetSizeTransitionForReminderTest(
        MainWindow window)
    {
        var timestamp = Stopwatch.GetTimestamp();
        Invoke(window, "ConsumePendingPetSizeTargetAt", timestamp);
        if (!GetField<bool>(window, "_isPetSizeTransitioning"))
        {
            return;
        }

        var transitionStartedAt = GetField<long>(
            window,
            "_petSizeTransitionStartedTimestamp");
        var transitionDuration = (TimeSpan)(typeof(MainWindow).GetField(
                "PetSizeTransitionDuration",
                StaticFlags)!.GetValue(null) ?? TimeSpan.Zero);
        var durationTicks = Math.Max(
            1L,
            (long)Math.Ceiling(
                transitionDuration.TotalSeconds * Stopwatch.Frequency));
        Invoke(
            window,
            "AdvancePetSizeTransition",
            checked(transitionStartedAt + durationTicks + 1));
    }

    private static void AssertTodoWindowLayoutApiAndIme()
    {
        var type = typeof(TodoWindow);
        foreach (var propertyName in new[]
                 {
                     "Todos",
                     "IsImeComposing",
                     "IsTodoDragInProgress"
                 })
        {
            Assert(type.GetProperty(propertyName, BindingFlags.Instance | BindingFlags.Public) is not null,
                $"TodoWindow 应公开 {propertyName} 属性");
        }

        foreach (var methodName in new[]
                 {
                     "FocusInput",
                     "SetEdgeRoamingEnabled",
                     "SetPetSizeScale"
                 })
        {
            Assert(type.GetMethod(methodName, BindingFlags.Instance | BindingFlags.Public) is not null,
                $"TodoWindow 应公开 {methodName} 方法");
        }

        foreach (var eventName in new[]
                 {
                     "AddRequested",
                     "TodoChanged",
                     "TodoEdited",
                     "TodoMoveRequested",
                     "TodoDragCompleted",
                     "DeleteRequested",
                     "EdgeRoamingEnabledChanged",
                     "PetSizeScaleChanged",
                     "CloseRequested",
                     "ExitRequested",
                     "ImeCompositionChanged"
                 })
        {
            Assert(type.GetEvent(eventName, BindingFlags.Instance | BindingFlags.Public) is not null,
                $"TodoWindow 应公开 {eventName} 事件");
        }

        var todoWindow = new TodoWindow
        {
            Left = -10000,
            Top = -10000,
            ShowActivated = false
        };
        try
        {
            AssertClose(todoWindow.Width, 292, "TodoWindow 总宽度");
            AssertClose(todoWindow.Height, 414, "TodoWindow 三条定时任务与底部设置共存后的总高度");
            Assert(string.Equals(
                    todoWindow.FontFamily.Source,
                    "Microsoft YaHei",
                    StringComparison.OrdinalIgnoreCase),
                $"TodoWindow 必须统一使用 Microsoft YaHei，实际 {todoWindow.FontFamily.Source}");
            Assert(todoWindow.WindowStyle == WindowStyle.None &&
                   todoWindow.AllowsTransparency &&
                   !todoWindow.ShowInTaskbar &&
                   todoWindow.Background is SolidColorBrush windowBackground &&
                   windowBackground.Color.A == 0,
                "TodoWindow 必须为透明背景、无边框且不占任务栏；" +
                $"style={todoWindow.WindowStyle}, allowsTransparency={todoWindow.AllowsTransparency}, " +
                $"taskbar={todoWindow.ShowInTaskbar}, background={todoWindow.Background}");
            var copyBindings = todoWindow.CommandBindings
                .OfType<CommandBinding>()
                .Where(binding => ReferenceEquals(binding.Command, ApplicationCommands.Copy))
                .ToArray();
            Assert(copyBindings.Length == 1,
                "TodoWindow 必须在窗口级显式绑定一次 ApplicationCommands.Copy");
            Assert(!todoWindow.CommandBindings.OfType<CommandBinding>().Any(binding =>
                    ReferenceEquals(binding.Command, ApplicationCommands.Paste) ||
                    ReferenceEquals(binding.Command, ApplicationCommands.Cut) ||
                    ReferenceEquals(binding.Command, ApplicationCommands.SelectAll)),
                "窗口级命令绑定不得替换 Ctrl+V、Ctrl+X 或 Ctrl+A；首字符剪切只由同步 PreviewKeyDown 路径修复");
            var todoXaml = File.ReadAllText(FindWorkspaceFile("TodoWindow.xaml"));
            Assert(todoXaml.Contains(
                       "x:Name=\"TodoRowBorder\"",
                       StringComparison.Ordinal),
                "待办行必须保留可单独验证的 TodoRowBorder");
            var todoXamlDocument = XDocument.Parse(todoXaml);
            var todoRowHoverBackgroundBrush = todoXamlDocument.Root!
                .Descendants()
                .Single(element =>
                    element.Name.LocalName == "SolidColorBrush" &&
                    element.Attributes().Any(attribute =>
                        attribute.Name.LocalName == "Key" &&
                        attribute.Value == "TodoRowHoverBackgroundBrush"));
            var todoRowHoverBorderBrush = todoXamlDocument.Root!
                .Descendants()
                .Single(element =>
                    element.Name.LocalName == "SolidColorBrush" &&
                    element.Attributes().Any(attribute =>
                        attribute.Name.LocalName == "Key" &&
                        attribute.Value == "TodoRowHoverBorderBrush"));
            Assert(
                (string?)todoRowHoverBackgroundBrush.Attribute("Color") == "#DCEBFF" &&
                (string?)todoRowHoverBorderBrush.Attribute("Color") == "#5B8DEF",
                "待办行悬停必须使用浅蓝背景和较深蓝色圆角描边");
            var todoRowBorder = todoXamlDocument.Root!
                .Descendants()
                .Single(element =>
                    element.Name.LocalName == "Border" &&
                    element.Attributes().Any(attribute =>
                        attribute.Name.LocalName == "Name" &&
                        attribute.Value == "TodoRowBorder"));
            var todoRowStyle = todoRowBorder
                .Elements()
                .Single(element => element.Name.LocalName == "Border.Style")
                .Elements()
                .Single(element => element.Name.LocalName == "Style");
            var todoRowBaseSetters = todoRowStyle
                .Elements()
                .Where(element => element.Name.LocalName == "Setter")
                .ToArray();
            var todoRowCompletedTrigger = todoRowStyle
                .Elements()
                .Single(element => element.Name.LocalName == "Style.Triggers")
                .Elements()
                .Single(element =>
                    element.Name.LocalName == "DataTrigger" &&
                    (string?)element.Attribute("Value") == "True");
            var todoRowCompletedSetters = todoRowCompletedTrigger
                .Elements()
                .Where(element => element.Name.LocalName == "Setter")
                .ToArray();
            Assert(
                todoRowBaseSetters.Any(setter =>
                    (string?)setter.Attribute("Property") == "Background" &&
                    (string?)setter.Attribute("Value") == "#F3F8FF") &&
                todoRowBaseSetters.Any(setter =>
                    (string?)setter.Attribute("Property") == "BorderBrush" &&
                    (string?)setter.Attribute("Value") == "Transparent") &&
                todoRowBaseSetters.Any(setter =>
                    (string?)setter.Attribute("Property") == "BorderThickness" &&
                    (string?)setter.Attribute("Value") == "1") &&
                todoRowCompletedSetters.Any(setter =>
                    (string?)setter.Attribute("Property") == "Background" &&
                    (string?)setter.Attribute("Value") == "#F5F9FE") &&
                todoRowCompletedSetters.Any(setter =>
                    (string?)setter.Attribute("Property") == "BorderBrush" &&
                    (string?)setter.Attribute("Value") == "Transparent"),
                "待办行必须像定时任务一样在静止态保留透明的一像素边框占位，" +
                "只有悬停时才显示完整蓝色描边");
            var todoRowHoverTrigger = todoRowStyle
                .Elements()
                .Single(element => element.Name.LocalName == "Style.Triggers")
                .Elements()
                .Single(element =>
                    element.Name.LocalName == "Trigger" &&
                    (string?)element.Attribute("Property") == "IsMouseOver" &&
                    (string?)element.Attribute("Value") == "True");
            var todoRowHoverSetters = todoRowHoverTrigger
                .Elements()
                .Where(element => element.Name.LocalName == "Setter")
                .ToArray();
            Assert(
                todoRowHoverSetters.Any(setter =>
                    (string?)setter.Attribute("Property") == "Background" &&
                    (string?)setter.Attribute("Value") ==
                        "{StaticResource TodoRowHoverBackgroundBrush}") &&
                todoRowHoverSetters.Any(setter =>
                    (string?)setter.Attribute("Property") == "BorderBrush" &&
                    (string?)setter.Attribute("Value") ==
                        "{StaticResource TodoRowHoverBorderBrush}") &&
                !todoRowHoverSetters.Any(setter =>
                    (string?)setter.Attribute("Property") == "BorderThickness"),
                "待办行悬停必须模仿定时任务的浅底加完整圆角框结构，" +
                "但使用独立蓝色画刷且不改变布局厚度");
            var scheduledTaskRowBorder = todoXamlDocument.Root!
                .Descendants()
                .Single(element =>
                    element.Name.LocalName == "Border" &&
                    element.Attributes().Any(attribute =>
                        attribute.Name.LocalName == "Name" &&
                        attribute.Value == "ScheduledTaskRowBorder"));
            foreach (var attributeName in new[] { "Margin", "Padding", "CornerRadius" })
            {
                Assert(
                    (string?)todoRowBorder.Attribute(attributeName) ==
                    (string?)scheduledTaskRowBorder.Attribute(attributeName),
                    $"待办行和定时任务行的 {attributeName} 必须保持同款结构");
            }
            var todoListBoxElement = todoXamlDocument.Root!
                .Descendants()
                .Single(element =>
                    element.Name.LocalName == "ListBox" &&
                    element.Attributes().Any(attribute =>
                        attribute.Name.LocalName == "Name" &&
                        attribute.Value == "TodoItemsControl"));
            var todoItemContainerStyle = todoListBoxElement
                .Elements()
                .Single(element =>
                    element.Name.LocalName == "ListBox.ItemContainerStyle")
                .Elements()
                .Single(element => element.Name.LocalName == "Style");
            var todoContainerBorderThickness = todoItemContainerStyle
                .Elements()
                .Single(element =>
                    element.Name.LocalName == "Setter" &&
                    (string?)element.Attribute("Property") ==
                    "BorderThickness");
            var todoContainerTemplate = todoItemContainerStyle
                .Descendants()
                .Single(element =>
                    element.Name.LocalName == "ControlTemplate");
            Assert(
                (string?)todoContainerBorderThickness.Attribute("Value") == "0" &&
                todoContainerTemplate.Descendants().Any(element =>
                    element.Name.LocalName == "Border" &&
                    element.Attributes().Any(attribute =>
                        attribute.Name.LocalName == "Name" &&
                        attribute.Value == "TodoItemContainerChrome") &&
                    (string?)element.Attribute("BorderBrush") ==
                        "{TemplateBinding BorderBrush}" &&
                    (string?)element.Attribute("BorderThickness") ==
                        "{TemplateBinding BorderThickness}") &&
                !todoContainerTemplate.Descendants().Any(element =>
                    element.Name.LocalName == "Trigger" &&
