                string.Join(", ", explicitFontFamilies.Distinct(StringComparer.OrdinalIgnoreCase)));

            var todoSource = File.ReadAllText(FindWorkspaceFile("TodoWindow.xaml.cs"));
            var previewCopySource = ExtractPrivateMethodSource(
