                    !dragMoveSource.Contains("Opacity", StringComparison.Ordinal) &&
                    autoScrollSource.Contains("_todoScrollViewer ??=", StringComparison.Ordinal) &&
                    autoScrollSource.Contains("Stopwatch.GetElapsedTime", StringComparison.Ordinal) &&
                    dropSource.Contains("TodoMoveRequested?.Invoke", StringComparison.Ordinal),
                "拖拽必须超过 Windows 系统阈值后才启动、不得把状态留在回收容器上，" +
                "自动滚动必须缓存并节流，而且一次 Drop 只发出一次最终索引移动请求");
            var mainWindowSource = File.ReadAllText(FindWorkspaceFile("MainWindow.xaml.cs"));
            var outsideCloseSource = ExtractPrivateMethodSource(
                mainWindowSource,
                "ProcessOutsideTodoClose");
            var advancePetSizeCompositionSource = ExtractPrivateMethodSource(
                mainWindowSource,
                "AdvancePetSizeCompositionFrame");
            Assert(outsideCloseSource.Contains(
                       "_todoWindow.IsTodoDragInProgress",
                       StringComparison.Ordinal) &&
                   mainWindowSource.Contains(
                       "_todoWindow.TodoDragCompleted += TodoWindow_TodoDragCompleted",
                       StringComparison.Ordinal),
                "DoDragDrop 嵌套消息循环期间外部失焦不得收起待办窗口，拖拽结束后才重新检查外部点击");
            Assert(advancePetSizeCompositionSource.Contains(
                       "UpdateTodoWindowTailPlacement(todoIsBeforePet)",
                       StringComparison.Ordinal) &&
                   advancePetSizeCompositionSource.IndexOf(
                       "UpdateTodoWindowTailPlacement(todoIsBeforePet)",
                       StringComparison.Ordinal) <
                   advancePetSizeCompositionSource.IndexOf(
                       "QueueTodoWindowPositionUpdate()",
                       StringComparison.Ordinal),
                "尺寸滑块的合成帧必须只更新气泡箭头跟随位置，并继续把 Todo HWND 移动延迟到松手后");
            Assert(queueSizeSource.Contains(
                       "_petSizeScaleNotificationQueued = true",
                       StringComparison.Ordinal) &&
                   !queueSizeSource.Contains(
                       "CompositionTarget.Rendering",
                       StringComparison.Ordinal) &&
                   flushSizeSource.Contains(
                        "PetSizeScaleChanged?.Invoke(scale)",
                        StringComparison.Ordinal) &&
                   !todoSource.Contains(
                       "CompositionTarget.Rendering",
                       StringComparison.Ordinal) &&
                   !todoSource.Contains(
                       "PetSizeScale_Rendering",
                       StringComparison.Ordinal) &&
                   typeof(TodoWindow).GetField(
                       "_petSizeRenderingSubscribed",
                       InstanceFlags) is null &&
                     !queueSizeSource.Contains(
                        "DispatcherPriority.Background",
                        StringComparison.Ordinal) &&
                   !flushSizeSource.Contains(
                        "DispatcherPriority.Background",
                        StringComparison.Ordinal) &&
                   endSizeSource.IndexOf(
                       "FlushPendingPetSizeScaleChanged()",
                       StringComparison.Ordinal) <
                   endSizeSource.IndexOf(
                       "PetSizeAdjustmentCompleted?.Invoke()",
                       StringComparison.Ordinal),
                "滑块手势必须只缓存最新尺寸并由MainWindow唯一Rendering合帧，" +
                "TodoWindow不得逐帧修改全局Rendering订阅表，松手必须先冲刷最终值");

            todoWindow.Todos = new ObservableCollection<TodoItem>(
                Enumerable.Range(1, 12)
                    .Select(index => new TodoItem
                    {
                        Text = $"待办 {index}",
                        IsCompleted = index == 4
                    }));
            todoWindow.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(40));

            var scrollViewer = FindVisualDescendant<ScrollViewer>(todoWindow)
                ?? throw new InvalidOperationException("TodoWindow 找不到待办滚动区域");
            var itemsControl = GetField<ItemsControl>(todoWindow, "TodoItemsControl");
            var isMouseOverPropertyKey =
                typeof(UIElement).GetField(
                    "IsMouseOverPropertyKey",
                    BindingFlags.Static | BindingFlags.NonPublic)?.GetValue(null)
                as DependencyPropertyKey
                ?? throw new InvalidOperationException(
                    "找不到 WPF IsMouseOverPropertyKey，无法执行真实悬停像素回归");
            foreach (var (todoIndex, stateLabel) in new[]
                     {
                         (2, "普通"),
                         (3, "已完成")
                     })
            {
                var todoContainer =
                    itemsControl.ItemContainerGenerator.ContainerFromIndex(todoIndex)
                        as ListBoxItem
                    ?? throw new InvalidOperationException(
                        $"待办悬停像素回归找不到第 {todoIndex + 1} 条{stateLabel}待办容器");
                var todoRow = FindVisualDescendants<Border>(todoContainer)
                    .Single(border => border.Name == "TodoRowBorder");
                var expectedRestBackground = todoIndex == 3
                    ? Color.FromRgb(0xF5, 0xF9, 0xFE)
                    : Color.FromRgb(0xF3, 0xF8, 0xFF);
                Assert(
                    todoRow.Background is SolidColorBrush restBackgroundBrush &&
                    restBackgroundBrush.Color == expectedRestBackground &&
                    todoRow.BorderBrush is SolidColorBrush restBorderBrush &&
                    restBorderBrush.Color.A == 0 &&
                    todoRow.BorderThickness == new Thickness(1),
                    $"{stateLabel}待办静止态必须使用平底蓝白背景和透明一像素边框占位");
                try
                {
                    todoRow.SetValue(isMouseOverPropertyKey, true);
                    todoRow.UpdateLayout();
                    Assert(
                        todoRow.Background is SolidColorBrush runtimeTodoRowHoverBackgroundBrush &&
                        todoRow.BorderBrush is SolidColorBrush runtimeTodoRowHoverBorderBrush &&
                        runtimeTodoRowHoverBackgroundBrush.Color ==
                            Color.FromRgb(0xDC, 0xEB, 0xFF) &&
                        runtimeTodoRowHoverBorderBrush.Color ==
                            Color.FromRgb(0x5B, 0x8D, 0xEF) &&
                        !ReferenceEquals(
                            runtimeTodoRowHoverBackgroundBrush,
                            runtimeTodoRowHoverBorderBrush) &&
                        todoRow.CornerRadius == new CornerRadius(9) &&
                        todoRow.BorderThickness == new Thickness(1),
                        $"{stateLabel}待办真实悬停必须使用浅蓝底和完整蓝色圆角描边");
                    AssertRoundedOutlineAndFillMatch(
                        RenderElementSnapshot(todoRow),
                        Color.FromRgb(0x5B, 0x8D, 0xEF),
                        Color.FromRgb(0xDC, 0xEB, 0xFF),
                        $"{stateLabel}待办悬停必须渲染四边完整圆角框，不能只剩上下横线");

                    var adjacentContainer =
                        itemsControl.ItemContainerGenerator.ContainerFromIndex(todoIndex + 1)
                            as ListBoxItem
                        ?? throw new InvalidOperationException(
                            $"待办悬停像素回归找不到第 {todoIndex + 2} 条相邻待办容器");
                    var adjacentRow = FindVisualDescendants<Border>(adjacentContainer)
                        .Single(border => border.Name == "TodoRowBorder");
                    Assert(
                        adjacentRow.BorderBrush is SolidColorBrush adjacentBorderBrush &&
                        adjacentBorderBrush.Color.A == 0,
                        $"悬停第 {todoIndex + 1} 条待办时不得给相邻行画蓝色上下横线");
                }
                finally
                {
                    todoRow.ClearValue(isMouseOverPropertyKey);
                    todoRow.UpdateLayout();
                }
                Assert(
                    todoRow.Background is SolidColorBrush restoredBackgroundBrush &&
                    restoredBackgroundBrush.Color == expectedRestBackground &&
                    todoRow.BorderBrush is SolidColorBrush restoredBorderBrush &&
                    restoredBorderBrush.Color.A == 0,
                    $"{stateLabel}待办离开悬停后必须恢复平底背景和透明边框，不能残留上下横线");
            }
            var taskHouseButtons =
                FindVisualDescendants<Button>(todoWindow).ToArray();
            var collapseButton = taskHouseButtons.Single(button =>
                System.Windows.Automation.AutomationProperties.GetName(
                    button) == "收起任务小屋");
            var exitButton = taskHouseButtons.Single(button =>
                System.Windows.Automation.AutomationProperties.GetName(
                    button) == "退出小鲁班桌宠");
            var addButton = taskHouseButtons.Single(button =>
                System.Windows.Automation.AutomationProperties.GetName(
                    button) == "新增待办事项");
            Assert(collapseButton.Style is not null &&
                   ReferenceEquals(collapseButton.Template, exitButton.Template) &&
                   ReferenceEquals(collapseButton.Template, addButton.Template) &&
                   collapseButton.Template.FindName(
                       "ButtonChrome",
                       collapseButton) is Border collapseChrome &&
                   collapseButton.Template.FindName(
                       "HoverTint",
                       collapseButton) is Border &&
                   collapseButton.Template.FindName(
                       "KeyboardFocusRing",
                       collapseButton) is Border &&
                   collapseChrome.CornerRadius.TopLeft == 10 &&
                   System.Windows.Automation.AutomationProperties.GetName(
                       collapseButton) == "收起任务小屋" &&
                   System.Windows.Automation.AutomationProperties.GetName(
                       exitButton) == "退出小鲁班桌宠" &&
                   System.Windows.Automation.AutomationProperties.GetName(
                       addButton) == "新增待办事项",
                "收起、退出、新增必须共用圆润高光按钮模板，并保留各自动化名称和不同语义配色");
            var roamingToggle = GetField<CheckBox>(todoWindow, "EdgeRoamingToggle");
            var startupToggle = GetField<CheckBox>(todoWindow, "StartupToggle");
            var sizeSlider = GetField<Slider>(todoWindow, "PetSizeSlider");
            var sizeLabel = GetField<TextBlock>(todoWindow, "PetSizeLabel");
            Assert(roamingToggle.IsChecked == true &&
                   string.Equals(
                       roamingToggle.Content?.ToString(),
                       "绕屏动画",
                       StringComparison.Ordinal) &&
                   string.Equals(
                       System.Windows.Automation.AutomationProperties.GetName(
                           roamingToggle),
                       "绕屏动画",
                       StringComparison.Ordinal) &&
                   string.Equals(
                       roamingToggle.FontFamily.Source,
                       "Microsoft YaHei",
                       StringComparison.OrdinalIgnoreCase) &&
                   roamingToggle.Template.FindName(
                       "SwitchTrack",
                       roamingToggle) is Border roamingSwitchTrack &&
                   startupToggle.Template.FindName(
                       "SwitchTrack",
                       startupToggle) is Border startupSwitchTrack &&
                   roamingSwitchTrack.CornerRadius.TopLeft == 11 &&
                   startupSwitchTrack.CornerRadius.TopLeft == 11,
                "绕屏与开机自启必须使用微软雅黑、无障碍名称和带笑脸圆钮的萌系开关");
            var roamingToggleCenter = roamingToggle.TranslatePoint(
                new Point(0, roamingToggle.ActualHeight / 2),
                todoWindow);
            var sizeSliderCenter = sizeSlider.TranslatePoint(
                new Point(0, sizeSlider.ActualHeight / 2),
                todoWindow);
            Assert(roamingToggleCenter.Y < sizeSliderCenter.Y &&
                   todoXaml.Contains(
                       "x:Name=\"EdgeRoamingToggle\"",
                       StringComparison.Ordinal) &&
                   todoXaml.Contains(
                       "<Grid Grid.Row=\"3\"",
                       StringComparison.Ordinal),
                "绕屏勾选必须直接位于桌宠大小滑块上方，不能挤进标题或列表区域");
            var roamingEventCount = 0;
            var roamingEventValue = false;
            todoWindow.EdgeRoamingEnabledChanged += enabled =>
            {
                roamingEventCount++;
                roamingEventValue = enabled;
            };
            todoWindow.SetEdgeRoamingEnabled(false);
            Assert(roamingToggle.IsChecked == false && roamingEventCount == 0,
                "程序加载已保存的绕屏设置时必须静默更新勾选，不能反向触发保存事件");
            roamingToggle.IsChecked = true;
            Assert(roamingEventCount == 1 && roamingEventValue,
                "用户重新勾选绕屏必须且只能发布一次true事件");
            roamingToggle.IsChecked = false;
            Assert(roamingEventCount == 2 && !roamingEventValue,
                "用户取消绕屏必须且只能发布一次false事件");
            todoWindow.SetEdgeRoamingEnabled(true);
            Assert(roamingToggle.IsChecked == true && roamingEventCount == 2,
                "程序同步最终绕屏状态不得重复发布用户事件");
            AssertClose(sizeSlider.Minimum, 75, "桌宠尺寸滑块下限");
            AssertClose(sizeSlider.Maximum, 140, "桌宠尺寸滑块上限");
            AssertClose(sizeSlider.TickFrequency, 1, "桌宠尺寸滑块刻度");
            Assert(!sizeSlider.IsSnapToTickEnabled,
                "桌宠尺寸滑块不得强制吸附5%档位");
            Assert(sizeSlider.IsMoveToPointEnabled,
                "桌宠尺寸滑块应允许直接移动到鼠标位置");
            Assert(!sizeSlider.UseLayoutRounding && !sizeSlider.SnapsToDevicePixels,
                "桌宠尺寸滑块必须关闭布局取整和物理像素吸附，避免拖动时逐像素卡顿");
            AssertClose(sizeSlider.SmallChange, 1, "桌宠尺寸键盘小步长");
            AssertClose(sizeSlider.LargeChange, 5, "桌宠尺寸键盘大步长");
            sizeSlider.ApplyTemplate();
            var cuteSizeTrack = sizeSlider.Template.FindName(
                "PART_Track",
                sizeSlider) as Track;
            cuteSizeTrack?.Thumb.ApplyTemplate();
            Assert(cuteSizeTrack?.Thumb is Thumb cuteSizeThumb &&
                   cuteSizeThumb.Template.FindName(
                       "ThumbFace",
                       cuteSizeThumb) is System.Windows.Shapes.Ellipse &&
                   Math.Abs(cuteSizeThumb.Width - 24) <= 0.1,
                "桌宠大小必须使用橘色轨道和带表情高光的萌系圆形滑块");
            todoWindow.SetPetSizeScale(2);
            AssertClose(sizeSlider.Value, 140, "尺寸API超过上限时应钳制");
            todoWindow.SetPetSizeScale(0.1);
            AssertClose(sizeSlider.Value, 75, "尺寸API低于下限时应钳制");
            todoWindow.SetPetSizeScale(1);
            AssertClose(sizeSlider.Value, 100, "尺寸API默认值");
            Assert(sizeLabel.Text == "100%", "尺寸标签必须同步显示百分比");
            var sizeEventValue = 0d;
            var sizeEventCount = 0;
            var adjustmentStartedCount = 0;
            var adjustmentCompletedCount = 0;
            todoWindow.PetSizeScaleChanged += value =>
            {
                sizeEventValue = value;
                sizeEventCount++;
            };
            todoWindow.PetSizeAdjustmentStarted += () => adjustmentStartedCount++;
            todoWindow.PetSizeAdjustmentCompleted += () => adjustmentCompletedCount++;
            Invoke(todoWindow, "BeginPetSizeAdjustment");
            for (var inputIndex = 0; inputIndex < 240; inputIndex++)
            {
                sizeSlider.Value = inputIndex == 239
                    ? 123.4
                    : 75.1 + inputIndex * (48.2 / 238d);
            }

            Assert(sizeEventCount == 1,
                "连续240次手势输入只能同步发布首个真实值，以便在Rendering前准备透明包络");
            Invoke(todoWindow, "FlushPendingPetSizeScaleChanged");
            Assert(sizeEventCount == 2,
                "除首个同步值外，MainWindow一次合成帧必须把其余239次输入折叠为一个最终尺寸事件");
            AssertClose(sizeEventValue, 1.234,
                "合成帧必须发布240次输入中的最终123.4%值");

            sizeSlider.Value = 124.5;
            Invoke(todoWindow, "FlushPendingPetSizeScaleChanged");
            Assert(sizeEventCount == 3,
                "下一次合成帧必须发布新输入且不能重播上一帧");
            AssertClose(sizeEventValue, 1.245,
                "下一次合成帧必须发布新的124.5%最终值");

            sizeSlider.Value = 126.5;
            Invoke(todoWindow, "EndPetSizeAdjustment");
            Assert(sizeEventCount == 4,
                "松开滑块必须在完成事件前显式冲刷尚未被合成帧消费的最终值");
            AssertClose(sizeEventValue, 1.265,
                "松手最终冲刷必须保留最新126.5%值");
            Assert(adjustmentStartedCount == 1 && adjustmentCompletedCount == 1,
                "尺寸滑块必须明确发出按下与松开手势边界");

            sizeSlider.Value = 127.5;
            Assert(sizeEventCount == 5,
                "非手势的程序化ValueChanged仍必须立即且仅发布一次");
            AssertClose(sizeEventValue, 1.275,
                "非手势程序化ValueChanged必须发布其最终值");
            Assert(scrollViewer.VerticalScrollBarVisibility == ScrollBarVisibility.Auto,
                "待办列表必须保留自动垂直滚动条");
            Assert(ScrollViewer.GetCanContentScroll(itemsControl) &&
                   !ScrollViewer.GetIsDeferredScrollingEnabled(itemsControl) &&
                   ScrollViewer.GetPanningMode(itemsControl) ==
                       PanningMode.VerticalOnly &&
                   VirtualizingPanel.GetIsVirtualizing(itemsControl) &&
                   VirtualizingPanel.GetVirtualizationMode(itemsControl) ==
                       VirtualizationMode.Recycling &&
                   VirtualizingPanel.GetScrollUnit(itemsControl) ==
                       ScrollUnit.Pixel,
                "待办列表必须使用 Pixel + Recycling 即时滚动，滚轮和滑块都不能按整行卡点跳动");
            Assert(scrollViewer.ActualHeight >= 155,
                $"待办可视区应完整容纳五行，实际 {scrollViewer.ActualHeight:F1} DIP");
            Assert(scrollViewer.ExtentHeight > scrollViewer.ViewportHeight,
                "超出可视区域的待办应进入滚动区域而不是撑大窗口");
            scrollViewer.ScrollToVerticalOffset(12.5);
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            Assert(Math.Abs(scrollViewer.VerticalOffset - 12.5) < 0.75,
                $"待办 Pixel 滚动必须保留小数级中间位置，实际 offset={scrollViewer.VerticalOffset:F2}");
            var todoVerticalScrollBar =
                FindVisualDescendants<ScrollBar>(itemsControl)
                    .First(scrollBar =>
                        scrollBar.Orientation == Orientation.Vertical);
            AssertTaskListScrollBarVisual(
                todoVerticalScrollBar,
                "待办列表",
