               advancePetSizeComposition.Contains(
                   "_todoWindow.FlushPendingPetSizeScaleChanged()",
                   StringComparison.Ordinal),
            "尺寸手势必须延迟到真实值变化后才建立预览会话；" +
            "固定最大HWND包络不变，MainWindow在整个手势期间保持唯一合成合帧器");
        var petSizeRenderLayoutWrites = new[]
        {
            "PreparePetSizePreviewEnvelope",
            "ApplyPetSizeWindowBounds",
            "PetSizeViewbox.Width",
            "PetSizeViewbox.Height",
            "PresentationSource.FromVisual",
            "Width =",
            "Height =",
            "Left =",
            "Top ="
        };
        Assert(petSizeRenderLayoutWrites.All(token =>
                   !advancePetSizeComposition.Contains(token, StringComparison.Ordinal) &&
                   !advancePetSizeTransition.Contains(token, StringComparison.Ordinal)) &&
               advancePetSizeComposition.Contains(
                   "!_isPetSizeTransitioning",
                   StringComparison.Ordinal) &&
               !prepareEnvelope.Contains(
                   "QueueTodoWindowPositionUpdate",
                   StringComparison.Ordinal),
            "尺寸Rendering热路径只能消费目标并写Scale/Translate，过渡结束后才能安排一次Todo跟随，不得再改窗口或Viewbox布局");
        var queueTodoPosition = ExtractPrivateMethodSource(
            mainSource,
            "QueueTodoWindowPositionUpdate");
        Assert(!queueTodoPosition.Contains("new Action", StringComparison.Ordinal) &&
               !queueTodoPosition.Contains("=>", StringComparison.Ordinal) &&
               mainSource.Contains(
                   "_processTodoWindowPositionUpdateAction = ProcessTodoWindowPositionUpdate",
                   StringComparison.Ordinal),
            "Todo跟随排队必须复用构造时缓存的委托，不能在Rendering边界帧创建捕获闭包");
    }

    private static string ExtractPrivateMethodSource(string source, string methodName)
    {
        var marker = $"{methodName}(";
        var searchFrom = 0;
        var start = -1;
        while (searchFrom < source.Length)
        {
            var candidate = source.IndexOf(marker, searchFrom, StringComparison.Ordinal);
            if (candidate < 0)
            {
                break;
            }

            var precedingIndex = candidate - 1;
            if (precedingIndex >= 0 &&
                (char.IsLetterOrDigit(source[precedingIndex]) ||
                 source[precedingIndex] == '_'))
            {
                searchFrom = candidate + marker.Length;
                continue;
            }

            var lineStart = source.LastIndexOf('\n', candidate);
            lineStart = lineStart < 0 ? 0 : lineStart + 1;
            var lineEnd = source.IndexOf('\n', candidate);
            lineEnd = lineEnd < 0 ? source.Length : lineEnd;
            var declarationLine = source[lineStart..lineEnd];
            if (declarationLine.Contains("private ", StringComparison.Ordinal) ||
                declarationLine.Contains("internal ", StringComparison.Ordinal))
            {
                start = lineStart;
                break;
            }

            searchFrom = candidate + marker.Length;
        }

        if (start < 0)
        {
            throw new InvalidOperationException($"找不到源码方法：{methodName}");
        }

        var end = source.IndexOf("\n    private ", start + 1, StringComparison.Ordinal);
        return end < 0 ? source[start..] : source[start..end];
    }

    private static T? FindVisualDescendant<T>(DependencyObject root)
        where T : DependencyObject
    {
        for (var index = 0; index < VisualTreeHelper.GetChildrenCount(root); index++)
        {
            var child = VisualTreeHelper.GetChild(root, index);
            if (child is T match)
            {
                return match;
            }

            var descendant = FindVisualDescendant<T>(child);
            if (descendant is not null)
            {
                return descendant;
            }
        }

        return null;
    }

    private static IEnumerable<T> FindVisualDescendants<T>(DependencyObject root)
        where T : DependencyObject
    {
        for (var index = 0; index < VisualTreeHelper.GetChildrenCount(root); index++)
        {
            var child = VisualTreeHelper.GetChild(root, index);
            if (child is T match)
            {
                yield return match;
            }

            foreach (var descendant in FindVisualDescendants<T>(child))
            {
                yield return descendant;
            }
        }
    }

    private static void PumpDispatcher(TimeSpan duration)
    {
        var frame = new DispatcherFrame();
        // Background priority can be starved by a continuously subscribed
        // CompositionTarget.Rendering callback, turning a 30 ms pump into
        // several seconds and letting the clip finish before an intermediate
        // state assertion. Normal priority keeps the requested wall-clock bound.
        var timer = new DispatcherTimer(DispatcherPriority.Normal)
        {
            Interval = duration
        };
        timer.Tick += (_, _) =>
        {
            timer.Stop();
            frame.Continue = false;
        };
        timer.Start();
        Dispatcher.PushFrame(frame);
    }

    private static RenderingEventArgs CreateRenderingEventArgs(TimeSpan renderingTime)
    {
        var constructor = typeof(RenderingEventArgs).GetConstructor(
            BindingFlags.Instance | BindingFlags.NonPublic,
            binder: null,
            [typeof(TimeSpan)],
            modifiers: null)
            ?? throw new InvalidOperationException(
                "找不到 RenderingEventArgs(TimeSpan) 内部构造函数");
        return (RenderingEventArgs)constructor.Invoke([renderingTime]);
    }

    private static void AssertTodoArrowPositionMatrixContract(MainWindow window)
    {
        var monitorWorkAreaType = typeof(MainWindow).Assembly.GetType(
            "LubanDesktopPet.MonitorWorkArea",
            throwOnError: true)!;
        var todoWindow = GetField<TodoWindow>(window, "_todoWindow");
        var positionCache = GetRawField(window, "_todoWindowPositionCache")!;
        var petViewbox = GetField<Viewbox>(window, "PetSizeViewbox");
        var originalBubbleMode = GetRawField(window, "_bubbleMode")!;
        var noneBubbleMode = GetNestedEnum("BubbleMode", "None");
        var todoBubbleMode = GetNestedEnum("BubbleMode", "Todo");
        var cuteBubbleMode = GetNestedEnum("BubbleMode", "Cute");
        var originalWindowVisible = window.IsVisible;
        var originalWindowHitTestVisible = window.IsHitTestVisible;
        var originalTodoHitTestVisible = todoWindow.IsHitTestVisible;
        var originalSuppressDeactivate =
            GetField<bool>(window, "_suppressTodoWindowDeactivate");
        var originalPetSizeScale = GetField<double>(window, "_petSizeScale");
        var originalLeft = window.Left;
        var originalTop = window.Top;
        var observedTailSides = new HashSet<bool>();

        try
        {
            window.IsHitTestVisible = false;
            todoWindow.IsHitTestVisible = false;
            SetField(window, "_suppressTodoWindowDeactivate", true);
            Invoke(window, "ApplyPetSizeScale", 1d, false, false);
            if (!window.IsVisible)
            {
                window.Show();
            }

            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            var petHost = GetField<Grid>(window, "PetHost");
            var clickDown = new MouseButtonEventArgs(
                Mouse.PrimaryDevice,
                Environment.TickCount,
                MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonDownEvent,
                Source = petHost
            };
            var clickUp = new MouseButtonEventArgs(
                Mouse.PrimaryDevice,
                Environment.TickCount,
                MouseButton.Left)
            {
                RoutedEvent = UIElement.MouseLeftButtonUpEvent,
                Source = petHost
            };
            Invoke(
                window,
                "PetHost_MouseLeftButtonDown",
                petHost,
                clickDown);
            Invoke(
                window,
                "PetHost_MouseLeftButtonUp",
                petHost,
                clickUp);
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            Assert(
                GetRawField(window, "_bubbleMode")?.ToString() == "Cute" &&
                GetField<Popup>(window, "BubblePopup").IsOpen &&
                GetRawField(window, "_activeClip") is not null,
                "真实左键单击小鲁班必须启动卖萌动作并显示可爱对话框");
            AssertCuteBubbleTailAtCurrentPosition(
                window,
                "real left-click reaction");
            var clickReactionClip =
                GetRawField(window, "_activeClip")
                ?? throw new InvalidOperationException(
                    "真实左键单击没有生成可结束的卖萌动作");
            Invoke(window, "CompleteActiveClip", clickReactionClip);
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            Assert(
                GetRawField(window, "_bubbleMode")?.ToString() == "None" &&
                !GetField<Popup>(window, "BubblePopup").IsOpen,
                "卖萌动作结束后可爱对话框必须正常收起，不能残留旧箭头方向");

            Invoke(window, "SetBubbleMode", todoBubbleMode);
            PumpDispatcher(TimeSpan.FromMilliseconds(40));
            Assert(todoWindow.IsVisible,
                "箭头位置矩阵必须使用真实可见的 Owned TodoWindow");

            var workArea = (Rect)InvokeStatic(
                monitorWorkAreaType,
                "GetForWindow",
                window)!;
            var windowWidth = window.ActualWidth > 0
                ? window.ActualWidth
                : window.Width;
            var windowHeight = window.ActualHeight > 0
                ? window.ActualHeight
                : window.Height;
            var horizontalInset = Math.Min(
                24,
                Math.Max(0, (workArea.Width - windowWidth) / 4));
            var verticalInset = Math.Min(
                24,
                Math.Max(0, (workArea.Height - windowHeight) / 4));
            var xPositions = new[]
            {
                (
                    Name: "left",
                    Value: workArea.Left + horizontalInset),
                (
                    Name: "center",
                    Value: workArea.Left + (workArea.Width - windowWidth) / 2),
                (
                    Name: "right",
                    Value: workArea.Right - windowWidth - horizontalInset)
            };
            var yPositions = new[]
            {
                (
                    Name: "top",
                    Value: workArea.Top + verticalInset),
                (
                    Name: "middle",
                    Value: workArea.Top + (workArea.Height - windowHeight) / 2),
                (
                    Name: "bottom",
                    Value: workArea.Bottom - windowHeight - verticalInset)
            };

            foreach (var xPosition in xPositions)
            {
                foreach (var yPosition in yPositions)
                {
                    PositionTodoArrowMatrixCase(
                        window,
                        todoWindow,
                        petViewbox,
                        positionCache,
                        xPosition.Value,
                        yPosition.Value);
                    var result = AssertTodoArrowAtCurrentPosition(
                        todoWindow,
                        petViewbox,
                        $"{xPosition.Name}/{yPosition.Name}");
                    observedTailSides.Add(result.TailOnRight);
                    Assert(!result.TopClamped && !result.BottomClamped,
                        $"{xPosition.Name}/{yPosition.Name}完全位于工作区时，" +
                        "箭头必须直接指向人物物理中心而不是提前夹紧");
                }
            }

            var centerX =
                workArea.Left + (workArea.Width - windowWidth) / 2;
            PositionTodoArrowMatrixCase(
                window,
                todoWindow,
                petViewbox,
                positionCache,
                centerX,
                workArea.Top - windowHeight);
            var topClamp = AssertTodoArrowAtCurrentPosition(
                todoWindow,
                petViewbox,
                "above-work-area clamp");
            observedTailSides.Add(topClamp.TailOnRight);
            Assert(topClamp.TopClamped && !topClamp.BottomClamped,
                "人物中心越过工作区上方时，真实箭头必须夹紧到气泡上安全边界");

            PositionTodoArrowMatrixCase(
                window,
                todoWindow,
                petViewbox,
                positionCache,
                centerX,
                workArea.Bottom + windowHeight * 0.1);
            var bottomClamp = AssertTodoArrowAtCurrentPosition(
                todoWindow,
                petViewbox,
                "below-work-area clamp");
            observedTailSides.Add(bottomClamp.TailOnRight);
            Assert(!bottomClamp.TopClamped && bottomClamp.BottomClamped,
                "人物中心越过工作区下方时，真实箭头必须夹紧到气泡下安全边界");

            Assert(observedTailSides.SetEquals([false, true]),
                "3x3真实位置矩阵必须实际覆盖待办位于人物左右两侧，" +
                "不能只直接调用SetTailPlacement假覆盖翻转");

            Invoke(window, "SetBubbleMode", noneBubbleMode);
            window.Left = workArea.Left + horizontalInset;
            window.Top =
                workArea.Top + (workArea.Height - windowHeight) / 2;
            window.UpdateLayout();
            SetField(window, "_cuteBubblePlacedOnLeft", null);
            Invoke(window, "SetBubbleMode", cuteBubbleMode);
            PumpDispatcher(TimeSpan.FromMilliseconds(30));
            var cutePopup = GetField<Popup>(window, "BubblePopup");
            Assert(cutePopup.IsOpen &&
                   cutePopup.Placement == PlacementMode.Right,
                "人物位于屏幕左侧时，可爱对话框应优先请求放到右边");
            Assert(!AssertCuteBubbleTailAtCurrentPosition(
                       window,
                       "left-side pet"),
                "人物位于屏幕左侧时，气泡实际应位于人物右边且箭头向左指向人物");

            window.Left =
                workArea.Right - windowWidth - horizontalInset;
            window.UpdateLayout();
            SetField(window, "_cuteBubblePlacedOnLeft", null);
            Invoke(window, "UpdateCuteBubblePlacementAndTail");
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
            Assert(cutePopup.Placement == PlacementMode.Left,
                "人物位于屏幕右侧时，可爱对话框应优先请求放到左边");
            Assert(AssertCuteBubbleTailAtCurrentPosition(
                       window,
                       "right-side pet"),
                "人物位于屏幕右侧时，气泡实际应位于人物左边且箭头向右指向人物");

            Assert(!(bool)InvokeStatic(
                       typeof(MainWindow),
                       "ResolveCuteBubbleIsOnLeft",
                       -1580d,
                       -1353d,
                       -1800d,
                       -1610d,
                       true)!,
                "负坐标副屏上气泡实际位于人物右侧时，箭头必须仍向左指向人物");
            Assert((bool)InvokeStatic(
                       typeof(MainWindow),
                       "ResolveCuteBubbleIsOnLeft",
                       1450d,
                       1677d,
                       1700d,
                       1890d,
                       false)!,
                "多屏物理坐标中气泡实际位于人物左侧时，箭头必须向右指向人物");
            Assert((bool)InvokeStatic(
                       typeof(MainWindow),
                       "ResolveCuteBubbleIsOnLeft",
                       double.NaN,
                       0d,
                       0d,
                       190d,
                       true)!,
                "Popup HWND 正在跨屏重建而坐标暂不可用时，必须保留请求侧作为安全回退");
        }
        finally
        {
            Invoke(window, "SetBubbleMode", noneBubbleMode);
            Invoke(
                window,
                "ApplyPetSizeScale",
                originalPetSizeScale,
                false,
                false);
            window.Left = originalLeft;
            window.Top = originalTop;
            window.IsHitTestVisible = originalWindowHitTestVisible;
            todoWindow.IsHitTestVisible = originalTodoHitTestVisible;
            SetField(
                window,
                "_suppressTodoWindowDeactivate",
                originalSuppressDeactivate);
            if (!Equals(originalBubbleMode, noneBubbleMode))
            {
                Invoke(window, "SetBubbleMode", originalBubbleMode);
            }

            if (!originalWindowVisible)
            {
                window.Hide();
            }

            PumpDispatcher(TimeSpan.FromMilliseconds(20));
        }
    }

    private static bool AssertCuteBubbleTailAtCurrentPosition(
        MainWindow window,
        string stage)
    {
        Invoke(window, "ReconcileCuteBubbleTailWithActualPlacement");
        PumpDispatcher(TimeSpan.FromMilliseconds(10));

        var popup = GetField<Popup>(window, "BubblePopup");
        var popupChild = popup.Child as FrameworkElement
            ?? throw new InvalidOperationException(
                $"{stage}: 可爱对话框缺少可测量的 Popup 子元素");
        var petViewbox = GetField<Viewbox>(window, "PetSizeViewbox");
        var bubbleHost = GetField<Grid>(window, "BubbleHost");
        var tailHost = GetField<Grid>(window, "BubbleTailHost");
        var tailPolygon =
            GetField<System.Windows.Shapes.Polygon>(
                window,
                "BubbleTailPolygon");
        var firstColumn =
            GetField<ColumnDefinition>(window, "BubbleBodyColumn");
        var secondColumn =
            GetField<ColumnDefinition>(window, "BubbleTailColumn");

        popupChild.UpdateLayout();
        var popupTopLeft = popupChild.PointToScreen(new Point(0, 0));
        var popupBottomRight = popupChild.PointToScreen(
            new Point(popupChild.ActualWidth, popupChild.ActualHeight));
        var petTopLeft = petViewbox.PointToScreen(new Point(0, 0));
        var petBottomRight = petViewbox.PointToScreen(
            new Point(petViewbox.ActualWidth, petViewbox.ActualHeight));
        var popupCenterX =
            (popupTopLeft.X + popupBottomRight.X) / 2;
        var petCenterX =
            (petTopLeft.X + petBottomRight.X) / 2;
        var popupIsOnLeft = popupCenterX < petCenterX;

        Assert(
            GetField<bool?>(window, "_cuteBubbleTailPlacedOnLeft") ==
            popupIsOnLeft,
            $"{stage}: 箭头侧必须按 Popup 最终物理位置复核，不能只看请求的 Placement");
        Assert(
            popupIsOnLeft
                ? firstColumn.Width.IsAuto &&
                  Math.Abs(secondColumn.Width.Value - 12) <= 0.01 &&
                  Grid.GetColumn(bubbleHost) == 0 &&
                  Grid.GetColumn(tailHost) == 1
                : Math.Abs(firstColumn.Width.Value - 12) <= 0.01 &&
                  secondColumn.Width.IsAuto &&
                  Grid.GetColumn(tailHost) == 0 &&
                  Grid.GetColumn(bubbleHost) == 1,
            $"{stage}: 气泡翻边时 215 DIP 正文列和 12 DIP 箭头列必须一起交换");
        Assert(tailPolygon.Points.Count == 3,
            $"{stage}: 可爱气泡箭头必须保持三角形几何");

        var tip = tailPolygon.PointToScreen(tailPolygon.Points[1]);
        var baseCenter = tailPolygon.PointToScreen(new Point(
            (tailPolygon.Points[0].X + tailPolygon.Points[2].X) / 2,
            (tailPolygon.Points[0].Y + tailPolygon.Points[2].Y) / 2));
        Assert(
            popupIsOnLeft ? tip.X > baseCenter.X : tip.X < baseCenter.X,
            $"{stage}: 箭头尖端必须朝向小鲁班所在的一侧");
        Assert(
            Math.Abs(tip.X - petCenterX) <
            Math.Abs(baseCenter.X - petCenterX),
            $"{stage}: 箭头尖端在物理屏幕坐标中必须比底边更接近小鲁班");

        return popupIsOnLeft;
    }

    private static void PositionTodoArrowMatrixCase(
        MainWindow window,
        TodoWindow todoWindow,
        Viewbox petViewbox,
        object positionCache,
        double left,
        double top)
    {
        window.Left = left;
        window.Top = top;
        window.UpdateLayout();
        PumpDispatcher(TimeSpan.FromMilliseconds(20));
        Invoke(positionCache, "InvalidateGeometry");
        Invoke(window, "UpdateTodoWindowPosition");
        todoWindow.UpdateLayout();
        PumpDispatcher(TimeSpan.FromMilliseconds(20));

        // A native SetWindowPos can synchronously update the child HWND before
        // WPF publishes its transform. Re-run the production placement once
        // after layout so this assertion observes the same settled coordinates
        // a user sees, rather than a transient test-harness transform.
        Invoke(positionCache, "InvalidateGeometry");
        Invoke(window, "UpdateTodoWindowPosition");
        window.UpdateLayout();
        todoWindow.UpdateLayout();
        PumpDispatcher(TimeSpan.FromMilliseconds(10));
        Assert(petViewbox.IsVisible && todoWindow.IsVisible,
            "箭头位置矩阵每个样本都必须保持人物和待办窗口真实可见");
    }

    private static (
        bool TailOnRight,
        bool TopClamped,
        bool BottomClamped) AssertTodoArrowAtCurrentPosition(
            TodoWindow todoWindow,
            Viewbox petViewbox,
            string stage)
    {
        var petBounds = GetVisualPhysicalBounds(petViewbox);
        var petCenterX = petBounds.Left + petBounds.Width / 2;
        var petCenterY = petBounds.Top + petBounds.Height / 2;
        var todoOrigin = todoWindow.PointToScreen(new Point(0, 0));
        var todoBottomRight = todoWindow.PointToScreen(
            new Point(todoWindow.ActualWidth, todoWindow.ActualHeight));
        var dpi = VisualTreeHelper.GetDpi(todoWindow);
        var dpiScaleY = Math.Max(0.01, dpi.DpiScaleY);
        var todoCenterX = (todoOrigin.X + todoBottomRight.X) / 2;
        var expectedTailOnRight = todoCenterX <= petCenterX;
        var actualTailOnRight = GetField<bool>(todoWindow, "_tailOnRight");
        Assert(actualTailOnRight == expectedTailOnRight,
            $"{stage}箭头左右方向必须按最终实际Todo HWND中心相对人物中心决定");

        var tailHost = GetField<Grid>(todoWindow, "TailHost");
        var tailVerticalTransform = GetField<TranslateTransform>(
            todoWindow,
            "TailVerticalTransform");
        var tailPolygon = GetField<System.Windows.Shapes.Polygon>(
            todoWindow,
            "TailPolygon");
        Assert(tailPolygon.Points.Count == 3,
            $"{stage}箭头必须保持三角形尖端几何");
        var localTip = tailPolygon.Points[1];
        var minimumPointX = tailPolygon.Points.Min(point => point.X);
        var maximumPointX = tailPolygon.Points.Max(point => point.X);
        AssertClose(
            localTip.X,
            actualTailOnRight ? maximumPointX : minimumPointX,
            $"{stage}箭头尖端水平朝向");
        var physicalTip = tailPolygon.PointToScreen(localTip);
        var expectedContactX = actualTailOnRight
            ? petBounds.Left
            : petBounds.Right;
        Assert(Math.Abs(physicalTip.X - expectedContactX) <= 2.01,
            $"{stage}箭头尖端必须接触人物当前物理边界：" +
            $"tip={physicalTip.X:F3}px, pet={expectedContactX:F3}px");

        var minimumTailTop = 18d;
        var maximumTailTop = Math.Max(
            minimumTailTop,
            todoWindow.ActualHeight - 36);
        var requestedTailCenterDip =
            (petCenterY - todoOrigin.Y) / dpiScaleY;
        var expectedTailTop = Math.Clamp(
            requestedTailCenterDip - 9,
            minimumTailTop,
            maximumTailTop);
        Assert(
            Math.Abs(tailVerticalTransform.Y - expectedTailTop) * dpiScaleY <= 1.01 &&
            Math.Abs(tailHost.Margin.Top) <= 0.001,
            $"{stage}箭头Y必须由真实人物物理中心换算并夹紧：" +
            $"expected={expectedTailTop:F3} DIP, actual={tailVerticalTransform.Y:F3} DIP");
        var expectedTipY =
            todoOrigin.Y + (expectedTailTop + 9) * dpiScaleY;
        Assert(Math.Abs(physicalTip.Y - expectedTipY) <= 1.01,
            $"{stage}箭头尖端物理Y必须与动态TailHost中心一致：" +
            $"expected={expectedTipY:F3}px, actual={physicalTip.Y:F3}px");

        var topClamped = Math.Abs(expectedTailTop - minimumTailTop) < 0.01;
        var bottomClamped =
            Math.Abs(expectedTailTop - maximumTailTop) < 0.01;
        if (!topClamped && !bottomClamped)
        {
            Assert(Math.Abs(physicalTip.Y - petCenterY) <= 1.01,
                $"{stage}未夹紧时箭头尖端必须直接指向人物物理中心：" +
                $"tip={physicalTip.Y:F3}px, pet={petCenterY:F3}px");
        }

        return (actualTailOnRight, topClamped, bottomClamped);
    }

    private static void AssertWorkModeVisualAndIsolationContract(MainWindow window)
    {
        var mainXamlPath = FindWorkspaceFile("MainWindow.xaml");
        var mainXaml = File.ReadAllText(mainXamlPath);
        var document = XDocument.Parse(mainXaml);
        var workButton = document
            .Descendants()
            .Single(element =>
                element.Name.LocalName == "Button" &&
                element.Attributes().Any(attribute =>
                    attribute.Name.LocalName == "Name" &&
                    attribute.Value == "WorkModeButton"));
        string? Attribute(string name) => workButton
            .Attributes()
            .FirstOrDefault(attribute => attribute.Name.LocalName == name)?
            .Value;

        Assert(Attribute("FontFamily") == "Microsoft YaHei" &&
               Attribute("Width") == "42" &&
               Attribute("Height") == "42" &&
               Attribute("Margin") == "6,6,6,0" &&
               Attribute("HorizontalAlignment") == "Left" &&
               Attribute("Content") is null &&
               Attribute("Tag") == "Idle" &&
               Attribute("Visibility") == "Collapsed" &&
               Attribute("Click") == "WorkModeButton_Click",
            "Work mode must use a 42x42 text-free icon hit target at the pet's " +
            "visual top-left with its dedicated click handler.");
        var iconRoot = workButton
            .Descendants()
            .Single(element =>
                element.Name.LocalName == "Grid" &&
                element.Attributes().Any(attribute =>
                    attribute.Name.LocalName == "Name" &&
                    attribute.Value == "WorkIconRoot"));
        var namedIcons = workButton
            .Descendants()
            .Where(element =>
                element.Name.LocalName == "Viewbox" &&
                element.Attributes().Any(attribute =>
                    attribute.Name.LocalName == "Name" &&
                    attribute.Value is "SunIcon" or "MoonIcon"))
            .ToArray();
        Assert(iconRoot.Attributes().Any(attribute =>
                   attribute.Name.LocalName == "Background" &&
                   attribute.Value == "Transparent") &&
               namedIcons.Length == 2 &&
               namedIcons.All(icon => icon.Attributes().Any(attribute =>
                   attribute.Name.LocalName == "Width" &&
                   attribute.Value == "32")) &&
               namedIcons.All(icon => icon.Attributes().Any(attribute =>
                   attribute.Name.LocalName == "Visibility" &&
                   attribute.Value == "Visible")) &&
               namedIcons.Single(icon => icon.Attributes().Any(attribute =>
                       attribute.Name.LocalName == "Name" &&
                       attribute.Value == "SunIcon"))
                   .Attributes().Any(attribute =>
                       attribute.Name.LocalName == "Opacity" &&
                       attribute.Value == "1") &&
               namedIcons.Single(icon => icon.Attributes().Any(attribute =>
                       attribute.Name.LocalName == "Name" &&
                       attribute.Value == "MoonIcon"))
                   .Attributes().Any(attribute =>
                       attribute.Name.LocalName == "Opacity" &&
                       attribute.Value == "0") &&
               workButton.Descendants().Count(element =>
                   element.Name.LocalName == "TextBlock") == 0 &&
               workButton.Descendants().Count(element =>
                   element.Name.LocalName == "Image") == 0 &&
               workButton.Descendants().Count(element =>
                   element.Name.LocalName == "Path") >= 5 &&
               !workButton.Descendants().Any(element =>
                   element.Name.LocalName == "DropShadowEffect"),
            "Work mode must use cute code-native sun/moon vectors without text, " +
            "bitmap scaling, or transparent-window shadow effects.");
        var namedVisualParts = workButton
            .Descendants()
            .SelectMany(element => element.Attributes())
            .Where(attribute => attribute.Name.LocalName == "Name")
            .Select(attribute => attribute.Value)
            .ToArray();
        Assert(namedVisualParts.Contains("WorkSunModeHalo") &&
               namedVisualParts.Contains("WorkMoonModeHalo") &&
               namedVisualParts.Contains("WorkIconTwinkle") &&
               namedVisualParts.Contains("WorkSunIconScale") &&
               namedVisualParts.Contains("WorkSunIconRotate") &&
               namedVisualParts.Contains("WorkSunIconTranslate") &&
               namedVisualParts.Contains("WorkMoonIconScale") &&
               namedVisualParts.Contains("WorkMoonIconRotate") &&
               namedVisualParts.Contains("WorkMoonIconTranslate") &&
               !workButton.Descendants().Any(element =>
                   element.Name.LocalName == "Setter" &&
                   element.Attributes().Any(attribute =>
                       attribute.Name.LocalName == "TargetName" &&
                       attribute.Value is "SunIcon" or "MoonIcon") &&
                   element.Attributes().Any(attribute =>
                       attribute.Name.LocalName == "Property" &&
                       attribute.Value == "Visibility")) &&
               !workButton.Descendants().Any(element =>
                   element.Name.LocalName == "Storyboard"),
            "Sun and moon must remain resident and Visible while cached transforms, " +
            "mode-coloured halos, and one preset twinkle provide the smooth switch.");

        var protectedFiles = new[]
        {
            "TodoWindow.xaml",
            "TodoWindow.xaml.cs",
            "TodoStore.cs",
            "TodoItem.cs",
            "ScheduledTaskEditWindow.xaml",
            "ScheduledTaskEditWindow.xaml.cs",
            "ScheduledTaskStore.cs",
            "ScheduledTaskItem.cs",
            "ScheduledQuietHours.cs",
            "ScheduledRepeatRule.cs",
            "TaskTextEditWindow.xaml",
            "TaskTextEditWindow.xaml.cs",
            "ReminderWindow.xaml",
            "ReminderWindow.xaml.cs"
        };
        var forbiddenFeatureTokens = new[]
        {
            "WorkModeButton",
            "WorkState",
            "TryEnterWorkMode",
            "HandleWorkPetClick",
            "luban-work-"
        };
        foreach (var protectedFile in protectedFiles)
        {
            var source = File.ReadAllText(FindWorkspaceFile(protectedFile));
            Assert(forbiddenFeatureTokens.All(token =>
                       !source.Contains(token, StringComparison.Ordinal)),
                $"Work mode leaked into protected Todo/Scheduled source: {protectedFile}");
        }

        var enterFrames = GetField<Array>(window, "_workEnterFrames");
        var loopFrames = GetField<Array>(window, "_workLoopFrames");
        var seriousLoopFrames = GetField<Array>(window, "_workSeriousLoopFrames");
        var seriousExitFrames = GetField<Array>(window, "_workSeriousExitFrames");
        Assert(enterFrames.Length == 48 &&
               loopFrames.Length == 96 &&
               seriousLoopFrames.Length == 96 &&
               seriousExitFrames.Length == 24,
            $"Work authored frame contract must be 48/96/96/24, actual " +
            $"{enterFrames.Length}/{loopFrames.Length}/{seriousLoopFrames.Length}/" +
            $"{seriousExitFrames.Length}.");
        AssertExactWorkFrameNames(enterFrames, "enter");
        AssertExactWorkFrameNames(loopFrames, "loop");
        AssertExactWorkFrameNames(seriousLoopFrames, "serious-loop");
        AssertExactWorkFrameNames(seriousExitFrames, "serious-exit");
        AssertWorkTypingFrameDiversity(loopFrames, "loop");
        AssertWorkTypingFrameDiversity(seriousLoopFrames, "serious-loop");
        AssertWorkTransitionPixelSeams(
            window,
            enterFrames,
            loopFrames,
            seriousLoopFrames,
            seriousExitFrames);

        var runtimeType = typeof(MainWindow);
        Assert(!runtimeType.GetFields(InstanceFlags | StaticFlags).Any(field =>
                   field.Name.Contains("WorkTap", StringComparison.OrdinalIgnoreCase) ||
                   field.Name.Contains("SingleClick", StringComparison.OrdinalIgnoreCase)) &&
               !runtimeType.GetMethods(InstanceFlags | StaticFlags).Any(method =>
                   method.Name.Contains("WorkTap", StringComparison.OrdinalIgnoreCase) ||
                   method.Name.Contains("SingleClick", StringComparison.OrdinalIgnoreCase)),
            "Runtime work mode must not retain tap clips or delayed single-click arbitration members.");
        Assert(new[] { enterFrames, loopFrames, seriousLoopFrames, seriousExitFrames }
                   .SelectMany(frames => frames.Cast<object>())
                   .All(frame => !GetSpriteFrameInfo(frame).Name.Contains(
                       "luban-work-tap-",
                       StringComparison.Ordinal)),
            "Runtime work sequences must not expose a work-tap logical frame.");

        var exitClipFrames = GetProperty<Array>(
            GetField<object>(window, "_workExitClip"),
            "Frames");
        Assert(exitClipFrames.Length == enterFrames.Length,
            "Work exit must reuse every authored enter pose in reverse.");
        for (var index = 0; index < enterFrames.Length; index++)
        {
            var exitImage = GetProperty<object>(
                exitClipFrames.GetValue(index)!,
                "Image");
            var expected = GetSpriteFrameInfo(
                enterFrames.GetValue(enterFrames.Length - 1 - index)!).Name;
            Assert(GetSpriteFrameInfo(exitImage).Name == expected,
                $"Work exit frame {index + 1} must reverse enter frame " +
                $"{enterFrames.Length - index}.");
        }

        Assert(!(bool)InvokeStatic(
                   typeof(MainWindow),
                   "IsWorkPillowHiddenFrame",
                   enterFrames.GetValue(23)!)! &&
               (bool)InvokeStatic(
                   typeof(MainWindow),
                   "IsWorkPillowHiddenFrame",
                   enterFrames.GetValue(24)!)! &&
               (bool)InvokeStatic(
                   typeof(MainWindow),
                   "IsWorkPillowHiddenFrame",
                   loopFrames.GetValue(0)!)! &&
               (bool)InvokeStatic(
                   typeof(MainWindow),
                   "IsWorkPillowHiddenFrame",
                   seriousLoopFrames.GetValue(0)!)! &&
               (bool)InvokeStatic(
                   typeof(MainWindow),
                   "IsWorkPillowHiddenFrame",
                   seriousExitFrames.GetValue(0)!)!,
            "Pillow must remain visible through enter frame 24, then hide atomically " +
            "for normal, serious, and serious-exit work frames.");
    }

    private static void AssertExactWorkFrameNames(Array frames, string sequence)
    {
        var names = new HashSet<string>(StringComparer.Ordinal);
        for (var index = 0; index < frames.Length; index++)
        {
            var name = GetSpriteFrameInfo(frames.GetValue(index)!).Name;
            var expected = $"Assets/luban-work-{sequence}-{index + 1:000}.png";
            Assert(string.Equals(name, expected, StringComparison.Ordinal),
                $"Work {sequence} frame {index + 1} name mismatch: {name}");
            Assert(names.Add(name),
                $"Work {sequence} frame {index + 1} is duplicated in the runtime sequence.");
            Assert(File.Exists(FindWorkspaceFile(name.Split('/'))),
                $"Missing authored work frame: {name}");
        }
    }

    private static void AssertWorkTypingFrameDiversity(
        Array frames,
        string sequence)
    {
        var digests = GetDecodedWorkFramePixelDigests(frames);
        var neutralSeams = new[] { 0, 10, 21, 33, 44, 56, 69, 81, 93 };
        var keyPressCenters = new[] { 4, 15, 27, 38, 50, 63, 75, 87 };
        var neutralDigest = digests[0];
        var maximumIdenticalRun = GetMaximumCyclicIdenticalRun(digests);
        Assert(frames.Length == 96 &&
               digests.Distinct(StringComparer.Ordinal).Count() >= 56 &&
               maximumIdenticalRun <= 5,
            $"Work {sequence} must retain a diverse 96-frame natural cycle " +
            $"without fake texture jitter or a static hold longer than five " +
            $"authored frames; unique={digests.Distinct(StringComparer.Ordinal).Count()}, " +
            $"maximum identical run={maximumIdenticalRun}.");
        Assert(neutralSeams.All(index =>
                   string.Equals(
                       digests[index],
                       neutralDigest,
                       StringComparison.Ordinal)),
            $"Work {sequence} neutral micro-seams must be pixel-identical at " +
            $"0/10/21/33/44/56/69/81/93.");
        foreach (var center in keyPressCenters)
        {
            var localDigests = Enumerable.Range(center - 2, 5)
                .Select(index => digests[(index + digests.Length) % digests.Length])
                .ToArray();
            Assert(!string.Equals(
                       digests[center],
                       neutralDigest,
                       StringComparison.Ordinal) &&
                   localDigests.Distinct(StringComparer.Ordinal).Count() >= 3,
                $"Work {sequence} keypress around authored frame {center + 1} " +
                "must contain real pose movement rather than a duplicated hold.");
        }
    }

    private static int GetMaximumCyclicIdenticalRun(
        IReadOnlyList<string> digests)
    {
        if (digests.Count == 0)
        {
            return 0;
        }

        var maximum = 1;
        var current = 1;
        for (var index = 1; index < digests.Count; index++)
        {
            if (string.Equals(
                    digests[index],
                    digests[index - 1],
                    StringComparison.Ordinal))
            {
                current++;
                maximum = Math.Max(maximum, current);
            }
            else
            {
                current = 1;
            }
        }

        var prefix = 1;
        while (prefix < digests.Count &&
               string.Equals(
                   digests[prefix],
                   digests[0],
                   StringComparison.Ordinal))
        {
            prefix++;
        }
        var suffix = 1;
        while (suffix < digests.Count &&
               string.Equals(
                   digests[digests.Count - 1 - suffix],
                   digests[^1],
                   StringComparison.Ordinal))
        {
            suffix++;
        }
        if (string.Equals(digests[0], digests[^1], StringComparison.Ordinal))
        {
            maximum = Math.Max(
                maximum,
                Math.Min(digests.Count, prefix + suffix));
        }

        return maximum;
    }

    private static void AssertWorkTransitionPixelSeams(
        MainWindow window,
        Array enterFrames,
        Array loopFrames,
        Array seriousLoopFrames,
        Array seriousExitFrames)
    {
        var enterDigests = GetDecodedWorkFramePixelDigests(enterFrames);
        var loopDigests = GetDecodedWorkFramePixelDigests(loopFrames);
        var seriousLoopDigests =
            GetDecodedWorkFramePixelDigests(seriousLoopFrames);
        var seriousExitDigests =
            GetDecodedWorkFramePixelDigests(seriousExitFrames);
        var neutralSeams = new[] { 0, 10, 21, 33, 44, 56, 69, 81, 93 };
        var normalNeutralDigest = loopDigests[0];
        var seriousNeutralDigest = seriousLoopDigests[0];

        Assert(neutralSeams.All(index =>
                   string.Equals(
                       loopDigests[index],
                       normalNeutralDigest,
                   StringComparison.Ordinal)) &&
               string.Equals(
                   enterDigests[^1],
                   normalNeutralDigest,
                   StringComparison.Ordinal),
            "Every ordinary neutral seam must be pixel-identical to the reverse " +
            "work-exit frame; numeric phase alignment alone " +
            "is insufficient.");
        Assert(neutralSeams.All(index =>
                   string.Equals(
                       seriousLoopDigests[index],
                       seriousNeutralDigest,
                       StringComparison.Ordinal)) &&
               string.Equals(
                   seriousExitDigests[0],
                   seriousNeutralDigest,
                   StringComparison.Ordinal),
            "Every serious neutral seam must be pixel-identical to the first " +
            "serious-exit frame.");
        Assert(string.Equals(
                   seriousExitDigests[^1],
                   normalNeutralDigest,
                   StringComparison.Ordinal),
            "Serious-exit must finish on the exact ordinary neutral " +
            "bitmap consumed by work-loop frame 001.");

        var runtimeNormalNeutralDigest =
            GetRuntimeDecodedWorkFramePixelDigest(window, loopFrames.GetValue(0)!);
        var runtimeSeriousNeutralDigest =
            GetRuntimeDecodedWorkFramePixelDigest(
                window,
                seriousLoopFrames.GetValue(0)!);
        Assert(neutralSeams.All(index => string.Equals(
                   GetRuntimeDecodedWorkFramePixelDigest(
                       window,
                       loopFrames.GetValue(index)!),
                   runtimeNormalNeutralDigest,
                   StringComparison.Ordinal)) &&
               string.Equals(
                   GetRuntimeDecodedWorkFramePixelDigest(
                       window,
                       enterFrames.GetValue(enterFrames.Length - 1)!),
                   runtimeNormalNeutralDigest,
                   StringComparison.Ordinal) &&
               string.Equals(
                   GetRuntimeDecodedWorkFramePixelDigest(
                       window,
                       seriousExitFrames.GetValue(seriousExitFrames.Length - 1)!),
                   runtimeNormalNeutralDigest,
                   StringComparison.Ordinal),
            "The decoded atlas output, not only source PNG files, must keep every " +
            "normal work transition seam byte-identical after viewport composition.");
        Assert(neutralSeams.All(index => string.Equals(
                   GetRuntimeDecodedWorkFramePixelDigest(
                       window,
                       seriousLoopFrames.GetValue(index)!),
                   runtimeSeriousNeutralDigest,
                   StringComparison.Ordinal)) &&
               string.Equals(
                   GetRuntimeDecodedWorkFramePixelDigest(
                       window,
                       seriousExitFrames.GetValue(0)!),
                   runtimeSeriousNeutralDigest,
                   StringComparison.Ordinal),
            "The decoded atlas output must keep serious-loop neutral seams and " +
            "serious-exit frame 001 byte-identical after viewport composition.");
        var seriousEnterClipFrames = GetClipFrames(
            GetField<object>(window, "_workSeriousEnterClip"));
        Assert(string.Equals(
                   GetRuntimeDecodedWorkFramePixelDigest(
                       window,
                       GetProperty<object>(
                           seriousEnterClipFrames.GetValue(0)!,
                           "Image")),
                   runtimeNormalNeutralDigest,
                   StringComparison.Ordinal) &&
               string.Equals(
                   GetRuntimeDecodedWorkFramePixelDigest(
                       window,
                       GetProperty<object>(
                           seriousEnterClipFrames.GetValue(
                               seriousEnterClipFrames.Length - 1)!,
                           "Image")),
                   runtimeSeriousNeutralDigest,
                   StringComparison.Ordinal),
            "The sampled serious-entry clip must decode from the exact normal " +
            "neutral bitmap to the exact serious neutral bitmap.");
    }

    private static string GetRuntimeDecodedWorkFramePixelDigest(
        MainWindow window,
        object frame)
    {
        PrimeSpritePageForFrame(window, frame);
        SetField(window, "_nextFrameBlendDuration", TimeSpan.Zero);
        Invoke(window, "ShowStableFrame", frame);
        var bitmap = GetField<WriteableBitmap>(window, "_displayFrameBuffer");
        var stride = checked(bitmap.PixelWidth * 4);
        var pixels = new byte[checked(stride * bitmap.PixelHeight)];
        bitmap.CopyPixels(pixels, stride, offset: 0);
        return Convert.ToHexString(
            System.Security.Cryptography.SHA256.HashData(pixels));
    }

    private static string[] GetDecodedWorkFramePixelDigests(Array frames)
    {
        var digests = new string[frames.Length];
        for (var index = 0; index < frames.Length; index++)
        {
            var name = GetSpriteFrameInfo(frames.GetValue(index)!).Name;
            var path = FindWorkspaceFile(name.Split('/'));
            using var stream = File.OpenRead(path);
            var decoder = BitmapDecoder.Create(
                stream,
                BitmapCreateOptions.PreservePixelFormat,
                BitmapCacheOption.OnLoad);
            Assert(decoder.Frames.Count == 1,
                $"Work frame {name} must decode to exactly one bitmap frame.");
            BitmapSource bitmap = decoder.Frames[0];
            if (bitmap.Format != PixelFormats.Pbgra32)
            {
                bitmap = new FormatConvertedBitmap(
                    bitmap,
                    PixelFormats.Pbgra32,
                    destinationPalette: null,
                    alphaThreshold: 0);
            }

            Assert(bitmap.PixelWidth == 450 && bitmap.PixelHeight == 550,
                $"Work frame {name} must remain 450x550 RGBA, actual " +
                $"{bitmap.PixelWidth}x{bitmap.PixelHeight}.");
            var stride = checked(bitmap.PixelWidth * 4);
            var pixels = new byte[checked(stride * bitmap.PixelHeight)];
            bitmap.CopyPixels(pixels, stride, offset: 0);
            digests[index] = Convert.ToHexString(
                System.Security.Cryptography.SHA256.HashData(pixels));
        }

        return digests;
    }

    private static void AssertWorkTypingPresentationSampling(
        MainWindow window,
        Array frames,
        string sequence,
        double playbackRate,
        double expectedCycleSeconds,
        IReadOnlyDictionary<int, int> expectedVisibleFrameSlotCounts)
    {
        const double poseFramesPerSecond = 60d;
        var cycleSeconds = frames.Length /
                           (poseFramesPerSecond * playbackRate);
        Assert(Math.Abs(cycleSeconds - expectedCycleSeconds) <= 0.000001,
            $"Work {sequence} cycle duration must be {expectedCycleSeconds:F1}s, " +
            $"actual {cycleSeconds:F6}s.");

        foreach (var refreshRate in new[] { 59, 60, 120, 144 })
        {
            var anchorTimestamp = Math.Max(1L, Stopwatch.GetTimestamp());
            SetField(window, "_workLoopAnchorFramePosition", 0d);
            SetField(window, "_workLoopAnchorTimestamp", anchorTimestamp);
            SetField(window, "_workLoopPlaybackRate", playbackRate);

            // StartWorkClip publishes frame 001 immediately. Rendering callbacks
            // then resolve their pose from the same Stopwatch absolute timeline.
            var visibleFrameIndices = new HashSet<int>
            {
                0
            };
            var callbackCount = (int)Math.Floor(
                cycleSeconds * refreshRate + 0.000000001);
            for (var callback = 1; callback <= callbackCount; callback++)
            {
                var callbackTimestamp = checked(
                    anchorTimestamp +
                    (long)Math.Ceiling(
                        callback / (double)refreshRate * Stopwatch.Frequency));
                var framePosition = (double)Invoke(
                    window,
                    "GetWorkLoopFramePositionAt",
                    callbackTimestamp)!;
                var frameIndex = (int)Math.Floor(framePosition) % frames.Length;
                if (frameIndex < 0)
                {
                    frameIndex += frames.Length;
                }

                visibleFrameIndices.Add(frameIndex);
            }

            var expectedVisibleCount = expectedVisibleFrameSlotCounts[refreshRate];
            Assert(visibleFrameIndices.Count == expectedVisibleCount,
                $"Work {sequence} at {refreshRate}Hz/{playbackRate:F0}x must expose " +
                $"{expectedVisibleCount} authored frame slots per cycle, actual " +
                $"{visibleFrameIndices.Count}.");
        }
    }

    private static void AssertWorkModeIconTransitionContract(MainWindow window)
    {
        var source = File.ReadAllText(FindWorkspaceFile("MainWindow.xaml.cs"));
        var xaml = File.ReadAllText(FindWorkspaceFile("MainWindow.xaml"));
        var refresh = ExtractPrivateMethodSource(source, "RefreshWorkModeButton");
        var updateTarget = ExtractPrivateMethodSource(
            source,
            "UpdateWorkModeIconVisualTarget");
        var initialize = ExtractPrivateMethodSource(
            source,
            "EnsureWorkModeIconVisuals");
        var advance = ExtractPrivateMethodSource(
            source,
            "AdvanceWorkModeIconTransition");
        var resolve = ExtractPrivateMethodSource(
            source,
            "ResolveWorkModeIconTransitionState");
        var apply = ExtractPrivateMethodSource(
            source,
            "ApplyWorkModeIconVisualState");
        var rendering = ExtractPrivateMethodSource(source, "VisualClock_Rendering");
        var subscription = ExtractPrivateMethodSource(
            source,
            "UpdateVisualClockSubscription");
        var stateType = typeof(MainWindow).GetNestedType(
            "WorkModeIconVisualState",
            BindingFlags.NonPublic)
            ?? throw new InvalidOperationException(
                "找不到 WorkModeIconVisualState");

        Assert(source.Contains(
                   "WorkModeIconTransitionDurationSeconds = 0.42",
                   StringComparison.Ordinal) &&
               stateType.IsValueType &&
               rendering.Contains(
                   "AdvanceWorkModeIconTransition(timestamp)",
                   StringComparison.Ordinal) &&
               advance.Contains(
                   "(timestamp - _workModeIconTransitionStartedTimestamp)",
                   StringComparison.Ordinal) &&
               advance.Contains("Stopwatch.Frequency", StringComparison.Ordinal) &&
               subscription.Contains(
                   "_workModeIconTransitionActive",
                   StringComparison.Ordinal),
            "太阳/月亮必须复用单一CompositionTarget.Rendering + Stopwatch的" +
            "420ms绝对时间轴，且视觉状态必须是无堆分配的值类型。");
        Assert(refresh.Contains(
                   "!_workExitRequested",
                   StringComparison.Ordinal) &&
               refresh.Contains(
                   "_workState != WorkState.Exiting",
                   StringComparison.Ordinal) &&
               updateTarget.Contains(
                   "AdvanceWorkModeIconTransition(timestamp)",
                   StringComparison.Ordinal) &&
               updateTarget.Contains(
                   "_workModeIconTransitionStartState = _workModeIconCurrentVisualState",
                   StringComparison.Ordinal),
            "退出请求当帧必须把月亮目标反转为太阳；若目标在过渡中反转，" +
            "必须先解析当前mix并从该值续播，不能跳回任一端点。");
        Assert(initialize.Contains("ApplyTemplate", StringComparison.Ordinal) &&
               initialize.Contains("template.FindName", StringComparison.Ordinal) &&
               !apply.Contains("FindName", StringComparison.Ordinal) &&
               !apply.Contains("ApplyTemplate", StringComparison.Ordinal) &&
               !advance.Contains("DispatcherTimer", StringComparison.Ordinal) &&
               !resolve.Contains("DispatcherTimer", StringComparison.Ordinal) &&
               !resolve.Contains("Storyboard", StringComparison.Ordinal) &&
               !resolve.Contains("BeginAnimation", StringComparison.Ordinal) &&
               !xaml.Contains("<Storyboard", StringComparison.Ordinal) &&
               !source.Split('\n').Any(line => line.Contains(
                   "DispatcherTimer _workModeIcon",
                   StringComparison.Ordinal)),
            "模板元素只能初始化时查找并缓存；每帧不得查找布局元素、创建timer/" +
            "Storyboard或启动独立动画对象。");

        object Stable(bool working) => InvokeStatic(
            typeof(MainWindow),
            "GetWorkModeIconStableState",
            working)!;
        object Resolve(object startState, double seconds, bool toWorking) =>
            InvokeStatic(
                typeof(MainWindow),
                "ResolveWorkModeIconTransitionState",
                startState,
                seconds,
                toWorking)!;
        double Value(object state, string property) =>
            GetProperty<double>(state, property);

        var idle = Stable(working: false);
        var working = Stable(working: true);
        var forwardStart = Resolve(idle, 0, toWorking: true);
        var firstRefresh = Resolve(idle, 1d / 60d, toWorking: true);
        var stalledAt250Milliseconds = Resolve(idle, 0.250, toWorking: true);
        var incomingOvershoot = Resolve(idle, 0.290, toWorking: true);
        var forwardEnd = Resolve(idle, 0.420, toWorking: true);
        AssertWorkModeIconStateClose(
            forwardStart,
            idle,
            "太阳→月亮的起点必须精确保持当前太阳状态");
        Assert(Value(firstRefresh, "SunScale") is < 0.98 and > 0.72 &&
               Math.Abs(Value(firstRefresh, "SunRotationDegrees")) > 0.05 &&
               Value(firstRefresh, "MoonOpacity") > 0 &&
               Value(firstRefresh, "SunOpacity") +
                   Value(firstRefresh, "MoonOpacity") is >= 0.999 and <= 1.051,
            "点击后一个60Hz刷新周期内必须看到太阳收拢/旋转和月亮淡入反馈，" +
            "且不能出现双图全透明帧。");
        Assert(Value(incomingOvershoot, "MoonScale") is >= 1.06 and <= 1.081 &&
               Value(stalledAt250Milliseconds, "TwinkleOpacity") > 0.20 &&
               Value(stalledAt250Milliseconds, "SunOpacity") > 0 &&
               Value(stalledAt250Milliseconds, "MoonOpacity") > 0,
            "入场图标必须从0.72回弹到约1.08再收敛，并以单个预置小星闪烁；" +
            "250ms阻塞后必须直接定位到当前交叉态。");
        AssertWorkModeIconStateClose(
            forwardEnd,
            working,
            "420ms结束必须精确收敛到月亮稳定态");

        var reverseStart = Resolve(working, 0, toWorking: false);
        var reverseFirstRefresh = Resolve(
            working,
            1d / 60d,
            toWorking: false);
        var reverseOvershoot = Resolve(working, 0.290, toWorking: false);
        var reverseEnd = Resolve(working, 0.420, toWorking: false);
        AssertWorkModeIconStateClose(
            reverseStart,
            working,
            "月亮→太阳的起点必须精确保持当前月亮状态");
        Assert(Value(reverseFirstRefresh, "MoonScale") is < 0.98 and > 0.72 &&
               Math.Abs(Value(reverseFirstRefresh, "MoonRotationDegrees")) > 0.05 &&
               Value(reverseFirstRefresh, "SunOpacity") > 0 &&
               Value(reverseOvershoot, "SunScale") is >= 1.06 and <= 1.081,
            "月亮退出和太阳入场必须使用同样丝滑的下沉、旋转与回弹质量。");
        AssertWorkModeIconStateClose(
            reverseEnd,
            idle,
            "420ms反向结束必须精确收敛到太阳稳定态");

        for (var millisecond = 0; millisecond <= 420; millisecond++)
        {
            var forward = Resolve(
                idle,
                millisecond / 1000d,
                toWorking: true);
            var reverse = Resolve(
                working,
                millisecond / 1000d,
                toWorking: false);
            var forwardCombinedOpacity = Value(forward, "SunOpacity") +
                                         Value(forward, "MoonOpacity");
            var reverseCombinedOpacity = Value(reverse, "SunOpacity") +
                                         Value(reverse, "MoonOpacity");
            Assert(forwardCombinedOpacity is >= 0.999 and <= 1.051 &&
                   reverseCombinedOpacity is >= 0.999 and <= 1.051,
                $"太阳/月亮交叉淡入淡出在{millisecond}ms必须保持总Opacity " +
                $"1.0–1.05，避免空帧或双图发亮：" +
                $"{forwardCombinedOpacity:F3}/{reverseCombinedOpacity:F3}。");
        }

        var forwardMid = Resolve(idle, 0.180, toWorking: true);
        var reversedFromCurrentMix = Resolve(
            forwardMid,
            0,
            toWorking: false);
        AssertWorkModeIconStateClose(
            reversedFromCurrentMix,
            forwardMid,
            "中途反转必须从同一mix、transform和halo值连续开始");
        AssertWorkModeIconStateClose(
            Resolve(forwardMid, 0.420, toWorking: false),
            idle,
            "中途反转仍必须在独立420ms绝对时间后收敛到太阳");

        foreach (var refreshRate in new[] { 59, 60, 120, 144 })
        {
            _ = refreshRate;
            AssertWorkModeIconStateClose(
                Resolve(idle, 0.250, toWorking: true),
                stalledAt250Milliseconds,
                "同一绝对时间在59/60/120/144Hz必须得到同一图标位置");
        }

        PrepareWorkModeIdleState(window);
    }

    private static void AssertWorkModeIconStateClose(
        object actual,
        object expected,
        string message)
    {
        foreach (var property in new[]
                 {
                     "SunOpacity", "MoonOpacity", "SunScale", "MoonScale",
                     "SunRotationDegrees", "MoonRotationDegrees",
                     "SunTranslateX", "SunTranslateY",
                     "MoonTranslateX", "MoonTranslateY",
                     "SunHaloOpacity", "MoonHaloOpacity",
                     "SunHaloScale", "MoonHaloScale",
                     "TwinkleOpacity", "TwinkleScale", "TwinkleRotationDegrees"
                 })
        {
            var actualValue = GetProperty<double>(actual, property);
            var expectedValue = GetProperty<double>(expected, property);
            Assert(Math.Abs(actualValue - expectedValue) <= 0.000001,
                $"{message}: {property}={actualValue:F6}/{expectedValue:F6}");
        }
    }

    private static void AssertWorkModeClockAndInputContract(MainWindow window)
    {
        var source = File.ReadAllText(FindWorkspaceFile("MainWindow.xaml.cs"));
        var rendering = ExtractPrivateMethodSource(source, "VisualClock_Rendering");
        var advanceLoop = ExtractPrivateMethodSource(source, "AdvanceWorkLoop");
        var getPosition = ExtractPrivateMethodSource(
            source,
            "GetWorkLoopFramePositionAt");
        var startWorkClip = ExtractPrivateMethodSource(source, "StartWorkClip");
        var handleWorkClick = ExtractPrivateMethodSource(
            source,
            "HandleWorkPetClick");
        var prefetchSeriousEntry = ExtractPrivateMethodSource(
            source,
            "PrefetchWorkSeriousEntryPage");
        var startFastTyping = ExtractPrivateMethodSource(
            source,
            "StartFastWorkTypingAt");
        var requestWorkExit = ExtractPrivateMethodSource(
            source,
            "RequestWorkExit");
        var mouseMove = ExtractPrivateMethodSource(
            source,
            "PetHost_MouseMove");
        var tryBeginDirectDrag = ExtractPrivateMethodSource(
            source,
            "TryBeginPetPointerDrag");
        var beginDirectDrag = ExtractPrivateMethodSource(
            source,
            "BeginDirectPetDrag");
        var mouseUp = ExtractPrivateMethodSource(
            source,
            "PetHost_MouseLeftButtonUp");
        var lostMouseCapture = ExtractPrivateMethodSource(
            source,
            "PetHost_LostMouseCapture");
        var completeDirectDrag = ExtractPrivateMethodSource(
            source,
            "CompleteDirectPetDrag");
        var updateEdgeDockAfterDrag = ExtractPrivateMethodSource(
            source,
            "UpdateEdgeDockAfterDrag");
        var rightClick = ExtractPrivateMethodSource(
            source,
            "PetHost_MouseRightButtonUp");
        var setBubbleMode = ExtractPrivateMethodSource(source, "SetBubbleMode");
        var queueSessionInactive = ExtractPrivateMethodSource(
            source,
            "QueueSessionInactive");
        var automaticTick = ExtractPrivateMethodSource(
            source,
            "AutomaticTimer_Tick");
        var startRoaming = ExtractPrivateMethodSource(
            source,
            "StartEdgeRoaming");
        var refreshSnore = ExtractPrivateMethodSource(
            source,
            "RefreshSnoreBubbleAnimationState");

        Assert(source.Contains("CompositionTarget.Rendering += VisualClock_Rendering", StringComparison.Ordinal) &&
               rendering.Contains("Stopwatch.GetTimestamp()", StringComparison.Ordinal) &&
               rendering.Contains("AdvanceWorkLoop(timestamp)", StringComparison.Ordinal) &&
               getPosition.Contains("Stopwatch.Frequency", StringComparison.Ordinal) &&
               getPosition.Contains("_workLoopPlaybackRate", StringComparison.Ordinal),
            "Work poses must be resolved from the shared CompositionTarget + Stopwatch absolute clock.");
        var workDispatcherTimerFields = source
            .Split('\n')
            .Where(line =>
                line.Contains("DispatcherTimer _work", StringComparison.Ordinal))
            .Select(line => line.Trim())
            .ToArray();
        Assert(workDispatcherTimerFields.Length == 0 &&
               !advanceLoop.Contains("DispatcherTimer", StringComparison.Ordinal) &&
               !startWorkClip.Contains("DispatcherTimer", StringComparison.Ordinal),
            "Work mode must not use click-decision or per-frame DispatcherTimers.");
        Assert(handleWorkClick.Contains("if (clickCount < 2)", StringComparison.Ordinal) &&
               handleWorkClick.Contains("PrefetchWorkSeriousEntryPage()", StringComparison.Ordinal) &&
               handleWorkClick.Contains("ReferenceEquals(_activeClip, _workLoopClip)", StringComparison.Ordinal) &&
               handleWorkClick.Contains("StartFastWorkTypingAt(Stopwatch.GetTimestamp())", StringComparison.Ordinal) &&
               !handleWorkClick.Contains("_workLoopPlaybackRate =", StringComparison.Ordinal) &&
               !handleWorkClick.Contains("_activeClip =", StringComparison.Ordinal) &&
               prefetchSeriousEntry.Contains("_spritePagePrefetchTask is not null", StringComparison.Ordinal) &&
               prefetchSeriousEntry.Contains("_desiredSpritePageName is not null", StringComparison.Ordinal) &&
               prefetchSeriousEntry.Contains("urgent: false", StringComparison.Ordinal) &&
               !prefetchSeriousEntry.Contains("urgent: true", StringComparison.Ordinal) &&
               startFastTyping.Contains("_workLoopPlaybackRate = WorkFastPlaybackMultiplier", StringComparison.Ordinal) &&
               startFastTyping.Contains("GetNextWorkNeutralMicroSeamFramePosition", StringComparison.Ordinal) &&
               !requestWorkExit.Contains(
                   "_workLoopPlaybackRate =",
                   StringComparison.Ordinal) &&
               requestWorkExit.Contains(
                   "GetNextWorkNeutralMicroSeamFramePosition",
                   StringComparison.Ordinal) &&
               !advanceLoop.Contains(
                   "ShowStableFrame(loopFrames[0])",
                   StringComparison.Ordinal) &&
               !advanceLoop.Contains(
                   "ShowStableFrame(_workSeriousLoopFrames[0])",
                   StringComparison.Ordinal),
            "A single click must be a strict visual no-op, while a double click " +
            "must switch the existing absolute clock to 2x immediately and hand " +
            "off the serious expression only at a neutral micro-seam.");

        var neutralMicroSeams = (int[])(
            typeof(MainWindow).GetField(
                "WorkNeutralMicroSeamFrameIndices",
                StaticFlags)?.GetValue(null) ?? Array.Empty<int>());
        var expectedNeutralMicroSeams =
            new[] { 0, 10, 21, 33, 44, 56, 69, 81, 93 };
        Assert(neutralMicroSeams.SequenceEqual(expectedNeutralMicroSeams),
            "The 96-frame typing cycle must expose its nine authored neutral " +
            "micro-seams to the runtime state machine.");
        var maximumForwardSeamFrames = 0d;
        for (var eighthFrame = -96 * 8; eighthFrame <= 96 * 16; eighthFrame++)
        {
            var framePosition = eighthFrame / 8d;
            var target = (double)InvokeStatic(
                typeof(MainWindow),
                "GetNextWorkNeutralMicroSeamFramePosition",
                framePosition)!;
            var waitFrames = target - framePosition;
            maximumForwardSeamFrames = Math.Max(
                maximumForwardSeamFrames,
                waitFrames);
            var wrappedTarget = target % 96d;
            if (wrappedTarget < 0)
            {
                wrappedTarget += 96d;
            }

            Assert(waitFrames >= -0.000001 && waitFrames <= 13.000001 &&
                   neutralMicroSeams.Any(seam =>
                       Math.Abs(wrappedTarget - seam) <= 0.000001),
                $"Neutral micro-seam lookup must move forward without a phase " +
                $"jump and wait at most 13 authored frames: " +
                $"phase={framePosition:F3}, target={target:F3}.");
        }
        var maximumNormalWaitMilliseconds =
            maximumForwardSeamFrames / 60d * 1000d;
        var maximumFastWaitMilliseconds =
            maximumForwardSeamFrames / (60d * 2d) * 1000d;
        Assert(maximumNormalWaitMilliseconds <= 217d &&
               maximumFastWaitMilliseconds <= 109d,
            $"Neutral seam wait must stay within 13 frames at 1x and about " +
            $"109ms at 2x; actual {maximumNormalWaitMilliseconds:F2}ms/" +
            $"{maximumFastWaitMilliseconds:F2}ms.");

        Assert(!source.Contains("GetDoubleClickTime", StringComparison.Ordinal) &&
               !source.Contains("WorkSingleClick", StringComparison.Ordinal) &&
               !source.Contains("WorkTap", StringComparison.Ordinal) &&
               !source.Contains("luban-work-tap-", StringComparison.Ordinal),
            "Runtime source must not retain delayed single-click arbitration or work-tap assets.");

        var thresholdReturn = tryBeginDirectDrag.IndexOf(
            "if (!HasExceededPetDragThreshold(",
            StringComparison.Ordinal);
        var cancelPending = tryBeginDirectDrag.IndexOf(
            "BeginDirectPetDrag(",
            StringComparison.Ordinal);
        Assert(thresholdReturn >= 0 &&
               cancelPending > thresholdReturn &&
               mouseMove.Contains(
                   "TryBeginPetPointerDrag(",
                   StringComparison.Ordinal) &&
               beginDirectDrag.Contains(
                   "_workPointerClickCount = 0",
                   StringComparison.Ordinal) &&
               beginDirectDrag.Contains(
                   "_dragPreservesWorkMode = _workState != WorkState.Idle",
                   StringComparison.Ordinal) &&
               !beginDirectDrag.Contains(
                   "StopWorkModeImmediately",
                   StringComparison.Ordinal) &&
               mouseUp.Contains(
                   "updateEdgeDock: true",
                   StringComparison.Ordinal) &&
               lostMouseCapture.Contains(
                   "updateEdgeDock: true",
                   StringComparison.Ordinal) &&
               completeDirectDrag.Contains(
                   "hadActiveDrag && updateEdgeDock",
                   StringComparison.Ordinal) &&
               updateEdgeDockAfterDrag.Contains(
                   "_dragPreservesWorkMode && _workState != WorkState.Idle",
                   StringComparison.Ordinal) &&
               updateEdgeDockAfterDrag.Contains(
                   "StartWorkEdgeHandoff(touchedEdge)",
                   StringComparison.Ordinal) &&
               !updateEdgeDockAfterDrag.Contains(
                   "RequestWorkExit()",
                   StringComparison.Ordinal) &&
               updateEdgeDockAfterDrag.Contains(
                   "EnterEdgePeek(touchedEdge)",
                   StringComparison.Ordinal),
            "Sub-threshold pointer motion must preserve click classification; a real " +
            "work drag must clear the click count, preserve work, and start a direct " +
            "edge handoff without routing through the ordinary work-exit clip.");
        Assert(rightClick.IndexOf(
                   "_openTodoAfterWorkExitRequested = true",
                   StringComparison.Ordinal) >= 0 &&
               rightClick.IndexOf(
                   "RequestWorkExit()",
                   StringComparison.Ordinal) >= 0,
            "Right-click must defer Todo until the authored work exit finishes.");
        Assert(setBubbleMode.Contains(
                   "StopWorkModeImmediately(restoreIdleFrame: false)",
                   StringComparison.Ordinal) &&
               queueSessionInactive.Contains(
                   "StopWorkModeImmediately(restoreIdleFrame: true)",
                   StringComparison.Ordinal),
            "Reminder/Todo interruption and session lock must stop work through the shared work path.");
        Assert(automaticTick.Contains(
                   "_workState != WorkState.Idle",
                   StringComparison.Ordinal) &&
               startRoaming.Contains(
                   "_workState != WorkState.Idle",
                   StringComparison.Ordinal) &&
               refreshSnore.Contains(
                   "_workState == WorkState.Idle",
                   StringComparison.Ordinal),
            "Work mode must suppress random actions, snore bubbles, and edge roaming.");

        var loopFrames = GetField<Array>(window, "_workLoopFrames");
        var seriousLoopFrames = GetField<Array>(window, "_workSeriousLoopFrames");
        AssertWorkTypingPresentationSampling(
            window,
            loopFrames,
            "normal loop",
            playbackRate: 1,
            expectedCycleSeconds: 1.6,
            expectedVisibleFrameSlotCounts: new Dictionary<int, int>
            {
                [59] = 95,
                [60] = 96,
                [120] = 96,
                [144] = 96
            });
        AssertWorkTypingPresentationSampling(
            window,
            seriousLoopFrames,
            "serious loop",
            playbackRate: 2,
            expectedCycleSeconds: 0.8,
            expectedVisibleFrameSlotCounts: new Dictionary<int, int>
            {
                [59] = 48,
                [60] = 48,
                [120] = 96,
                [144] = 96
            });

        var loopClip = GetField<object>(window, "_workLoopClip");
        var seriousLoopClip = GetField<object>(window, "_workSeriousLoopClip");
        var seriousEnterClip = GetField<object>(window, "_workSeriousEnterClip");
        var seriousExitClip = GetField<object>(window, "_workSeriousExitClip");
        var seriousEnterFrames = GetClipFrames(seriousEnterClip);
        var seriousExitFrames = GetField<Array>(window, "_workSeriousExitFrames");
        var expectedSeriousEnterSourceIndices =
            new[] { 23, 20, 16, 13, 10, 7, 3, 0 };
        Assert(seriousEnterFrames.Length == expectedSeriousEnterSourceIndices.Length &&
               seriousEnterFrames.Cast<object>().Select(GetAnimationFrameName)
                   .SequenceEqual(expectedSeriousEnterSourceIndices.Select(index =>
                       Path.GetFileName(
                           GetSpriteFrameInfo(
                               seriousExitFrames.GetValue(index)!).Name))) &&
               seriousEnterFrames.Cast<object>().All(frame =>
                   ToProductionCharacterAnimationTicks(GetFrameDuration(frame)) ==
                   ToProductionStopwatchTicks(
                       TimeSpan.FromTicks(TimeSpan.TicksPerSecond / 60))),
            "Serious entry must deterministically sample the authored exit in " +
            "reverse as eight 60fps poses (about 133ms), not rely on compositor " +
            "frame skipping.");
        PrepareWorkModeIdleState(window);
        EnterWorkTypingForTest(window);
        var baseTimestamp = Stopwatch.GetTimestamp();
        SetField(window, "_workLoopAnchorFramePosition", 17.25d);
        SetField(window, "_workLoopAnchorTimestamp", baseTimestamp);
        SetField(window, "_workLoopPlaybackRate", 1d);
        SetField(window, "_workFastUntilTimestamp", 0L);
        SetField(window, "_activeClip", loopClip);

        var clickTimestamp = checked(
            baseTimestamp + Stopwatch.Frequency * 3 / 8);
        var phaseBefore = (double)Invoke(
            window,
            "GetWorkLoopFramePositionAt",
            clickTimestamp)!;
        Invoke(window, "StartFastWorkTypingAt", clickTimestamp);
        var phaseAfter = (double)Invoke(
            window,
            "GetWorkLoopFramePositionAt",
            clickTimestamp)!;
        Assert(Math.Abs(phaseAfter - phaseBefore) <= 0.000001 &&
               Math.Abs(GetField<double>(window, "_workLoopPlaybackRate") - 2d) <=
               0.000001 &&
               GetField<bool>(window, "_workSeriousEnterRequested") &&
               ReferenceEquals(GetRawField(window, "_activeClip"), loopClip) &&
               GetField<long>(window, "_workFastUntilTimestamp") == 0,
            "Double-click must preserve the current normal-loop phase, respond " +
            "immediately at 2x, and defer the face change until a neutral seam.");

        var seriousEnterTarget = GetField<double>(
            window,
            "_workSeriousEnterTargetFramePosition");
        Assert(seriousEnterTarget >= phaseBefore &&
               seriousEnterTarget - phaseBefore <= 13.000001,
            "The immediate 2x response must reach its serious-entry seam within " +
            "13 authored frames (about 109ms).");
        var seriousEnterTimestamp = checked(
            clickTimestamp +
            (long)Math.Ceiling(
                (seriousEnterTarget - phaseBefore) /
                (60d * 2d) * Stopwatch.Frequency) + 2);
        Invoke(window, "AdvanceWorkLoop", seriousEnterTimestamp);
        Assert(ReferenceEquals(
                   GetRawField(window, "_activeClip"),
                   seriousEnterClip) &&
               !GetField<bool>(window, "_workSeriousEnterRequested") &&
               Math.Abs(
                   GetField<double>(window, "_workLoopAnchorFramePosition") -
                   seriousEnterTarget) <= 0.000001 &&
               GetField<long>(window, "_workFastUntilTimestamp") == 0,
            "Normal 2x typing must hand off to the sampled serious-entry clip at " +
            "the selected neutral seam without starting the four-second timer early.");

        var seriousLoopTimestamp = checked(
            seriousEnterTimestamp +
            ToProductionStopwatchTicks(TimeSpan.FromMilliseconds(133.34)));
        Invoke(
            window,
            "CompleteActiveClipAt",
            seriousEnterClip,
            seriousLoopTimestamp);
        Invoke(
            window,
            "StartActiveClipClockAt",
            seriousLoopTimestamp,
            TimeSpan.Zero);
        var fastUntil = GetField<long>(window, "_workFastUntilTimestamp");
        var expectedFastUntil = checked(
            seriousLoopTimestamp + Stopwatch.Frequency * 4L);
        Assert(ReferenceEquals(GetRawField(window, "_activeClip"), seriousLoopClip) &&
               Math.Abs(fastUntil - expectedFastUntil) <= 1 &&
               Math.Abs(
                   GetField<double>(window, "_workLoopAnchorFramePosition") -
                   seriousEnterTarget) <= 0.000001 &&
               Math.Abs(GetField<double>(window, "_workLoopPlaybackRate") - 2d) <=
                   0.000001,
            "Serious typing must start pixel-safely at the same seam phase and " +
            "receive a fresh four-second 2x window only after entry completes.");
        var phaseAtFastEnd = (double)Invoke(
            window,
            "GetWorkLoopFramePositionAt",
            fastUntil)!;
        Invoke(window, "AdvanceWorkLoop", fastUntil);
        var exitedAtExactFastEndSeam = ReferenceEquals(
            GetRawField(window, "_activeClip"),
            seriousExitClip);
        var phasePreservedWhileWaiting = exitedAtExactFastEndSeam ||
            Math.Abs(
                phaseAtFastEnd -
                (double)Invoke(
                    window,
                    "GetWorkLoopFramePositionAt",
                    fastUntil)!) <= 0.000001;
        Assert(phasePreservedWhileWaiting &&
               Math.Abs(phaseAtFastEnd - (seriousEnterTarget + 480d)) <= 0.001 &&
               (exitedAtExactFastEndSeam ||
                GetField<bool>(window, "_workSeriousExitRequested")),
            "Four-second serious expiry must remain on the unchanged absolute " +
            "2x phase before the authored facial relaxation begins.");
        var seriousExitTimestamp = fastUntil;
        if (!ReferenceEquals(GetRawField(window, "_activeClip"), seriousExitClip))
        {
            var seriousExitTarget =
                GetField<double>(window, "_workSeriousExitTargetFramePosition");
            seriousExitTimestamp = checked(
                GetField<long>(window, "_workLoopAnchorTimestamp") +
                (long)Math.Ceiling(
                    (seriousExitTarget -
                     GetField<double>(window, "_workLoopAnchorFramePosition")) /
                    (60d * GetField<double>(window, "_workLoopPlaybackRate")) *
                    Stopwatch.Frequency) + 2);
            Invoke(window, "AdvanceWorkLoop", seriousExitTimestamp);
        }
        Assert(ReferenceEquals(GetRawField(window, "_activeClip"), seriousExitClip),
            "Serious typing must reach its authored 24-frame exit at the next seam.");
        var normalLoopTimestamp = checked(
            seriousExitTimestamp + Stopwatch.Frequency / 2);
        Invoke(
            window,
            "CompleteActiveClipAt",
            seriousExitClip,
            normalLoopTimestamp);
        Invoke(window, "StartActiveClipClockAt", normalLoopTimestamp, TimeSpan.Zero);
        Assert(ReferenceEquals(GetRawField(window, "_activeClip"), loopClip) &&
               Math.Abs(GetField<double>(window, "_workLoopPlaybackRate") - 1d) <=
               0.000001 &&
               GetField<long>(window, "_workFastUntilTimestamp") == 0,
            "Completing serious-exit must land on ordinary loop-001 at 1x.");
        var halfSecondLater = checked(
            normalLoopTimestamp + Stopwatch.Frequency / 2);
        var phaseHalfSecondLater = (double)Invoke(
            window,
            "GetWorkLoopFramePositionAt",
            halfSecondLater)!;
        Assert(Math.Abs(phaseHalfSecondLater - 30d) <= 0.001,
            "Normal typing must continue from loop-001 at 60 authored poses/second " +
            "after the serious-exit clip.");

        // The assertions below mutate the production clock anchors directly.
        // Freeze the shared compositor subscription first so a real Rendering
        // callback from earlier full-suite work cannot advance the visible pose
        // between the before/after snapshots.
        Invoke(window, "StopVisualClock");
        var singleClickAnchorTimestamp = Stopwatch.GetTimestamp();
        const double singleClickAnchorPosition = 17.25d;
        SetField(window, "_activeClip", loopClip);
        SetField(window, "_activeFrameIndex", 17);
        SetField(
            window,
            "_workLoopAnchorFramePosition",
            singleClickAnchorPosition);
        SetField(window, "_workLoopAnchorTimestamp", singleClickAnchorTimestamp);
        SetField(window, "_workLoopPlaybackRate", 1d);
        SetField(window, "_workFastUntilTimestamp", 0L);
        SetField(window, "_workSeriousEnterRequested", false);
        SetField(
            window,
            "_workSeriousEnterTargetFramePosition",
            double.PositiveInfinity);
        SetField(window, "_workSeriousExitRequested", false);
        SetField(
            window,
            "_workSeriousExitTargetFramePosition",
            double.PositiveInfinity);
        PrimeSpritePageForFrame(window, loopFrames.GetValue(17)!);
        Invoke(window, "ShowStableFrame", loopFrames.GetValue(17)!);

        var singleClipBefore = GetRawField(window, "_activeClip");
        var singleFrameIndexBefore = GetField<int>(window, "_activeFrameIndex");
        var singleFrameNameBefore = GetSpriteFrameInfo(
            GetField<object>(window, "_currentSpriteFrame")).Name;
        var singleAnchorBefore =
            GetField<double>(window, "_workLoopAnchorFramePosition");
        var singleTimestampBefore =
            GetField<long>(window, "_workLoopAnchorTimestamp");
        var singleRateBefore =
            GetField<double>(window, "_workLoopPlaybackRate");
        var singleFastUntilBefore =
            GetField<long>(window, "_workFastUntilTimestamp");
        Invoke(window, "HandleWorkPetClick", 1);
        Assert(ReferenceEquals(GetRawField(window, "_activeClip"), singleClipBefore) &&
               GetField<int>(window, "_activeFrameIndex") == singleFrameIndexBefore &&
               string.Equals(
                   GetSpriteFrameInfo(
                       GetField<object>(window, "_currentSpriteFrame")).Name,
                   singleFrameNameBefore,
                   StringComparison.Ordinal) &&
               Math.Abs(
                   GetField<double>(window, "_workLoopAnchorFramePosition") -
                   singleAnchorBefore) <= 0.000001 &&
               GetField<long>(window, "_workLoopAnchorTimestamp") ==
                   singleTimestampBefore &&
               Math.Abs(
                   GetField<double>(window, "_workLoopPlaybackRate") -
                   singleRateBefore) <= 0.000001 &&
               GetField<long>(window, "_workFastUntilTimestamp") ==
                   singleFastUntilBefore &&
               !GetField<bool>(window, "_workSeriousEnterRequested") &&
               !GetField<bool>(window, "_workSeriousExitRequested") &&
               double.IsPositiveInfinity(GetField<double>(
                   window,
                   "_workSeriousEnterTargetFramePosition")) &&
               double.IsPositiveInfinity(GetField<double>(
                   window,
                   "_workSeriousExitTargetFramePosition")),
            "A single click must be a strict visual no-op: clip, visible pose, " +
            "absolute phase, speed, serious flags, and deadline must all remain unchanged.");

        // Keep a real cold-page-shaped Task in flight for the next ordinary
        // loop page. The speculative first-click prewarm must not replace it,
        // cancel it, change its urgency, or advance the page generation.
        WaitForSpritePagePrefetchToSettle(window);
        Invoke(window, "StopVisualClock");
        singleClipBefore = GetRawField(window, "_activeClip");
        singleFrameIndexBefore = GetField<int>(window, "_activeFrameIndex");
        singleFrameNameBefore = GetSpriteFrameInfo(
            GetField<object>(window, "_currentSpriteFrame")).Name;
        var normalLoopColdFrame = loopFrames.GetValue(32)!;
        var normalLoopColdPageName = GetSpriteFrameInfo(normalLoopColdFrame).PageName;
        var pendingNormalLoopDecode = CreatePendingSpritePageLoadTask();
        var normalLoopDecodeCancellation = new CancellationTokenSource();
        var normalLoopDecodeGeneration =
            GetField<int>(window, "_spritePagePrefetchGeneration") + 1;
        SetField(
            window,
            "_spritePagePrefetchGeneration",
            normalLoopDecodeGeneration);
        SetField(window, "_desiredSpritePageName", normalLoopColdPageName);
        SetField(window, "_desiredSpritePageUrgent", true);
        SetField(window, "_spritePagePrefetchTask", pendingNormalLoopDecode);
        SetField(
            window,
            "_spritePagePrefetchCancellation",
            normalLoopDecodeCancellation);
        SetField(
            window,
            "_spritePagePrefetchPageName",
            normalLoopColdPageName);

        Invoke(window, "HandleWorkPetClick", 1);
        Assert(ReferenceEquals(
                   GetRawField(window, "_spritePagePrefetchTask"),
                   pendingNormalLoopDecode) &&
               ReferenceEquals(
                   GetRawField(window, "_spritePagePrefetchCancellation"),
                   normalLoopDecodeCancellation) &&
               string.Equals(
                   GetRawField(window, "_desiredSpritePageName") as string,
                   normalLoopColdPageName,
                   StringComparison.Ordinal) &&
               string.Equals(
                   GetRawField(window, "_spritePagePrefetchPageName") as string,
                   normalLoopColdPageName,
                   StringComparison.Ordinal) &&
               GetField<bool>(window, "_desiredSpritePageUrgent") &&
               GetField<int>(window, "_spritePagePrefetchGeneration") ==
                   normalLoopDecodeGeneration &&
               !normalLoopDecodeCancellation.IsCancellationRequested &&
               ReferenceEquals(GetRawField(window, "_activeClip"), singleClipBefore) &&
               string.Equals(
                   GetSpriteFrameInfo(
                       GetField<object>(window, "_currentSpriteFrame")).Name,
                   singleFrameNameBefore,
                   StringComparison.Ordinal),
            "A single click during an asynchronous cold ordinary-loop decode " +
            "must be a strict no-op and must never preempt the visible-loop page.");

        SetField(window, "_spritePagePrefetchTask", null);
        SetField(window, "_spritePagePrefetchCancellation", null);
        SetField(window, "_spritePagePrefetchPageName", null);
        SetField(window, "_desiredSpritePageName", null);
        SetField(window, "_desiredSpritePageUrgent", false);
        normalLoopDecodeCancellation.Dispose();

        var seriousEntryFirstFrame = GetProperty<object>(
            GetClipFrames(seriousEnterClip).GetValue(0)!,
            "Image");
        var seriousEntryPageName =
            GetSpriteFrameInfo(seriousEntryFirstFrame).PageName;
        PrimeSpritePageForFrame(window, loopFrames.GetValue(17)!);
        EvictResidentSpritePageForTest(window, seriousEntryPageName);
        var pendingSeriousEntryDecode = CreatePendingSpritePageLoadTask();
        var seriousEntryDecodeCancellation = new CancellationTokenSource();
        var seriousEntryDecodeGeneration =
            GetField<int>(window, "_spritePagePrefetchGeneration") + 1;
        SetField(
            window,
            "_spritePagePrefetchGeneration",
            seriousEntryDecodeGeneration);
        SetField(window, "_desiredSpritePageName", seriousEntryPageName);
        SetField(window, "_desiredSpritePageUrgent", true);
        SetField(window, "_spritePagePrefetchTask", pendingSeriousEntryDecode);
        SetField(
            window,
            "_spritePagePrefetchCancellation",
            seriousEntryDecodeCancellation);
        SetField(
            window,
            "_spritePagePrefetchPageName",
            seriousEntryPageName);

        var doubleClickBefore = Stopwatch.GetTimestamp();
        Invoke(window, "HandleWorkPetClick", 2);
        var doubleClickAfter = Stopwatch.GetTimestamp();
        var doubleClickAnchorTimestamp =
            GetField<long>(window, "_workLoopAnchorTimestamp");
        var doubleClickAnchorPosition =
            GetField<double>(window, "_workLoopAnchorFramePosition");
        var doubleClickTarget = GetField<double>(
            window,
            "_workSeriousEnterTargetFramePosition");
        Assert(ReferenceEquals(GetRawField(window, "_activeClip"), loopClip) &&
               Math.Abs(GetField<double>(window, "_workLoopPlaybackRate") - 2d) <=
                   0.000001 &&
               GetField<bool>(window, "_workSeriousEnterRequested") &&
               GetField<long>(window, "_workFastUntilTimestamp") == 0 &&
               doubleClickAnchorTimestamp >= doubleClickBefore &&
               doubleClickAnchorTimestamp <= doubleClickAfter &&
               doubleClickTarget >= doubleClickAnchorPosition &&
               doubleClickTarget - doubleClickAnchorPosition <= 13.000001 &&
               ReferenceEquals(
                   GetRawField(window, "_spritePagePrefetchTask"),
                   pendingSeriousEntryDecode) &&
               !seriousEntryDecodeCancellation.IsCancellationRequested,
            "A double click must switch the existing normal loop to 2x in the " +
            "same input turn, select the nearest serious-expression seam, and " +
            "reuse an in-flight decode for that cold entry page.");

        var doubleClickSeamTimestamp = checked(
            doubleClickAnchorTimestamp +
            (long)Math.Ceiling(
                (doubleClickTarget - doubleClickAnchorPosition) /
                (60d * 2d) * Stopwatch.Frequency) + 2);
        Invoke(window, "AdvanceWorkLoop", doubleClickSeamTimestamp);
        Assert(ReferenceEquals(
                   GetRawField(window, "_activeClip"),
                   seriousEnterClip) &&
               !GetField<bool>(window, "_workSeriousEnterRequested") &&
               Math.Abs(
                   GetField<double>(window, "_workLoopAnchorFramePosition") -
                   doubleClickTarget) <= 0.000001 &&
               Math.Abs(GetField<double>(window, "_workLoopPlaybackRate") - 2d) <=
                   0.000001 &&
               string.Equals(
                   GetSpriteFrameInfo(
                       GetField<object>(window, "_currentSpriteFrame")).Name,
                   singleFrameNameBefore,
                   StringComparison.Ordinal) &&
               string.Equals(
                   GetSpriteFrameInfo(
                       GetField<object>(window, "_pendingSpriteFrame")).Name,
                   GetSpriteFrameInfo(seriousEntryFirstFrame).Name,
                   StringComparison.Ordinal) &&
               GetField<long>(window, "_activeClipStartedTimestamp") == 0 &&
               GetField<long>(window, "_activeFrameDeadlineTimestamp") == long.MaxValue,
            "The serious expression must enter exactly at the selected neutral seam " +
            "without resetting the accelerated absolute phase or flashing a " +
            "placeholder while its first atlas page is cold.");

        var completedSeriousEntryDecode = CreateCompletedSpritePageLoadTask(
            window,
            seriousEntryPageName);
        var seriousEntryPublishCancellation = new CancellationTokenSource();
        seriousEntryDecodeCancellation.Dispose();
        SetField(
            window,
            "_spritePagePrefetchTask",
            completedSeriousEntryDecode);
        SetField(
            window,
            "_spritePagePrefetchCancellation",
            seriousEntryPublishCancellation);
        SetField(
            window,
            "_spritePagePrefetchPageName",
            seriousEntryPageName);
        Invoke(
            window,
            "CompleteSpritePagePrefetch",
            seriousEntryPageName,
            seriousEntryDecodeGeneration,
            seriousEntryPublishCancellation,
            completedSeriousEntryDecode);
        var seriousEntryFirstPresentationTimestamp = Stopwatch.GetTimestamp();
        Invoke(
            window,
            "TryShowPendingSpriteFrameAt",
            seriousEntryFirstPresentationTimestamp);
        Assert(string.Equals(
                   GetSpriteFrameInfo(
                       GetField<object>(window, "_currentSpriteFrame")).Name,
                   GetSpriteFrameInfo(seriousEntryFirstFrame).Name,
                   StringComparison.Ordinal) &&
               GetRawField(window, "_pendingSpriteFrame") is null &&
               GetField<long>(window, "_activeClipStartedTimestamp") ==
                   seriousEntryFirstPresentationTimestamp &&
               GetField<long>(window, "_activeFrameDeadlineTimestamp") >
                   seriousEntryFirstPresentationTimestamp,
            "A cold serious-entry page must publish its exact first pose before " +
            "starting the sampled entry clock; no normal-frame flash or elapsed " +
            "hidden time is allowed.");

        var seriousLoopStartTimestamp = checked(
            doubleClickSeamTimestamp +
            ToProductionStopwatchTicks(TimeSpan.FromMilliseconds(133.34)));
        Invoke(
            window,
            "CompleteActiveClipAt",
            seriousEnterClip,
            seriousLoopStartTimestamp);
        Invoke(
            window,
            "StartActiveClipClockAt",
            seriousLoopStartTimestamp,
            TimeSpan.Zero);
        Assert(ReferenceEquals(GetRawField(window, "_activeClip"), seriousLoopClip) &&
               Math.Abs(GetField<double>(window, "_workLoopPlaybackRate") - 2d) <=
                   0.000001 &&
               Math.Abs(
                   GetField<long>(window, "_workFastUntilTimestamp") -
                   (seriousLoopStartTimestamp + Stopwatch.Frequency * 4L)) <= 1,
            "Completing serious entry must begin the serious 2x loop and its fresh " +
            "four-second deadline.");

        var seriousClipBeforeSingle = GetRawField(window, "_activeClip");
        var seriousAnchorBeforeSingle =
            GetField<double>(window, "_workLoopAnchorFramePosition");
        var seriousTimestampBeforeSingle =
            GetField<long>(window, "_workLoopAnchorTimestamp");
        var seriousRateBeforeSingle =
            GetField<double>(window, "_workLoopPlaybackRate");
        var seriousDeadlineBeforeSingle =
            GetField<long>(window, "_workFastUntilTimestamp");
        Invoke(window, "HandleWorkPetClick", 1);
        Assert(ReferenceEquals(
                   GetRawField(window, "_activeClip"),
                   seriousClipBeforeSingle) &&
               Math.Abs(
                   GetField<double>(window, "_workLoopAnchorFramePosition") -
                   seriousAnchorBeforeSingle) <= 0.000001 &&
               GetField<long>(window, "_workLoopAnchorTimestamp") ==
                   seriousTimestampBeforeSingle &&
               Math.Abs(
                   GetField<double>(window, "_workLoopPlaybackRate") -
                   seriousRateBeforeSingle) <= 0.000001 &&
               GetField<long>(window, "_workFastUntilTimestamp") ==
                   seriousDeadlineBeforeSingle,
            "A single click during serious typing must also be a strict visual no-op.");

        var reboostTimestamp = checked(
            seriousLoopStartTimestamp + Stopwatch.Frequency);
        Invoke(window, "StartFastWorkTypingAt", reboostTimestamp);
        Assert(ReferenceEquals(GetRawField(window, "_activeClip"), seriousLoopClip) &&
               Math.Abs(GetField<double>(window, "_workLoopPlaybackRate") - 2d) <=
                   0.000001 &&
               Math.Abs(
                   GetField<long>(window, "_workFastUntilTimestamp") -
                   (reboostTimestamp + Stopwatch.Frequency * 4L)) <= 1,
            "A repeated double click during serious typing must immediately keep " +
            "2x and restart a full four-second deadline.");

        var fastExitAnchorTimestamp = Stopwatch.GetTimestamp();
        SetField(window, "_workLoopAnchorFramePosition", 93.25d);
        SetField(window, "_workLoopAnchorTimestamp", fastExitAnchorTimestamp);
        SetField(window, "_workLoopPlaybackRate", 2d);
        SetField(
            window,
            "_workFastUntilTimestamp",
            checked(fastExitAnchorTimestamp + Stopwatch.Frequency * 4L));
        Invoke(window, "RequestWorkExit");
        var fastExitTarget = GetField<double>(
            window,
            "_workExitTargetFramePosition");
        Assert(string.Equals(
                   GetRawField(window, "_workState")?.ToString(),
                   "Typing",
                   StringComparison.Ordinal) &&
               Math.Abs(GetField<double>(window, "_workLoopPlaybackRate") - 2d) <=
                   0.000001 &&
               GetField<long>(window, "_workLoopAnchorTimestamp") ==
                   fastExitAnchorTimestamp &&
               fastExitTarget > 93.25d &&
               (fastExitTarget - 93.25d) / 120d * 1000d <= 109d,
            "Requesting exit during serious typing must preserve the 2x phase " +
            "and reach the next neutral seam within about 109ms.");
        var fastExitSeamTimestamp = checked(
            fastExitAnchorTimestamp +
            (long)Math.Ceiling(
                (fastExitTarget - 93.25d) / 120d *
                Stopwatch.Frequency) + 2);
        Invoke(window, "AdvanceWorkLoop", fastExitSeamTimestamp);
        var seriousExitClipAfterRightClick =
            GetField<object>(window, "_workSeriousExitClip");
        Assert(ReferenceEquals(
                   GetRawField(window, "_activeClip"),
                   seriousExitClipAfterRightClick),
            "Right-click during serious typing must play the authored brow " +
            "relaxation at the selected seam before work-exit.");
        Invoke(
            window,
            "CompleteActiveClipAt",
            seriousExitClipAfterRightClick,
            checked(fastExitSeamTimestamp + Stopwatch.Frequency / 2));
        Assert(ReferenceEquals(
                   GetRawField(window, "_activeClip"),
                   GetField<object>(window, "_workExitClip")),
            "After a serious right-click, facial relaxation must continue into " +
            "the authored work-exit instead of returning to the normal loop.");
    }

    private static void AssertWorkModeDragContinuationContract(MainWindow window)
    {
        var source = File.ReadAllText(FindWorkspaceFile("MainWindow.xaml.cs"));
        var updateAfterDrag = ExtractPrivateMethodSource(
            source,
            "UpdateEdgeDockAfterDrag");
        var startHandoff = ExtractPrivateMethodSource(
            source,
            "StartWorkEdgeHandoff");
        var rendering = ExtractPrivateMethodSource(
            source,
            "VisualClock_Rendering");
        Assert(updateAfterDrag.Contains(
                   "StartWorkEdgeHandoff(touchedEdge)",
                   StringComparison.Ordinal) &&
               !updateAfterDrag.Contains(
                   "RequestWorkExit()",
                   StringComparison.Ordinal) &&
               !startHandoff.Contains(
                   "RequestWorkExit()",
                   StringComparison.Ordinal) &&
               !startHandoff.Contains(
                   "_workExitClip",
                   StringComparison.Ordinal) &&
               rendering.Contains(
                   "workEdgeHandoffPending",
                   StringComparison.Ordinal) &&
               rendering.Contains(
                   "TryCompletePendingWorkEdgeHandoff()",
                   StringComparison.Ordinal),
            "A work drag must use the frozen direct edge handoff and must never " +
            "route through the ordinary pillow-return work-exit clip.");

        var phaseNames = new[]
        {
            "Entering",
            "Typing",
            "SeriousEnter",
            "SeriousLoop",
            "SeriousExit",
            "Exiting"
        };
        var idleFrame = GetField<object>(window, "_idleFrame");
        var idleDigest = GetRuntimeDecodedWorkFramePixelDigest(window, idleFrame);

        foreach (var edgeName in new[] { "Left", "Right", "Bottom" })
        {
            foreach (var phaseName in phaseNames)
            {
                var fixture = ArrangeDirectWorkEdgePhase(window, phaseName);
                var workDigest = GetRuntimeDecodedWorkFramePixelDigest(
                    window,
                    fixture.DisplayedFrame);
                Assert(!string.Equals(workDigest, idleDigest, StringComparison.Ordinal) &&
                       !IsPillowVisibleWorkEnterFrame(
                           GetSpriteFrameInfo(fixture.DisplayedFrame).Name),
                    $"{phaseName}/{edgeName} must start from a real work pose, " +
                    "not idle or one of work-enter 001-024 pillow poses.");

                var edgeFrames = GetEdgeFramesForTest(window, edgeName);
                var edgeRestFrame = edgeFrames.GetValue(edgeFrames.Length - 1)!;
                var edgeRestInfo = GetSpriteFrameInfo(edgeRestFrame);
                // Load the target page without changing the displayed work
                // descriptor. StartWorkEdgeHandoff must therefore take its hot
                // path synchronously.
                PrimeSpritePageForFrame(window, edgeRestFrame);
                Assert(Equals(
                           GetRawField(window, "_currentSpriteFrame"),
                           fixture.DisplayedFrame),
                    $"{phaseName}/{edgeName} hot-page preparation must keep " +
                    "the displayed work frame.");

                var boundsBefore = (Rect)Invoke(
                    window,
                    "GetPetViewboxBoundsInScreenDips")!;
                var leftBefore = window.Left;
                var topBefore = window.Top;
                var published = new List<(string PageName, string Name)>();
                Action<string, string, int, int, int, int> observe =
                    (pageName, name, _, _, _, _) =>
                        published.Add((pageName, name));
                SetField(
                    window,
                    "_spriteFrameDescriptorPublishedForTesting",
                    observe);
                try
                {
                    Invoke(
                        window,
                        "StartWorkEdgeHandoff",
                        GetNestedEnum("EdgeDock", edgeName));
                }
                finally
                {
                    SetField(
                        window,
                        "_spriteFrameDescriptorPublishedForTesting",
                        null);
                }

                Assert(string.Equals(
                           GetRawField(window, "_workState")?.ToString(),
                           "Idle",
                           StringComparison.Ordinal) &&
                       string.Equals(
                           GetRawField(window, "_edgeDock")?.ToString(),
                           edgeName,
                           StringComparison.Ordinal) &&
                       string.Equals(
                           GetRawField(window, "_workEdgeDock")?.ToString(),
                           "None",
                           StringComparison.Ordinal) &&
                       GetField<long>(
                           window,
                           "_workEdgeHandoffFrozenTimestamp") == 0 &&
                       GetRawField(window, "_activeClip") is null &&
                       Equals(
                           GetRawField(window, "_currentSpriteFrame"),
                           edgeRestFrame),
                    $"{phaseName}/{edgeName} hot handoff must atomically enter " +
                    "edge rest and fully clear the work clock.");
                Assert(published.Count == 1 &&
                       string.Equals(
                           published[0].PageName,
                           edgeRestInfo.PageName,
                           StringComparison.Ordinal) &&
                       string.Equals(
                           published[0].Name,
                           edgeRestInfo.Name,
                           StringComparison.Ordinal) &&
                       published.All(descriptor =>
                           !string.Equals(
                               descriptor.Name,
                               GetSpriteFrameInfo(idleFrame).Name,
                               StringComparison.Ordinal) &&
                           !IsPillowVisibleWorkEnterFrame(descriptor.Name)),
                    $"{phaseName}/{edgeName} hot handoff may publish only the " +
                    "edge-rest descriptor—never idle or a pillow-return pose.");
                AssertRectClose(
                    (Rect)Invoke(window, "GetPetViewboxBoundsInScreenDips")!,
                    boundsBefore,
                    $"{phaseName}/{edgeName} hot handoff must preserve viewbox bounds");
                AssertClose(
                    window.Left,
                    leftBefore,
                    $"{phaseName}/{edgeName} hot handoff must preserve Left");
                AssertClose(
                    window.Top,
                    topBefore,
                    $"{phaseName}/{edgeName} hot handoff must preserve Top");
            }
        }

        var monitorType = typeof(MainWindow).Assembly.GetType(
            "LubanDesktopPet.MonitorWorkArea",
            throwOnError: true)!;
        var petSizeViewbox = GetField<Viewbox>(window, "PetSizeViewbox");
        foreach (var releaseKind in new[] { "Top", "Center" })
        {
            var fixture = ArrangeDirectWorkEdgePhase(window, "Typing");
            var workArea = (Rect)InvokeStatic(
                monitorType,
                "GetForVisual",
                window,
                petSizeViewbox)!;
            var visibleBounds = (Rect)Invoke(
                window,
                "GetPetViewboxBoundsInScreenDips")!;
            var contactBounds = (Rect)Invoke(
                window,
                "GetPetContactBounds",
                visibleBounds)!;
            var centerLeft = workArea.Left +
                             Math.Max(24, (workArea.Width - visibleBounds.Width) / 2);
            var centerTop = workArea.Top +
                            Math.Max(24, (workArea.Height - visibleBounds.Height) / 2);
            window.Left += centerLeft - visibleBounds.Left;
            window.Top += centerTop - visibleBounds.Top;
            window.UpdateLayout();
            if (releaseKind == "Top")
            {
                visibleBounds = (Rect)Invoke(
                    window,
                    "GetPetViewboxBoundsInScreenDips")!;
                contactBounds = (Rect)Invoke(
                    window,
                    "GetPetContactBounds",
                    visibleBounds)!;
                window.Top += workArea.Top - contactBounds.Top;
                window.UpdateLayout();
            }

            SetField(window, "_dragPreservesWorkMode", true);
            SetField(window, "_edgeDockDragContext", null);
            Invoke(window, "UpdateEdgeDockAfterDrag");
            Assert(string.Equals(
                       GetRawField(window, "_workState")?.ToString(),
                       "Typing",
                       StringComparison.Ordinal) &&
                   ReferenceEquals(
                       GetRawField(window, "_activeClip"),
                       fixture.Clip) &&
                   Equals(
                       GetRawField(window, "_currentSpriteFrame"),
                       fixture.DisplayedFrame) &&
                   string.Equals(
                       GetRawField(window, "_workEdgeDock")?.ToString(),
                       "None",
                       StringComparison.Ordinal) &&
                   string.Equals(
                       GetRawField(window, "_edgeDock")?.ToString(),
                       "None",
                       StringComparison.Ordinal),
                $"{releaseKind} release must keep the existing work pose and " +
                "must not start an unsupported edge handoff.");
            SetField(window, "_dragPreservesWorkMode", false);
        }

        PrepareWorkModeIdleState(window);
    }

    private static void AssertWorkEdgeColdHandoffContract(MainWindow window)
    {
        var idleSourceBytes = File.ReadAllBytes(
            FindWorkspaceFile("Assets", "luban-idle.png"));
        var workEnter001Bytes = File.ReadAllBytes(
            FindWorkspaceFile("Assets", "luban-work-enter-001.png"));
        var idleSourceDigest = Convert.ToHexString(
            System.Security.Cryptography.SHA256.HashData(idleSourceBytes));
        var workEnter001Digest = Convert.ToHexString(
            System.Security.Cryptography.SHA256.HashData(workEnter001Bytes));
        Assert(idleSourceBytes.AsSpan().SequenceEqual(workEnter001Bytes) &&
               string.Equals(
                   idleSourceDigest,
                   workEnter001Digest,
                   StringComparison.Ordinal),
            "The regression fixture must prove why descriptor-only checks are " +
            "insufficient: work-enter-001 is byte-for-byte the idle PNG.");

        var phaseNames = new[]
        {
            "Entering",
            "Typing",
            "SeriousEnter",
            "SeriousLoop",
            "SeriousExit",
            "Exiting"
        };
        var idleFrame = GetField<object>(window, "_idleFrame");
        var idleRuntimeDigest =
            GetRuntimeDecodedWorkFramePixelDigest(window, idleFrame);

        foreach (var edgeName in new[] { "Left", "Right", "Bottom" })
        {
            foreach (var phaseName in phaseNames)
            {
                var fixture = ArrangeDirectWorkEdgePhase(window, phaseName);
                var releaseDigest = GetCurrentDisplayPixelDigest(window);
                Assert(!string.Equals(
                           releaseDigest,
                           idleRuntimeDigest,
                           StringComparison.Ordinal) &&
                       !IsPillowVisibleWorkEnterFrame(
                           GetSpriteFrameInfo(fixture.DisplayedFrame).Name),
                    $"{phaseName}/{edgeName} cold fixture must release from a " +
                    "real work frame rather than idle/pillow pixels.");

                var edgeFrames = GetEdgeFramesForTest(window, edgeName);
                var edgeRestFrame = edgeFrames.GetValue(edgeFrames.Length - 1)!;
                var edgeRestInfo = GetSpriteFrameInfo(edgeRestFrame);
                EvictResidentSpritePageForTest(
                    window,
                    edgeRestInfo.PageName);
                Assert(!GetField<IDictionary>(window, "_residentSpritePages")
                           .Contains(edgeRestInfo.PageName),
                    $"{phaseName}/{edgeName} target page must be genuinely cold.");

                var activeClipBefore = GetRawField(window, "_activeClip");
                var activeFrameIndexBefore =
                    GetField<int>(window, "_activeFrameIndex");
                var activeClipStartedBefore =
                    GetField<long>(window, "_activeClipStartedTimestamp");
                var activeFrameDeadlineBefore =
                    GetField<long>(window, "_activeFrameDeadlineTimestamp");
                var loopAnchorBefore =
                    GetField<long>(window, "_workLoopAnchorTimestamp");
                var loopPositionBefore =
                    GetField<double>(window, "_workLoopAnchorFramePosition");
                var playbackRateBefore =
                    GetField<double>(window, "_workLoopPlaybackRate");
                var boundsBefore = (Rect)Invoke(
                    window,
                    "GetPetViewboxBoundsInScreenDips")!;
                var leftBefore = window.Left;
                var topBefore = window.Top;
                var published = new List<(string PageName, string Name)>();
                Action<string, string, int, int, int, int> observe =
                    (pageName, name, _, _, _, _) =>
                        published.Add((pageName, name));
                SetField(
                    window,
                    "_spriteFrameDescriptorPublishedForTesting",
                    observe);
                try
                {
                    // Defer the request exactly as production Rendering does so
                    // no background decode can win the cold-state assertions.
                    SetField(window, "_isInsideVisualRenderingCallback", true);
                    try
                    {
                        Invoke(
                            window,
                            "StartWorkEdgeHandoff",
                            GetNestedEnum("EdgeDock", edgeName));
                    }
                    finally
                    {
                        SetField(
                            window,
                            "_isInsideVisualRenderingCallback",
                            false);
                        GetField<DispatcherTimer>(
                            window,
                            "_spritePagePrefetchDispatchTimer").Stop();
                    }

                    Assert(string.Equals(
                               GetRawField(window, "_workEdgeDock")?.ToString(),
                               edgeName,
                               StringComparison.Ordinal) &&
                           GetField<long>(
                               window,
                               "_workEdgeHandoffFrozenTimestamp") > 0 &&
                           string.Equals(
                               GetRawField(window, "_edgeDock")?.ToString(),
                               "None",
                               StringComparison.Ordinal) &&
                           ReferenceEquals(
                               GetRawField(window, "_activeClip"),
                               activeClipBefore) &&
                           GetField<int>(window, "_activeFrameIndex") ==
                               activeFrameIndexBefore &&
                           Equals(
                               GetRawField(window, "_currentSpriteFrame"),
                               fixture.DisplayedFrame) &&
                           published.Count == 0,
                        $"{phaseName}/{edgeName} cold release must freeze the " +
                        "current work descriptor and publish nothing.");

                    Invoke(window, "VisualClock_Rendering", null, EventArgs.Empty);
                    GetField<DispatcherTimer>(
                        window,
                        "_spritePagePrefetchDispatchTimer").Stop();
                    Assert(ReferenceEquals(
                               GetRawField(window, "_activeClip"),
                               activeClipBefore) &&
                           GetField<int>(window, "_activeFrameIndex") ==
                               activeFrameIndexBefore &&
                           GetField<long>(
                               window,
                               "_activeClipStartedTimestamp") ==
                               activeClipStartedBefore &&
                           GetField<long>(
                               window,
                               "_activeFrameDeadlineTimestamp") ==
                               activeFrameDeadlineBefore &&
                           GetField<long>(
                               window,
                               "_workLoopAnchorTimestamp") ==
                               loopAnchorBefore &&
                           Math.Abs(
                               GetField<double>(
                                   window,
                                   "_workLoopAnchorFramePosition") -
                               loopPositionBefore) <= 0.000001 &&
                           Math.Abs(
                               GetField<double>(
                                   window,
                                   "_workLoopPlaybackRate") -
                               playbackRateBefore) <= 0.000001 &&
                           Equals(
                               GetRawField(window, "_currentSpriteFrame"),
                               fixture.DisplayedFrame) &&
                           string.Equals(
                               GetCurrentDisplayPixelDigest(window),
                               releaseDigest,
                               StringComparison.Ordinal) &&
                           published.Count == 0 &&
                           GetField<bool>(window, "_isVisualClockSubscribed"),
                        $"{phaseName}/{edgeName} cold Rendering must keep both " +
                        "the visible work pixels and every absolute-clock anchor frozen.");

                    SetField(window, "_renderDeferredSpritePageName", null);
                    SetField(window, "_renderDeferredSpritePageUrgent", false);
                    PrimeSpritePageForFrame(window, edgeRestFrame);
                    Assert((bool)Invoke(
                               window,
                               "TryCompletePendingWorkEdgeHandoff")!,
                        $"{phaseName}/{edgeName} must complete once its page is resident.");
                    Assert(string.Equals(
                               GetRawField(window, "_workState")?.ToString(),
                               "Idle",
                               StringComparison.Ordinal) &&
                           string.Equals(
                               GetRawField(window, "_edgeDock")?.ToString(),
                               edgeName,
                               StringComparison.Ordinal) &&
                           string.Equals(
                               GetRawField(window, "_workEdgeDock")?.ToString(),
                               "None",
                               StringComparison.Ordinal) &&
                           GetRawField(window, "_activeClip") is null &&
                           Equals(
                               GetRawField(window, "_currentSpriteFrame"),
                               edgeRestFrame),
                        $"{phaseName}/{edgeName} resident retry must atomically " +
                        "finish in the real edge-rest state.");
                    Assert(published.Count == 1 &&
                           string.Equals(
                               published[0].PageName,
                               edgeRestInfo.PageName,
                               StringComparison.Ordinal) &&
                           string.Equals(
                               published[0].Name,
                               edgeRestInfo.Name,
                               StringComparison.Ordinal) &&
                           published.All(descriptor =>
                               !string.Equals(
                                   descriptor.Name,
                                   GetSpriteFrameInfo(idleFrame).Name,
                                   StringComparison.Ordinal) &&
                               !IsPillowVisibleWorkEnterFrame(descriptor.Name)),
                        $"{phaseName}/{edgeName} cold handoff may publish only " +
                        "edge rest after the page becomes resident.");
                    AssertRectClose(
                        (Rect)Invoke(window, "GetPetViewboxBoundsInScreenDips")!,
                        boundsBefore,
                        $"{phaseName}/{edgeName} cold handoff must preserve viewbox bounds");
                    AssertClose(
                        window.Left,
                        leftBefore,
                        $"{phaseName}/{edgeName} cold handoff must preserve Left");
                    AssertClose(
                        window.Top,
                        topBefore,
                        $"{phaseName}/{edgeName} cold handoff must preserve Top");
                }
                finally
                {
                    SetField(
                        window,
                        "_spriteFrameDescriptorPublishedForTesting",
                        null);
                    SetField(window, "_renderDeferredSpritePageName", null);
                    SetField(window, "_renderDeferredSpritePageUrgent", false);
                    GetField<DispatcherTimer>(
                        window,
                        "_spritePagePrefetchDispatchTimer").Stop();
                }
            }
        }

        foreach (var edgeName in new[] { "Left", "Right", "Bottom" })
        {
            var fixture = ArrangeDirectWorkEdgePhase(window, "Typing");
            var edgeFrames = GetEdgeFramesForTest(window, edgeName);
            var edgeRestFrame = edgeFrames.GetValue(edgeFrames.Length - 1)!;
            var edgeRestPageName = GetSpriteFrameInfo(edgeRestFrame).PageName;
            EvictResidentSpritePageForTest(window, edgeRestPageName);
            SetField(window, "_failedSpritePageName", edgeRestPageName);
            var published = new List<(string PageName, string Name)>();
            Action<string, string, int, int, int, int> observe =
                (pageName, name, _, _, _, _) =>
                    published.Add((pageName, name));
            SetField(
                window,
                "_spriteFrameDescriptorPublishedForTesting",
                observe);
            try
            {
                SetField(window, "_isInsideVisualRenderingCallback", true);
                try
                {
                    Invoke(
                        window,
                        "StartWorkEdgeHandoff",
                        GetNestedEnum("EdgeDock", edgeName));
                }
                finally
                {
                    SetField(
                        window,
                        "_isInsideVisualRenderingCallback",
                        false);
                }

                Assert(string.Equals(
                           GetRawField(window, "_workState")?.ToString(),
                           "Idle",
                           StringComparison.Ordinal) &&
                       string.Equals(
                           GetRawField(window, "_workEdgeDock")?.ToString(),
                           "None",
                           StringComparison.Ordinal) &&
                       GetField<long>(
                           window,
                           "_workEdgeHandoffFrozenTimestamp") == 0 &&
                       GetRawField(window, "_activeClip") is null &&
                       Equals(
                           GetRawField(window, "_currentSpriteFrame"),
                           idleFrame) &&
                       string.Equals(
                           GetCurrentDisplayPixelDigest(window),
                           idleRuntimeDigest,
                           StringComparison.Ordinal),
                    $"{edgeName} corrupt edge page must fail closed to idle " +
                    "instead of freezing work or losing Rendering forever.");
                Assert(published.Count == 1 &&
                       string.Equals(
                           published[0].Name,
                           GetSpriteFrameInfo(idleFrame).Name,
                           StringComparison.Ordinal),
                    $"{edgeName} failure is the only path allowed to publish " +
                    "one safe idle descriptor.");
            }
            finally
            {
                SetField(
                    window,
                    "_spriteFrameDescriptorPublishedForTesting",
                    null);
                SetField(window, "_failedSpritePageName", null);
                SetField(window, "_renderDeferredSpritePageName", null);
                SetField(window, "_renderDeferredSpritePageUrgent", false);
                GetField<DispatcherTimer>(
                    window,
                    "_spritePagePrefetchDispatchTimer").Stop();
            }
        }

        PrepareWorkModeIdleState(window);
    }

    private static (object Clip, object DisplayedFrame)
        ArrangeDirectWorkEdgePhase(MainWindow window, string phaseName)
    {
        PrepareWorkModeIdleState(window);
        var (clipField, stateName) = phaseName switch
        {
            "Entering" => ("_workEnterClip", "Entering"),
            "Typing" => ("_workLoopClip", "Typing"),
            "SeriousEnter" => ("_workSeriousEnterClip", "Typing"),
            "SeriousLoop" => ("_workSeriousLoopClip", "Typing"),
            "SeriousExit" => ("_workSeriousExitClip", "Typing"),
            "Exiting" => ("_workExitClip", "Exiting"),
            _ => throw new ArgumentOutOfRangeException(nameof(phaseName))
        };
        var clip = GetField<object>(window, clipField);
        var frames = GetClipFrames(clip);
        var frameIndex = phaseName switch
        {
            "Entering" => frames.Length - 1,
            "Typing" => Math.Min(10, frames.Length - 1),
            "SeriousEnter" => frames.Length / 2,
            "SeriousLoop" => Math.Min(10, frames.Length - 1),
            "SeriousExit" => frames.Length / 2,
            "Exiting" => 0,
            _ => 0
        };
        var displayedFrame = GetProperty<object>(
            frames.GetValue(frameIndex)!,
            "Image");
        PrimeSpritePageForFrame(window, displayedFrame);

        var timestamp = Math.Max(1L, Stopwatch.GetTimestamp());
        SetField(window, "_workState", GetNestedEnum("WorkState", stateName));
        SetField(window, "_activeClip", clip);
        SetField(window, "_activeFrameIndex", frameIndex);
        SetField(window, "_activeClipStartedTimestamp", timestamp);
        SetField(
            window,
            "_activeFrameDeadlineTimestamp",
            phaseName is "Typing" or "SeriousLoop"
                ? long.MaxValue
                : checked(timestamp + Stopwatch.Frequency));
        SetField(window, "_workExitRequested", false);
        SetField(window, "_workSeriousEnterRequested", false);
        SetField(window, "_workSeriousExitRequested", false);
        SetField(window, "_workExitTargetFramePosition", double.PositiveInfinity);
        SetField(
            window,
            "_workSeriousEnterTargetFramePosition",
            double.PositiveInfinity);
        SetField(
            window,
            "_workSeriousExitTargetFramePosition",
            double.PositiveInfinity);
        SetField(window, "_workLoopAnchorTimestamp", timestamp);
        SetField(window, "_workLoopAnchorFramePosition", (double)frameIndex);
        SetField(window, "_workLoopPlaybackRate", 1d);
        SetField(window, "_workFastUntilTimestamp", 0L);
        SetField(window, "_workEdgeDock", GetNestedEnum("EdgeDock", "None"));
        SetField(window, "_workEdgeHandoffFrozenTimestamp", 0L);
        Invoke(window, "ClearDeferredActiveClipClock");
        SetField(window, "_nextFrameBlendDuration", TimeSpan.Zero);
        Invoke(window, "ShowStableFrame", displayedFrame);
        Invoke(window, "RefreshWorkModeButton");
        Assert(Equals(
                   GetRawField(window, "_currentSpriteFrame"),
                   displayedFrame),
            $"{phaseName} fixture must visibly publish its selected work pose.");
        return (clip, displayedFrame);
    }

    private static Array GetEdgeFramesForTest(
        MainWindow window,
        string edgeName) =>
        edgeName is "Left" or "Right"
            ? GetField<Array>(window, "_edgeLeftFrames")
            : edgeName == "Bottom"
                ? GetField<Array>(window, "_edgeBottomFrames")
                : throw new ArgumentOutOfRangeException(nameof(edgeName));

    private static bool IsPillowVisibleWorkEnterFrame(string frameName)
    {
        const string prefix = "Assets/luban-work-enter-";
        if (!frameName.StartsWith(prefix, StringComparison.Ordinal) ||
            frameName.Length < prefix.Length + 3)
        {
            return false;
        }

        return int.TryParse(
                   frameName.AsSpan(prefix.Length, 3),
                   NumberStyles.None,
                   CultureInfo.InvariantCulture,
                   out var frameNumber) &&
               frameNumber is >= 1 and <= 24;
    }

    private static string GetCurrentDisplayPixelDigest(MainWindow window)
    {
        var bitmap = GetField<WriteableBitmap>(window, "_displayFrameBuffer");
        var stride = checked(bitmap.PixelWidth * 4);
        var pixels = new byte[checked(stride * bitmap.PixelHeight)];
        bitmap.CopyPixels(pixels, stride, offset: 0);
        return Convert.ToHexString(
            System.Security.Cryptography.SHA256.HashData(pixels));
    }

    private static void AssertCompletedTodoMovesToEndContract(MainWindow window)
    {
        var tempDirectory = Path.Combine(
            Path.GetTempPath(),
            $"xlb-pet-todo-completed-order-{Guid.NewGuid():N}");
        var todoPath = Path.Combine(tempDirectory, "todos.json");
        var todoStore = new TodoStore(todoPath);
        var originalTodoStore = GetField<TodoStore>(window, "_todoStore");
        var todos = GetField<ObservableCollection<TodoItem>>(window, "_todos");
        var originalTodos = todos.ToArray();
        SetField(window, "_todoStore", todoStore);

        try
        {
            todos.Clear();
            var first = new TodoItem { Text = "第一项" };
            var second = new TodoItem { Text = "第二项" };
            var third = new TodoItem { Text = "第三项" };
            var fourth = new TodoItem { Text = "第四项" };
            todos.Add(first);
            todos.Add(second);
            todos.Add(third);
            todos.Add(fourth);
            var todoWindow = GetField<TodoWindow>(window, "_todoWindow");

            var moveNotifications = 0;
            NotifyCollectionChangedEventHandler collectionChanged = (_, eventArgs) =>
            {
                if (eventArgs.Action == NotifyCollectionChangedAction.Move)
                {
                    moveNotifications++;
                }
            };
            todos.CollectionChanged += collectionChanged;
            try
            {
                var secondCheckBox = new CheckBox
                {
                    DataContext = second,
                    IsChecked = true
                };
                Invoke(
                    todoWindow,
                    "TodoCheckBox_Click",
                    secondCheckBox,
                    new RoutedEventArgs(ButtonBase.ClickEvent));
                Assert(todos.SequenceEqual(new[] { first, third, fourth, second }) &&
                       second.IsCompleted &&
                       moveNotifications == 1,
                    "真实勾选事件完成中间待办后必须只移动当前项到最后，" +
                    "其他项相对顺序保持不变");

                var persistedAfterFirstCompletion = todoStore.Load();
                Assert(persistedAfterFirstCompletion.Select(item => item.Text)
                           .SequenceEqual(new[] { "第一项", "第三项", "第四项", "第二项" }) &&
                       persistedAfterFirstCompletion[^1].IsCompleted,
                    "完成项自动移动后的最终顺序和完成状态必须立即持久化");

                third.IsCompleted = true;
                Invoke(window, "TodoWindow_TodoChanged", third);
                Assert(todos.SequenceEqual(new[] { first, fourth, second, third }) &&
                       moveNotifications == 2,
                    "连续勾选时，新完成项必须追加到最底部，并保留先前完成项顺序");

                var notificationsBeforeNoOp = moveNotifications;
                third.Text = "已经在末尾的第三项";
                Invoke(window, "TodoWindow_TodoChanged", third);
                Assert(todos.SequenceEqual(new[] { first, fourth, second, third }) &&
                       moveNotifications == notificationsBeforeNoOp,
                    "完成项已经位于最后时不得产生无意义的二次 Move");

                var persistedAfterNoOp = todoStore.Load();
                Assert(persistedAfterNoOp[^1].Text == "已经在末尾的第三项" &&
                       persistedAfterNoOp[^1].IsCompleted,
                    "末项无需移动时仍必须保存最新状态");

                second.IsCompleted = false;
                Invoke(window, "TodoWindow_TodoChanged", second);
                Assert(todos.SequenceEqual(new[] { first, fourth, second, third }) &&
                       moveNotifications == notificationsBeforeNoOp,
                    "取消完成只更新状态，不应覆盖用户当前的手动排序");

                var persistedAfterReopen = todoStore.Load();
                Assert(!persistedAfterReopen[2].IsCompleted &&
                       persistedAfterReopen[3].IsCompleted,
                    "取消完成后必须保留当前顺序并立即保存未完成状态");
            }
            finally
            {
                todos.CollectionChanged -= collectionChanged;
            }
        }
        finally
        {
            SetField(window, "_todoStore", originalTodoStore);
            todos.Clear();
            foreach (var item in originalTodos)
            {
                todos.Add(item);
            }

            try
            {
                Directory.Delete(tempDirectory, recursive: true);
            }
            catch
            {
                // 临时持久化文件清理失败不应掩盖完成项排序契约结果。
            }
        }
    }

    private static void AssertWorkModeRuntimeStateContract(MainWindow window)
    {
        PrepareWorkModeIdleState(window);
        var button = GetField<Button>(window, "WorkModeButton");
        var idleFrame = GetField<object>(window, "_idleFrame");
        var todoFrame = GetField<object>(window, "_todoFrame");
        var noneBubble = GetNestedEnum("BubbleMode", "None");
        var cuteBubble = GetNestedEnum("BubbleMode", "Cute");
        var noDock = GetNestedEnum("EdgeDock", "None");
        var leftDock = GetNestedEnum("EdgeDock", "Left");

        Assert((bool)Invoke(window, "CanEnterWorkMode")! &&
               button.IsEnabled && button.IsHitTestVisible &&
               button.Visibility == Visibility.Visible &&
               button.Opacity > 0.99 &&
               string.Equals(button.Tag as string, "Idle", StringComparison.Ordinal) &&
               button.Content is null &&
               string.Equals(
                   AutomationProperties.GetName(button),
                   "去打工",
                   StringComparison.Ordinal),
            "A fully settled idle pose must expose the enabled sun icon.");

        var facingScale = GetField<ScaleTransform>(window, "PetFacingScale");
        var iconFacingCompensation = GetField<ScaleTransform>(
            window,
            "WorkModeFacingCompensation");
        facingScale.ScaleX = -1;
        Invoke(window, "RefreshWorkModeButton");
        Assert(button.HorizontalAlignment == HorizontalAlignment.Right &&
               Math.Abs(iconFacingCompensation.ScaleX + 1d) <= 0.000001,
            "人物水平镜像时图标布局必须换到父画布右侧并反向补偿，" +
            "最终仍固定在屏幕视觉左上角且太阳脸不倒转");
        facingScale.ScaleX = 1;
        Invoke(window, "RefreshWorkModeButton");
        Assert(button.HorizontalAlignment == HorizontalAlignment.Left &&
               Math.Abs(iconFacingCompensation.ScaleX - 1d) <= 0.000001,
            "人物恢复正向后太阳必须回到画布左侧并清除镜像补偿");

        AssertIdleWorkModeButtonFollowsDrag(window);

        SetField(window, "_isReminderActive", true);
        Assert(!(bool)Invoke(window, "CanEnterWorkMode")!,
            "An active reminder must block work entry.");
        SetField(window, "_isReminderActive", false);
        SetField(window, "_dragInteractionActive", true);
        Assert(!(bool)Invoke(window, "CanEnterWorkMode")!,
            "A drag gesture must block work entry.");
        SetField(window, "_dragInteractionActive", false);
        SetField(window, "_isPetSizeTransitioning", true);
        Assert(!(bool)Invoke(window, "CanEnterWorkMode")!,
            "A pet-size transition must block work entry.");
        SetField(window, "_isPetSizeTransitioning", false);
        SetField(window, "_bubbleMode", cuteBubble);
        Assert(!(bool)Invoke(window, "CanEnterWorkMode")!,
            "Any open pet bubble must block work entry.");
        SetField(window, "_bubbleMode", noneBubble);
        SetField(window, "_edgeDock", leftDock);
        Assert(!(bool)Invoke(window, "CanEnterWorkMode")!,
            "An edge-docked pet must block work entry.");
        SetField(window, "_edgeDock", noDock);
        SetField(window, "_currentSpriteFrame", todoFrame);
        Assert(!(bool)Invoke(window, "CanEnterWorkMode")!,
            "A non-idle character pose must block work entry.");
        Invoke(window, "ShowStableFrame", idleFrame);
        Invoke(window, "RefreshWorkModeButton");

        Invoke(window, "StartPillowBreathing");
        Assert((bool)Invoke(window, "TryEnterWorkMode")!,
            "A fully idle pet must enter work mode.");
        Assert(string.Equals(
                   GetRawField(window, "_workState")?.ToString(),
                   "Entering",
                   StringComparison.Ordinal) &&
               ReferenceEquals(
                   GetRawField(window, "_activeClip"),
                   GetField<object>(window, "_workEnterClip")) &&
               !GetField<bool>(window, "_isPillowBreathing") &&
               !GetField<bool>(window, "_isSnoreBubbleAnimating") &&
               !GetField<DispatcherTimer>(window, "_automaticTimer").IsEnabled &&
               string.Equals(button.Tag as string, "Working", StringComparison.Ordinal) &&
               button.Content is null &&
               string.Equals(
                   AutomationProperties.GetName(button),
                   "去睡觉",
                   StringComparison.Ordinal),
            "Entering work must atomically stop idle breathing, snore, and automatic activity: " +
            $"state={GetRawField(window, "_workState")}, " +
            $"clip={GetProperty<string>(GetField<object>(window, "_activeClip"), "ActionName")}, " +
            $"pillow={GetField<bool>(window, "_isPillowBreathing")}, " +
            $"snore={GetField<bool>(window, "_isSnoreBubbleAnimating")}, " +
            $"timer={GetField<DispatcherTimer>(window, "_automaticTimer").IsEnabled}, " +
            $"button={button.Tag}");
        Assert(!(bool)Invoke(window, "StartEdgeRoaming")! &&
               !(bool)Invoke(
                   window,
                   "TryStartReaction",
                   GetField<Array>(window, "_reactionClips").GetValue(0)!,
                   false)!,
            "Work state must reject both edge roaming and random/click reaction clips.");

        var enterClip = GetField<object>(window, "_workEnterClip");
        var loopClip = GetField<object>(window, "_workLoopClip");
        Invoke(window, "CompleteActiveClipAt", enterClip, Stopwatch.GetTimestamp());
        Assert(string.Equals(
                   GetRawField(window, "_workState")?.ToString(),
                   "Typing",
                   StringComparison.Ordinal) &&
               ReferenceEquals(GetRawField(window, "_activeClip"), loopClip),
            "The 48-frame enter clip must lead into the 96-frame typing loop.");

        var clipBeforeSingleClick = GetRawField(window, "_activeClip");
        var frameBeforeSingleClick = GetField<int>(window, "_activeFrameIndex");
        Invoke(window, "HandleWorkPetClick", 1);
        Assert(ReferenceEquals(
                   GetRawField(window, "_activeClip"),
                   clipBeforeSingleClick) &&
               GetField<int>(window, "_activeFrameIndex") == frameBeforeSingleClick,
            "A single click must not change the active work clip or visible pose.");
        var rightClickArgs = new MouseButtonEventArgs(
            Mouse.PrimaryDevice,
            Environment.TickCount,
            MouseButton.Right)
        {
            RoutedEvent = UIElement.MouseRightButtonUpEvent,
            Source = GetField<Grid>(window, "PetHost")
        };
        Invoke(
            window,
            "PetHost_MouseRightButtonUp",
            GetField<Grid>(window, "PetHost"),
            rightClickArgs);
        var todoWindow = GetField<TodoWindow>(window, "_todoWindow");
        var stateAfterRightClick =
            GetRawField(window, "_workState")?.ToString();
        Assert(GetField<bool>(window, "_openTodoAfterWorkExitRequested") &&
               !todoWindow.IsVisible &&
               button.Visibility == Visibility.Collapsed &&
               button.Opacity < 0.01 &&
               !button.IsHitTestVisible &&
               button.Content is null &&
               string.Equals(
                   AutomationProperties.GetName(button),
                   "去睡觉",
                   StringComparison.Ordinal) &&
               stateAfterRightClick is "Typing" or "Exiting",
            "Right-click must hide the moon control immediately, " +
            "and keep Todo hidden until work exit completes.");

        if (string.Equals(stateAfterRightClick, "Typing", StringComparison.Ordinal))
        {
            Invoke(window, "StartWorkExitClip");
        }
        var exitClip = GetField<object>(window, "_workExitClip");
        Assert(string.Equals(
                   GetRawField(window, "_workState")?.ToString(),
                   "Exiting",
                   StringComparison.Ordinal) &&
               ReferenceEquals(GetRawField(window, "_activeClip"), exitClip),
            "Right-click work exit must play the authored reverse transition.");
        Invoke(window, "CompleteActiveClipAt", exitClip, Stopwatch.GetTimestamp());
        Assert(string.Equals(
                   GetRawField(window, "_workState")?.ToString(),
                   "Idle",
                   StringComparison.Ordinal) &&
               GetSpriteFrameInfo(GetField<object>(window, "_currentSpriteFrame")).Name ==
                   GetSpriteFrameInfo(idleFrame).Name &&
               !todoWindow.IsVisible &&
               button.Visibility == Visibility.Collapsed &&
               button.Opacity < 0.01 &&
               !button.IsHitTestVisible &&
               button.Content is null &&
               string.Equals(
                   AutomationProperties.GetName(button),
                   "去打工",
                   StringComparison.Ordinal),
            "Completing the reverse work transition must publish logical idle while " +
            "keeping the return-to-work control hidden until deferred Todo opens.");
        PumpDispatcher(TimeSpan.FromMilliseconds(80));
        Assert(todoWindow.IsVisible &&
               string.Equals(
                   GetRawField(window, "_bubbleMode")?.ToString(),
                   "Todo",
                   StringComparison.Ordinal),
            "Todo must open on a later dispatcher turn after work has returned to idle.");

        PrepareWorkModeIdleState(window);
        EnterWorkTypingForTest(window);
        Invoke(window, "QueueSessionInactive");
        PumpDispatcher(TimeSpan.FromMilliseconds(50));
        Assert(string.Equals(
                   GetRawField(window, "_workState")?.ToString(),
                   "Idle",
                   StringComparison.Ordinal),
            "Session lock must restore idle immediately.");

        PrepareWorkModeIdleState(window);
    }

    private static void AssertIdleWorkModeButtonFollowsDrag(MainWindow window)
    {
        var button = GetField<Button>(window, "WorkModeButton");
        var petVisual = GetField<Grid>(window, "PetVisual");
        var facingScale = GetField<ScaleTransform>(window, "PetFacingScale");
        var noDock = GetNestedEnum("EdgeDock", "None");
        var leftDock = GetNestedEnum("EdgeDock", "Left");
        var monitorWorkAreaType = typeof(MainWindow).Assembly.GetType(
            "LubanDesktopPet.MonitorWorkArea",
            throwOnError: true)!;
        var originalLeft = window.Left;
        var originalTop = window.Top;
        var originalFacingScaleX = facingScale.ScaleX;

        try
        {
            var workArea = (Rect)InvokeStatic(
                monitorWorkAreaType,
                "GetForWindow",
                window)!;
            var windowWidth = window.ActualWidth > 0
                ? window.ActualWidth
                : window.Width;
            var windowHeight = window.ActualHeight > 0
                ? window.ActualHeight
                : window.Height;
            var firstLeft = workArea.Left +
                            Math.Max(0, workArea.Width - windowWidth) * 0.42;
            var firstTop = workArea.Top +
                           Math.Max(0, workArea.Height - windowHeight) * 0.42;
            var secondLeft = Math.Clamp(
                firstLeft + 47,
                workArea.Left,
                Math.Max(workArea.Left, workArea.Right - windowWidth));
            var secondTop = Math.Clamp(
                firstTop + 31,
                workArea.Top,
                Math.Max(workArea.Top, workArea.Bottom - windowHeight));

            foreach (var mirrored in new[] { false, true })
            {
                facingScale.ScaleX = mirrored ? -1d : 1d;
                SetField(window, "_edgeDock", noDock);
                SetField(window, "_dragInteractionActive", false);
                SetField(window, "_pointerDown", false);
                SetField(window, "_dragStarted", false);
                Invoke(window, "MoveMainWindowTo", firstLeft, firstTop);
                Invoke(window, "RefreshWorkModeButton");
                window.UpdateLayout();
                PumpDispatcher(TimeSpan.FromMilliseconds(30));

                var buttonBefore = GetVisualPhysicalBounds(button);
                var petBefore = GetVisualPhysicalBounds(petVisual);

                SetField(window, "_dragInteractionActive", true);
                SetField(window, "_pointerDown", true);
                SetField(window, "_dragStarted", true);
                Invoke(window, "RefreshWorkModeButton");
                window.UpdateLayout();

                Assert((bool)Invoke(
                           window,
                           "CanShowIdleWorkModeButton")! &&
                       !(bool)Invoke(window, "CanEnterWorkMode")! &&
                       button.Visibility == Visibility.Visible &&
                       button.Opacity > 0.99 &&
                       !button.IsEnabled &&
                       !button.IsHitTestVisible,
                    $"{(mirrored ? "镜像" : "正向")}待机拖动期间太阳必须持续可见，" +
                    "但在释放前不能响应点击");

                Invoke(window, "MoveMainWindowTo", secondLeft, secondTop);
                window.UpdateLayout();
                PumpDispatcher(TimeSpan.FromMilliseconds(30));

                var buttonAfter = GetVisualPhysicalBounds(button);
                var petAfter = GetVisualPhysicalBounds(petVisual);
                var buttonDelta = new Vector(
                    buttonAfter.Left - buttonBefore.Left,
                    buttonAfter.Top - buttonBefore.Top);
                var petDelta = new Vector(
                    petAfter.Left - petBefore.Left,
                    petAfter.Top - petBefore.Top);
                var relativeBefore = new Vector(
                    buttonBefore.Left - petBefore.Left,
                    buttonBefore.Top - petBefore.Top);
                var relativeAfter = new Vector(
                    buttonAfter.Left - petAfter.Left,
                    buttonAfter.Top - petAfter.Top);

                Assert(buttonDelta.Length > 4 &&
                       Math.Abs(buttonDelta.X - petDelta.X) <= 1.01 &&
                       Math.Abs(buttonDelta.Y - petDelta.Y) <= 1.01 &&
                       Math.Abs(relativeAfter.X - relativeBefore.X) <= 1.01 &&
                       Math.Abs(relativeAfter.Y - relativeBefore.Y) <= 1.01,
                    $"{(mirrored ? "镜像" : "正向")}待机拖动必须让太阳和人物共用真实 HWND 位移：" +
                    $"buttonDelta={buttonDelta}, petDelta={petDelta}, " +
                    $"relative={relativeBefore}/{relativeAfter}");

                SetField(window, "_edgeDock", leftDock);
                Invoke(window, "RefreshWorkModeButton");
                Assert(button.Visibility == Visibility.Collapsed &&
                       button.Opacity < 0.01 &&
                       !button.IsEnabled &&
                       !button.IsHitTestVisible,
                    "拖动释放到既有边缘吸附时，待机太阳仍必须隐藏");

                SetField(window, "_edgeDock", noDock);
                SetField(window, "_dragInteractionActive", false);
                SetField(window, "_pointerDown", false);
                SetField(window, "_dragStarted", false);
                Invoke(window, "RefreshWorkModeButton");
                Assert(button.Visibility == Visibility.Visible &&
                       button.Opacity > 0.99 &&
                       button.IsEnabled &&
                       button.IsHitTestVisible,
                    "普通位置释放后，待机太阳必须恢复可点击状态");
            }
        }
        finally
        {
            facingScale.ScaleX = originalFacingScaleX;
            SetField(window, "_edgeDock", noDock);
            SetField(window, "_dragInteractionActive", false);
            SetField(window, "_pointerDown", false);
            SetField(window, "_dragStarted", false);
            Invoke(window, "MoveMainWindowTo", originalLeft, originalTop);
            Invoke(window, "RefreshWorkModeButton");
            window.UpdateLayout();
            PumpDispatcher(TimeSpan.FromMilliseconds(20));
        }
    }

    private static void AssertWorkModeRegressionContract(MainWindow window)
    {
        const string removedPagePrefix = "work-" + "tap";
        const string removedFramePrefix = "Assets/luban-work-" + "tap-";
        var source = File.ReadAllText(FindWorkspaceFile("MainWindow.xaml.cs"));
        var handleWorkPetClick = ExtractPrivateMethodSource(
            source,
            "HandleWorkPetClick");
        var prefetchSeriousEntry = ExtractPrivateMethodSource(
            source,
            "PrefetchWorkSeriousEntryPage");
        var startFastTyping = ExtractPrivateMethodSource(
            source,
            "StartFastWorkTypingAt");
        var advanceWorkLoop = ExtractPrivateMethodSource(
            source,
            "AdvanceWorkLoop");
        var completeClip = ExtractPrivateMethodSource(
            source,
            "CompleteActiveClipAt");

        Assert(handleWorkPetClick.Contains(
                   "if (clickCount < 2)",
                   StringComparison.Ordinal) &&
               handleWorkPetClick.Contains(
                   "PrefetchWorkSeriousEntryPage()",
                   StringComparison.Ordinal) &&
               handleWorkPetClick.Contains(
                   "StartFastWorkTypingAt(Stopwatch.GetTimestamp())",
                   StringComparison.Ordinal) &&
               !handleWorkPetClick.Contains(
                   "_workLoopPlaybackRate =",
                   StringComparison.Ordinal) &&
               !handleWorkPetClick.Contains(
                   "ShowStableFrame",
                   StringComparison.Ordinal),
            "Single click must only prefetch and return; double click must dispatch " +
            "the immediate fast-typing path in the same input turn.");
        Assert(prefetchSeriousEntry.Contains(
                   "_workSeriousEnterClip.Frames[0].Image.PageName",
                   StringComparison.Ordinal) &&
               prefetchSeriousEntry.Contains(
                   "_spritePagePrefetchTask is not null",
                   StringComparison.Ordinal) &&
               prefetchSeriousEntry.Contains(
                   "_desiredSpritePageName is not null",
                   StringComparison.Ordinal) &&
               prefetchSeriousEntry.Contains(
                   "urgent: false",
                   StringComparison.Ordinal) &&
               !prefetchSeriousEntry.Contains(
                   "urgent: true",
                   StringComparison.Ordinal) &&
               startFastTyping.Contains(
                   "_workLoopPlaybackRate = WorkFastPlaybackMultiplier",
                   StringComparison.Ordinal) &&
               startFastTyping.Contains(
                   "GetNextWorkNeutralMicroSeamFramePosition(framePosition)",
                   StringComparison.Ordinal) &&
               startFastTyping.Contains(
                   "_workSeriousEnterRequested = true",
                   StringComparison.Ordinal) &&
               advanceWorkLoop.Contains(
                   "StartWorkSeriousEnterClip(timestamp)",
                   StringComparison.Ordinal),
            "Double click must switch to 2x immediately, then enter the serious " +
            "expression at the selected neutral seam.");
        Assert(completeClip.Contains(
                   "ReferenceEquals(clip, _workSeriousEnterClip)",
                   StringComparison.Ordinal) &&
               completeClip.Contains(
                   "StartSeriousWorkLoopAt(timestamp)",
                   StringComparison.Ordinal) &&
               !source.Contains("WorkTap", StringComparison.Ordinal) &&
               !source.Contains("WorkSingleClick", StringComparison.Ordinal) &&
               !source.Contains(removedFramePrefix, StringComparison.Ordinal),
            "Runtime source must contain only enter/loop/serious-loop/serious-exit " +
            "work phases and no delayed single-click or tap branch.");

        var workFields = typeof(MainWindow)
            .GetFields(InstanceFlags | StaticFlags)
            .Select(field => field.Name)
            .ToArray();
        var workMethods = typeof(MainWindow)
            .GetMethods(InstanceFlags | StaticFlags)
            .Select(method => method.Name)
            .ToArray();
        Assert(!workFields.Any(name =>
                   name.Contains("WorkTap", StringComparison.OrdinalIgnoreCase) ||
                   name.Contains("SingleClick", StringComparison.OrdinalIgnoreCase)) &&
               !workMethods.Any(name =>
                   name.Contains("WorkTap", StringComparison.OrdinalIgnoreCase) ||
                   name.Contains("SingleClick", StringComparison.OrdinalIgnoreCase)),
            "Compiled MainWindow metadata must not retain tap clips or single-click timers.");

        using var manifest = JsonDocument.Parse(File.ReadAllText(
            FindWorkspaceFile("Assets", "luban-sprite-pages.json")));
        var manifestRoot = manifest.RootElement;
        var pages = manifestRoot.GetProperty("pages");
        var pageProperties = pages.EnumerateObject().ToArray();
        var pageNames = pageProperties.Select(page => page.Name).ToArray();
        var expectedWorkPages = new[]
        {
            "work-enter",
            "work-enter-part-02",
            "work-loop",
            "work-loop-part-02",
            "work-loop-part-03",
            "work-serious-loop",
            "work-serious-loop-part-02",
            "work-serious-loop-part-03",
            "work-serious-exit"
        };
        var actualWorkPages = pageNames
            .Where(name => name.StartsWith("work-", StringComparison.Ordinal))
            .ToArray();
        var manifestFrameNames = pageProperties
            .SelectMany(page =>
                page.Value.GetProperty("frames").EnumerateObject())
            .Select(frame => frame.Name)
            .ToArray();
        var workFrameNames = pageProperties
            .Where(page => page.Name.StartsWith("work-", StringComparison.Ordinal))
            .SelectMany(page =>
                page.Value.GetProperty("frames").EnumerateObject())
            .Select(frame => frame.Name)
            .ToArray();
        var expectedWorkPhaseCounts = new Dictionary<string, int>
        {
            ["Assets/luban-work-enter-"] = 48,
            ["Assets/luban-work-loop-"] = 96,
            ["Assets/luban-work-serious-loop-"] = 96,
            ["Assets/luban-work-serious-exit-"] = 24
        };
        Assert(actualWorkPages.SequenceEqual(expectedWorkPages) &&
               actualWorkPages.Length == 9 &&
               workFrameNames.Length == 264 &&
               workFrameNames.Distinct(StringComparer.Ordinal).Count() == 264 &&
               expectedWorkPhaseCounts.All(expected =>
                   workFrameNames.Count(name => name.StartsWith(
                       expected.Key,
                       StringComparison.Ordinal)) == expected.Value) &&
               !pageNames.Any(name =>
                   name.StartsWith(removedPagePrefix, StringComparison.Ordinal)) &&
               !manifestFrameNames.Any(name =>
                   name.StartsWith(removedFramePrefix, StringComparison.Ordinal)),
            "The work atlas contract must contain exactly 264 frames across nine " +
            "enter/loop/serious-loop/serious-exit pages and no tap page/frame, " +
            "without pinning unrelated global atlas totals.");

        var runtimePageNames = GetField<IDictionary>(window, "_spritePages")
            .Keys.Cast<object>()
            .Select(key => key.ToString() ?? string.Empty)
            .ToArray();
        Assert(!runtimePageNames.Any(name =>
                   name.StartsWith(removedPagePrefix, StringComparison.Ordinal)),
            "Runtime sprite-page dictionary must not expose a tap page.");

        var assembly = typeof(MainWindow).Assembly;
        var generatedResourceName = assembly.GetManifestResourceNames()
            .Single(name => name.EndsWith(
                ".g.resources",
                StringComparison.OrdinalIgnoreCase));
        using var resourceStream = assembly.GetManifestResourceStream(
            generatedResourceName)
            ?? throw new InvalidOperationException("Missing WPF generated resource stream.");
        using var resourceReader = new ResourceReader(resourceStream);
        var resourceEnumerator = resourceReader.GetEnumerator();
        var embeddedTapResource = false;
        while (resourceEnumerator.MoveNext())
        {
            if (resourceEnumerator.Key is string key &&
                key.Contains(removedPagePrefix, StringComparison.OrdinalIgnoreCase))
            {
                embeddedTapResource = true;
                break;
            }
        }
        Assert(!embeddedTapResource,
            "Compiled MainWindow assembly resources must not contain a work-tap page.");

        // Frame 094 lives near the end of the third serious-loop page. Starting
        // there must keep that visible pose while asynchronously warming frame
        // 001's page for the wrap; the loop may not stall or flash at the seam.
        PrepareWorkModeIdleState(window);
        EnterWorkTypingForTest(window);
        var seriousLoopFrames = GetField<Array>(window, "_workSeriousLoopFrames");
        var seriousLoopClip = GetField<object>(window, "_workSeriousLoopClip");
        var frame094 = seriousLoopFrames.GetValue(93)!;
        var wrapFrame001 = seriousLoopFrames.GetValue(0)!;
        Assert(!string.Equals(
                   GetSpriteFrameInfo(frame094).PageName,
                   GetSpriteFrameInfo(wrapFrame001).PageName,
                   StringComparison.Ordinal),
            "Serious loop frame 094 and wrap frame 001 must exercise different pages.");
        PrimeSpritePageForFrame(window, frame094);
        EvictResidentSpritePageForTest(
            window,
            GetSpriteFrameInfo(wrapFrame001).PageName);
        Invoke(window, "StartWorkClipAt", seriousLoopClip, 93);
        Assert(string.Equals(
                   GetSpriteFrameInfo(
                       GetField<object>(window, "_currentSpriteFrame")).Name,
                   GetSpriteFrameInfo(frame094).Name,
                   StringComparison.Ordinal),
            "Starting the cold-wrap regression at serious-loop frame 094 must " +
            "publish that exact hot pose first.");
        WaitForSpritePagePrefetchToSettleWithoutRendering(window);
        Assert(GetField<IDictionary>(window, "_residentSpritePages").Contains(
                   GetSpriteFrameInfo(wrapFrame001).PageName) &&
               string.Equals(
                   GetSpriteFrameInfo(
                       GetField<object>(window, "_currentSpriteFrame")).Name,
                   GetSpriteFrameInfo(frame094).Name,
                   StringComparison.Ordinal),
            "Asynchronous wrap-page prefetch must not replace serious-loop " +
            "frame 094 before the absolute clock reaches the seam.");
        PrepareWorkModeIdleState(window);
        AssertRestoredWorkExitAndEdgeButtonContract(window);
    }

    private static void AssertRestoredWorkExitAndEdgeButtonContract(
        MainWindow window)
    {
        var loopClip = GetField<object>(window, "_workLoopClip");
        var seriousEnterClip = GetField<object>(window, "_workSeriousEnterClip");
        var seriousExitClip = GetField<object>(window, "_workSeriousExitClip");
        var workExitClip = GetField<object>(window, "_workExitClip");
        var button = GetField<Button>(window, "WorkModeButton");

        // An exit requested before the selected serious-entry seam cancels the
        // expression transition but preserves the already accelerated absolute
        // keyboard phase until the ordinary exit seam.
        PrepareWorkModeIdleState(window);
        EnterWorkTypingForTest(window);
        var pendingEnterAnchorTimestamp = Stopwatch.GetTimestamp();
        SetField(window, "_workLoopAnchorFramePosition", 17.25d);
        SetField(
            window,
            "_workLoopAnchorTimestamp",
            pendingEnterAnchorTimestamp);
        SetField(window, "_workLoopPlaybackRate", 1d);
        Invoke(window, "StartFastWorkTypingAt", pendingEnterAnchorTimestamp);
        Assert(GetField<bool>(window, "_workSeriousEnterRequested"),
            "Pending serious-entry exit setup must first request serious entry.");
        Invoke(window, "RequestWorkExit");
        Assert(!GetField<bool>(window, "_workSeriousEnterRequested") &&
               double.IsPositiveInfinity(GetField<double>(
                   window,
                   "_workSeriousEnterTargetFramePosition")) &&
               GetField<bool>(window, "_workExitRequested") &&
               ReferenceEquals(GetRawField(window, "_activeClip"), loopClip) &&
               Math.Abs(GetField<double>(window, "_workLoopPlaybackRate") - 2d) <=
                   0.000001,
            "Exiting before the serious-entry seam must cancel only the face " +
            "transition while preserving the current 2x absolute phase.");

        // Once the eight-frame serious entry is already visible, an exit must
        // finish it, play the authored serious relaxation, then continue into
        // work-exit without exposing a serious-loop pose between the clips.
        PrepareWorkModeIdleState(window);
        EnterWorkTypingForTest(window);
        var seriousExitFrames = GetClipFrames(seriousExitClip);
        PrimeSpritePageForFrame(
            window,
            GetProperty<object>(seriousExitFrames.GetValue(0)!, "Image"));
        var midEnterTimestamp = Stopwatch.GetTimestamp();
        SetField(window, "_workLoopAnchorFramePosition", 0d);
        SetField(window, "_workLoopAnchorTimestamp", midEnterTimestamp);
        SetField(window, "_workLoopPlaybackRate", 1d);
        Invoke(window, "StartFastWorkTypingAt", midEnterTimestamp);
        Invoke(window, "StartWorkSeriousEnterClip", midEnterTimestamp);
        Assert(ReferenceEquals(
                   GetRawField(window, "_activeClip"),
                   seriousEnterClip),
            "Mid-entry exit setup must reach the sampled serious-entry clip.");
        Invoke(window, "RequestWorkExit");
        Invoke(
            window,
            "CompleteActiveClipAt",
            seriousEnterClip,
            checked(midEnterTimestamp + Stopwatch.Frequency / 8));
        Assert(ReferenceEquals(
                   GetRawField(window, "_activeClip"),
                   seriousExitClip) &&
               GetField<bool>(window, "_workExitRequested"),
            "Exiting during serious entry must play serious-exit directly, " +
            "without flashing a serious-loop frame.");
        Invoke(
            window,
            "CompleteActiveClipAt",
            seriousExitClip,
            checked(midEnterTimestamp + Stopwatch.Frequency / 2));
        Assert(ReferenceEquals(
                   GetRawField(window, "_activeClip"),
                   workExitClip) &&
               string.Equals(
                   GetRawField(window, "_workState")?.ToString(),
                   "Exiting",
                   StringComparison.Ordinal),
            "Serious-entry interruption must continue from facial relaxation " +
            "into the authored work-exit transition.");

        // work-exit is the exact reverse of work-enter. Leaving from an
        // already displayed entry frame must therefore start at its mirrored
        // index rather than replaying the transition from either endpoint.
        PrepareWorkModeIdleState(window);
        Assert((bool)Invoke(window, "TryEnterWorkMode")!,
            "Entering-exit mirror setup could not enter work mode.");
        var enterFrames = GetField<Array>(window, "_workEnterFrames");
        const int enterFrameIndex = 25;
        PrimeSpritePageForFrame(window, enterFrames.GetValue(enterFrameIndex)!);
        SetField(window, "_activeFrameIndex", enterFrameIndex);
        Invoke(
            window,
            "ShowStableFrame",
            enterFrames.GetValue(enterFrameIndex)!);
        Invoke(window, "RequestWorkExit");
        Assert(string.Equals(
                   GetRawField(window, "_workState")?.ToString(),
                   "Exiting",
                   StringComparison.Ordinal) &&
               ReferenceEquals(GetRawField(window, "_activeClip"), workExitClip) &&
               GetField<int>(window, "_activeFrameIndex") ==
                   enterFrames.Length - 1 - enterFrameIndex,
            "Exiting during work-enter must start from the mirrored reverse " +
            "pose instead of finishing or replaying the full entry.");

        // A hidden/disabled work button is still callable through reflection.
        // All supported dock states must reject that synthetic Click without
        // starting work or requesting an edge-peek retreat.
        var edgeLeftFrames = GetField<Array>(window, "_edgeLeftFrames");
        foreach (var edgeName in new[] { "Left", "Right", "Bottom" })
        {
            PrepareWorkModeIdleState(window);
            var edgeFrames = edgeName is "Left" or "Right"
                ? edgeLeftFrames
                : GetField<Array>(window, "_edgeBottomFrames");
            var entryFrameIndex = edgeFrames.Length - 1;
            PrimeSpritePageForFrame(
                window,
                edgeFrames.GetValue(entryFrameIndex)!);
            Invoke(window, "EnterEdgePeek", GetNestedEnum("EdgeDock", edgeName));
            Invoke(window, "RefreshWorkModeButton");
            Assert(!(bool)Invoke(window, "CanEnterWorkMode")!,
                $"{edgeName} edge-peek must block direct work entry.");
            AssertWorkButtonContract(
                window,
                phase: $"{edgeName} edge-peek",
                expectedState: "Idle",
                expectedContent: "去打工",
                expectedOpacity: 0,
                expectedIsEnabled: false,
                expectedIsHitTestVisible: false);

            Invoke(
                window,
                "WorkModeButton_Click",
                button,
                new RoutedEventArgs(Button.ClickEvent, button));
            Assert(!GetField<bool>(window, "_workEnterAfterEdgePeekExitRequested") &&
                   string.Equals(
                       GetRawField(window, "_edgeDock")?.ToString(),
                       edgeName,
                       StringComparison.Ordinal) &&
                   string.Equals(
                       GetRawField(window, "_workState")?.ToString(),
                       "Idle",
                       StringComparison.Ordinal) &&
                   GetRawField(window, "_activeClip") is null,
                $"{edgeName} hidden work button must remain a no-op when its " +
                "Click handler is invoked reflectively.");
            AssertWorkButtonContract(
                window,
                phase: $"{edgeName} post-reflection click",
                expectedState: "Idle",
                expectedContent: "去打工",
                expectedOpacity: 0,
                expectedIsEnabled: false,
                expectedIsHitTestVisible: false);
        }

        PrepareWorkModeIdleState(window);
    }

    private static void AssertWorkButtonContract(
        MainWindow window,
        string phase,
        string expectedState,
        string expectedContent,
        double expectedOpacity,
        bool expectedIsEnabled,
        bool expectedIsHitTestVisible)
    {
        Invoke(window, "RefreshWorkModeButton");
        var button = GetField<Button>(window, "WorkModeButton");
        var expectedTag = string.Equals(
            expectedState,
            "Idle",
            StringComparison.Ordinal)
                ? "Idle"
                : "Working";
        var expectedVisibility = expectedOpacity > 0.5
            ? Visibility.Visible
            : Visibility.Collapsed;
        var expectedHelpText = expectedTag == "Idle"
            ? "太阳图标，点击让小鲁班去打工"
            : "月亮图标，点击让小鲁班回去休息";
        _ = button.ApplyTemplate();
        var sunIcon = button.Template.FindName("SunIcon", button) as FrameworkElement;
        var moonIcon = button.Template.FindName("MoonIcon", button) as FrameworkElement;
        var actualState = GetRawField(window, "_workState")?.ToString();
        Assert(string.Equals(
                   actualState,
                   expectedState,
                   StringComparison.Ordinal) &&
               string.Equals(
                   button.Tag as string,
                   expectedTag,
                   StringComparison.Ordinal) &&
               button.Content is null &&
               string.Equals(
                   AutomationProperties.GetName(button),
                   expectedContent,
                   StringComparison.Ordinal) &&
               string.Equals(
                   AutomationProperties.GetHelpText(button),
                   expectedHelpText,
                   StringComparison.Ordinal) &&
               button.Visibility == expectedVisibility &&
               Math.Abs(button.Opacity - expectedOpacity) <= 0.001 &&
               button.IsEnabled == expectedIsEnabled &&
               button.IsHitTestVisible == expectedIsHitTestVisible &&
               sunIcon is not null && moonIcon is not null &&
               sunIcon.Visibility == Visibility.Visible &&
               moonIcon.Visibility == Visibility.Visible &&
               sunIcon.Opacity + moonIcon.Opacity is >= 0.999 and <= 1.051 &&
               (expectedTag == "Idle"
                   ? sunIcon.Opacity > 0.999 && moonIcon.Opacity < 0.001
                   : moonIcon.Opacity > 0.999 && sunIcon.Opacity < 0.001),
            $"{phase} work-icon contract mismatch: " +
            $"state={actualState}/{expectedState}, " +
            $"tag={button.Tag}/{expectedTag}, " +
            $"content={button.Content}/null, " +
            $"automation={AutomationProperties.GetName(button)}/{expectedContent}, " +
            $"visibility={button.Visibility}/{expectedVisibility}, " +
            $"opacity={button.Opacity:F3}/{expectedOpacity:F3}, " +
            $"enabled={button.IsEnabled}/{expectedIsEnabled}, " +
            $"hit={button.IsHitTestVisible}/{expectedIsHitTestVisible}.");
    }

    private static void PrepareWorkModeIdleState(MainWindow window)
    {
        if (!window.IsLoaded)
        {
            window.Show();
            PumpDispatcher(TimeSpan.FromMilliseconds(80));
        }

        Invoke(window, "StopWorkModeImmediately", true);
        GetField<Grid>(window, "PetHost").ReleaseMouseCapture();
        Invoke(window, "ExitEdgePeek", false, true);
        SetField(window, "_spritePageWarmupEnabled", false);
        PumpDispatcher(TimeSpan.FromMilliseconds(20));
        WaitForSpritePagePrefetchToSettle(window);
        GetField<DispatcherTimer>(window, "_automaticTimer").Stop();
        GetField<DispatcherTimer>(window, "_spritePagePrefetchDispatchTimer").Stop();
        GetField<TodoWindow>(window, "_todoWindow").Hide();
        GetField<Popup>(window, "BubblePopup").IsOpen = false;
        SetField(window, "_isClosing", false);
        SetField(window, "_sessionInactive", false);
        SetField(window, "_automaticAnimationEnabled", true);
        SetField(window, "_isReminderActive", false);
        SetField(window, "_isTransientPetSizeOverride", false);
        SetField(window, "_dragInteractionActive", false);
        SetField(window, "_pointerDown", false);
        SetField(window, "_dragStarted", false);
        SetField(window, "_dragPreservesWorkMode", false);
        SetField(window, "_workEdgeDock", GetNestedEnum("EdgeDock", "None"));
        SetField(window, "_workEdgeHandoffFrozenTimestamp", 0L);
        SetField(window, "_isPetSizeTransitioning", false);
        SetField(window, "_isPetSizePreviewSessionActive", false);
        SetField(window, "_isPetSizeAdjustmentActive", false);
        SetField(window, "_petSizeTargetUpdatePending", false);
        SetField(window, "_isFrameBlending", false);
        SetField(window, "_spriteFrameDescriptorPublishedForTesting", null);
        SetField(window, "_pendingSpriteFrame", null);
        SetField(window, "_desiredSpritePageName", null);
        SetField(window, "_renderDeferredSpritePageName", null);
        SetField(window, "_renderDeferredSpritePageFailureName", null);
        SetField(window, "_renderDeferredSpritePageCancellation", false);
        SetField(window, "_isEdgeRoaming", false);
        SetField(window, "_edgeDock", GetNestedEnum("EdgeDock", "None"));
        SetField(window, "_bubbleMode", GetNestedEnum("BubbleMode", "None"));
        SetField(window, "_activeClip", null);
        SetField(window, "_activeFrameIndex", -1);
        SetField(window, "_activeClipStartedTimestamp", 0L);
        SetField(window, "_activeFrameDeadlineTimestamp", 0L);
        SetField(window, "_workState", GetNestedEnum("WorkState", "Idle"));
        SetField(window, "_workExitRequested", false);
        SetField(window, "_workSeriousEnterRequested", false);
        SetField(window, "_workEnterAfterEdgePeekExitRequested", false);
        SetField(window, "_workSeriousExitRequested", false);
        SetField(window, "_openTodoAfterWorkExitRequested", false);
        SetField(window, "_todoOpenAfterWorkExitQueued", false);
        SetField(window, "_workLoopAnchorTimestamp", 0L);
        SetField(window, "_workLoopAnchorFramePosition", 0d);
        SetField(window, "_workLoopPlaybackRate", 1d);
        SetField(
            window,
            "_workSeriousEnterTargetFramePosition",
            double.PositiveInfinity);
        SetField(
            window,
            "_workSeriousExitTargetFramePosition",
            double.PositiveInfinity);
        SetField(window, "_workExitTargetFramePosition", double.PositiveInfinity);
        SetField(window, "_workFastUntilTimestamp", 0L);
        Invoke(window, "ClearDeferredActiveClipClock");
        Invoke(
            window,
            "ShowStableFrame",
            GetField<object>(window, "_idleFrame"));
        Invoke(window, "RefreshSnoreBubbleAnimationState");
        Invoke(window, "RefreshWorkModeButton");
        // Full-suite predecessors may legitimately leave the roaming-sized
        // resident set warm. Once this fixture has restored the ordinary idle
        // state, converge it through the production LRU trim before arranging
        // cold-page work scenarios; otherwise a later explicit test eviction
        // observes the stale high-water set rather than the scenario under test.
        Invoke(
            window,
            "TrimResidentSpritePagesToBudget",
            (object?)null);
        AssertResidentSpriteCacheAccounting(window, "work fixture idle trim");
    }

    private static void EnterWorkTypingForTest(MainWindow window)
    {
        Assert((bool)Invoke(window, "TryEnterWorkMode")!,
            "Work test setup requires a fully idle entry state.");
        Invoke(
            window,
            "CompleteActiveClipAt",
            GetField<object>(window, "_workEnterClip"),
            Stopwatch.GetTimestamp());
        Assert(string.Equals(
                   GetRawField(window, "_workState")?.ToString(),
                   "Typing",
                   StringComparison.Ordinal),
            "Work test setup failed to reach Typing.");
        Invoke(
            window,
            "StartActiveClipClockAt",
            Stopwatch.GetTimestamp(),
            TimeSpan.Zero);
    }

    private static object GetNestedEnum(string enumName, string valueName)
    {
        var type = typeof(MainWindow).GetNestedType(enumName, BindingFlags.NonPublic)
            ?? throw new InvalidOperationException($"找不到 MainWindow.{enumName}");
        return Enum.Parse(type, valueName);
    }

    private static object FindSpriteFrameBySuffix(
        MainWindow window,
        string frameNameSuffix)
    {
        var pages = GetDictionaryEntries(GetField<IDictionary>(window, "_spritePages"));
        foreach (var page in pages)
        {
            var frames = GetDictionaryEntries(
                GetProperty<IDictionary>(page.Value!, "Frames"));
            foreach (var frame in frames)
            {
                if (GetSpriteFrameInfo(frame.Value!).Name.EndsWith(
                        frameNameSuffix,
                        StringComparison.Ordinal))
                {
                    return frame.Value!;
                }
            }
        }

        throw new InvalidOperationException($"找不到精灵帧后缀：{frameNameSuffix}");
    }

    private static object CloneSpriteFrameWithName(object frame, string name)
    {
        var info = GetSpriteFrameInfo(frame);
        return Activator.CreateInstance(
                   frame.GetType(),
                   InstanceFlags,
                   binder: null,
                   args:
                   [
                       info.X,
                       info.Y,
                       info.Width,
                       info.Height,
                       info.DestinationX,
                       info.DestinationY,
                       info.PageName,
                       name
                   ],
                   culture: null)
               ?? throw new InvalidOperationException("无法克隆测试SpriteFrame");
    }

    private static void PrimeSpritePageForFrame(MainWindow window, object frame)
    {
        WaitForSpritePagePrefetchToSettle(window);
        var pageName = GetSpriteFrameInfo(frame).PageName;
        if (string.Equals(
                GetRawField(window, "_loadedSpritePageName") as string,
                pageName,
                StringComparison.Ordinal))
        {
            return;
        }

        // This synchronous wrapper is test-only. Production page changes must
        // continue to use the background decoder and old-frame retention.
        SetField(window, "_pendingSpriteFrame", null);
        SetField(window, "_pendingSpriteFrameBlendDuration", TimeSpan.Zero);
        SetField(window, "_desiredSpritePageName", null);
        SetField(window, "_desiredSpritePageUrgent", false);
        SetField(window, "_failedSpritePageName", null);

        var pageEntry = GetDictionaryEntries(
                GetField<IDictionary>(window, "_spritePages"))
            .Single(entry => string.Equals(
                entry.Key as string,
                pageName,
                StringComparison.Ordinal));
        Invoke(
            window,
            "LoadSpritePageIntoBuffer",
            pageName,
            pageEntry.Value!);
    }

    private static void WaitForPrefetchedSpritePage(
        MainWindow window,
        object expectedFrame)
    {
        var expectedPageName = GetSpriteFrameInfo(expectedFrame).PageName;
        WaitForSpritePagePrefetchToSettle(window);
        Assert(string.Equals(
                   GetRawField(window, "_loadedSpritePageName") as string,
                   expectedPageName,
                   StringComparison.Ordinal) ||
               GetField<IDictionary>(window, "_residentSpritePages")
                   .Contains(expectedPageName),
            $"预测预取必须准备目标分页：{expectedPageName}");
    }

    private static void EvictResidentSpritePageForTest(
        MainWindow window,
        string pageName)
    {
        _ = Invoke(window, "RemoveResidentSpritePage", pageName);
        AssertResidentSpriteCacheAccounting(window, $"测试驱逐 {pageName}");
    }

    private static void WaitForSpritePagePrefetchToSettle(MainWindow window)
    {
        var stopwatch = Stopwatch.StartNew();
        while (GetRawField(window, "_spritePagePrefetchTask") is Task task)
        {
            if (stopwatch.Elapsed >= TimeSpan.FromSeconds(3))
            {
                throw new InvalidOperationException(
                    "精灵分页后台预取必须在3秒内完成并发布到UI线程");
            }

            if (task.IsCompleted)
            {
                PumpDispatcher(TimeSpan.FromMilliseconds(10));
            }
            else
            {
                Thread.Yield();
            }
        }
    }

    private static void WaitForSpritePagePrefetchToSettleWithoutRendering(
        MainWindow window)
    {
        var stopwatch = Stopwatch.StartNew();
        while (GetRawField(window, "_spritePagePrefetchTask") is not null)
        {
            if (stopwatch.Elapsed >= TimeSpan.FromSeconds(3))
            {
                throw new InvalidOperationException(
                    "精灵分页后台预取必须在3秒内由唯一Normal dispatcher回调发布");
            }

            // The production continuation is queued at Normal. A same-priority
            // sentinel drains it but exits before the lower Render priority can
            // present the pending frame, preserving the test's synthetic clock.
            var frame = new DispatcherFrame();
            Dispatcher.CurrentDispatcher.BeginInvoke(
                DispatcherPriority.Normal,
                new Action(() => frame.Continue = false));
            Dispatcher.PushFrame(frame);
            Thread.Yield();
        }
    }

    private static object? Invoke(object instance, string name, params object?[] arguments)
    {
        var method = instance.GetType().GetMethod(name, InstanceFlags)
            ?? throw new InvalidOperationException($"找不到方法 {instance.GetType().Name}.{name}");
        return method.Invoke(instance, arguments);
    }

    private static object? InvokeOverload(
        object instance,
        string name,
        params object?[] arguments)
    {
        var method = instance.GetType()
            .GetMethods(InstanceFlags)
            .Single(candidate =>
            {
                if (!string.Equals(candidate.Name, name, StringComparison.Ordinal))
                {
                    return false;
                }

                var parameters = candidate.GetParameters();
                return parameters.Length == arguments.Length &&
                       parameters.Select((parameter, index) => (parameter, index))
                           .All(entry =>
                               arguments[entry.index] is null
                                   ? !entry.parameter.ParameterType.IsValueType ||
                                     Nullable.GetUnderlyingType(
                                         entry.parameter.ParameterType) is not null
                                   : entry.parameter.ParameterType.IsInstanceOfType(
                                       arguments[entry.index]));
            });
        return method.Invoke(instance, arguments);
    }

    private static object? InvokeStatic(Type type, string name, params object?[] arguments)
    {
        var method = type.GetMethod(name, StaticFlags)
            ?? throw new InvalidOperationException($"找不到静态方法 {type.Name}.{name}");
        return method.Invoke(null, arguments);
    }

    private static T GetField<T>(object instance, string name)
    {
        var field = instance.GetType().GetField(name, InstanceFlags)
            ?? throw new InvalidOperationException($"找不到字段 {instance.GetType().Name}.{name}");
        var value = field.GetValue(instance);
        return value is T typed
            ? typed
            : throw new InvalidOperationException(
                $"字段 {instance.GetType().Name}.{name} 类型不正确或为空");
    }

    private static object? GetRawField(object instance, string name)
    {
        var field = instance.GetType().GetField(name, InstanceFlags)
            ?? throw new InvalidOperationException($"找不到字段 {instance.GetType().Name}.{name}");
        return field.GetValue(instance);
    }

    private static void SetField(object instance, string name, object? value)
    {
        var field = instance.GetType().GetField(name, InstanceFlags)
            ?? throw new InvalidOperationException($"找不到字段 {instance.GetType().Name}.{name}");
        field.SetValue(instance, value);
    }

    private static T GetProperty<T>(object instance, string name)
    {
        var property = instance.GetType().GetProperty(name, InstanceFlags)
            ?? throw new InvalidOperationException($"找不到属性 {instance.GetType().Name}.{name}");
        var value = property.GetValue(instance);
        return value is T typed
            ? typed
            : throw new InvalidOperationException(
                $"属性 {instance.GetType().Name}.{name} 类型不正确或为空");
    }

    private static void AssertValidRect(Rect rect, string stage)
    {
        Assert(!rect.IsEmpty &&
               double.IsFinite(rect.Left) &&
               double.IsFinite(rect.Top) &&
               double.IsFinite(rect.Width) &&
               double.IsFinite(rect.Height) &&
               rect.Width > 0 && rect.Height > 0,
            $"{stage}必须是有限且宽高为正的矩形，实际 {rect}");
    }

    private static void AssertClose(double actual, double expected, string message)
    {
        Assert(Math.Abs(actual - expected) < 0.01,
            $"{message}：期望 {expected}，实际 {actual}");
    }

    private static void AssertTaskListScrollBarVisual(
        ScrollBar scrollBar,
        string stage,
        Color expectedColor)
    {
        scrollBar.ApplyTemplate();
        var track = scrollBar.Template.FindName(
                "PART_Track",
                scrollBar) as Track
            ?? throw new InvalidOperationException(
                $"{stage}滚动条缺少PART_Track");
        var thumb = track.Thumb
            ?? throw new InvalidOperationException(
                $"{stage}滚动条缺少Thumb");
        thumb.ApplyTemplate();
        var pill = thumb.Template.FindName(
                "ThumbPill",
                thumb) as Border
            ?? throw new InvalidOperationException(
                $"{stage}滚动块缺少ThumbPill");
        var highlight = thumb.Template.FindName(
                "ThumbHighlight",
                thumb) as Border;
        Assert(Math.Abs(scrollBar.Width - 12) < 0.01 &&
               Math.Abs(pill.Width - 7) < 0.01 &&
               Math.Abs(pill.CornerRadius.TopLeft - 3.5) < 0.01 &&
               pill.Background is SolidColorBrush background &&
               background.Color == expectedColor &&
               highlight is not null,
            $"{stage}滚动块必须是12 DIP热区内的主题色圆角高光药丸，不能使用生硬的系统默认滑块");
    }

    private static void AssertTaskFullTextTheme(
        TodoWindow todoWindow,
        bool scheduled)
    {
        var stage = scheduled ? "定时任务全文窗" : "待办全文窗";
        var chrome = GetField<Border>(
            todoWindow,
            "TaskFullTextPopupChrome");
        var title = GetField<TextBlock>(
            todoWindow,
            "TaskFullTextTitle");
        var preview = GetField<TextBox>(
            todoWindow,
            "TaskFullTextPreviewTextBox");
        var count = GetField<TextBlock>(
            todoWindow,
            "TaskFullTextCountText");
        var expectedChromeBackground = scheduled
            ? Color.FromRgb(0xFF, 0xF8, 0xF1)
            : Color.FromRgb(0xF3, 0xF7, 0xFD);
        var expectedChromeBorder = scheduled
            ? Color.FromRgb(0xEF, 0x94, 0x65)
            : Color.FromRgb(0x8C, 0xB4, 0xF4);
        var expectedShadow = scheduled
            ? Color.FromRgb(0xA8, 0x55, 0x36)
            : Color.FromRgb(0x5B, 0x78, 0xA8);
        var expectedTitle = scheduled
            ? Color.FromRgb(0xC4, 0x5F, 0x3D)
            : Color.FromRgb(0x3E, 0x70, 0xC6);
        var expectedTextBackground = scheduled
            ? Color.FromRgb(0xFF, 0xFC, 0xF8)
            : Color.FromRgb(0xF8, 0xFB, 0xFF);
        var expectedTextBorder = scheduled
            ? Color.FromRgb(0xF1, 0xC1, 0x9E)
            : Color.FromRgb(0xBD, 0xD2, 0xEF);
        var expectedTextForeground = scheduled
            ? Color.FromRgb(0x4B, 0x34, 0x2B)
            : Color.FromRgb(0x30, 0x37, 0x44);
        var expectedSelection = scheduled
            ? Color.FromRgb(0xF5, 0xB0, 0x7D)
            : Color.FromRgb(0xA9, 0xC9, 0xF4);
        var expectedCount = scheduled
            ? Color.FromRgb(0xC1, 0x8A, 0x6C)
            : Color.FromRgb(0x82, 0x95, 0xB3);
        var expectedScrollTrack = scheduled
            ? Color.FromArgb(0x22, 0xD6, 0xA0, 0x6A)
            : Color.FromArgb(0x24, 0x5B, 0x8D, 0xEF);
        var expectedScrollDrag = scheduled
            ? Color.FromRgb(0xD9, 0x7B, 0x2F)
            : Color.FromRgb(0x3E, 0x70, 0xC6);
        var expectedScrollThumb = scheduled
            ? Color.FromRgb(0xE7, 0xA1, 0x5E)
            : Color.FromRgb(0x7B, 0xA6, 0xE8);
        var expectedScrollHover = scheduled
            ? Color.FromRgb(0xF0, 0x9A, 0x48)
            : Color.FromRgb(0x5B, 0x8D, 0xEF);

        preview.ApplyTemplate();
        var scrollBar = FindVisualDescendants<ScrollBar>(preview)
            .FirstOrDefault(candidate =>
                candidate.Orientation == Orientation.Vertical)
            ?? throw new InvalidOperationException(
                $"{stage}缺少自绘纵向滚动条");
        scrollBar.ApplyTemplate();
        Assert(chrome.Background is SolidColorBrush chromeBackground &&
               chromeBackground.Color == expectedChromeBackground &&
               chrome.BorderBrush is SolidColorBrush chromeBorder &&
               chromeBorder.Color == expectedChromeBorder &&
               chrome.Effect is DropShadowEffect shadow &&
               shadow.Color == expectedShadow &&
               title.Foreground is SolidColorBrush titleBrush &&
               titleBrush.Color == expectedTitle &&
               preview.Background is SolidColorBrush textBackground &&
               textBackground.Color == expectedTextBackground &&
               preview.BorderBrush is SolidColorBrush textBorder &&
               textBorder.Color == expectedTextBorder &&
               preview.Foreground is SolidColorBrush textForeground &&
               textForeground.Color == expectedTextForeground &&
               preview.SelectionBrush is SolidColorBrush selection &&
               selection.Color == expectedSelection &&
               count.Foreground is SolidColorBrush countBrush &&
               countBrush.Color == expectedCount &&
               scrollBar.Background is SolidColorBrush scrollTrack &&
               scrollTrack.Color == expectedScrollTrack &&
               scrollBar.BorderBrush is SolidColorBrush scrollDrag &&
               scrollDrag.Color == expectedScrollDrag &&
               scrollBar.Foreground is SolidColorBrush scrollThumb &&
               scrollThumb.Color == expectedScrollThumb &&
               scrollBar.Tag is SolidColorBrush scrollHover &&
               scrollHover.Color == expectedScrollHover &&
               scrollBar.Template.FindName(
                   "PART_Track",
                   scrollBar) is Track,
            $"{stage}必须整套使用{(scheduled ? "橘色" : "蓝色")}主题，" +
            "包括窗口、正文、选区、计数和滚动条");
    }

    private static IDisposable HoldClipboardOpenForTest()
    {
        var ready = new ManualResetEventSlim();
        var release = new ManualResetEventSlim();
        Exception? failure = null;
        var clipboardOpened = false;
        var thread = new Thread(() =>
        {
            try
            {
                var deadline = Stopwatch.StartNew();
                while (!(clipboardOpened = OpenClipboard(IntPtr.Zero)) &&
                       deadline.Elapsed < TimeSpan.FromSeconds(2))
                {
                    Thread.Sleep(10);
                }

                if (!clipboardOpened)
                {
                    failure = new InvalidOperationException(
                        $"测试线程无法独占剪贴板，Win32={Marshal.GetLastWin32Error()}");
                }

                ready.Set();
                if (clipboardOpened)
                {
                    release.Wait(TimeSpan.FromSeconds(10));
                }
            }
            catch (Exception exception)
            {
                failure = exception;
                ready.Set();
            }
            finally
            {
                if (clipboardOpened)
                {
                    _ = CloseClipboard();
                }

                ready.Set();
            }
        })
        {
            IsBackground = true,
            Name = "UiStateChecks clipboard lock"
        };
        thread.Start();
        if (!ready.Wait(TimeSpan.FromSeconds(3)))
        {
            release.Set();
            throw new TimeoutException("测试线程在3秒内未取得剪贴板");
        }

        if (failure is not null)
        {
            release.Set();
            _ = thread.Join(TimeSpan.FromSeconds(1));
            throw new InvalidOperationException(
                "无法建立剪贴板占用回归条件",
                failure);
        }

        return new CallbackDisposable(() =>
        {
            release.Set();
            if (!thread.Join(TimeSpan.FromSeconds(3)))
            {
                throw new TimeoutException("剪贴板占用测试线程未能正常退出");
            }

            ready.Dispose();
            release.Dispose();
        });
    }

